const e="72 chapters",t=[{id:"chapter-57",number:57,title:"Lexical causatives: V + -이/히/리/기/우/구/추- · V-게 하다",goal:"Build natural causative pairs such as 먹다/먹이다, 자다/재우다, 입다/입히다, and 앉다/앉히다.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 먹이다~",cards:[{kind:"guess",word:{ko:"먹이다",romanization:"meogida",en:"to feed / make someone take",pos:"verb",nuance:"The subject is the causer, not the person eating."},sentence:{ko:"엄마가 아이에게 약을 먹였어요.",en:"The mother gave the child medicine."},target:"먹였",options:["to feed / make someone take","to inform / let know","to lower"],note:"Linked to chapter card word-ext-ch38-meogida."},{kind:"guess",word:{ko:"재우다",romanization:"jaeuda",en:"to put someone to sleep",pos:"verb",nuance:"자다 is intransitive: 아기가 자요. 재우다 adds a causer: 엄마가 아기를 재워요."},sentence:{ko:"아빠가 아기를 재웠어요.",en:"The father put the baby to sleep."},target:"재웠",options:["to inform / let know","to lower","to put someone to sleep"],note:"Chapter card word-ext-ch57-jaeuda."},{kind:"guess",word:{ko:"입히다",romanization:"iphida",en:"to dress someone / put clothing on someone",pos:"verb",nuance:"입다 is wear; 입히다 is dress someone else."},sentence:{ko:"아버지가 아기에게 코트를 입혔어요.",en:"The father put a coat on the baby."},target:"입혔",options:["to dress someone / put clothing on someone","to inform / let know","to lower"],note:"Linked to chapter card word-ext-ch38-iphida."},{kind:"guess",word:{ko:"읽히다",romanization:"ilkida",en:"to make someone read / to be read",pos:"verb",nuance:"With texts, 읽히다 often describes how easily something is read or understood."},sentence:{ko:"선생님이 학생들에게 본문을 읽혔어요.",en:"The teacher had the students read the passage."},target:"읽혔",options:["to make someone read / to be read","to inform / let know","to lower"],note:"Causative use; linked to word-ext-ch38-ilkida-passive."},{kind:"guess",word:{ko:"앉히다",romanization:"anjhida",en:"to seat someone",pos:"verb",nuance:"앉다 is what the person does; 앉히다 is what someone else does to seat them."},sentence:{ko:"직원이 손님을 창가 자리에 앉혔어요.",en:"The staff seated the guest by the window."},target:"앉혔",options:["to seat someone","to inform / let know","to lower"],note:"Linked to chapter card word-ext-ch38-anjhida."}],canDo:"Use lexical causatives for everyday care (밥을 먹이다, 옷을 입히다, 재우다)",id:"chapter-57-b1",chapterId:"chapter-57",index:0},{kind:"pattern",title:"문법 Grammar · Lexical causatives: V + -이/히/리/기/우/구/추-",cards:[{kind:"teach",name:"Lexical causatives: V + -이/히/리/기/우/구/추-",sub:"",rows:[{when:"-이- (e.g. after ㄱ, ㅁ, vowel stems)",add:"먹다 → 먹이다 (feed), 죽다 → 죽이다 (kill), 끓다 → 끓이다 (boil sth)",ex:"엄마가 아기에게 밥을 먹여요. (Mom feeds the baby.)"},{when:"-히- (often after ㄱ, ㄷ, ㅂ)",add:"입다 → 입히다 (dress sb), 앉다 → 앉히다 (seat sb), 눕다 → 눕히다 (lay sb down)",ex:"아이에게 옷을 입혔어요. (I dressed the child.)"},{when:"-리- (often after ㄹ)",add:"살다 → 살리다 (save), 울다 → 울리다 (make cry), 알다 → 알리다 (let know)",ex:"동생이 형을 울렸어요. (The younger one made the older one cry.)"},{when:"-기-",add:"웃다 → 웃기다 (make laugh), 벗다 → 벗기다 (take sth off sb), 남다 → 남기다 (leave sth)",ex:"그 영화가 저를 웃겼어요. (That movie made me laugh.)"},{when:"-우- (note the stem often changes shape)",add:"자다 → 재우다 (put to sleep), 깨다 → 깨우다 (wake sb), 타다 → 태우다 (give a ride)",ex:"아빠가 아기를 재웠어요. (Dad put the baby to sleep.)"},{when:"-구-/-추- (a very small set)",add:"달다 → 달구다 (heat sth up), 낮다 → 낮추다 (lower), 맞다 → 맞추다 (set/adjust)",ex:"소리를 좀 낮춰 주세요. (Please turn the volume down.)"}],examples:[{ko:"제가 강아지한테 밥을 먹였어요.",en:"I fed the puppy.",romanization:"Jega gangaji-hante bab-eul meogyeosseoyo.",note:"먹다 (eat) → 먹이다 (feed): the eater (강아지) takes -한테/에게, and the new causer (저) becomes the subject."},{ko:"엄마가 아이를 일찍 재웠어요.",en:"Mom put the child to bed early.",romanization:"Eomma-ga ai-reul iljjik jaewosseoyo.",note:"자다 (sleep) → 재우다: the stem changes shape (자→재우), so memorize this pair — you can't just add a suffix."}],more:{func:"A fixed, closed set of verbs that build a causative meaning ('make/get X to happen', or 'do the action to X') right into the verb stem by inserting -이-, -히-, -리-, -기-, -우-, -구-, or -추-. The doer of the plain verb becomes the object (usually -을/를), and a new causer becomes the subject. Because the set is fixed, you can't apply it to just any verb — each causative pair is learned as its own vocabulary item.",funcLead:"A fixed, closed set of verbs that build a causative meaning ('make/get X to happen', or 'do the action to X') right into the verb stem by inserting -이-, -히-, -…",keyPoint:{label:"Same suffix, opposite job: causative vs. passive",body:"The suffixes -이/히/리/기- also build passives, so one word can be either. 보이다 = 'be seen' (passive) or 'show' (causative); 잡히다 = 'be caught' (passive) or 'get sb to hold' (causative). Tell them apart by the arguments: a causative ADDS a causer-subject and keeps an object (친구가 저를 웃겨요 'my friend makes me laugh'), while a passive DROPS the agent and the old object becomes the subject (도둑이 잡혔어요 'the thief got caught'). If there's still a direct object being acted on, it's causative."},pronunciation:"Listen for the linking and aspiration the inserted consonant creates: 먹이다 is [머기다] (ㄱ links across), 입히다 is [이피다] (ㅂ+ㅎ → aspirated ㅍ), and 앉히다 is [안치다] (ㅈ+ㅎ → ㅊ). The suffix tends to fuse with the stem-final sound rather than staying separate.",pitfall:{wrong:"엄마가 아기를 먹게 했어요. (to mean 'Mom fed the baby')",right:"엄마가 아기에게 밥을 먹였어요.",explanation:"English has one verb 'feed', so learners grab the all-purpose V-게 하다 and say 먹게 했어요 — but that means 'made/let the baby eat (on its own)', not 'spoon-fed it'. When Korean has a dedicated lexical causative (먹이다, 재우다, 입히다), native speakers use it for the hands-on action. Save V-게 하다 for getting someone to do it themselves."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I fed the puppy." (제가 시작 · Start with 제가.)',tokens:["제가","강아지한테","밥을","먹였어요."],correct:"제가 강아지한테 밥을 먹였어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Mom put the child to bed early."',tokens:["엄마가","아이를","일찍","재웠어요."],correct:"엄마가 아이를 일찍 재웠어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"엄마가 아기를 먹게 했어요. (to mean 'Mom fed the baby')",ok:!1},{text:"엄마가 아기에게 밥을 먹였어요.",ok:!0}],explanation:"English has one verb 'feed', so learners grab the all-purpose V-게 하다 and say 먹게 했어요 — but that means 'made/let the baby eat (on its own)', not 'spoon-fed it'. When Korean has a dedicated lexical causative (먹이다, 재우다, 입히다), native speakers use it for the hands-on action. Save V-게 하다 for getting someone to do it themselves."}],canDo:"Use lexical causatives for everyday care (밥을 먹이다, 옷을 입히다, 재우다)",id:"chapter-57-b2",chapterId:"chapter-57",index:1},{kind:"words",title:"단어 Words 2 · 웃기다~",cards:[{kind:"guess",word:{ko:"웃기다",romanization:"utgida",en:"to make someone laugh / to be funny",pos:"verb",nuance:"웃다 is what the person does; 웃기다 is what causes the laughing. In speech, 웃기다 also works like 'to be funny.'"},sentence:{ko:"그 농담이 모두를 웃겼어요.",en:"That joke made everyone laugh."},target:"웃겼",options:["to inform / let know","to lower","to make someone laugh / to be funny"],note:"Chapter card word-ext-ch57-utgida."},{kind:"guess",word:{ko:"울리다",romanization:"ullida",en:"to make someone cry / to ring",pos:"verb",nuance:"울다 is cry or ring by itself; 울리다 makes someone cry or makes a sound ring."},sentence:{ko:"그 영화가 저를 울렸어요.",en:"That movie made me cry."},target:"울렸",options:["to inform / let know","to lower","to make someone cry / to ring"],note:"Chapter card word-ext-ch57-ullida."},{kind:"guess",word:{ko:"알리다",romanization:"allida",en:"to inform / let know",pos:"verb",nuance:"알리다 is the causative of 알다 ('to know'), so literally 'to make (someone) know' — you give a piece of information to a person, who takes 에게/한테, while the fact taught takes 을/를. The form you will reach for ten times a day is 알려 주세요 ('please let me know'), used to ask for an address, a time, a price, or any update. The near-synonym 가르치다 also means 'let know', but 가르치다 leans toward teaching a skill or directions ('역으로 가는 길 좀 가르쳐 주세요'), while 알리다 is just transmitting a fact ('결과를 알려 주세요'). The classic learner error is using plain 알다: 알아요 means 'I know' (a state), and you cannot make a request with it — you must use the causative 알려 주세요 to mean 'inform me'. Beyond person-to-person, 알리다 also covers public announcing — '진실을 세상에 알리다' (reveal the truth to the world)."},sentence:{ko:"일정이 바뀌면 바로 알려 주세요.",en:"If the schedule changes, please let me know right away."},target:"알려",options:["to feed / make someone take","to put someone to sleep","to inform / let know"],note:"Linked to dictionary card word-verb-075."},{kind:"guess",word:{ko:"낮추다",romanization:"natchuda",en:"to lower",pos:"verb",nuance:"낮다 is an adjective, while 낮추다 is an action verb. Compare 소리가 낮아요 with 소리를 낮춰 주세요."},sentence:{ko:"회의 중이라서 목소리를 낮췄어요.",en:"I lowered my voice because we were in a meeting."},target:"낮췄",options:["to feed / make someone take","to put someone to sleep","to lower"],note:"Chapter card word-ext-ch57-natchuda."},{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"아이가 밥을 먹어요.",en:"The child eats rice."},target:"먹어",options:["to feed / make someone take","to put someone to sleep","to eat"],note:"Base verb for comparison with 먹이다."},{kind:"payoff",line:{speaker:"민서",ko:"아이가 밥을 먹었어요와 엄마가 아이에게 밥을 먹였어요는 다르죠?",en:"The child ate and the mother fed the child are different, right?"},hl:"먹었"}],canDo:"Make or have someone do something with V-게 하다 (아이를 웃게 했어요)",id:"chapter-57-b3",chapterId:"chapter-57",index:2},{kind:"pattern",title:"문법 Grammar · V-게 하다",cards:[{kind:"hunt",name:"V-게 하다",sub:"make / have / let someone do something",lines:[{tokens:[{pre:"엄마가",mid:"",post:"",hit:!1},{pre:"저를",mid:"",post:"",hit:!1},{pre:"매일",mid:"",post:"",hit:!1},{pre:"운동하",mid:"게",post:"",hit:!0},{pre:"해요.",mid:"",post:"",hit:!1}],ko:"엄마가 저를 매일 운동하게 해요.",en:"My mom makes me exercise every day.",romanization:"Eomma-ga jeo-reul maeil undonghage haeyo."},{tokens:[{pre:"선생님이",mid:"",post:"",hit:!1},{pre:"학생들에게",mid:"",post:"",hit:!1},{pre:"책을",mid:"",post:"",hit:!1},{pre:"읽",mid:"게",post:"",hit:!0},{pre:"했어요.",mid:"",post:"",hit:!1}],ko:"선생님이 학생들에게 책을 읽게 했어요.",en:"The teacher had the students read the book.",romanization:"Seonsaengnim-i haksaengdeul-ege chaek-eul ilkge haesseoyo."}],rule:{name:"V-게 하다",rows:[{when:"Verb stem + -게 하다",add:"가다 → 가게 하다, 먹다 → 먹게 하다, 공부하다 → 공부하게 하다",ex:"선생님이 학생들을 일찍 가게 했어요. (The teacher made the students leave early.)"},{when:"Adjective stem + -게 하다 ('make become ~')",add:"행복하다 → 행복하게 하다, 깨끗하다 → 깨끗하게 하다",ex:"그 소식이 저를 행복하게 했어요. (That news made me happy.)"},{when:"Causee marker sets the nuance",add:"-이/가 (let/allow, softer), -을/를 (make, direct), -에게/한테 (get sb to do)",ex:"아이에게 채소를 먹게 했어요. (I got the child to eat vegetables.)"},{when:"Past / negative command",add:"-게 했어요, -게 하지 마(세요)",ex:"동생을 울게 하지 마. (Don't make your little sibling cry.)"}]},more:{func:"The productive, all-purpose causative: add -게 하다 to almost any verb or adjective stem to mean 'make/have/let someone do or become something.' Unlike the lexical causatives, this works with every verb, so it's the go-to whenever no special causative form exists. The causee is marked with -이/가, -을/를, or -에게/한테 depending on the nuance (letting vs. making vs. getting someone to do it).",funcLead:"The productive, all-purpose causative: add -게 하다 to almost any verb or adjective stem to mean 'make/have/let someone do or become something.' Unlike the lexica…",keyPoint:{label:"Lexical causative vs. V-게 하다 — how hands-on is the causer?",body:"When both exist, they differ in directness. 재우다 / 먹이다 mean the causer DOES the action to the causee (physically putting to sleep, spoon-feeding). 자게 하다 / 먹게 하다 mean the causer gets the causee to do it THEMSELVES. So 아기를 재웠어요 = 'I put the baby to sleep,' but 아기를 자게 했어요 = 'I made the baby sleep (e.g., by turning off the lights).' Use -게 하다 whenever there's no lexical form, or when you specifically mean indirect causing / letting."},pronunciation:"-게 하다 is said as written, [게 하다]; in fast speech 하다 can weaken, but unlike some patterns it does NOT contract into one word — keep 게 and 하다 separate. Don't confuse the causative with plain adverbial -게 (e.g. 크게 'loudly'); the causative needs the following 하다.",pitfall:{wrong:"선생님이 저를 공부하라고 했어요. (used loosely for 'made me study')",right:"선생님이 저를 공부하게 했어요.",explanation:"English 'make me do' covers everything, so learners reach for -라고 하다, which actually means 'told me to' (a reported spoken order), not 'made me'. For the neutral, everyday 'make/have someone do X,' the default is -게 하다. Use -라고 하다 only when there was a real spoken command, and save -게 만들다 (next note) for forceful or emotional results."}}},{kind:"drill",prompt:"The child wanted to sleep, so I let him.",sentence:"아이가 자고 싶어 해서 자___ 했어요.",options:[{text:"게",ok:!0},{text:"추-",ok:!1}],explanation:"With -이/가 and a permissive context, -게 하다 reads as 'let/allow', not 'force'."},{kind:"drill",prompt:"This song makes people dance.",sentence:"이 노래가 사람들을 춤추___ 해요.",options:[{text:"게",ok:!0},{text:"추-",ok:!1}],explanation:"The causer can be an inanimate thing (노래); -게 하다 freely takes non-human subjects."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "My mom makes me exercise every day."',tokens:["엄마가","저를","매일","운동하게","해요."],correct:"엄마가 저를 매일 운동하게 해요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The teacher had the students read the book." (선생님이 시작 · Start with 선생님이.)',tokens:["선생님이","학생들에게","책을","읽게","했어요."],correct:"선생님이 학생들에게 책을 읽게 했어요.",explanation:""}],canDo:"Make or have someone do something with V-게 하다 (아이를 웃게 했어요)",id:"chapter-57-b4",chapterId:"chapter-57",index:3},{kind:"words",title:"단어 Words 3 · 자다~",cards:[{kind:"guess",word:{ko:"자다",romanization:"jada",en:"to sleep",pos:"verb",nuance:"자다 becomes 잘 before some future or ability forms: 잘 거예요, 잘 수 있어요."},sentence:{ko:"아기가 자요.",en:"The baby sleeps."},target:"자요",options:["to feed / make someone take","to sleep","to dress someone / put clothing on someone"],note:"Base verb for comparison with 재우다."},{kind:"guess",word:{ko:"입다",romanization:"ipda",en:"to wear",pos:"verb",nuance:"입다 is a regular verb (입어요, 입었어요, 입습니다) meaning to put on or wear clothing on the torso and legs — shirts, coats, dresses, trousers, uniforms. The thing English speakers must internalize is that Korean has no single verb for 'wear'; it splits the action by body part: 입다 for body clothes, 신다 for footwear (shoes, socks), 쓰다 for things on the head/face (hats, glasses), 끼다 for snug items (gloves, rings), 차다 for things you strap on (watch, belt), and 매다 for ties/scarves you knot. So 'wear shoes' is never 신발을 입다 — it must be 신발을 신다. A second nuance is aspect: 입다 is the action of putting on, while the resulting state 'be wearing' is 입고 있다 (티셔츠를 입고 있어요 = is wearing a T-shirt). The opposite, for taking off any of these, is the single verb 벗다. The pitfall is simply over-extending 입다 to cover everything 'wear' covers in English."},sentence:{ko:"아기가 코트를 입었어요.",en:"The baby wore a coat."},target:"입었",options:["to wear","to feed / make someone take","to put someone to sleep"],note:"Base verb for comparison with 입히다."},{kind:"guess",word:{ko:"앉다",romanization:"anjda",en:"to sit",pos:"verb",nuance:"앉아 주세요 is a polite request; 앉으세요 is also common and a little more direct."},sentence:{ko:"학생들이 앞자리에 앉았어요.",en:"The students sat in the front row."},target:"앉았",options:["to feed / make someone take","to put someone to sleep","to sit"],note:"Base verb for comparison with 앉히다."},{kind:"guess",word:{ko:"울다",romanization:"ulda",en:"to cry",pos:"verb",nuance:"울다 means to cry and is a ㄹ irregular verb: the stem ㄹ drops before endings starting with ㅂ, ㄴ, or ㅅ, so the formal present is 웁니다 (not 울습니다) and the honorific is 우세요; before a plain vowel the ㄹ stays, giving 울어요 and 울었어요, and the future keeps it too in 울 거예요. The crier is the subject and takes 이/가 (아기가 울어요), unlike English where 'cry' can feel transitive. Its natural opposite is 웃다 (laugh), and its near-synonyms split by intensity and register: 눈물을 흘리다 ('shed tears', literally, more composed/quiet) describes tears running down without sobbing, while 흐느끼다 ('to sob') is heavier and more literary; plain 울다 is the everyday all-purpose word, often boosted by mimetics like 펑펑 울다 (bawl) or 엉엉 울다. Note 울다 also describes animals making their cry/call (새가 울다 = a bird sings/cries) and even a phone or alarm 'ringing/sounding'. The English-speaker pitfall is the conjugation — writing 울습니다 by habit when the ㄹ must drop to 웁니다 — plus confusing 울다 with 웃다, which differ by a single jamo."},sentence:{ko:"저는 그 영화를 보고 울었어요.",en:"I cried after watching that movie."},target:"울었",options:["to feed / make someone take","to put someone to sleep","to cry"],note:"Base verb for comparison with 울리다."}],canDo:"Say something brought about a result with V-게 만들다 (영화가 울게 만들었어요)",id:"chapter-57-b5",chapterId:"chapter-57",index:4},{kind:"pattern",title:"문법 Grammar · V-게 만들다",cards:[{kind:"teach",name:"V-게 만들다",sub:"bring about a result (often emotional or forceful)",rows:[{when:"Verb stem + -게 만들다",add:"울다 → 울게 만들다, 떠나다 → 떠나게 만들다, 포기하다 → 포기하게 만들다",ex:"그 영화가 저를 울게 만들었어요. (That movie made me cry.)"},{when:"Adjective stem + -게 만들다 ('cause to become ~')",add:"화나다 → 화나게 만들다, 행복하다 → 행복하게 만들다",ex:"그 말이 저를 화나게 만들었어요. (Those words made me angry.)"},{when:"Inanimate / situational causer (very common)",add:"스트레스가 / 그 일이 / 날씨가 ... + -게 만들다",ex:"스트레스가 저를 아프게 만들었어요. (Stress made me sick.)"},{when:"Past / negative command",add:"-게 만들었어요, -게 만들지 마(세요)",ex:"분위기를 어색하게 만들지 마세요. (Don't make things awkward.)"}],examples:[{ko:"그 드라마가 모두를 울게 만들었어요.",en:"That drama made everyone cry.",romanization:"Geu deurama-ga modu-reul ulge mandeureosseoyo.",note:"Emotional result + inanimate causer (드라마): the most typical use of -게 만들다."},{ko:"네 말이 나를 화나게 만들었어.",en:"What you said made me angry.",romanization:"Ne mal-i na-reul hwanage mandeureosseo.",note:"-게 만들다 fits strong feelings; here it sounds more loaded than the neutral 화나게 했어."}],more:{func:"Structurally just like V-게 하다 (add -게 만들다 to a verb or adjective stem), but with a stronger 'bring about / cause to become' flavor. Since 만들다 means 'make/create,' V-게 만들다 stresses that the causer actively PRODUCES the resulting state or behavior. It's especially common when the result is emotional (made me cry / angry / happy) or when the causing feels forceful, unintended, or hard to resist. The causer is very often an inanimate thing or a situation.",funcLead:"Structurally just like V-게 하다 (add -게 만들다 to a verb or adjective stem), but with a stronger 'bring about / cause to become' flavor.",keyPoint:{label:"-게 하다 vs. -게 만들다 — neutral instruction vs. strong/emotional result",body:"-게 하다 is the neutral default: a person tells or gets someone to do something (엄마가 저를 운동하게 해요 'Mom makes me exercise'). -게 만들다 highlights a produced result, usually emotional or forceful, and very often with a thing/situation as the cause (그 영화가 저를 울게 만들었어요 'That movie made me cry'). You usually wouldn't say 엄마가 저를 운동하게 만들어요 for routine instructing — that sounds like she forced an unwilling you into it. Rule of thumb: choosing/instructing → -게 하다; an event or feeling that takes you over → -게 만들다."},pronunciation:"만들다 is [만들다]; in the past tense the ㄹ stays and you get 만들었어요 [만드러써요] — don't drop the ㄹ. -게 is light and unstressed, so the phrase often runs together as one breath group: 울게 만들었어요 → [울게 만드러써요].",pitfall:{wrong:"엄마가 저를 매일 청소하게 만들어요. (for routine 'Mom makes me clean every day')",right:"엄마가 저를 매일 청소하게 해요.",explanation:"English 'make me clean' is neutral, but -게 만들다 adds a forceful, almost resentful 'forced me into it' coloring, so it sounds off for an everyday instruction. For routine 'has me / makes me do X,' use -게 하다. Reserve -게 만들다 for genuinely strong or emotional results, and especially when a thing or situation is the cause (그 영화가 저를 울게 만들었어요)."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "That drama made everyone cry."',tokens:["그","드라마가","모두를","울게","만들었어요."],correct:"그 드라마가 모두를 울게 만들었어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "What you said made me angry."',tokens:["네","말이","나를","화나게","만들었어."],correct:"네 말이 나를 화나게 만들었어.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"엄마가 저를 매일 청소하게 만들어요. (for routine 'Mom makes me clean every day')",ok:!1},{text:"엄마가 저를 매일 청소하게 해요.",ok:!0}],explanation:"English 'make me clean' is neutral, but -게 만들다 adds a forceful, almost resentful 'forced me into it' coloring, so it sounds off for an everyday instruction. For routine 'has me / makes me do X,' use -게 하다. Reserve -게 만들다 for genuinely strong or emotional results, and especially when a thing or situation is the cause (그 영화가 저를 울게 만들었어요)."}],canDo:"Say something brought about a result with V-게 만들다 (영화가 울게 만들었어요)",id:"chapter-57-b6",chapterId:"chapter-57",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A learner practices causative pairs in caregiving, classroom, and emotion scenes.",lines:[{speaker:"민서",ko:"아이가 밥을 먹었어요와 엄마가 아이에게 밥을 먹였어요는 다르죠?",en:"The child ate and the mother fed the child are different, right?",romanization:"aiga babeul meogeosseoyowa eommaga aiege babeul meogyeosseoyoneun dareujyo?"},{speaker:"지훈",ko:"네. 먹었어요는 아이가 한 행동이고, 먹였어요는 엄마가 하게 한 행동이에요.",en:"Yes. Ate is what the child did; fed is what the mother caused to happen.",romanization:"ne. meogeosseoyoneun aiga han haengdongigo, meogyeosseoyoneun eommaga hage han haengdongieyo."},{speaker:"민서",ko:"그럼 선생님이 학생들에게 본문을 읽혔어요도 사동이에요?",en:"Then is 'the teacher had the students read the passage' also causative?",romanization:"geureom seonsaengnimi haksaengdeurege bonmuneul ilkyeosseoyodo sadongieyo?"},{speaker:"지훈",ko:"맞아요. 하지만 책이 잘 읽혀요는 사동보다 피동처럼 느껴져요.",en:"Right. But 'the book reads well' feels more passive-like than causative.",romanization:"majayo. hajiman chaegi jal ilkyeoyoneun sadongboda pidongcheoreom neukkyeojyeoyo."},{speaker:"민서",ko:"웃기다와 울리다는 감정이 바뀌는 사동으로 보면 되겠네요.",en:"So I can see utgida and ullida as causatives where emotions change.",romanization:"utgidawa ullidaneun gamjeongi bakkwineun sadongeuro bomyeon doegenneyo."}]},{kind:"order",prompt:"Build: 'The teacher made the student read the book.'",tokens:["선생님이","학생에게","책을 읽혔어요"],correct:"선생님이 학생에게 책을 읽혔어요",explanation:"읽히다 can be causative: make someone read. 학생에게 marks who was made to read."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"네. 먹었어요는 아이가 한 행동이고, 먹였어요는 엄마가 하게 한 행동이에요.",options:[{text:"지훈",ok:!0},{text:"민서",ok:!1}],explanation:"Yes. Ate is what the child did; fed is what the mother caused to happen."},{kind:"drill",prompt:'무엇이 들어갈까요? · "So I can see utgida and ullida as causatives where emotions change."',sentence:"___와 울리다는 감정이 바뀌는 사동으로 보면 되겠네요.",options:[{text:"먹이다",ok:!1},{text:"재우다",ok:!1},{text:"웃기다",ok:!0}],explanation:""}],canDo:"Use lexical causatives for everyday care (밥을 먹이다, 옷을 입히다, 재우다)",id:"chapter-57-b7",chapterId:"chapter-57",index:6},{kind:"reading",title:"읽기 Reading · 누가 하게 만들었는지 보기",cards:[{kind:"read",title:"누가 하게 만들었는지 보기",chunks:["사동사를 공부할 때는 접미사만 외우면 헷갈리기 쉬워요. 먼저 누가 실제 행동을 하는지 보고, 그다음 누가 그 행동을 하게 했는지 확인해야 해요. 아이가 밥을 먹으면 아이가 행동의 주체예요. 하지만 엄마가 아이에게 밥을 먹이면 엄마가 사동의 주체이고 아이가 먹는 사람이에요.","선생님이 학생들에게 본문을 읽혔어요는 학생들이 읽지만 선생님이 읽게 한 문장이에요. 반대로 책이 잘 읽혀요는 책이 쉽게 읽힌다는 뜻이라 사동보다 피동처럼 느껴져요. 그래서 먹이다, 재우다, 입히다, 앉히다 같은 단어는 기본형과 짝으로 외우는 것이 좋아요."],translation:"When studying causative verbs, memorizing only suffixes can be confusing. First check who actually performs the action, and then who causes that action to happen. If a child eats rice, the child is the doer. But if a mother feeds the child, the mother is the causative subject and the child is the one eating. In 'the teacher had the students read the passage,' the students read but the teacher caused it. By contrast, 'the book reads well' means the book is easy to read, so it feels more passive-like than causative. That is why words like 먹이다, 재우다, 입히다, and 앉히다 are best memorized as pairs with their base forms.",qas:[{q:"사동사를 공부할 때 먼저 무엇을 확인해야 해요?",a:"누가 실제 행동을 하는지 확인해야 해요."},{q:"엄마가 아이에게 밥을 먹이면 누가 밥을 먹어요?",a:"아이가 밥을 먹어요."},{q:"책이 잘 읽혀요는 사동보다 무엇처럼 느껴져요?",a:"피동처럼 느껴져요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"그래서 ___, 재우다, 입히다, 앉히다 같은 단어는 기본형과 짝으로 외우는 것이 좋아요.",options:[{text:"먹이다",ok:!0},{text:"읽히다",ok:!1},{text:"웃기다",ok:!1}],explanation:""}],canDo:"Make or have someone do something with V-게 하다 (아이를 웃게 했어요)",id:"chapter-57-b8",chapterId:"chapter-57",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence means the mother fed the child?",sentence:null,options:[{text:"엄마가 아이에게 밥을 먹였어요.",ok:!0},{text:"엄마가 아이에게 밥을 먹었어요.",ok:!1},{text:"아이가 엄마에게 밥을 먹였어요.",ok:!1}],explanation:"먹이다 means someone causes or helps another person eat."},{kind:"drill",prompt:"Which sentence is causative 읽히다?",sentence:null,options:[{text:"선생님이 학생들에게 본문을 읽혔어요.",ok:!0},{text:"책이 술술 읽혔어요.",ok:!1},{text:"학생들이 책을 읽었어요.",ok:!1}],explanation:"The teacher causes the students to read. 책이 술술 읽혔어요 is passive-like/text-focused."},{kind:"drill",prompt:"Which form is better for a strong emotional result?",sentence:null,options:[{text:"그 영화가 저를 울게 만들었어요.",ok:!0},{text:"그 영화가 저를 자게 했어요.",ok:!1},{text:"그 영화 때문에 저는 울었어요.",ok:!1}],explanation:"V-게 만들다 fits emotional or resultative causation."},{kind:"drill",prompt:"아이___ 자리에 앉혔어요. (I seated the child.)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"앉히다 is causative, and 아이 is the person caused/helped to sit. That person takes 를."},{kind:"drill",prompt:"Which sentence means “The news made me cry”?",sentence:null,options:[{text:"그 소식이 저를 울렸어요.",ok:!0},{text:"그 소식에 제가 울었어요.",ok:!1},{text:"그 소식이 울었어요.",ok:!1}],explanation:"울리다 can mean make someone cry. 저를 marks the person affected by the news."}],canDo:"Say something brought about a result with V-게 만들다 (영화가 울게 만들었어요)",id:"chapter-57-b9",chapterId:"chapter-57",index:8}]},{id:"chapter-58",number:58,title:"V-겠어요 / V-겠습니다 · A/V-겠네요 / A/V-겠군요",goal:"Use -겠습니다 for formal commitment and service speech.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 확인하다~",cards:[{kind:"guess",word:{ko:"확인하다",romanization:"hwaginhada",en:"to check / confirm",pos:"verb",nuance:"확인하다 (確認하다, 確 'certain/firm' + 認 'recognize') means to check, verify, or confirm that something is correct or true — facts, times, reservations, messages — making sure reality matches what you expect. The crucial contrast is with 찾다, which English 'check' can blur: 찾다 is 'to look FOR / search' something not yet located (열쇠를 찾다, 'look for the keys'), whereas 확인하다 is 'to verify' something you can already see (열쇠가 있는지 확인하다, 'check whether the keys are there'). It also differs from 알아보다 ('look into/inquire to find out', 가격을 알아보다). It's a regular noun+하다 verb: 확인하 + 여요 → 확인해요, past 확인했어요, with 안/못 splitting before 하다 (확인 안 해요, 확인 못 해요). English-speaker pitfall: 'check the box' or 'check off' is NOT 확인하다 — ticking a box is 체크하다/표시하다; and 'check out a book/check out (a hotel)' uses 빌리다 or 체크아웃하다, not 확인하다, which strictly means 'verify/confirm'."},sentence:{ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},target:"확인하",options:["to handle / process","to check / confirm","to help politely"],note:"Linked to dictionary card word-verb-482."},{kind:"guess",word:{ko:"처리하다",romanization:"cheorihada",en:"to handle / process",pos:"verb",nuance:"처리하다 (處理하다, 處 'manage/place' + 理 'put in order') is a workhorse meaning to process, handle, or take care of a task, request, or problem, and the passive 처리되다 ('be processed') saturates official status messages. The register is neutral-professional, ideal for office work and paperwork. Watch three near-neighbors: 해결하다 ('to solve/resolve') implies fully fixing a problem so it's gone, whereas 처리하다 can just mean 'deal with / move it along the pipeline' without a happy ending; 다루다 means 'to handle/treat' in the sense of how you manage a topic or object; and bare 하다 ('do') cannot stand in for 'take care of a matter.' The English-speaker pitfall is exactly that bare-하다 trap: 'I'll do this issue' translated literally as '이 문제를 할게요' is wrong — you must say 처리할게요. Reach for 처리하다 whenever English would say 'handle,' 'take care of,' or 'process.'"},sentence:{ko:"이 일은 제가 처리하겠습니다.",en:"I will handle this matter."},target:"처리하",options:["to check / confirm","to help politely","to handle / process"],note:"Linked to dictionary card word-verb-046."},{kind:"guess",word:{ko:"도와드리다",romanization:"dowadeurida",en:"to help politely",pos:"verb",nuance:"도와드리다 is the humble form of 도와주다 ('help (as a favour)'), where 돕다 (to help) becomes 도와- by the ㅂ-irregular (돕 + 아 → 도와), and the helper-benefit 주다 is upgraded to its humble twin 드리다. So it literally means 'humbly do the favour of helping' — you lower yourself to help someone above you: a customer, elder, or guest. Contrast the three levels you must keep straight: 돕다 (bare dictionary 'help'), 도와주다 (help someone, neutral/friendly), 도와드리다 (help a superior, humble). English flattens all of these to 'help', so the pitfall is using 도와주다 with a customer (too casual for service) or, conversely, 도와드리다 with a buddy (oddly stiff). The phrase 무엇을 도와드릴까요? is the fixed, must-know service line. Conjugation follows 드리다: 도와드려요, 도와드렸어요."},sentence:{ko:"손님을 도와드리겠습니다.",en:"I will help the customer."},target:"도와드리",options:["to help politely","to check / confirm","to handle / process"],note:"Linked to dictionary card word-verb-265."},{kind:"guess",word:{ko:"참석하다",romanization:"chamseokhada",en:"to attend",pos:"verb",nuance:"참석하다 is Sino-Korean 參席 — 參 'take part' + 席 'seat' — literally 'take one's seat (and take part)', i.e. attend a formal event like a meeting, ceremony, or banquet. Its register is more formal than just 가다 'to go'; you 결혼식에 가요 casually but 결혼식에 참석합니다 in polite/written contexts. Distinguish it from its close cousin 참가하다 (參加, 'participate/enter'): 참석하다 emphasizes being PRESENT and seated at a gathering, while 참가하다 emphasizes actively TAKING PART (참가하다 fits a contest, race, or program — 대회에 참가하다). The big English-speaker pitfall is the particle: English 'attend THE meeting' (object) drives learners to 회의를 참석하다, but Korean uses 에 — 회의에 참석하다 — because you 'join INTO' the event. As a noun+하다 verb it conjugates on 하다 (참석해요, 참석했어요, formal 참석합니다); negative/impossible split the noun (참석 안 해요, 참석 못 해요)."},sentence:{ko:"죄송하지만 오늘은 참석하기 어렵겠습니다.",en:"I'm sorry, but it will be difficult for me to attend today."},target:"참석하",options:["to check / confirm","to attend","to handle / process"],note:"Linked to dictionary card word-verb-494."},{kind:"guess",word:{ko:"거절하다",romanization:"geojeolhada",en:"to refuse / decline",pos:"verb",nuance:"거절하다 (Sino-Korean 拒絶, 'block-and-sever') is the standard verb for declining a request, offer, or invitation, and the thing refused — 부탁, 제안, 초대 — takes 을/를. Compare it with the harsher 거부하다 (拒否, 'block-and-deny'): 거부하다 is a flat, often institutional rejection ('출석을 거부하다', 'refuse to comply'), while 거절하다 is the ordinary interpersonal 'no thanks'. Because directly refusing can feel rude in Korean social life, 거절하다 is habitually cushioned with 죄송하지만 ('sorry, but…'), 정중하게 ('politely'), or 어렵겠어요 ('that would be difficult'); the bare verb can sound cold. A frequent English-speaker slip is reaching for 거절하다 to mean 'reject a person' romantically — that is 차다 (dump) or 까이다 (get rejected), not 거절하다, which targets the request, not the human. Also do not confuse it with 사양하다, a humble 'I'll pass' used to politely decline an offer of food or a gift."},sentence:{ko:"정중하게 거절해야 할 때도 있어요.",en:"There are times when you have to decline politely."},target:"거절해",options:["to check / confirm","to handle / process","to refuse / decline"],note:"Linked to dictionary card word-verb-077."},{kind:"guess",word:{ko:"정중하다",romanization:"jeongjunghada",en:"courteous / respectful",pos:"adjective",nuance:"정중하다 (鄭重하다; the 重 carries 'weighty/grave,' so the word evokes treating someone with weighty respect) means courteous and respectful in a formal, dignified way — proper manners and respectful language. The near-synonym you must separate is 친절하다 (kind/friendly), and the dividing line is warmth vs. form: 친절하다 is personal warmth and helpfulness (a 친절한 점원 smiles and helps you happily), while 정중하다 is formal respect shown through correct manners and language (a 정중한 점원 is impeccably proper, not necessarily warm). For a careful apology, a polite refusal, or staff toward an important guest, you reach for 정중하다, where 친절하다 would feel too casual-warm. Also distinguish 겸손하다 (inner humility about oneself) from 정중하다 (outward courtesy toward others) — different directions. Register: 정중하다 is itself a formal-leaning word, at home in business Korean and written apologies (정중히 사과드립니다). The English-speaker pitfall is collapsing all 'polite' into one word: friendly-polite is 친절하다, formally-courteous is 정중하다. Stem note: 정중해요, not 정중하해요."},sentence:{ko:"어렵겠습니다는 정중한 거절에 자주 쓰여요.",en:"Eoryeopgesseumnida is often used in courteous refusals."},target:"정중한",options:["to be possible","to be tired","courteous / respectful"],note:"Linked to dictionary card word-ext-1792."},{kind:"payoff",line:{speaker:"직원",ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},hl:"확인하"}],canDo:"State my own intention politely with V-겠습니다 / V-겠어요 (확인하겠습니다)",id:"chapter-58-b1",chapterId:"chapter-58",index:0},{kind:"pattern",title:"문법 Grammar · V-겠어요 / V-겠습니다",cards:[{kind:"hunt",name:"V-겠어요 / V-겠습니다",sub:"stating your own intention",lines:[{tokens:[{pre:"제가",mid:"",post:"",hit:!1},{pre:"먼저",mid:"",post:"",hit:!1},{pre:"할게요.",mid:"",post:"",hit:!1},{pre:"제가",mid:"",post:"",hit:!1},{pre:"하",mid:"겠습니다",post:".",hit:!0}],ko:"제가 먼저 할게요. 제가 하겠습니다.",en:"Let me do it first. I'll do it.",romanization:"je-ga meon-jeo hal-ge-yo. je-ga ha-get-sseum-ni-da."},{tokens:[{pre:"오늘은",mid:"",post:"",hit:!1},{pre:"제가",mid:"",post:"",hit:!1},{pre:"살게요.",mid:"",post:"",hit:!1},{pre:"제가",mid:"",post:"",hit:!1},{pre:"사",mid:"겠습니다",post:".",hit:!0}],ko:"오늘은 제가 살게요. 제가 사겠습니다.",en:"Today it's on me — I'll pay.",romanization:"o-neu-reun je-ga sal-ge-yo. je-ga sa-get-sseum-ni-da."}],rule:{name:"V-겠어요 / V-겠습니다",rows:[{when:"Polite spoken intention",add:"verb stem + 겠어요",ex:"먹다 → 먹겠어요 (I'll eat / I'll have it)"},{when:"Formal commitment / announcement",add:"verb stem + 겠습니다",ex:"하다 → 하겠습니다 (I will do it)"},{when:"Set greeting phrases",add:"frozen 겠 forms",ex:"잘 먹겠습니다 / 처음 뵙겠습니다"}]},more:{func:"Attach 겠 to a verb stem to say what YOU are going to do, decided right now, as a will or promise. Because it carries the speaker's own will, it almost always has a first-person subject (저/제가). 겠어요 is polite-conversational; 겠습니다 is formal and sounds like a firm, clean promise — the kind you make to a boss, a teacher, or a customer.",funcLead:"Attach 겠 to a verb stem to say what YOU are going to do, decided right now, as a will or promise.",keyPoint:{label:"겠어요 vs 겠습니다",body:"Same intention meaning, different register. 겠어요 is everyday polite ('제가 할게요'/'먹겠어요'); 겠습니다 is formal and weightier, so it's the default for promises, service speech, and announcements. Don't use either for someone ELSE's plan — for that you need -(으)ㄹ 거예요 (친구가 올 거예요)."},pronunciation:"겠 ends in a [ㄷ] sound, so before 습니다 the ㅅ tenses and the batchim drops in: 겠습니다 → [게씀니다]. 겠어요 links smoothly as [게써요].",pitfall:{wrong:"친구가 내일 오겠어요 always reports the friend's plan.",right:"친구가 내일 올 거예요. (plan/prediction) / 이 시간이면 친구도 곧 오겠어요. (speaker's inference)",explanation:"Volitional 겠 normally expresses the speaker's own intention, so use -(으)ㄹ 거예요 to report another person's plan. But third-person 겠 is possible when it expresses the speaker's inference rather than that person's will."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Let me do it first. I'll do it."`,tokens:["제가","먼저","할게요.","제가","하겠습니다."],correct:"제가 먼저 할게요. 제가 하겠습니다.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Today it's on me — I'll pay."`,tokens:["오늘은","제가","살게요.","제가","사겠습니다."],correct:"오늘은 제가 살게요. 제가 사겠습니다.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구가 내일 올 거예요. (plan/prediction) / 이 시간이면 친구도 곧 오겠어요. (speaker's inference)",ok:!0},{text:"친구가 내일 오겠어요 always reports the friend's plan.",ok:!1}],explanation:"Volitional 겠 normally expresses the speaker's own intention, so use -(으)ㄹ 거예요 to report another person's plan. But third-person 겠 is possible when it expresses the speaker's inference rather than that person's will."}],canDo:"State my own intention politely with V-겠습니다 / V-겠어요 (확인하겠습니다)",id:"chapter-58-b2",chapterId:"chapter-58",index:1},{kind:"words",title:"단어 Words 2 · 자료~",cards:[{kind:"guess",word:{ko:"자료",romanization:"jaryo",en:"data / materials / documents",pos:"noun",nuance:"자료 can mean data, but in daily work and study talk it often means the file, handout, or slide deck someone needs."},sentence:{ko:"자료를 보니 결과가 달라지겠네요.",en:"Looking at the data, it looks like the result will change."},target:"자료",options:["data / materials / documents","result / outcome","customer / guest"],note:"Linked to dictionary card word-ext-ch35-jaryo."},{kind:"guess",word:{ko:"결과",romanization:"gyeolgwa",en:"result / outcome",pos:"noun",nuance:"결과 (結果, literally '結 form/bear + 果 fruit', i.e. the fruit that an action bears) is the end outcome of an action or event, and it almost always pairs with 나오다 (come out) or 나타나다 (appear) rather than any verb of 'making'. Its built-in partner is 과정 (the process leading up to it) and its mirror image is 원인 (the cause behind it), so Koreans constantly say 과정도 중요하고 결과도 중요하다. Register is neutral — fine in a doctor's office (검사 결과), a classroom (시험 결과), or a news report. The big English-speaker trap is twofold: first, you do not 'get' a result with a transitive verb the way English does — the result 나오다 (comes out) on its own and takes 이/가, so 결과를 나오다 is wrong; second, do not confuse the outcome 결과 with the reason 원인/이유 — 결과 is what happened at the end, never why."},sentence:{ko:"결과가 달라지겠네요.",en:"It looks like the result will change."},target:"결과",options:["result / outcome","data / materials / documents","customer / guest"],note:"Linked to dictionary card word-ext-1672."},{kind:"guess",word:{ko:"손님",romanization:"sonnim",en:"customer / guest",pos:"noun",nuance:"손님 is native Korean — 손 'guest' + the honorific suffix -님 — so it builds 'guest' into a respectful form, and it covers BOTH a paying customer in a shop AND a guest visiting your home. That built-in 님 is why 손님 is inherently polite and why staff address you directly as 손님 (like English 'sir/ma'am'). Contrast it with the neutral 사람 'person' (too plain and even rude to call a customer) and with 고객, the more formal/corporate term banks, telecoms, and notices use (고객님, 고객 센터 customer center) — 손님 feels face-to-face and shop-floor, 고객 feels institutional. Because 손님 deserves respect, it's counted with the honorific 분 (손님 한 분, not 한 명) and described with honorific verbs (오시다 'come', 계시다 'be present', 기다리고 계세요). The English-speaker pitfall is reaching for 사람 ('a person came to the shop' → 사람이 왔어요 sounds cold); say 손님이 오셨어요. Collocations: 손님을 받다 (take/receive customers), 손님이 들다 (customers come in), 단골손님 (regular), 손님 접대 (hosting guests)."},sentence:{ko:"손님을 바로 도와드리겠습니다.",en:"I will help the customer right away."},target:"손님",options:["customer / guest","data / materials / documents","result / outcome"],note:"Linked to dictionary card word-ext-140."},{kind:"guess",word:{ko:"바로",romanization:"baro",en:"right away",pos:"adverb",nuance:"바로 carries two everyday senses split by context: 'right away / immediately' with actions (바로 가요, 바로 출발해요) and 'exactly / right (there)' with places and identifications (바로 여기, 바로 앞, 바로 그거예요). For the time sense, its near-synonym 곧 means 'soon / shortly' — a small gap remains — while 바로 means truly 'this instant, with zero delay', so 바로 가요 is more immediate than 곧 가요. For the location/identification sense, 바로 tightens 'next to/in front of' into 'directly, precisely' and has no single English twin; it behaves like 'right' in 'right next to'. It collocates tightly with position words (바로 옆/앞/뒤/위) and with emphatic confirmations (바로 그거, 바로 너 'you, exactly'). The English-speaker pitfall is assuming 바로 only means 'immediately' and missing its 'exactly/right-there' use, plus stranding it from the word it marks — keep 바로 hugging the verb or noun (바로 앞, not 앞 바로)."},sentence:{ko:"바로 확인하겠습니다.",en:"I will check right away."},target:"바로",options:["right away","a little / a bit","to check / confirm"],note:"Linked to dictionary card word-ext-1293."},{kind:"guess",word:{ko:"주문",romanization:"jumun",en:"order",pos:"noun",nuance:"주문 is the noun 'order', from 注文 (注 'pour/note down' + 文 'writing') — originally 'to write down a request', which fits ordering perfectly. The verb is 주문하다, and a key contrast is 주문하다 vs 시키다: both mean 'to order', but 시키다 is more casual and also means 'to make someone do something', so toward staff the cleaner, slightly more standard choice is 주문하다 (시키다 is fine among friends: '뭐 시킬까?'). Knowing the bare noun unlocks the phrases you hear constantly — '주문 도와드릴게요', '주문 들어갔어요', '주문 확인해 주세요' — where 주문 stands alone. Register is neutral and identical in casual and formal dining. It collocates with 하다, 들어가다 (go in), 받다 (take an order), 확인하다 (confirm), and 취소하다 (cancel)."},sentence:{ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},target:"주문",options:["data / materials / documents","order","result / outcome"],note:"Linked to dictionary card word-ext-587."},{kind:"guess",word:{ko:"기다리다",romanization:"gidarida",en:"to wait",pos:"verb",nuance:"기다려 주세요 is one of the most useful service and classroom requests."},sentence:{ko:"그럼 조금 기다리겠습니다.",en:"Then I will wait a little."},target:"기다리",options:["to check / confirm","to handle / process","to wait"],note:"Linked to dictionary card word-verb-018."},{kind:"payoff",line:{speaker:"직원",ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away."},hl:"바로"}],canDo:"Make a careful inference from evidence with A/V-겠네요 (바쁘겠네요)",id:"chapter-58-b3",chapterId:"chapter-58",index:2},{kind:"pattern",title:"문법 Grammar · A/V-겠네요 / A/V-겠군요",cards:[{kind:"hunt",name:"A/V-겠네요 / A/V-겠군요",sub:"'that must be…' (inference from evidence)",lines:[{tokens:[{pre:"밖에",mid:"",post:"",hit:!1},{pre:"눈이",mid:"",post:"",hit:!1},{pre:"와요?",mid:"",post:"",hit:!1},{pre:"길이",mid:"",post:"",hit:!1},{pre:"막히",mid:"겠네요",post:".",hit:!0}],ko:"밖에 눈이 와요? 길이 막히겠네요.",en:"It's snowing outside? Then the roads must be jammed.",romanization:"ba-kke nu-ni wa-yo? gi-ri ma-ki-get-ne-yo."},{tokens:[{pre:"하루",mid:"",post:"",hit:!1},{pre:"종일",mid:"",post:"",hit:!1},{pre:"일했어요?",mid:"",post:"",hit:!1},{pre:"정말",mid:"",post:"",hit:!1},{pre:"피곤하",mid:"겠네요",post:".",hit:!0}],ko:"하루 종일 일했어요? 정말 피곤하겠네요.",en:"You worked all day? You must be really tired.",romanization:"ha-ru jong-il il-hae-sseo-yo? jeong-mal pi-gon-ha-get-ne-yo."}],rule:{name:"A/V-겠네요 / A/V-겠군요",rows:[{when:"Reacting to fresh evidence (spoken)",add:"stem + 겠네요",ex:"춥다 → 춥겠네요 (It must be cold!)"},{when:"Realization / 'I see, so…'",add:"stem + 겠군요",ex:"맛있다 → 맛있겠군요 (That must be tasty)"},{when:"Inferring about the past",add:"-았/었 + 겠네요",ex:"힘들었겠네요 (That must have been hard)"}]},more:{func:"This is the other big job of 겠: drawing a confident conclusion from what you can see, hear, or have just been told. Add 겠 to a verb or adjective stem, then 네요/군요 to react out loud. It means 'must be / I bet / I can tell.' 겠네요 is the everyday reaction; 겠군요 sounds a touch more reflective ('Ah, so it must be…').",funcLead:"This is the other big job of 겠: drawing a confident conclusion from what you can see, hear, or have just been told.",keyPoint:{label:"The two faces of 겠: will vs guess",body:"With a first-person action verb, 겠 = intention (먹겠어요 = I'll eat). With an adjective, or a third-person situation plus 네요/군요, 겠 = inference (맛있겠네요 = that must be tasty). Adjectives can't 'intend' anything, so 춥겠어요 can only mean 'it must be cold,' never 'I will be cold.'"},pronunciation:"겠네요 → [겐네요] (the [ㄷ] of 겠 becomes ㄴ before ㄴ, by nasalization). 겠어요 links as [게써요], and 겠군요 → [겓꾼뇨] with the ㄱ tensing.",pitfall:{wrong:"맛있을 거예요. (reacting to food right in front of you)",right:"맛있겠어요.",explanation:"English 'it'll be delicious' and 'it must be delicious' look similar, but Korean splits them: -(으)ㄹ 거예요 is a neutral prediction, while 겠 is the on-the-spot reaction to evidence in front of you. Looking at a steaming dish, say 맛있겠어요, not 맛있을 거예요."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "It's snowing outside? Then the roads must be jammed." (밖에 시작 · Start with 밖에.)`,tokens:["밖에","눈이","와요?","길이","막히겠네요."],correct:"밖에 눈이 와요? 길이 막히겠네요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "You worked all day? You must be really tired."',tokens:["하루","종일","일했어요?","정말","피곤하겠네요."],correct:"하루 종일 일했어요? 정말 피곤하겠네요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"맛있겠어요.",ok:!0},{text:"맛있을 거예요. (reacting to food right in front of you)",ok:!1}],explanation:"English 'it'll be delicious' and 'it must be delicious' look similar, but Korean splits them: -(으)ㄹ 거예요 is a neutral prediction, while 겠 is the on-the-spot reaction to evidence in front of you. Looking at a steaming dish, say 맛있겠어요, not 맛있을 거예요."}],canDo:"Make a careful inference from evidence with A/V-겠네요 (바쁘겠네요)",id:"chapter-58-b4",chapterId:"chapter-58",index:3},{kind:"words",title:"단어 Words 3 · 회의~",cards:[{kind:"guess",word:{ko:"회의",romanization:"hoeui",en:"meeting",pos:"noun",nuance:"회의 (漢字 會議, 會 'gather' + 議 'discuss') is a formal, work-style meeting where people gather to discuss and decide something — a board meeting, a team sync, a planning session. The near-synonym learners reach for is 모임, but 모임 is a social get-together (a dinner, a club, friends meeting up) with no agenda, so calling drinks with friends a 회의 sounds robotic; conversely calling a budget review a 모임 sounds too loose. It pairs naturally with 회의를 하다 (hold), 회의에 들어가다 (go into), 회의가 길어지다 (run long). The English-speaker pitfall is the particle: you are *in* a meeting as a location, so the action takes 회의에서, but you *enter* a meeting with 회의에 들어가다 — and never confuse 회의 with the look-alike 회사 (company) or 회비 (membership fee)."},sentence:{ko:"오늘 회의에서는 설명이 좀 어렵겠습니다.",en:"In today's meeting, explaining it may be a bit difficult."},target:"회의",options:["meeting","data / materials / documents","result / outcome"],note:"Linked to dictionary card word-ext-121."},{kind:"guess",word:{ko:"설명",romanization:"seolmyeong",en:"explanation",pos:"noun",nuance:"설명(說明) is Sino-Korean — 說 'to tell/speak' + 明 'clear, bright' — literally 'to make clear by telling,' i.e. an explanation of how or why something works. Distinguish it from 설득(說得) 'persuasion' (talking someone INTO agreeing, sharing the 說 root) and from 묘사(描寫) 'description' (depicting what something looks/feels like); 설명 is about clarifying and informing, not convincing or portraying. As a noun it becomes the verb with 하다: 설명하다, very often softened to 설명해 주세요/주시겠어요 'please explain for me.' Collocations: 설명을 하다/듣다, 자세한 설명, 설명이 부족하다/이해가 안 되다, 설명서 'instruction manual.' The English-speaker pitfall: English 'explain to me' tempts learners to mark the listener with 를 (저를 설명하다 ✗, which would mean 'explain ME'); the listener takes 한테/에게 (저한테 설명해 주세요), and what you explain takes 을/를. Bare 설명 can't be the verb — use 설명하다. Don't confuse 설명 with the look-alike 설탕 'sugar.'"},sentence:{ko:"설명이 길어지면 이해하기 어렵겠네요.",en:"If the explanation gets long, it will be hard to understand."},target:"설명",options:["data / materials / documents","explanation","result / outcome"],note:"Linked to dictionary card word-ext-1461."},{kind:"guess",word:{ko:"조금",romanization:"jogeum",en:"a little / a bit",pos:"adverb",nuance:"조금 means 'a little / a bit / a few' and is the natural counterweight to 많이 for small amounts or mild degrees. Its closest relative is its own contracted form 좀: 조금 is the full, slightly more careful version you can write and say, while 좀 is the quick spoken reduction (조금만요 ↔ 좀만요 are the same idea). Compared with the noun-ish 약간 ('slightly', a touch more formal/written), 조금 is the warm conversational choice. It naturally collocates with quantities and gentle states — 조금 더 ('a little more'), 조금 있다가 ('in a little while') — and its softness makes it ideal for modest answers and polite requests. The English-speaker pitfall is hearing 좀 in speech and not realizing it is just 조금 reduced, and over-stacking it with big-amount words: 조금 많이 is self-contradictory because 조금 only ever points to a small degree."},sentence:{ko:"조금 기다리겠습니다.",en:"I will wait a little."},target:"조금",options:["a little / a bit","right away","to check / confirm"],note:"Linked to dictionary card word-ext-1286."},{kind:"guess",word:{ko:"가능하다",romanization:"ganeunghada",en:"to be possible",pos:"adjective",nuance:"가능하다 (可能, 可 'can/permissible' + 能 'ability') means 'possible / doable / available', and it is wonderfully practical for daily service questions — 예약 가능해요? ('Is a reservation possible?'), 카드 가능해요? ('Can I pay by card?'). In these, a noun sits directly before it and it neatly replaces a longer '-ㄹ 수 있다' clause, sounding crisp and businesslike. The softener 가능하면 ('if possible') makes requests polite, and the fixed frame 가능한 한 + adjective/adverb means 'as ~ as possible' (가능한 한 빨리 'as soon as possible') — note this is different from 가능한 N ('a possible N'). Its antonym is 불가능하다. One pitfall: while 가능하다 and '-ㄹ 수 있다' both render English 'can', '-ㄹ 수 있다' attaches to a verb stem describing an action you're able to do (갈 수 있어요 'I can go'), whereas 가능하다 attaches to a noun or stands alone judging feasibility — don't merge them into 갈 가능해요."},sentence:{ko:"이 방법이 가능할 것 같아요.",en:"I think this method might be possible."},target:"가능할",options:["to be possible","courteous / respectful","to be tired"],note:"Linked to dictionary card word-ext-1255."},{kind:"guess",word:{ko:"피곤하다",romanization:"pigonhada",en:"to be tired",pos:"adjective",nuance:"피곤하다 is physical/general tiredness — worn out, drained, exhausted — typically after work, study, travel, or poor sleep. It is Sino-Korean 疲困 (疲 weary + 困 exhausted), literally 'weary-exhausted', which is why it reads as bodily fatigue rather than sleepiness. Keep it apart from 졸리다 ('sleepy'): you can be 피곤하다 yet wide awake (drained but not nodding off), and 졸리다 is specifically wanting to sleep — don't swap them. It is also milder and more everyday than 지치다 ('to be worn out/burned out'), which implies you've reached your limit. As a regular 하다-adjective it is 피곤해요 (not 피곤하요). One common English-speaker slip: 피곤하다 normally describes a PERSON being tired; to call an activity 'tiring' you also use 피곤하다 (피곤한 일 = 'tiring work'), but to call a person 'tiresome/draining' Koreans say 피곤한 사람 — meaning 'a person who is exhausting to deal with', a nuance worth knowing so you don't misread it as 'a tired person.'"},sentence:{ko:"표정을 보니 많이 피곤하시겠네요.",en:"Seeing your expression, you must be very tired."},target:"피곤하",options:["to be tired","courteous / respectful","to be possible"],note:"Linked to dictionary card word-ext-257."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"오늘은 참석하기 어렵겠습니다.",en:"It will be difficult for me to attend today."},target:"어렵",options:["to be difficult","courteous / respectful","to be possible"],note:"Linked to dictionary card word-adjective-037."},{kind:"payoff",line:{speaker:"손님",ko:"감사합니다. 그럼 조금 기다리겠습니다.",en:"Thank you. Then I will wait a little."},hl:"조금"}],canDo:"Talk about a future plan with V-(으)ㄹ 거예요 (기다릴 거예요)",id:"chapter-58-b5",chapterId:"chapter-58",index:4},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 거예요",cards:[{kind:"hunt",name:"V-(으)ㄹ 거예요",sub:"talking about a future plan",lines:[{tokens:[{pre:"이번",mid:"",post:"",hit:!1},{pre:"주말에",mid:"",post:"",hit:!1},{pre:"부산에",mid:"",post:"",hit:!1},{pre:"갈",mid:"",post:"",hit:!1},{pre:"",mid:"거예요",post:".",hit:!0}],ko:"이번 주말에 부산에 갈 거예요.",en:"I'm going to Busan this weekend.",romanization:"i-beon ju-ma-re bu-sa-ne gal kkeo-ye-yo."},{tokens:[{pre:"민수",mid:"",post:"",hit:!1},{pre:"씨는",mid:"",post:"",hit:!1},{pre:"안",mid:"",post:"",hit:!1},{pre:"올",mid:"",post:"",hit:!1},{pre:"",mid:"거예요",post:".",hit:!0},{pre:"바쁘대요.",mid:"",post:"",hit:!1}],ko:"민수 씨는 안 올 거예요. 바쁘대요.",en:"Minsu isn't going to come. He says he's busy.",romanization:"min-su ssi-neun an ol kkeo-ye-yo. ba-ppeu-dae-yo."}],rule:{name:"V-(으)ㄹ 거예요",rows:[{when:"Stem ends in a vowel",add:"+ ㄹ 거예요",ex:"가다 → 갈 거예요 (I'm going to go)"},{when:"Stem ends in a consonant",add:"+ 을 거예요",ex:"먹다 → 먹을 거예요 (I'm going to eat)"},{when:"ㄹ-final stem",add:"+ 거예요 (ㄹ stays)",ex:"만들다 → 만들 거예요 (I'll make it)"}]},more:{func:"Use -(으)ㄹ 거예요 to state a plan or prediction about the future — yours OR someone else's. Unlike volitional 겠, it doesn't sound like an on-the-spot vow; it just reports what is going to happen. It's the everyday way to say 'I'm going to…' / 'X is going to…'.",funcLead:"Use -(으)ㄹ 거예요 to state a plan or prediction about the future — yours OR someone else's.",keyPoint:{label:"거예요 vs 겠",body:"Both reach into the future, but the feel differs. -(으)ㄹ 거예요 = a settled plan or neutral prediction, and works for anyone (저도, 친구도). 겠 = a will/promise made right now, almost always first-person (제가 하겠습니다). So a server taking your order says 주문하시겠어요? (your intention), while you describe your trip with 갈 거예요 (it's planned)."},pronunciation:"Standard spelling is 거예요 (you'll also see 거에요, but 거예요 is correct). The ㄹ of the -(으)ㄹ form tenses the next sound: 갈 거예요 → [갈 꺼예요], 먹을 거예요 → [머글 꺼예요].",pitfall:{wrong:"제가 도와줄 거예요 is always wrong as an offer.",right:"제가 도와드릴게요. / 제가 도와드리겠습니다. / 제가 도와줄 거예요.",explanation:"All three can work, with different tones. 도와드릴게요 is the natural everyday offer; 도와드리겠습니다 is formal and firm. 도와줄 거예요 can reassure or emphasize a future plan to help, although it is less like a spontaneous service-style offer."}}},{kind:"drill",prompt:"I'm going to eat dinner at home.",sentence:"저녁은 집에서 먹을 ___.",options:[{text:"겠어요",ok:!1},{text:"거예요",ok:!0},{text:"겠습니다",ok:!1}],explanation:"Stem 먹- ends in a consonant, so it takes 을 거예요."},{kind:"drill",prompt:"The weather will be clear tomorrow.",sentence:"내일은 날씨가 맑을 ___.",options:[{text:"겠어요",ok:!1},{text:"겠습니다",ok:!1},{text:"거예요",ok:!0}],explanation:"A neutral forecast — the typical 'prediction' use, where 겠 would sound oddly personal."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm going to Busan this weekend." (이번 시작 · Start with 이번.)`,tokens:["이번","주말에","부산에","갈","거예요."],correct:"이번 주말에 부산에 갈 거예요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Minsu isn't going to come. He says he's busy."`,tokens:["민수","씨는","안","올","거예요.","바쁘대요."],correct:"민수 씨는 안 올 거예요. 바쁘대요.",explanation:""}],canDo:"Talk about a future plan with V-(으)ㄹ 거예요 (기다릴 거예요)",id:"chapter-58-b6",chapterId:"chapter-58",index:5},{kind:"pattern",title:"문법 Grammar · A/V-(으)ㄹ 것 같아요",cards:[{kind:"hunt",name:"A/V-(으)ㄹ 것 같아요",sub:"a soft, tentative guess",lines:[{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"올",mid:"",post:"",hit:!1},{pre:"",mid:"것",post:"",hit:!0},{pre:"",mid:"같아요",post:".",hit:!0}],ko:"오늘 비가 올 것 같아요.",en:"I think it's going to rain today.",romanization:"o-neul bi-ga ol geot ga-ta-yo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"옷은",mid:"",post:"",hit:!1},{pre:"저한테",mid:"",post:"",hit:!1},{pre:"좀",mid:"",post:"",hit:!1},{pre:"클",mid:"",post:"",hit:!1},{pre:"",mid:"것",post:"",hit:!0},{pre:"",mid:"같아요",post:".",hit:!0}],ko:"이 옷은 저한테 좀 클 것 같아요.",en:"I think this shirt will be a bit big on me.",romanization:"i o-seun jeo-han-te jom keul geot ga-ta-yo."}],rule:{name:"A/V-(으)ㄹ 것 같아요",rows:[{when:"Verb, future guess",add:"+ -(으)ㄹ 것 같아요",ex:"오다 → 올 것 같아요 (I think it'll come/rain)"},{when:"Adjective, present-state guess",add:"+ -(으)ㄴ 것 같아요",ex:"비싸다 → 비싼 것 같아요 (It seems expensive)"},{when:"Adjective, future or tentative expectation",add:"+ -(으)ㄹ 것 같아요",ex:"비싸다 → 비쌀 것 같아요 (I think it will be expensive)"},{when:"Past guess (already happened)",add:"-(으)ㄴ 것 같아요",ex:"가다 → 간 것 같아요 (Seems they left)"}]},more:{func:"-(으)ㄹ 것 같아요 means 'I think / it seems / probably.' It softens a statement into a guess about the future or about something uncertain, so it sounds modest and polite. It pairs with this 겠 chapter as the gentler cousin of inference: where 겠네요 is a confident 'must be,' -(으)ㄹ 것 같아요 is a hedged 'I think / probably.'",funcLead:"-(으)ㄹ 것 같아요 means 'I think / it seems / probably.' It softens a statement into a guess about the future or about something uncertain, so it sounds modest and p…",keyPoint:{label:"겠네요 vs (으)ㄹ 것 같아요",body:"Both are guesses, but the confidence differs. 겠네요 = a confident 'it must be…,' usually a quick reaction to evidence right there (춥겠네요). -(으)ㄹ 것 같아요 = a softer 'I think / probably' that leaves room for doubt (추울 것 같아요). When you want to sound modest or unsure, reach for -(으)ㄹ 것 같아요."},pronunciation:"것 같아요 → [걷 까타요]: the ㄱ of 같- tenses to [까] after the [ㄷ] of 것, and 같아요 links as [가타요]. The ㄹ form tenses too: 올 것 → [올 껃].",pitfall:{wrong:"맛있을 것 같아요. (reacting to a dish steaming in front of you)",right:"맛있겠어요.",explanation:"When the evidence is right there and you're confident, -(으)ㄹ 것 같아요 sounds oddly hesitant — like you're unsure about food you can clearly see is good. Use the confident 겠어요/겠네요 for that on-the-spot reaction, and save -(으)ㄹ 것 같아요 for genuinely uncertain guesses."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I think it's going to rain today."`,tokens:["오늘","비가","올","것","같아요."],correct:"오늘 비가 올 것 같아요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"맛있을 것 같아요. (reacting to a dish steaming in front of you)",ok:!1},{text:"맛있겠어요.",ok:!0}],explanation:"When the evidence is right there and you're confident, -(으)ㄹ 것 같아요 sounds oddly hesitant — like you're unsure about food you can clearly see is good. Use the confident 겠어요/겠네요 for that on-the-spot reaction, and save -(으)ㄹ 것 같아요 for genuinely uncertain guesses."}],canDo:"Soften a statement into a tentative guess with -(으)ㄹ 것 같아요 (끝날 것 같아요)",id:"chapter-58-b7",chapterId:"chapter-58",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A workplace chat moves through service commitment, evidence-based inference, and polite refusal.",lines:[{speaker:"직원",ko:"주문은 제가 바로 확인하겠습니다.",en:"I will check the order right away.",romanization:"jumuneun jega baro hwaginhagetseumnida."},{speaker:"손님",ko:"감사합니다. 그럼 조금 기다리겠습니다.",en:"Thank you. Then I will wait a little.",romanization:"gamsahamnida. geureom jogeum gidarigetseumnida."},{speaker:"연구원",ko:"자료를 보니 결과가 달라지겠네요.",en:"Looking at the data, it looks like the result will change.",romanization:"jaryoreul boni gyeolgwa-ga dallajigenneyo."},{speaker:"동료",ko:"그럼 오늘 회의에서는 설명이 좀 어렵겠습니다.",en:"Then in today's meeting, explaining it may be a bit difficult.",romanization:"geureom oneul hoeuieseo-neun seolmyeongi jom eoryeopgetseumnida."},{speaker:"민서",ko:"죄송하지만 오늘은 참석하기 어렵겠습니다.",en:"I'm sorry, but it will be difficult for me to attend today.",romanization:"joesonghajiman oneureun chamseokhagi eoryeopgetseumnida."},{speaker:"지훈",ko:"알겠습니다. 이 일은 제가 처리하겠습니다.",en:"Understood. I will handle this matter.",romanization:"algesseumnida. i ireun jega cheorihagetseumnida."}]},{kind:"order",prompt:"Build: 'I will help you right away.'",tokens:["바로","도와드리겠습니다"],correct:"바로 도와드리겠습니다",explanation:"도와드리겠습니다 is formal and respectful. 바로 adds the service promise “right away.”"},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"그럼 오늘 회의에서는 설명이 좀 어렵겠습니다.",options:[{text:"직원",ok:!1},{text:"동료",ok:!0}],explanation:"Then in today's meeting, explaining it may be a bit difficult."},{kind:"drill",prompt:'무엇이 들어갈까요? · "I will check the order right away."',sentence:"주문은 제가 ___ 확인하겠습니다.",options:[{text:"조금",ok:!1},{text:"확인하다",ok:!1},{text:"바로",ok:!0}],explanation:""}],canDo:"State my own intention politely with V-겠습니다 / V-겠어요 (확인하겠습니다)",id:"chapter-58-b8",chapterId:"chapter-58",index:7},{kind:"reading",title:"읽기 Reading · 겠의 세 가지 얼굴",cards:[{kind:"read",title:"겠의 세 가지 얼굴",chunks:["겠은 단순히 미래를 말하는 표현이 아니에요. 직원이 손님에게 주문을 확인하겠습니다라고 말하면, 그냥 미래 계획이 아니라 지금 책임지고 처리하겠다는 약속처럼 들려요. 반대로 자료를 보니 결과가 달라지겠네요는 자료라는 근거를 보고 내린 추론이에요.","또 죄송하지만 참석하기 어렵겠습니다처럼 말하면 못 가요보다 훨씬 정중하고 부드러운 거절이 돼요. 그래서 겠을 볼 때는 먼저 상황을 봐야 해요. 내가 하겠다는 약속인지, 근거를 보고 추측하는지, 아니면 말을 부드럽게 만드는지 구분해야 자연스럽게 쓸 수 있어요."],translation:"겠 is not simply a future marker. When a staff member says 'I will check the order,' it sounds like a responsible promise, not just a future plan. By contrast, 'Looking at the data, the result will change' is an inference from evidence. And saying 'I'm sorry, but it will be difficult for me to attend' is a much more courteous and softened refusal than simply saying 'I can't go.' So when you see 겠, look at the situation first. Is it a promise that I will do something, an inference from evidence, or a way to soften speech?",qas:[{q:"직원이 확인하겠습니다라고 말하면 어떤 느낌이에요?",a:"책임지고 처리하겠다는 약속처럼 들려요."},{q:"자료를 보니 결과가 달라지겠네요는 어떤 겠이에요?",a:"근거를 보고 내린 추론이에요."},{q:"참석하기 어렵겠습니다는 왜 써요?",a:"거절을 정중하고 부드럽게 말하기 위해 써요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"직원이 ___에게 주문을 확인하겠습니다라고 말하면, 그냥 미래 계획이 아니라 지금 책임지고 처리하겠다는 약속처럼 들려요.",options:[{text:"회의",ok:!1},{text:"설명",ok:!1},{text:"손님",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"반대로 ___를 보니 결과가 달라지겠네요는 자료라는 근거를 보고 내린 추론이에요.",options:[{text:"회의",ok:!1},{text:"자료",ok:!0},{text:"확인하다",ok:!1}],explanation:""}],canDo:"Make a careful inference from evidence with A/V-겠네요 (바쁘겠네요)",id:"chapter-58-b9",chapterId:"chapter-58",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence is a formal service commitment?",sentence:null,options:[{text:"주문은 제가 바로 확인하겠습니다.",ok:!0},{text:"주문은 제가 바로 확인할 것 같아요.",ok:!1},{text:"주문은 제가 바로 확인했겠네요.",ok:!1}],explanation:"-겠습니다 marks a formal commitment controlled by the speaker."},{kind:"drill",prompt:"Which sentence uses 겠 for inference from evidence?",sentence:null,options:[{text:"자료를 보니 결과가 달라지겠네요.",ok:!0},{text:"자료를 보니 제가 처리하겠습니다.",ok:!1},{text:"자료를 보니 참석하기 어렵겠습니다.",ok:!1}],explanation:"The data gives evidence for the speaker's inference."},{kind:"drill",prompt:"Which sentence is the most courteous formal refusal?",sentence:null,options:[{text:"죄송하지만 오늘은 참석하기 어렵겠습니다.",ok:!0},{text:"오늘 못 가요.",ok:!1},{text:"오늘 참석 안 할 거예요.",ok:!1}],explanation:"어렵겠습니다 softens the refusal in formal speech."},{kind:"drill",prompt:"자료___ 많겠네요. (The materials must be a lot.)",sentence:null,options:[{text:"가",ok:!0},{text:"를",ok:!1},{text:"에",ok:!1}],explanation:"많다 describes the amount of 자료, so 자료 takes 가. 겠네요 gives an inference from what you see or hear."},{kind:"drill",prompt:"Which sentence uses 겠 for inference, not a promise?",sentence:null,options:[{text:"자료가 많겠네요.",ok:!0},{text:"제가 처리하겠습니다.",ok:!1},{text:"제가 참석하겠습니다.",ok:!1}],explanation:"많겠네요 is an inference from evidence. 처리하겠습니다 and 참석하겠습니다 are formal commitments."}],canDo:"Talk about a future plan with V-(으)ㄹ 거예요 (기다릴 거예요)",id:"chapter-58-b10",chapterId:"chapter-58",index:9}]},{id:"chapter-59",number:59,title:"V-았/었으면 좋겠어요 · V-았/었으면 … -았/었을 텐데요",goal:"Build counterfactual sentences from a missed past condition.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 알다~",cards:[{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"For a neutral ‘I don't know,’ Korean normally uses 모르다: 몰라요 or the softer 잘 모르겠어요. 안 알아요 is not universally wrong; context can give it ‘I don't recognize/know,’ ‘I won't find out,’ or a contrastive denial, so do not treat it as an impossible form."},sentence:{ko:"미리 알았으면 준비를 더 했을 텐데요.",en:"If I had known in advance, I would have prepared more."},target:"알았",options:["to know","to prepare","to arrive"],note:"알았으면 is one of the most common starting points for regret."},{kind:"guess",word:{ko:"미리",romanization:"miri",en:"in advance, beforehand",pos:"adverb",nuance:"미리 means doing something ahead of the relevant moment so you're ready when it arrives — its whole focus is the timing being early relative to a deadline or event. The classic English-speaker trap is confusing it with 우선 / 먼저 / 일단: 먼저 and 우선 mean 'first in a sequence or in priority' (do A before B), while 미리 means 'before the due time' (do it now so it's done early). 'I paid first' = 먼저 냈어요 (before others), but 'I paid in advance' = 미리 냈어요 (before the due date) — different ideas entirely. 미리 is native Korean, not Sino-Korean, and it glues onto preparation verbs: 미리 예약하다, 미리 준비하다, 미리 확인하다, 미리 알리다. Register is neutral and works in both polite and casual speech. Note the affectionate doubled 미리미리, which nags 'do it good and early.'"},sentence:{ko:"미리 말했더라면 문제가 커지지 않았을 거예요.",en:"If I had said it in advance, the problem would not have gotten bigger."},target:"미리",options:["in advance, beforehand","early","to know"],note:"미리 naturally pairs with 알다, 말하다, 준비하다, and 예약하다."},{kind:"guess",word:{ko:"준비하다",romanization:"junbihada",en:"to prepare",pos:"verb",nuance:"준비하다 comes from 한자 準備 (準 'standard, level' + 備 'provide, equip'), literally 'get equipped to standard' — to ready things or yourself beforehand. It naturally collocates with events and outcomes: 시험을 준비하다, 여행을 준비하다, 저녁을 준비하다, 마음의 준비. Compare 마련하다 ('arrange/procure' funds or a place — 집을 마련하다) and 챙기다 ('gather up, pack' your own belongings — 여권 챙겼어? = did you grab your passport?); 준비하다 is the broad 'prepare,' while 챙기다 zooms in on not forgetting items. The classic English-speaker pitfall is the particle: 'prepare FOR the exam' tempts 시험에 준비하다, but Korean treats the exam as a direct object — 시험을 준비하다. Also don't reach for 만들다 'make' when you only mean getting ready. As a 하다 verb, negate inside (준비 안 해요), and its passive 준비되다 ('be ready') is everywhere: 준비됐어요."},sentence:{ko:"서류를 미리 준비했더라면 접수를 놓치지 않았을 텐데요.",en:"If I had prepared the documents in advance, I would not have missed the application."},target:"준비했",options:["to know","to miss","to prepare"],note:"준비했더라면 turns a practical mistake into a counterfactual condition."},{kind:"guess",word:{ko:"시험",romanization:"siheom",en:"exam",pos:"noun",nuance:"시험 is Sino-Korean 試驗 — 試 'try/test' + 驗 'examine', literally 'a trial examination'. The collocation English speakers must memorize is 시험을 보다 — Koreans 'see' an exam, they do not 'do' it, so 시험을 하다 is wrong. Passing and failing are vivid metaphors with the particle 에: 시험에 붙다 (literally 'stick to the exam') = pass, 시험에 떨어지다 ('fall off the exam') = fail — note these take 에, not 을. Contrast 시험 with 퀴즈(quiz, a small in-class test) and with 검사(檢査, an inspection/medical test like 건강 검사): a graded school test is always 시험, never 퀴즈 unless it is a tiny informal one. The classic 직역 trap is 'take an exam' → 시험을 가지다/취하다 ✗ (English 'take' never transfers); and learners often write 시험을 통과하다, which is understandable but bookish — the everyday word is 붙다."},sentence:{ko:"조금만 일찍 도착했더라면 시험을 볼 수 있었을 거예요.",en:"If I had arrived just a little earlier, I could have taken the exam."},target:"시험",options:["exam","bus","regret"],note:"시험을 보다 is the fixed phrase for taking an exam."},{kind:"guess",word:{ko:"일찍",romanization:"iljjik",en:"early",pos:"adverb",nuance:"일찍 means 'early' in the sense of an EARLY POINT IN TIME — early hour of the day or ahead of a schedule — and is the natural opposite of 늦게(late). The classic confusion is 일찍 vs 빨리: 일찍 is about WHEN on the clock (일찍 일어나요 = 'wake up at an early hour'), while 빨리 is about SPEED/quickness (빨리 일어나요 = 'get up quick!'). So '일찍 오세요' invites someone to arrive at an early time, whereas '빨리 오세요' urges them to hurry. It pairs habitually with 자다, 일어나다, 출근하다, 도착하다, 출발하다. Register-neutral and polite-safe. The English-speaker pitfall is exactly this 일찍/빨리 mix-up, since English 'early' and 'fast/quick' feel adjacent but map to two different Korean adverbs; also remember 일찍 is an adverb already, so you never conjugate it like the adjective 이르다."},sentence:{ko:"조금만 일찍 나왔으면 버스를 놓치지 않았을 텐데요.",en:"If I had left just a little earlier, I would not have missed the bus."},target:"일찍",options:["in advance, beforehand","early","to know"],note:"조금만 일찍 is a very natural regret chunk."},{kind:"guess",word:{ko:"도착하다",romanization:"dochakada",en:"to arrive",pos:"verb",nuance:"도착하다 is Sino-Korean 到着(도착: 到 reach + 着 attach/touch down) plus 하다 — the moment of REACHING and touching a destination. Its mirror is 출발하다(depart), and the key is the particle: you arrive AT a place with 에 (호텔에 도착해요), whereas 출발하다 leaves FROM a place with 에서. Don't confuse it with 들어가다/들어오다(enter): 도착하다 is reaching the destination's threshold, not stepping inside a building. As a 하다 verb, 하 + 아 fuses to 해 (도착해요) and the short negative and inability split the noun off: 도착 안 해요, 도착 못 해요. The classic English-speaker error is copying 'arrive at' as 에서 — 'at' here is the static endpoint 에, so 공항에 도착해요, and 공항에서 도착해요 is wrong."},sentence:{ko:"제시간에 도착했더라면 면접을 볼 수 있었을 거예요.",en:"If I had arrived on time, I could have had the interview."},target:"도착했",options:["to know","to arrive","to miss"],note:"도착했더라면 is useful for exams, interviews, trains, and appointments."},{kind:"payoff",line:{speaker:"민서",ko:"어제 공지를 미리 알았으면 시험 준비를 더 했을 텐데.",en:"If I had known about the notice in advance yesterday, I would have prepared more for the exam."},hl:"알았"}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b1",chapterId:"chapter-59",index:0},{kind:"pattern",title:"문법 Grammar · V-았/었으면 좋겠어요",cards:[{kind:"hunt",name:"V-았/었으면 좋겠어요",sub:'a wish ("I wish / I hope")',lines:[{tokens:[{pre:"주말에",mid:"",post:"",hit:!1},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋",mid:"았으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"주말에 날씨가 좋았으면 좋겠어요.",en:"I hope the weather is nice this weekend.",romanization:"jumare nalssiga joasseumyeon jokesseoyo."},{tokens:[{pre:"지금",mid:"",post:"",hit:!1},{pre:"친구가",mid:"",post:"",hit:!1},{pre:"옆에",mid:"",post:"",hit:!1},{pre:"있",mid:"었으면",post:"",hit:!0},{pre:"",mid:"좋겠어요",post:".",hit:!0}],ko:"지금 친구가 옆에 있었으면 좋겠어요.",en:"I wish a friend were here beside me right now.",romanization:"jigeum chinguga yeope isseosseumyeon jokesseoyo."}],rule:{name:"V-았/었으면 좋겠어요",rows:[{when:"Stem ends in ㅏ/ㅗ",add:"-았으면 좋겠어요",ex:"오다 → 봄이 왔으면 좋겠어요 (I wish spring would come)"},{when:"Stem ends in any other vowel",add:"-었으면 좋겠어요",ex:"있다 → 시간이 있었으면 좋겠어요 (I wish I had time)"},{when:"하다 verbs/adjectives",add:"-했으면 좋겠어요",ex:"건강하다 → 건강했으면 좋겠어요 (I hope you stay healthy)"},{when:"Casual register (반말)",add:"-(았/었)으면 좋겠다",ex:"비가 그쳤으면 좋겠다 (I wish the rain would stop)"}]},more:{func:'Expresses a wish that the present situation were different, or a hope for something to come true. The past-shaped -았/었- here is NOT real past tense; it sets the wish against current reality. English renders it as "I wish..." (reality is the opposite) or "I hope..." (still possible).',funcLead:"Expresses a wish that the present situation were different, or a hope for something to come true.",keyPoint:{label:"-았/었으면 좋겠어요 vs -(으)면 좋겠어요",body:"Both mean 'I wish/hope.' The -았/었- version is by far the more common, natural choice in everyday speech and leans toward wishing reality were currently otherwise. The plain -(으)면 좋겠어요 sounds a bit more like a neutral 'it would be good if...'. When in doubt, use -았/었으면 좋겠어요."},pronunciation:"좋겠어요 is pronounced [조케써요]: the ㅎ of 좋 and the ㄱ of 겠 fuse into aspirated [ㅋ], and 겠어요 links smoothly as [게써요].",pitfall:{wrong:"시간이 있으면 원해요.",right:"시간이 있었으면 좋겠어요.",explanation:"English 'I wish' tempts learners to reach for 원하다 ('want'). Korean does not use 원하다 for wishing a situation were different. The fixed frame is -았/었으면 좋겠어요, literally 'it would be good if it had been (so).' Don't translate 'wish' as 원하다."}}},{kind:"drill",prompt:"I hope the exam isn't too hard.",sentence:"시험이 너무 어렵지 않___.",options:[{text:"았으면 좋겠어요",ok:!0},{text:"었으면 좋겠어요",ok:!1}],explanation:"Negative wish: 어렵지 않다 takes -았으면 just like any other stem."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I hope the weather is nice this weekend." (주말에 시작 · Start with 주말에.)',tokens:["주말에","날씨가","좋았으면","좋겠어요."],correct:"주말에 날씨가 좋았으면 좋겠어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I wish a friend were here beside me right now." (지금 시작 · Start with 지금.)',tokens:["지금","친구가","옆에","있었으면","좋겠어요."],correct:"지금 친구가 옆에 있었으면 좋겠어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"시간이 있었으면 좋겠어요.",ok:!0},{text:"시간이 있으면 원해요.",ok:!1}],explanation:"English 'I wish' tempts learners to reach for 원하다 ('want'). Korean does not use 원하다 for wishing a situation were different. The fixed frame is -았/었으면 좋겠어요, literally 'it would be good if it had been (so).' Don't translate 'wish' as 원하다."}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b2",chapterId:"chapter-59",index:1},{kind:"words",title:"단어 Words 2 · 놓치다~",cards:[{kind:"guess",word:{ko:"놓치다",romanization:"nochida",en:"to miss",pos:"verb",nuance:"놓치다 is for missing something you were actively trying to catch or hold — a bus, a train, a flight, a chance, or even the thread of a conversation (요점을 놓치다 = 'miss the point') — and it always takes a 을/를 object. Its make-up shows the meaning: 놓다 ('to let go/release') + 치다, so it literally pictures something slipping out of your grasp. The single biggest English-speaker pitfall is using it for missing a *person*: English 'I miss you' is NOT 놓치다 — that is 보고 싶다 ('want to see'), so 엄마가 보고 싶어요, never 엄마를 놓쳐요. Contrast 놓치다 ('fail to catch what was within reach') with 지나가다/지나치다 ('let pass / pass by'): you 놓치다 a bus you ran for, but a chance that quietly 지나가다 simply went by. It is a regular ㅣ-stem verb: 놓치 + 어 → 놓쳐요, and it frequently appears alongside 늦다 ('be late')."},sentence:{ko:"버스를 놓치지 않았더라면 늦지 않았을 텐데요.",en:"If I had not missed the bus, I would not have been late."},target:"놓치",options:["to know","to miss","to prepare"],note:"Use 놓치다 for transport, chances, deadlines, and timing."},{kind:"guess",word:{ko:"버스",romanization:"beoseu",en:"bus",pos:"noun",nuance:"버스 is useful with 타다, 기다리다, 내리다, and 로/으로 for transportation method."},sentence:{ko:"그 버스를 탔더라면 약속 시간에 맞췄을 거예요.",en:"If I had taken that bus, I would have made it on time for the appointment."},target:"버스",options:["exam","regret","bus"],note:"Transport words make counterfactuals concrete: take it, miss it, arrive late."},{kind:"guess",word:{ko:"후회하다",romanization:"huhoehada",en:"to regret",pos:"verb",nuance:"후회하다 is Sino-Korean — 後悔 literally stacks 後 'after' + 悔 'regret/remorse', i.e. the regret that comes AFTER the deed — and names the painful wish that you had chosen differently. It typically points backward (그 결정을 후회해요 'I regret that decision') and frequently pairs with a reason clause in -아서/어서 or with a past-action nominalizer -(으)ㄴ 걸: 그렇게 말한 걸 후회해. Distinguish it from 아쉽다, which is a milder 'it's a shame / I wish it were a bit different' about things often outside your control, whereas 후회하다 carries genuine self-reproach over your own past action. Also separate it from 미안하다 ('to be sorry' TO someone) — 후회하다 is regret felt inside, not an apology directed at another person. Pitfall: 'I regret to inform you' has no 후회하다 equivalent; that polite-letter formula becomes 안타깝게도 or 죄송하지만. Keep the object with 를, and remember the negative splits as 후회 안 해요."},sentence:{ko:"바로 사과했더라면 이렇게 후회하지 않았을 거예요.",en:"If I had apologized right away, I would not regret it like this."},target:"후회하",options:["to know","to regret","to prepare"],note:"후회하다 often appears in the result clause."},{kind:"guess",word:{ko:"후회",romanization:"huhoe",en:"regret",pos:"noun",nuance:"후회 is regret aimed squarely *backward* at a choice you already made, with a sting of self-blame. It is Sino-Korean 後悔 (後 'after/behind' + 悔 'to repent'), literally 'after-regret', the regret that comes *after* the deed. The verb 후회하다 is everyday, but the noun surfaces in lines like 후회예요 or 후회가 남아요, and the motto 후회 없이 (without regret) is hugely popular among 20-30s. The key synonym contrast is 후회 vs 아쉬움: 후회 blames *your own* decision ('I shouldn't have done that'), while 아쉬움 is a softer, fate-tinged 'aw, what a shame it didn't work out' with little self-blame. The English-speaker trap is mapping 'I regret it' straight to 후회해요 when you actually want the noun-predicate 후회예요 ('it's a regret'), and reaching for 후회 when the gentle 아쉬움 is what the situation calls for."},sentence:{ko:"그때 말하지 않은 게 아직도 후회예요.",en:"Not saying it back then is still a regret."},target:"후회",options:["exam","bus","regret"],note:"Noun form 후회 works when the regret itself is the topic."},{kind:"guess",word:{ko:"결과",romanization:"gyeolgwa",en:"result, outcome",pos:"noun",nuance:"결과 (結果, literally '結 form/bear + 果 fruit', i.e. the fruit that an action bears) is the end outcome of an action or event, and it almost always pairs with 나오다 (come out) or 나타나다 (appear) rather than any verb of 'making'. Its built-in partner is 과정 (the process leading up to it) and its mirror image is 원인 (the cause behind it), so Koreans constantly say 과정도 중요하고 결과도 중요하다. Register is neutral — fine in a doctor's office (검사 결과), a classroom (시험 결과), or a news report. The big English-speaker trap is twofold: first, you do not 'get' a result with a transitive verb the way English does — the result 나오다 (comes out) on its own and takes 이/가, so 결과를 나오다 is wrong; second, do not confuse the outcome 결과 with the reason 원인/이유 — 결과 is what happened at the end, never why."},sentence:{ko:"마지막까지 포기하지 않았더라면 결과가 달라졌을지도 몰라요.",en:"If I had not given up until the end, the result might have changed."},target:"결과",options:["exam","bus","result, outcome"],note:"결과가 달라지다 is the key outcome phrase."},{kind:"guess",word:{ko:"달라지다",romanization:"dallajida",en:"to change, to become different",pos:"verb",nuance:"달라지다 spotlights the before-and-after gap: something is now clearly unlike how it used to be, which makes it the everyday verb for noticing change in a person's looks, mood, or a situation. It's the inchoative of the adjective 다르다 (to be different) — 다르 + -아지다 'become' — and that origin is the #1 pitfall: 다르다 states a static difference between two things (A는 B와 달라요 = A is different from B), while 달라지다 is the dynamic act of becoming different over time (분위기가 달라졌어요 = the mood changed). It overlaps with 변하다 and 바뀌다, but the dividing line is focus: 달라지다 = 'the result looks different now,' 변하다 = 'the inner nature transformed,' 바뀌다 = 'one thing got swapped for another.' Both 달라지다 and the thing changing take 이/가; the form 달라져요 comes from -지다 verbs taking 어 in the 요-form (지+어 → 져)."},sentence:{ko:"그때 선택을 바꿨더라면 지금 상황이 달라졌을 거예요.",en:"If I had changed my choice then, the situation would be different now."},target:"달라졌",options:["to know","to change, to become different","to prepare"],note:"달라졌을 거예요 is a natural result clause for counterfactuals."},{kind:"payoff",line:{speaker:"민서",ko:"맞아. 결과가 조금은 달라졌을 것 같아.",en:"You're right. The result might have been a little different."},hl:"결과"}],canDo:"Regret a missed past with V-았/었으면 … -았/었을 텐데요 (도착했으면 … 봤을 텐데요)",id:"chapter-59-b3",chapterId:"chapter-59",index:2},{kind:"pattern",title:"문법 Grammar · V-았/었으면 … -았/었을 텐데요",cards:[{kind:"hunt",name:"V-았/었으면 … -았/었을 텐데요",sub:"a past counterfactual with regret",lines:[{tokens:[{pre:"미리",mid:"",post:"",hit:!1},{pre:"공지를",mid:"",post:"",hit:!1},{pre:"알",mid:"았으면",post:"",hit:!0},{pre:"시험",mid:"",post:"",hit:!1},{pre:"준비를",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"했",mid:"을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"미리 공지를 알았으면 시험 준비를 더 했을 텐데요.",en:"If I had known about the notice in advance, I would have prepared more for the exam.",romanization:"miri gongjireul arasseumyeon siheom junbireul deo haesseul tendeyo."},{tokens:[{pre:"조금만",mid:"",post:"",hit:!1},{pre:"더",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"일어났",mid:"으면",post:"",hit:!0},{pre:"버스를",mid:"",post:"",hit:!1},{pre:"탔",mid:"을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"조금만 더 일찍 일어났으면 버스를 탔을 텐데요.",en:"If I had gotten up just a little earlier, I would have caught the bus.",romanization:"jogeumman deo iljjik ireonasseumyeon beoseureul tasseul tendeyo."}],rule:{name:"V-았/었으면 … -았/었을 텐데요",rows:[{when:"Condition: stem + 았/었 + 으면",add:"-았/었으면",ex:"알다 → 알았으면 (if I had known)"},{when:"Result: stem + 았/었 + 을 텐데요",add:"-았/었을 텐데요",ex:"가다 → 갔을 텐데요 (I would have gone)"},{when:"하다 verbs",add:"-했으면 / -했을 텐데요",ex:"공부했으면 합격했을 텐데요 (if I'd studied, I'd have passed)"},{when:"Whole frame",add:"A-았/었으면 B-았/었을 텐데요",ex:"일찍 출발했으면 안 늦었을 텐데요 (if I'd left early, I wouldn't have been late)"}]},more:{func:"States a counterfactual about the past: a condition that did NOT happen, and the result that therefore did NOT happen. -았/었으면 marks the unreal past condition; the result clause stays hypothetical with -았/었을 텐데요 ('would have...'). The 텐데 ending softens it into a wistful 'but it wasn't so.'",funcLead:"States a counterfactual about the past: a condition that did NOT happen, and the result that therefore did NOT happen.",keyPoint:{label:"Keep the result clause hypothetical",body:"Whichever condition you use, the result must also be marked unreal: -았/었을 텐데요, -았/었을 거예요, or -았/었을지도 몰라요 ('might have'). Never finish a past counterfactual with a plain past or present verb — that cancels the 'would have' meaning. 텐데요 adds the softest, most wistful tone of the three."},pronunciation:"텐데요 is [텐데요], no special change. Note 갔을 텐데요 → [가쓸 텐데요]: 갔 closes as [갇] and links into 을 as [가쓸].",pitfall:{wrong:"알았으면 전화해요.",right:"알았으면 전화했을 텐데요.",explanation:"Learners set up the 'if had' clause correctly but then drop into a plain present/future result ('I call' / 'I will call'). In Korean the result of a past counterfactual must itself be marked unreal: -았/었을 텐데요. A plain result clause cancels the 'would have' meaning."}}},{kind:"drill",prompt:"If I had taken an umbrella, I wouldn't have gotten rained on.",sentence:"우산을 가져갔___ 비를 안 맞았을 텐데요.",options:[{text:"좋겠어요",ok:!1},{text:"었더라면",ok:!1},{text:"으면",ok:!0}],explanation:"가져갔으면 strongly implies the speaker did NOT take one."},{kind:"drill",prompt:"If I had apologized right then, the relationship wouldn't have gone bad.",sentence:"그때 바로 사과했___ 사이가 안 나빠졌을 텐데요.",options:[{text:"좋겠어요",ok:!1},{text:"으면",ok:!0},{text:"었더라면",ok:!1}],explanation:"사과하다 fits the regret vocabulary of the chapter; 달라지다/나빠지다 carry the changed outcome."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"알았으면 전화했을 텐데요.",ok:!0},{text:"알았으면 전화해요.",ok:!1}],explanation:"Learners set up the 'if had' clause correctly but then drop into a plain present/future result ('I call' / 'I will call'). In Korean the result of a past counterfactual must itself be marked unreal: -았/었을 텐데요. A plain result clause cancels the 'would have' meaning."}],canDo:"Regret a missed past with V-았/었으면 … -았/었을 텐데요 (도착했으면 … 봤을 텐데요)",id:"chapter-59-b4",chapterId:"chapter-59",index:3},{kind:"words",title:"단어 Words 3 · 기회~",cards:[{kind:"guess",word:{ko:"기회",romanization:"gihoe",en:"chance, opportunity",pos:"noun",nuance:"기회 (機會, 機 'opportune moment/device' + 會 'meeting') is a window of opportunity that may not come twice, so it carries a faint pressure to act. The key contrast is 기회 vs 기능: 기회 is a chance to do something, while 기능 is a 'function/feature.' Koreans treat 기회 as something you physically handle — 기회를 잡다 (seize), 기회를 놓치다 (miss), 기회를 주다/얻다 (give/get) — so the partner verb is concrete, never 기회를 하다. With existence it is 기회가 있다/없다, and 기회가 되면 is a gentle, non-committal 'if the chance comes up.' The English-speaker trap is twofold: don't say 기회를 하다 by mapping 'take a chance' word-for-word, and don't mark existence with 를 (기회를 있다 ✗ → 기회가 있다 ✓). Register is neutral, fine in both polite speech and writing."},sentence:{ko:"그 기회를 잡았더라면 다른 회사에 갔을지도 몰라요.",en:"If I had taken that opportunity, I might have gone to a different company."},target:"기회",options:["chance, opportunity","exam","bus"],note:"기회를 잡다 and 기회를 놓치다 are both useful in hindsight."},{kind:"guess",word:{ko:"말하다",romanization:"malhada",en:"to say, to speak",pos:"verb",nuance:"Use 로 for language: 한국어로 말해요, 영어로 말해요. 말하다 can mean both “speak” and “say,” so the object or quote decides the English translation."},sentence:{ko:"그때 솔직하게 말했더라면 오해가 풀렸을 거예요.",en:"If I had spoken honestly then, the misunderstanding would have cleared up."},target:"말했",options:["to know","to say, to speak","to prepare"],note:"말하다 becomes powerful in regret scenes because one sentence could have changed the relationship."},{kind:"guess",word:{ko:"사과하다",romanization:"sagwahada",en:"to apologize",pos:"verb",nuance:"사과하다 is 謝過(사과)하다, hanja 謝 'express thanks/apology' + 過 'fault/error', so it literally means to 'acknowledge one's fault' — you take responsibility for a mistake to the person you wronged, who is marked with 에게/한테 or honorific 께. The boundary against 미안하다 and 변명하다 is essential: 미안하다 is the adjective/feeling 'to be sorry' (an emotional state — 미안해요), while 사과하다 is the ACT of formally apologizing (you can 사과하다 even publicly or in writing); and 변명하다 is the opposite move, to 'make excuses.' So you might 사과하다 instead of merely feeling 미안하다. The cause of the apology attaches with -아서: 늦어서 사과했어요. A notorious trap is the homograph: 사과 also means 'apple' (native-Korean noun), so context disambiguates 사과를 했어요 'apologized' from 사과를 먹었어요 'ate an apple' — they share spelling but are unrelated words. English speakers also wrongly say '~에 대해 미안해요' as if 'sorry' were a verb taking objects; to apologize FOR something, use 사과하다 with -아서 or -에 대해. Regular 하다 verb: 사과 + 해요, negative 사과 안 해요."},sentence:{ko:"먼저 사과했더라면 아직 어색하지 않았을 텐데요.",en:"If I had apologized first, it would not still be awkward."},target:"사과했",options:["to know","to apologize","to prepare"],note:"사과했더라면 fits relationship repair after the fact."},{kind:"guess",word:{ko:"그때",romanization:"geuttae",en:"that time, back then",pos:"noun",nuance:"그때 is the demonstrative 그 ('that', the listener-known one) fused with 때 ('time, occasion'), so it points at a specific moment both speakers can already identify — looking back ('back then') or to a plan just arranged ('see you then'). Write it solid as 그때; the spaced 그 때 is non-standard. Mind the demonstrative trio that mirrors 이/그/저: 이때 = this moment / now in the flow of events, 그때 = that known moment, and the question 언제 = 'when?'. The key English-speaker pitfall is the 'that' default: because English freely says 'that time' for brand-new information, learners reach for 그때 even when the listener has no idea which moment is meant. But 그때 presupposes shared knowledge — if the time is new to your listener you must first establish it (give the date or event), and only then can 그때 refer back to it."},sentence:{ko:"그때 멈췄더라면 일이 이렇게 커지지 않았을 거예요.",en:"If I had stopped back then, this would not have gotten this big."},target:"그때",options:["exam","that time, back then","bus"],note:"그때 anchors the regret in a specific past moment."},{kind:"guess",word:{ko:"포기하다",romanization:"pogihada",en:"to give up",pos:"verb",nuance:"포기하다 = to give up, abandon, or relinquish a goal, plan, claim, or even a person. The hanja 抛棄 is vivid: 抛 'to throw/hurl away' + 棄 'to discard, abandon', so the image is hurling something aside and walking off — a decisive letting-go, not a gentle fade. Contrast 포기하다 (stop pursuing a goal entirely) with 그만두다 (stop/quit an ongoing activity — a job, a habit) and with 단념하다 (a more bookish 'resign oneself to abandoning hope'); in speech 포기하다 is the everyday choice. Grammar: it pairs with 을/를 (목표를 포기하다) or with 는 거 / 는 걸 (사는 걸 포기하다 = 'give up on buying'). Culturally the word is loaded: N포세대, the 'give-up generation', names young Koreans said to have surrendered dating, marriage, and kids to economic pressure. English-speaker pitfall: the negative is 포기 안 해 / 포기 못 해 (noun + 안/못 + 해), NOT 안 포기해."},sentence:{ko:"포기하지 않았더라면 합격했을지도 몰라요.",en:"If I had not given up, I might have passed."},target:"포기하",options:["to know","to prepare","to give up"],note:"포기하지 않았더라면 is a high-frequency negative counterfactual."},{kind:"guess",word:{ko:"합격하다",romanization:"hapgyeokada",en:"to pass an exam",pos:"verb",nuance:"합격하다 is Sino-Korean 合格 — 合 'meet/match' + 格 'standard' — literally 'meet the standard', i.e. clear a cut-off and pass a test, interview, or admissions screen. Its opposite is 불합격하다 (不合格) or, much more colloquially, 떨어지다 'to fall/drop' (시험에 떨어졌어요 = I failed/flunked). Don't confuse 합격하다 with 통과하다 'to pass through': 통과하다 is moving past a checkpoint or a bill passing, while 합격하다 specifically means meeting a qualifying standard. The headline English-speaker pitfall is the particle: English 'pass THE exam' (object) makes learners write 시험을 합격하다, but Korean uses 에 — 시험에 합격하다 — because you're 'matching up TO the standard'. Note also 합격하다 (verb) vs 합격 (the noun, 'a pass/acceptance'): the noun is what you put on banners — 합격 축하해! As a noun+하다 verb it conjugates on 하다 (합격해요, 합격했어요, formal 합격합니다); negative/impossible split the noun (합격 안 해요, 합격 못 해요)."},sentence:{ko:"마지막 문제를 풀었더라면 합격했을 거예요.",en:"If I had solved the last question, I would have passed."},target:"합격했",options:["to know","to pass an exam","to prepare"],note:"합격하다 belongs naturally in exam-regret counterfactuals."},{kind:"payoff",line:{speaker:"지훈",ko:"그래도 포기하지 않았더라면 마지막 문제는 풀 수 있었을지도 몰라.",en:"Still, if you had not given up, you might have been able to solve the last question."},hl:"포기하"}],canDo:"State a reflective counterfactual with V-았/었더라면 … -았/었을 거예요 (준비했더라면 … 놓치지 않았을 거예요)",id:"chapter-59-b5",chapterId:"chapter-59",index:4},{kind:"pattern",title:"문법 Grammar · V-았/었더라면 … -았/었을 거예요",cards:[{kind:"hunt",name:"V-았/었더라면 … -았/었을 거예요",sub:"a stronger, more reflective counterfactual",lines:[{tokens:[{pre:"조금만",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"도착했",mid:"더라면",post:"",hit:!0},{pre:"시험을",mid:"",post:"",hit:!1},{pre:"볼",mid:"",post:"",hit:!1},{pre:"수",mid:"",post:"",hit:!1},{pre:"있",mid:"었을",post:"",hit:!0},{pre:"",mid:"거예요",post:".",hit:!0}],ko:"조금만 일찍 도착했더라면 시험을 볼 수 있었을 거예요.",en:"If I had arrived just a little earlier, I could have taken the exam.",romanization:"jogeumman iljjik dochakaetdeoramyeon siheomeul bol su isseosseul geoyeyo."},{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"소식을",mid:"",post:"",hit:!1},{pre:"들",mid:"었더라면",post:"",hit:!0},{pre:"바로",mid:"",post:"",hit:!1},{pre:"전화했",mid:"을",post:"",hit:!0},{pre:"",mid:"거예요",post:".",hit:!0}],ko:"그 소식을 들었더라면 바로 전화했을 거예요.",en:"If I had heard the news, I would have called right away.",romanization:"geu sosigeul deureotdeoramyeon baro jeonhwahaesseul geoyeyo."}],rule:{name:"V-았/었더라면 … -았/었을 거예요",rows:[{when:"Condition: stem + 았/었 + 더라면",add:"-았/었더라면",ex:"도착하다 → 도착했더라면 (if I had arrived)"},{when:"Result: stem + 았/었 + 을 거예요",add:"-았/었을 거예요",ex:"보다 → 봤을 거예요 (I would have seen it)"},{when:"하다 verbs",add:"-했더라면",ex:"공부했더라면 (if I had studied)"},{when:"Whole frame",add:"A-았/었더라면 B-았/었을 거예요",ex:"조금만 일찍 도착했더라면 시험을 봤을 거예요 (if I'd arrived a bit earlier, I'd have taken the exam)"}]},more:{func:"Replays a missed past from a reflective distance: 'if (only) it had happened, the result would have...'. -았/었더라면 marks the unreal past condition with a heavier, more regretful tone than -았/었으면; the result stays hypothetical with -았/었을 거예요 ('would have').",funcLead:"Replays a missed past from a reflective distance: 'if (only) it had happened, the result would have...'.",keyPoint:{label:"-았/었더라면 vs -았/었으면",body:"Both open a past counterfactual, but -았/었더라면 is heavier and more clearly regretful — it almost always implies 'and that's a shame, because it didn't happen.' -았/었으면 is more neutral and far more common in casual speech. In friendly chat 더라면 can sound dramatic, so friends often just use -았/었으면. The result clause stays hypothetical either way."},pronunciation:"봤더라면 → [봗떠라면]: the ㅆ of 봤 closes to [ㄷ] before a consonant, and ㄷ of 더 tenses to [떠]. 들었더라면 → [드럳떠라면] follows the same tensing.",pitfall:{wrong:"알았으면더라면 전화했을 거예요.",right:"알았더라면 전화했을 거예요.",explanation:"Learners sometimes try to stack -으면 and -더라면 together. They are two different conditional endings and cannot combine. Use one or the other directly on the past stem: 알았으면 OR 알았더라면, never 알았으면더라면."}}},{kind:"drill",prompt:"If I had looked at the map in advance, I wouldn't have gotten lost.",sentence:"지도를 미리 봤___ 길을 안 잃었을 거예요.",options:[{text:"좋겠어요",ok:!1},{text:"더라면",ok:!0},{text:"었으면",ok:!1}],explanation:"봤더라면 = the look-up that never happened; 안 잃었을 거예요 = the avoided result."},{kind:"drill",prompt:"If I had apologized then, the outcome would have been different.",sentence:"그때 사과했___ 결과가 달라졌을 거예요.",options:[{text:"좋겠어요",ok:!1},{text:"더라면",ok:!0},{text:"었으면",ok:!1}],explanation:"사과하다, 결과, 달라지다 are all the chapter's target regret words."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "If I had heard the news, I would have called right away."',tokens:["그","소식을","들었더라면","바로","전화했을","거예요."],correct:"그 소식을 들었더라면 바로 전화했을 거예요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"알았더라면 전화했을 거예요.",ok:!0},{text:"알았으면더라면 전화했을 거예요.",ok:!1}],explanation:"Learners sometimes try to stack -으면 and -더라면 together. They are two different conditional endings and cannot combine. Use one or the other directly on the past stem: 알았으면 OR 알았더라면, never 알았으면더라면."}],canDo:"State a reflective counterfactual with V-았/었더라면 … -았/었을 거예요 (준비했더라면 … 놓치지 않았을 거예요)",id:"chapter-59-b6",chapterId:"chapter-59",index:5},{kind:"pattern",title:"문법 Grammar · V-지 않았더라면",cards:[{kind:"hunt",name:"V-지 않았더라면",sub:`a negative counterfactual ("if … hadn't …")`,lines:[{tokens:[{pre:"버스를",mid:"",post:"",hit:!1},{pre:"놓치",mid:"지",post:"",hit:!0},{pre:"",mid:"않았더라면",post:"",hit:!0},{pre:"면접에",mid:"",post:"",hit:!1},{pre:"늦지",mid:"",post:"",hit:!1},{pre:"않았을",mid:"",post:"",hit:!1},{pre:"텐데요.",mid:"",post:"",hit:!1}],ko:"버스를 놓치지 않았더라면 면접에 늦지 않았을 텐데요.",en:"If I hadn't missed the bus, I wouldn't have been late for the interview.",romanization:"beoseureul nochiji anatdeoramyeon myeonjeobe neutji anasseul tendeyo."},{tokens:[{pre:"포기하",mid:"지",post:"",hit:!0},{pre:"",mid:"않았더라면",post:"",hit:!0},{pre:"합격했을지도",mid:"",post:"",hit:!1},{pre:"몰라요.",mid:"",post:"",hit:!1}],ko:"포기하지 않았더라면 합격했을지도 몰라요.",en:"If I hadn't given up, I might have passed.",romanization:"pogihaji anatdeoramyeon hapgyeokaesseuljido mollayo."}],rule:{name:"V-지 않았더라면",rows:[{when:"Long negation (standard)",add:"V-지 않았더라면",ex:"놓치다 → 놓치지 않았더라면 (if I hadn't missed it)"},{when:"Short negation 안",add:"안 + V-았/었더라면",ex:"안 갔더라면 (if I hadn't gone)"},{when:"Inability 못",add:"못 + V-았/었더라면",ex:"못 봤더라면 (if I hadn't been able to see it)"},{when:"Result clause",add:"-았/었을 거예요 / -았/었을 텐데요",ex:"포기하지 않았더라면 합격했을지도 몰라요 (if I hadn't given up, I might have passed)"}]},more:{func:"Forms the negative side of a past counterfactual: 'if (something) had NOT happened.' Because the event DID happen, a certain (often bad) result followed — and you imagine the opposite past. It pairs with a hypothetical result clause.",funcLead:"Forms the negative side of a past counterfactual: 'if (something) had NOT happened.' Because the event DID happen, a certain (often bad) result followed — and…",keyPoint:{label:"-지 않았더라면 vs -았/었더라면",body:"Use affirmative -았/었더라면 to imagine an action you wish HAD happened ('if I had studied'). Use -지 않았더라면 to imagine an action you wish had NOT happened ('if I hadn't missed it'). The result clause works identically for both; only the polarity of the condition changes."},pronunciation:"않았더라면 → [아낟떠라면]: the ㅎ of 않 is silent so 않았 reads [아낟] (the ㅆ closing to [ㄷ] before 더), and 더 tenses to [떠].",pitfall:{wrong:"안 비가 왔더라면 소풍을 갔을 거예요.",right:"비가 오지 않았더라면 소풍을 갔을 거예요.",explanation:"Learners often put 안 before the noun (안 비가). With this frame, the clean choice is long negation V-지 않았더라면. If you do use short 안, it goes directly before the verb (비가 안 왔더라면), never before the subject noun."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "If I hadn't given up, I might have passed."`,tokens:["포기하지","않았더라면","합격했을지도","몰라요."],correct:"포기하지 않았더라면 합격했을지도 몰라요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"안 비가 왔더라면 소풍을 갔을 거예요.",ok:!1},{text:"비가 오지 않았더라면 소풍을 갔을 거예요.",ok:!0}],explanation:"Learners often put 안 before the noun (안 비가). With this frame, the clean choice is long negation V-지 않았더라면. If you do use short 안, it goes directly before the verb (비가 안 왔더라면), never before the subject noun."}],canDo:"Tell an open condition (-(으)면) from a missed one (-았/었으면)",id:"chapter-59-b7",chapterId:"chapter-59",index:6},{kind:"pattern",title:"문법 Grammar · -(으)면 vs -았/었으면",cards:[{kind:"hunt",name:"-(으)면 vs -았/었으면",sub:"open condition vs missed condition",lines:[{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있",mid:"으면",post:"",hit:!0},{pre:"같이",mid:"",post:"",hit:!1},{pre:"확인해요.",mid:"",post:"",hit:!1}],ko:"시간이 있으면 같이 확인해요.",en:"If you have time, let's check it together.",romanization:"sigani isseumyeon gachi hwaginhaeyo."},{tokens:[{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있",mid:"었으면",post:"",hit:!0},{pre:"같이",mid:"",post:"",hit:!1},{pre:"확인했을",mid:"",post:"",hit:!1},{pre:"텐데요.",mid:"",post:"",hit:!1}],ko:"시간이 있었으면 같이 확인했을 텐데요.",en:"If there had been time, we would have checked it together.",romanization:"sigani isseosseumyeon gachi hwaginhaesseul tendeyo."}],rule:{name:"-(으)면 vs -았/었으면",rows:[{when:"Open if/when condition",add:"V-(으)면",ex:"시간이 있으면 같이 확인해요 (if you have time, let's check together)"},{when:"Missed/unreal past condition",add:"V-았/었으면",ex:"시간이 있었으면 같이 확인했을 텐데요 (if there had been time, we'd have checked)"},{when:"하다 verbs",add:"-하면 / -했으면",ex:"준비하면 덜 불안해요 / 준비했으면 안 늦었을 텐데요"},{when:"Reusable rule (always V-(으)면)",add:"V-(으)면",ex:"미리 준비하면 덜 불안해요 (if you prepare ahead, you feel less anxious)"}]},more:{func:"Distinguishes a real, still-open condition from an unreal, already-missed one. Plain V-(으)면 leaves the door open ('if/when you have time'). Past-shaped V-았/었으면 usually looks backward at a condition that did NOT happen, setting up a counterfactual result.",funcLead:"Distinguishes a real, still-open condition from an unreal, already-missed one.",keyPoint:{label:"Let context and the result decide the reading",body:"The past form alone doesn't always mean counterfactual — context and the result clause decide. A simple test: can the condition still happen? If yes, plain V-(으)면 with a real result is usually enough. If it's already too late, use V-았/었으면 and keep the result unreal (-았/었을 텐데요 / -았/었을 거예요)."},pronunciation:"있었으면 → [이써쓰면]: 있 closes as [읻] then links into 었 as [이써], and 었으면 connects as [쓰면]. 있으면 (open) stays lighter as [이쓰면].",pitfall:{wrong:"어제 시간이 있으면 같이 봤을 거예요.",right:"어제 시간이 있었으면 같이 봤을 거예요.",explanation:"For a clearly past, missed condition (어제 'yesterday'), the plain present -(으)면 clashes with the past result 봤을 거예요. Match the condition to the timeframe: a missed past needs -았/었으면, not plain -(으)면."}}},{kind:"drill",prompt:"If you prepare in advance, you feel less anxious.",sentence:"미리 준비하___ 덜 불안해요.",options:[{text:"좋겠어요",ok:!1},{text:"텐데요",ok:!1},{text:"면",ok:!0}],explanation:"A reusable rule, so plain V-(으)면 is correct — not counterfactual."},{kind:"drill",prompt:"If I had known in advance then, I wouldn't have missed it.",sentence:"그때 미리 알___ 놓치지 않았을 거예요.",options:[{text:"었으면",ok:!1},{text:"좋겠어요",ok:!1},{text:"았으면",ok:!0}],explanation:"그때 plus the unreal result shows this is a missed past, not an open rule."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "If you have time, let's check it together." (시간이 시작 · Start with 시간이.)`,tokens:["시간이","있으면","같이","확인해요."],correct:"시간이 있으면 같이 확인해요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "If there had been time, we would have checked it together." (시간이 시작 · Start with 시간이.)',tokens:["시간이","있었으면","같이","확인했을","텐데요."],correct:"시간이 있었으면 같이 확인했을 텐데요.",explanation:""}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b8",chapterId:"chapter-59",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends compare three regrets after a hard week: a missed notice, a missed bus, and a message that should have been sent sooner.",lines:[{speaker:"민서",ko:"어제 공지를 미리 알았으면 시험 준비를 더 했을 텐데.",en:"If I had known about the notice in advance yesterday, I would have prepared more for the exam.",romanization:"eoje gongjireul miri arasseumyeon siheom junbireul deo haesseul tende."},{speaker:"지훈",ko:"그래도 포기하지 않았더라면 마지막 문제는 풀 수 있었을지도 몰라.",en:"Still, if you had not given up, you might have been able to solve the last question.",romanization:"geuraedo pogihaji anatdeoramyeon majimak munjeneun pul su isseosseuljido molla."},{speaker:"민서",ko:"맞아. 결과가 조금은 달라졌을 것 같아.",en:"You're right. The result might have been a little different.",romanization:"maja. gyeolgwaga jogeumeun dallajyeosseul geot gata."},{speaker:"지훈",ko:"나는 버스를 놓치지 않았더라면 면접에 늦지 않았을 텐데.",en:"If I had not missed the bus, I would not have been late for the interview.",romanization:"naneun beoseureul notchiji anatdeoramyeon myeonjeobe neutji anatseul tende."},{speaker:"민서",ko:"그때 다른 길로 갔으면 도착 시간이 달라졌을지도 몰라.",en:"If you had taken a different route then, the arrival time might have changed.",romanization:"geuttae dareun gillo gasseumyeon dochak sigani dallajyeosseuljido molla."},{speaker:"지훈",ko:"그리고 친구한테 바로 사과했더라면 아직 이렇게 어색하지는 않았을 거야.",en:"And if I had apologized to my friend right away, it probably would not still be this awkward.",romanization:"geurigo chinguhante baro sagwahaetdeoramyeon ajik ireoke eosaekajineun anatseul geoya."}]},{kind:"order",prompt:"Build: 'If I had known in advance, I would have prepared.'",tokens:["미리 알았더라면","준비했을 거예요"],correct:"미리 알았더라면 준비했을 거예요",explanation:"The condition is a missed past condition, so 알았더라면 fits. The result stays hypothetical with 했을 거예요."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"그리고 친구한테 바로 사과했더라면 아직 이렇게 어색하지는 않았을 거야.",options:[{text:"민서",ok:!1},{text:"지훈",ok:!0}],explanation:"And if I had apologized to my friend right away, it probably would not still be this awkward."},{kind:"drill",prompt:'무엇이 들어갈까요? · "If I had known about the notice in advance yesterday, I would have prepared more for the exam."',sentence:"어제 공지를 ___ 알았으면 시험 준비를 더 했을 텐데.",options:[{text:"일찍",ok:!1},{text:"알다",ok:!1},{text:"미리",ok:!0}],explanation:""}],canDo:"Express a wish that things were different with V-았/었으면 좋겠어요 (일찍 일어났으면 좋겠어요)",id:"chapter-59-b9",chapterId:"chapter-59",index:8},{kind:"reading",title:"읽기 Reading · 그때 알았더라면",cards:[{kind:"read",title:"그때 알았더라면",chunks:["민서는 시험 전날 공지가 바뀐 것을 늦게 알았다. 미리 알았으면 자료를 다시 확인했을 텐데, 그대로 시험장에 갔다. 지훈은 면접 날 버스를 놓쳤다. 조금만 일찍 나왔더라면 제시간에 도착했을 거라고 생각했다.",'두 사람은 나중에 서로의 이야기를 듣고 같은 말을 했다. "그때 바로 알았더라면 결과가 달라졌을지도 몰라." 하지만 마지막에는 후회만 반복하지 않기로 했다. 다음에는 중요한 공지를 미리 확인하고, 늦을 것 같으면 바로 연락하고, 마음에 걸리는 말은 빨리 사과하기로 했다.'],translation:`Minseo found out late that the notice had changed before the exam. If she had known in advance, she would have checked the materials again, but she went to the exam room as she was. Jihoon missed the bus on interview day. He thought that if he had left a little earlier, he would have arrived on time. Later, after hearing each other's stories, they said the same thing: "If we had known right away back then, the result might have changed." In the end, they decided not to repeat only regret. Next time they would check important notices in advance, contact people right away if they might be late, and apologize quickly for words that bothered them.`,qas:[{q:"민서는 무엇을 늦게 알았어요?",a:"시험 전날 공지가 바뀐 것을 늦게 알았어요."},{q:"지훈은 왜 면접에 늦을 뻔했어요?",a:"버스를 놓쳤기 때문이에요."},{q:"두 사람은 다음에 무엇을 하기로 했어요?",a:"중요한 공지를 미리 확인하고, 늦을 것 같으면 바로 연락하고, 마음에 걸리는 말은 빨리 사과하기로 했어요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"민서는 ___ 전날 공지가 바뀐 것을 늦게 알았다.",options:[{text:"기회",ok:!1},{text:"시험",ok:!0},{text:"알다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___ 알았으면 자료를 다시 확인했을 텐데, 그대로 시험장에 갔다.",options:[{text:"알다",ok:!1},{text:"준비하다",ok:!1},{text:"미리",ok:!0}],explanation:""}],canDo:"Regret a missed past with V-았/었으면 … -았/었을 텐데요 (도착했으면 … 봤을 텐데요)",id:"chapter-59-b10",chapterId:"chapter-59",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence correctly expresses regret about not knowing earlier?",sentence:null,options:[{text:"미리 알았으면 준비했을 텐데요.",ok:!0},{text:"미리 알면 준비했어요.",ok:!1},{text:"미리 알기로 준비했어요.",ok:!1}],explanation:"The condition is missed in the past, and the result is also hypothetical with -했을 텐데요."},{kind:"drill",prompt:"Choose the correct negative counterfactual.",sentence:null,options:[{text:"놓치지 않았더라면 늦지 않았을 거예요.",ok:!0},{text:"놓치지 않으면더라면 늦지 않았어요.",ok:!1},{text:"놓치지 않았으면 늦지 않아요.",ok:!1}],explanation:"The negative must be inside the past condition: -지 않았더라면."},{kind:"drill",prompt:"Which result clause stays hypothetical?",sentence:null,options:[{text:"결과가 달라졌을지도 몰라요.",ok:!0},{text:"결과가 달라져요.",ok:!1},{text:"결과가 달라지고 있어요.",ok:!1}],explanation:"-았/었을지도 몰라요 marks an imagined different result."},{kind:"drill",prompt:"버스___ 놓쳤더라면 늦었을 거예요. (If I had missed the bus...)",sentence:null,options:[{text:"를",ok:!0},{text:"가",ok:!1},{text:"에",ok:!1}],explanation:"놓치다 takes the thing missed as an object, so 버스를 fits. The counterfactual ending shows this did not actually happen."},{kind:"drill",prompt:"Which condition is clearly about a missed past chance?",sentence:null,options:[{text:"일찍 도착했더라면 만났을 거예요.",ok:!0},{text:"일찍 도착하면 만나요.",ok:!1},{text:"일찍 도착해서 만났어요.",ok:!1}],explanation:"-았/었더라면 points to a past condition that did not happen. The other choices are open condition or real past result."}],canDo:"State a reflective counterfactual with V-았/었더라면 … -았/었을 거예요 (준비했더라면 … 놓치지 않았을 거예요)",id:"chapter-59-b11",chapterId:"chapter-59",index:10}]},{id:"chapter-60",number:60,title:"V-기 · V-는 것/거",goal:"Choose -기 for activity labels, goals, and fixed frames such as 기로 했어요, 기 전에, 기 위해, and 기 시작하다.",biteCount:12,bites:[{kind:"words",title:"단어 Words 1 · 운동하다~",cards:[{kind:"guess",word:{ko:"운동하다",romanization:"undonghada",en:"to exercise",pos:"verb",nuance:"운동하다 = 한자 運動 (運 'move, transport' + 動 'move') + 하다, literally 'movement-movement,' i.e. to physically exercise. The same noun 운동 also means a sports movement or a social campaign, but with 하다 it's working out. A key feature for learners: Korean builds most sports the same way — noun + 하다 (축구하다 play soccer, 수영하다 swim), though racket sports take 치다 'hit' instead (테니스 치다). The contrast with 놀다 ('play, hang out, have fun') matters: 놀다 is unstructured fun, 운동하다 is purposeful physical activity, so don't say 놀다 when you mean training. Natural collocations: 헬스장에서 운동하다, 건강을 위해 운동하다, 운동 부족. As a 하다 verb the negatives split — 운동 안 해요, 운동 못 해요 — and you can swap in 운동을 안 하다 with the object marker for a touch more emphasis."},sentence:{ko:"운동하기는 어렵지만 건강에 좋아요.",en:"Exercising is hard, but it is good for your health."},target:"운동하",options:["to exercise","to walk","to memorize"],note:"Use -기 when 운동하다 becomes an activity label."},{kind:"guess",word:{ko:"운동",romanization:"undong",en:"exercise",pos:"noun",nuance:"운동 is Sino-Korean, 運動 ('move-motion'), and is the umbrella word for physical exercise; it normally appears as 운동하다 (운동을 해요). Crucially it is NOT counted or pluralized like English 'a workout' — you don't say 운동들 for several sessions; you say 운동을 자주 해요. The nearest relative is 스포츠 (a borrowed word for organized sports as a category, e.g. watching 스포츠 on TV), whereas 운동 is the act of exercising your own body, so '운동선수' = athlete but '스포츠 경기' = a sports match. The very same 運動 also means a social 'movement/campaign' (민주화 운동 the democracy movement), so context decides. The English-speaker pitfall is reaching for 만들다 ('make') by analogy with 'make exercise' — Korean uses the light verb 하다; and remember the desire ending goes on the verb (운동하고 싶어요), never on the bare noun."},sentence:{ko:"운동을 시작하기 전에 목표를 정했어요.",en:"Before starting exercise, I set a goal."},target:"운동",options:["study, studying","exercise","habit"],note:"운동 is already a noun, so it can take 을 before 시작하다."},{kind:"guess",word:{ko:"공부하다",romanization:"gongbuhada",en:"to study",pos:"verb",nuance:"공부하다 is noun + 하다, so the short negative is often 공부 안 해요."},sentence:{ko:"공부하기 전에 오늘 목표를 먼저 써요.",en:"Before studying, I write today's goal first."},target:"공부하",options:["to study","to exercise","to walk"],note:"기 전에 is the natural before-doing frame."},{kind:"guess",word:{ko:"공부",romanization:"gongbu",en:"study, studying",pos:"noun",nuance:"공부(工夫)는 한자 그대로 '공을 들여 애씀'이라는 뜻으로, 지식이나 기술을 배우고 익히는 모든 활동을 가리키는 가장 기본적인 단어예요. 비슷한 말 '학습'은 교과서나 보고서에 어울리는 딱딱한 한자어라 일상 대화에서는 거의 안 쓰고, '연습'은 이미 배운 것을 몸에 익히려 반복하는 것이라 '머리로 새로 익히는' 공부와는 결이 달라요. 영어 study처럼 목적어를 바로 붙여 '공부 Korean'이라고 하면 안 되고, 반드시 '한국어를 공부하다'처럼 -을/를을 쓰거나 '한국어 공부를 하다'로 명사화해야 해요. 동사로 쓸 때 '공부를 하다'와 한 단어 '공부하다'가 둘 다 자연스럽고, '열심히/같이/매일'과 잘 어울려요."},sentence:{ko:"공부를 시작하기 전에 책상을 정리해요.",en:"Before starting my studying, I clear my desk."},target:"공부",options:["exercise","habit","study, studying"],note:"공부 is a noun; 공부를 시작하다 is different from 공부하기 시작하다 but both are useful."},{kind:"guess",word:{ko:"걷다",romanization:"geotda",en:"to walk",pos:"verb",nuance:"걷다 means to walk on foot and is a ㄷ irregular verb: before a vowel ending the final ㄷ softens to ㄹ, so the 요-form is 걸어요 (not 걷어요) and the past is 걸었어요. Before a consonant ending the ㄷ stays put, so the formal form remains 걷습니다 and you say 걷지 마세요, 걷고 싶어요. The nearest relative is 산책하다 ('take a stroll'): 걷다 is the raw act of walking anywhere, while 산책하다 implies a leisurely walk for pleasure, so 'I walk to work' is 걸어서 출근해요, never 산책해서 출근해요. The trap for English speakers is that 걷다 doesn't take an object the way 'walk the dog' does — Korean uses 산책시키다 for that, and the path you walk takes 을/를 (공원을 걸어요), so don't reach for 에. Also remember 걸어서 ('on foot') is one fixed chunk for describing how you travel."},sentence:{ko:"저는 먼저 걷기부터 시작하기로 했어요.",en:"I decided to start with walking first."},target:"걷기",options:["to walk","to exercise","to study"],note:"걷기 names the activity; 시작하기로 했어요 reports the decision."},{kind:"guess",word:{ko:"듣다",romanization:"deutda",en:"to listen",pos:"verb",nuance:"듣다 is ㄷ irregular: 듣다 becomes 들어요 in polite speech."},sentence:{ko:"예문을 듣는 게 단어 외우기에 도움이 돼요.",en:"Listening to example sentences helps with memorizing words."},target:"듣는",options:["to exercise","to study","to listen"],note:"듣는 게 presents listening as the concrete helpful action."},{kind:"guess",word:{ko:"읽다",romanization:"ikda",en:"to read",pos:"verb",nuance:"읽다 has pronunciation changes, but beginners can first memorize 읽어요 as the practical polite form."},sentence:{ko:"책을 읽기 시작하면 휴대폰을 덜 보게 돼요.",en:"Once I start reading a book, I end up looking at my phone less."},target:"읽기",options:["to read","to exercise","to study"],note:"읽기 시작하다 is the fixed start-doing frame."},{kind:"payoff",line:{speaker:"튜터",ko:"매일 운동하기는 어렵지만 건강을 위해 필요해요.",en:"Exercising every day is hard, but it is necessary for health."},hl:"운동하"}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b1",chapterId:"chapter-60",index:0},{kind:"pattern",title:"문법 Grammar · V-기",cards:[{kind:"teach",name:"V-기",sub:"turning a verb into a noun",rows:[{when:"Any verb stem (vowel or consonant)",add:"stem + 기",ex:"먹다 → 먹기, 읽다 → 읽기"},{when:"Stem ends in ㄹ (ㄹ stays before 기)",add:"stem + 기",ex:"살다 → 살기, 만들다 → 만들기"},{when:"As the object of 좋아하다/싫어하다 etc.",add:"V-기 + 를/을",ex:"운동하기를 좋아해요"},{when:"As the subject of 어렵다/쉽다/힘들다",add:"V-기 + 가",ex:"말하기가 어려워요"}],examples:[{ko:"저는 책 읽기를 좋아해요.",en:"I like reading books.",romanization:"jeo-neun chaek ilg-gi-reul jo-a-hae-yo.",note:"읽기 names the action so it can be the object of 좋아하다."},{ko:"오늘 숙제는 일기 쓰기예요.",en:"Today's homework is writing a diary.",romanization:"o-neul suk-je-neun il-gi sseu-gi-ye-yo.",note:"쓰기 is a plain noun (a task/title) here, right after 은."}],more:{func:"Add 기 to a verb stem to name the action as a thing. The 기-noun can be a task, a goal, or the object of verbs like 좋아하다, 싫어하다, 시작하다, and it is the natural subject of difficulty/ease adjectives like 어렵다, 쉽다, 힘들다.",funcLead:"Add 기 to a verb stem to name the action as a thing.",keyPoint:{label:"When to reach for V-기",body:"Use V-기 to label an action as a thing — especially as the subject of 어렵다/쉽다/좋다/힘들다, or the object of 좋아하다/싫어하다/시작하다. It sounds abstract and title-like, which is exactly why textbook section headings are 듣기, 읽기, 쓰기, 말하기."},pronunciation:"After a stem ending in a plain consonant, the 기 tenses: 읽기 [일끼], 먹기 [먹끼], 닦기 [닥끼]. Vowel stems stay soft: 가기 [가기], 자기 [자기].",pitfall:{wrong:"저는 읽다를 좋아해요.",right:"저는 읽기를 좋아해요.",explanation:"English 'reading' can be a noun on its own, but Korean cannot use the dictionary form 읽다 as a noun. Nominalise the stem first: 읽 + 기 → 읽기, then add the particle."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I like reading books."',tokens:["저는","책","읽기를","좋아해요."],correct:"저는 책 읽기를 좋아해요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Today's homework is writing a diary."`,tokens:["오늘","숙제는","일기","쓰기예요."],correct:"오늘 숙제는 일기 쓰기예요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 읽기를 좋아해요.",ok:!0},{text:"저는 읽다를 좋아해요.",ok:!1}],explanation:"English 'reading' can be a noun on its own, but Korean cannot use the dictionary form 읽다 as a noun. Nominalise the stem first: 읽 + 기 → 읽기, then add the particle."}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b2",chapterId:"chapter-60",index:1},{kind:"words",title:"단어 Words 2 · 외우다~",cards:[{kind:"guess",word:{ko:"외우다",romanization:"oeuda",en:"to memorize",pos:"verb",nuance:"외우다 is a NATIVE Korean verb (no hanja), meaning to commit something to memory deliberately — to get it 'by heart' through effort. Contrast it sharply with 기억하다 (記憶, 'remember/recall'): 외우다 is the act of putting info IN ('I'll memorize these words tonight'), while 기억하다 is having or pulling it back OUT ('Do you remember my number?'). Mixing them is the #1 English-speaker error, because English 'remember' blurs both. A near-synonym 암기하다 (暗記) means the same as 외우다 but sounds more bookish/formal. Crucially, because 외우다 is native (not noun+하다), its conjugation differs from every other verb on this list: the stem 외우- meets 어요 and the 우 + 어 fuse to 워 → 외워요, past 외웠어요; the negative is the simple 안 외워요 and impossible 못 외워요 — there is NO noun to split off. Common collocations: 단어를 외우다, 통째로 외우다, 줄줄 외우다."},sentence:{ko:"단어를 외우기 전에 예문을 들어요.",en:"Before memorizing words, I listen to example sentences."},target:"외우",options:["to exercise","to study","to memorize"],note:"외우기 전에 is more natural than trying to attach 전에 to 외우는 것."},{kind:"guess",word:{ko:"배우다",romanization:"baeuda",en:"to learn",pos:"verb",nuance:"배우다 means 'to learn / acquire a skill or subject' and takes the object marker 을/를: 한국어를 배워요. It is a regular verb, but the stem ends in the vowel 우, so when 어요 attaches the two vowels contract into 워 — 배우 + 어요 → 배워요 (not 배우어요), past 배웠어요. The natural partner verb is 가르치다 ('to teach'), the giving side of the same act; and the person you learn from takes 한테/에게서 (사람) — 선생님한테 배워요 — never the place particle 에서 for the source. Contrast 배우다 with 공부하다 (工夫하다, 'to study'): 공부하다 is the effort of studying (sitting down, reviewing, hitting the books), while 배우다 is the result of acquiring a skill or being taught it, often from someone. So you 공부하다 for an exam at your desk but 배우다 the piano from a teacher. The English-speaker pitfall is writing the uncontracted 배우어요, and saying 학원에서 배우다 to mean 'learn from the academy' — 에서 marks where, while the human source must take 한테/에게서."},sentence:{ko:"한국어를 배우기 시작한 지 6개월 됐어요.",en:"It has been six months since I started learning Korean."},target:"배우",options:["to exercise","to walk","to learn"],note:"배우기 시작하다 marks the beginning of the learning action."},{kind:"guess",word:{ko:"시작하다",romanization:"sijakada",en:"to start",pos:"verb",nuance:"시작하다 means 'to start / begin' and is a Sino-Korean 하다 verb — 시작 (始作, literally 始 'begin' + 作 'make/do', i.e. 'set in motion') plus 하다. As a 하다 verb it conjugates regularly with 하다 → 해요: 시작해요 / 시작합니다 / 시작했어요. A point that trips learners is that 시작하다 works both transitively and intransitively: with a doer it takes an object (저는 일을 시작해요 'I start work', 을/를), and with no doer the thing simply begins and takes the subject marker (수업이 시작해요 'class starts', 이/가). Contrast it with the pure intransitive 시작되다 (始作되다, 'to be started/begin'), which is more formal and never takes an object — 회의가 시작됐어요 'the meeting began'. Its natural opposite is 끝나다 ('to end'). The English-speaker pitfalls are (1) conjugating the 하다 wrongly as 시작하요 instead of 시작해요, and (2) forcing an object onto the no-doer case (수업을 시작해요 when you simply mean class begins) — when nothing actively starts it, use 수업이 시작해요 or the passive 시작돼요."},sentence:{ko:"걷기부터 시작했어요.",en:"I started with walking."},target:"시작했",options:["to start","to study","to walk"],note:"A noun or -기 activity can come before 시작하다."},{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"For a neutral ‘I don't know,’ Korean normally uses 모르다: 몰라요 or the softer 잘 모르겠어요. 안 알아요 is not universally wrong; context can give it ‘I don't recognize/know,’ ‘I won't find out,’ or a contrastive denial, so do not treat it as an impossible form."},sentence:{ko:"친구가 매일 운동하는 것을 알고 있어요.",en:"I know that my friend exercises every day."},target:"알고",options:["to know","to exercise","to study"],note:"알다 often takes a concrete proposition with -는 것."},{kind:"guess",word:{ko:"보다",romanization:"boda",en:"to see, to watch",pos:"verb",nuance:"보다 covers seeing, watching, and looking at something. Context tells which English verb fits."},sentence:{ko:"친구가 걷는 것을 보고 저도 시작했어요.",en:"After seeing my friend walk, I started too."},target:"보고",options:["to see, to watch","to exercise","to study"],note:"보다 makes the action concrete and observable, so -는 것 fits."},{kind:"guess",word:{ko:"느끼다",romanization:"neukkida",en:"to feel",pos:"verb",nuance:"느끼다 (a native verb, no 한자) means to become aware of something through the senses or the heart — an emotion (행복을 느끼다), a physical sensation (통증을 느끼다 = feel pain), or an abstract impression (차이·분위기를 느끼다). The contrast with 생각하다 is sharp: 느끼다 is what your body and heart register, 생각하다 is what your mind concludes. The big English-speaker pitfall is over-using it for states: 'I feel cold/sick/tired' in natural Korean is usually the plain adjective — 추워요, 아파요, 피곤해요 — not 추움을 느껴요. Reserve 느끼다 for when you're consciously naming the sensation as an object (감동을 느끼다, 책임감을 느끼다). Conjugation: the stem 느끼 + -어 contracts to 느껴 (느껴요, 느꼈어요), never the spelled-out 느끼어요."},sentence:{ko:"매일 듣는 것이 발음에 도움이 된다고 느껴요.",en:"I feel that listening every day helps pronunciation."},target:"느껴",options:["to exercise","to feel","to study"],note:"느끼다 can take a proposition treated as a concrete fact."},{kind:"guess",word:{ko:"자다",romanization:"jada",en:"to sleep",pos:"verb",nuance:"자다 becomes 잘 before some future or ability forms: 잘 거예요, 잘 수 있어요."},sentence:{ko:"자기 전에 휴대폰 보는 것을 줄이기로 했어요.",en:"I decided to reduce looking at my phone before sleeping."},target:"자기",options:["to study","to sleep","to walk"],note:"자기 전에 is the fixed before-sleeping frame."},{kind:"payoff",line:{speaker:"민서",ko:"그래서 저는 걷기부터 시작하기로 했어요.",en:"So I decided to start with walking."},hl:"시작하"}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b3",chapterId:"chapter-60",index:2},{kind:"pattern",title:"문법 Grammar · V-는 것/거",cards:[{kind:"hunt",name:"V-는 것/거",sub:"an action or fact as a noun",lines:[{tokens:[{pre:"저는",mid:"",post:"",hit:!1},{pre:"영화",mid:"",post:"",hit:!1},{pre:"보",mid:"는",post:"",hit:!0},{pre:"",mid:"것",post:"을",hit:!0},{pre:"좋아해요.",mid:"",post:"",hit:!1}],ko:"저는 영화 보는 것을 좋아해요.",en:"I like watching movies.",romanization:"jeo-neun yeong-hwa bo-neun geos-eul jo-a-hae-yo."},{tokens:[{pre:"매일",mid:"",post:"",hit:!1},{pre:"운동하",mid:"는",post:"",hit:!0},{pre:"",mid:"것",post:"이",hit:!0},{pre:"중요해요.",mid:"",post:"",hit:!1}],ko:"매일 운동하는 것이 중요해요.",en:"Exercising every day is important.",romanization:"mae-il un-dong-ha-neun geos-i jung-yo-hae-yo."}],rule:{name:"V-는 것/거",rows:[{when:"Verb (present action/habit)",add:"stem + 는 것/거",ex:"먹다 → 먹는 것, 보다 → 보는 것"},{when:"Stem ends in ㄹ (ㄹ drops before 는)",add:"stem(-ㄹ) + 는 것",ex:"살다 → 사는 것, 만들다 → 만드는 것"},{when:"Subject, casual speech (것이 → 게)",add:"는 게",ex:"보는 게 좋아요"},{when:"Object, casual speech (것을 → 걸)",add:"는 걸",ex:"보는 걸 좋아해요"}]},more:{func:"Add 는 것 (casual 는 거) to a verb to name an action, a habit, or something you saw or know — as a noun. It points at the real, ongoing act, and it is the everyday default after 좋아하다 and as a sentence subject.",funcLead:"Add 는 것 (casual 는 거) to a verb to name an action, a habit, or something you saw or know — as a noun.",keyPoint:{label:"기 vs 는 것",body:"Both make a verb into a noun. V-기 is abstract and title-like — good for skills, tasks, and subjects of 어렵다/쉽다 (말하기가 어려워요). V-는 것 points at the real act or a habit, and is the default after 좋아하다 and as a subject (영화 보는 게 좋아요). When you are talking and unsure, 는 거 is the safer choice."},pronunciation:"것 links its final ㅅ into a following vowel: 것을 [거슬], 것이 [거시]. In casual speech learn the contractions early — 것이 → 게 [게], 것을 → 걸 [걸], 것은 → 건 [건] — they are everywhere.",pitfall:{wrong:"저는 영화 보것을 좋아해요.",right:"저는 영화 보는 것을 좋아해요.",explanation:"Learners often drop 는 and glue 것 straight onto the stem. The verb must take its present modifier ending -는 before 것: 보 + 는 + 것. Without 는, the phrase is ungrammatical."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I like watching movies."',tokens:["저는","영화","보는","것을","좋아해요."],correct:"저는 영화 보는 것을 좋아해요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Exercising every day is important."',tokens:["매일","운동하는","것이","중요해요."],correct:"매일 운동하는 것이 중요해요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 영화 보것을 좋아해요.",ok:!1},{text:"저는 영화 보는 것을 좋아해요.",ok:!0}],explanation:"Learners often drop 는 and glue 것 straight onto the stem. The verb must take its present modifier ending -는 before 것: 보 + 는 + 것. Without 는, the phrase is ungrammatical."}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b4",chapterId:"chapter-60",index:3},{kind:"words",title:"단어 Words 3 · 먹다~",cards:[{kind:"guess",word:{ko:"먹다",romanization:"meokda",en:"to eat",pos:"verb",nuance:"먹다 is used for meals and food. For medicine, Korean often uses 약을 먹어요, literally “eat medicine,” which means “take medicine.”"},sentence:{ko:"밤에 늦게 먹는 것을 줄이려고 해요.",en:"I am trying to reduce eating late at night."},target:"먹는",options:["to exercise","to study","to eat"],note:"먹는 것 is the habit being reduced."},{kind:"guess",word:{ko:"쉬다",romanization:"swida",en:"to rest",pos:"verb",nuance:"쉬다 is used for taking a break, resting, or being off work/school."},sentence:{ko:"쉬는 것도 공부 계획에 넣어야 해요.",en:"Resting should also be included in the study plan."},target:"쉬는",options:["to rest","to walk","to listen"],note:"쉬는 것 points to resting as a concrete part of the plan."},{kind:"guess",word:{ko:"습관",romanization:"seupgwan",en:"habit",pos:"noun",nuance:"습관 (習慣, 習 'to practice/learn' + 慣 'to grow accustomed') frames a habit as something drilled in until it feels natural, and it leans slightly formal and neutral. The key contrast is 습관 vs 버릇: 습관 is a broad, often deliberate routine (early rising, daily exercise, good study habits), while 버릇 is colloquial and usually a quirky or annoying unconscious tic — nail-biting, leg-shaking, a child's bad manners. Crucially, scolding a child you say 버릇없다 ('has no manners / is rude'), never 습관없다. Both pair with 고치다 ('fix') for breaking them and 들이다/생기다 for forming them (습관을 들이다 = cultivate a habit; 습관이 생기다 = a habit forms). To say you have one, use 습관이 있다. Pitfall: English 'I have a habit of doing X' must use the verb's -는 present-modifier form before 습관: 일찍 자는 습관 (the habit of sleeping early), not 일찍 자기 습관. Also do not use 가지다 here — habits 있다/되다/생기다, they are not 'had' with 가지다."},sentence:{ko:"매일 듣는 습관을 만들고 있어요.",en:"I am building a habit of listening every day."},target:"습관",options:["exercise","habit","study, studying"],note:"-는 습관 naturally describes repeated behavior."},{kind:"guess",word:{ko:"목표",romanization:"mokpyo",en:"goal, target",pos:"noun",nuance:"목표 (目標, 目 'eye' + 標 'mark/sign' — literally the mark the eye fixes on) is a concrete, measurable goal or target you aim at, and it travels with a tight verb family: 세우다 or 정하다 to set it, 이루다 or 달성하다 to achieve it. The synonym line is 목표 vs 꿈: 목표 is specific and outcome-focused (pass TOPIK 3, save 1,000,000 won, run 5km), while 꿈 is broader, emotional, and aspirational (become a doctor, a better world), so use 목표 for things you can tick off and 꿈 for the life vision behind them. Note also 목표 vs 목적(目的): 목표 is the concrete TARGET, 목적 is the underlying PURPOSE/reason. The English-speaker pitfall is forming a verb directly: 'to goal' tempts learners into 목표하다, which is unnatural in writing — say 목표를 세우다 or 목표로 하다 instead."},sentence:{ko:"오늘 목표는 예문 다섯 개를 외우는 거예요.",en:"Today's goal is memorizing five example sentences."},target:"목표",options:["exercise","study, studying","goal, target"],note:"Spoken 거예요 makes the action into the goal."},{kind:"guess",word:{ko:"건강",romanization:"geongang",en:"health",pos:"noun",nuance:"건강 is Sino-Korean 健康, where 健 means 'sturdy/robust' and 康 means 'peaceful/well,' together the sound, robust state of body and mind. It splits into a noun and an adjective: the noun 건강 ('health') pairs with 좋다/나쁘다 (good/bad) — never 높다/낮다 (high/low), which is the typical English-influenced slip from 'high level of health' — and you actively mind it with 챙기다 (건강을 챙기다, 'look after your health'); the adjective 건강하다 means 'to be healthy' (저는 건강해요 = 'I'm healthy'). Its honorific imperative 건강하세요 is a beloved set phrase, a warm farewell/blessing meaning 'stay healthy,' especially said to elders and at New Year. A near-synonym is 컨디션 (a loanword from 'condition') — but 컨디션 is your day-to-day fitness/energy level (오늘 컨디션이 안 좋아 = 'I'm not feeling great today'), whereas 건강 is your overall, long-term state of wellness; don't swap them."},sentence:{ko:"건강을 위해 매일 걷기로 했어요.",en:"For my health, I decided to walk every day."},target:"건강",options:["exercise","study, studying","health"],note:"Noun + 을 위해 is the noun version of V-기 위해."},{kind:"guess",word:{ko:"꾸준히",romanization:"kkujunhi",en:"steadily, consistently",pos:"adverb",nuance:"꾸준히 means doing something *steadily and consistently over time, without quitting* — it is the warm praise-word Koreans reach for to describe sustainable, unglamorous, day-after-day effort. The contrast you must internalize is 꾸준히 vs 열심히: 열심히 means 'hard, with intensity/diligence' and can describe a single burst (오늘 열심히 공부했어요 = I studied hard today), whereas 꾸준히 is inherently about *continuity* across time — you cannot be 꾸준히 for one day, because the word means you kept it up. So an all-nighter is 열심히, never 꾸준히; daily practice for a year is 꾸준히. In a self-improvement context it is the natural opposite of cramming (벼락치기) or giving up. The grammar pitfall for English speakers is part of speech: 꾸준히 is an *adverb* that modifies verbs (꾸준히 공부하다), so you cannot use it to describe a noun directly — for that you need the adjective 꾸준하다 (e.g. 꾸준한 노력 'steady effort'). Habitual partners: 꾸준히 공부하다, 꾸준히 연습하다, 꾸준히 노력하다, 꾸준히 늘다."},sentence:{ko:"꾸준히 듣는 게 말하기에도 도움이 돼요.",en:"Listening consistently helps speaking too."},target:"꾸준히",options:["to exercise","steadily, consistently","exercise"],note:"꾸준히 works well with repeated -는 것 habits."},{kind:"guess",word:{ko:"줄이다",romanization:"jurida",en:"to reduce, to cut down on",pos:"verb",nuance:"줄이다 is transitive: you reduce something. 줄다 is intransitive: something decreases by itself."},sentence:{ko:"휴대폰 보는 것을 줄이기로 했어요.",en:"I decided to cut down on looking at my phone."},target:"줄이",options:["to exercise","to reduce, to cut down on","to study"],note:"The thing reduced is a concrete habit, so 보는 것을 is natural."},{kind:"payoff",line:{speaker:"튜터",ko:"매일 운동하기는 어렵지만 건강을 위해 필요해요.",en:"Exercising every day is hard, but it is necessary for health."},hl:"건강"}],canDo:"Give the purpose of an action with V-기 위해(서) (건강해지기 위해서)",id:"chapter-60-b5",chapterId:"chapter-60",index:4},{kind:"pattern",title:"문법 Grammar · V-기로 했어요",cards:[{kind:"hunt",name:"V-기로 했어요",sub:"decided to do",lines:[{tokens:[{pre:"내일부터",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"일어나",mid:"기로",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"내일부터 일찍 일어나기로 했어요.",en:"I've decided to get up early from tomorrow.",romanization:"nae-il-bu-teo il-jjik il-eo-na-gi-ro haess-eo-yo."},{tokens:[{pre:"우리",mid:"",post:"",hit:!1},{pre:"주말에",mid:"",post:"",hit:!1},{pre:"같이",mid:"",post:"",hit:!1},{pre:"등산하",mid:"기로",post:"",hit:!0},{pre:"",mid:"했어요",post:".",hit:!0}],ko:"우리 주말에 같이 등산하기로 했어요.",en:"We decided to go hiking together on the weekend.",romanization:"u-ri ju-mal-e ga-chi deung-san-ha-gi-ro haess-eo-yo."}],rule:{name:"V-기로 했어요",rows:[{when:"State a decision (most common)",add:"stem + 기로 했어요",ex:"운동하다 → 운동하기로 했어요"},{when:"Deciding right now / promise",add:"stem + 기로 해요 / 할게요",ex:"담배를 끊기로 할게요"},{when:"Mutual agreement (we agreed)",add:"stem + 기로 했어요 (with 같이/우리)",ex:"같이 가기로 했어요"},{when:"Decide NOT to do",add:"안 + V / V-지 않 + 기로 했어요",ex:"야식을 안 먹기로 했어요"}]},more:{func:"Use V-기로 하다 for a decision, plan, or agreement to do something. The 기-noun takes 로 ('settle on') plus 하다. It is almost always said in the past — 했어요 — because the decision is already made by the time you mention it.",funcLead:"Use V-기로 하다 for a decision, plan, or agreement to do something.",keyPoint:{label:"했어요 vs 해요",body:"The decision is usually reported in the past: V-기로 했어요 ('I (have) decided'), because the decision already exists by the time you say it. Use the present V-기로 해요 / 할게요 only when you are making the resolution at the very moment of speaking ('okay, I'll do X from now on')."},pronunciation:"기로 is read smoothly [기로], with no special change. A tensing stem still tenses the 기: 먹기로 [먹끼로]; and ㅎ + ㄱ aspirates: 끊기로 [끈키로].",pitfall:{wrong:"저는 운동하기를 했어요.",right:"저는 운동하기로 했어요.",explanation:"The pattern needs the particle 로 ('settle on'), not the object particle 를. 기 + 로 + 하다 is a fixed chunk meaning 'decide to'; 기를 하다 is not a decision and sounds wrong."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I've decided to get up early from tomorrow." (내일부터 시작 · Start with 내일부터.)`,tokens:["내일부터","일찍","일어나기로","했어요."],correct:"내일부터 일찍 일어나기로 했어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "We decided to go hiking together on the weekend." (우리 시작 · Start with 우리.)',tokens:["우리","주말에","같이","등산하기로","했어요."],correct:"우리 주말에 같이 등산하기로 했어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 운동하기를 했어요.",ok:!1},{text:"저는 운동하기로 했어요.",ok:!0}],explanation:"The pattern needs the particle 로 ('settle on'), not the object particle 를. 기 + 로 + 하다 is a fixed chunk meaning 'decide to'; 기를 하다 is not a decision and sounds wrong."}],canDo:"Give the purpose of an action with V-기 위해(서) (건강해지기 위해서)",id:"chapter-60-b6",chapterId:"chapter-60",index:5},{kind:"pattern",title:"문법 Grammar · V-기 위해(서)",cards:[{kind:"hunt",name:"V-기 위해(서)",sub:"in order to do",lines:[{tokens:[{pre:"건강해지",mid:"기",post:"",hit:!0},{pre:"",mid:"위해서",post:"",hit:!0},{pre:"매일",mid:"",post:"",hit:!1},{pre:"운동해요.",mid:"",post:"",hit:!1}],ko:"건강해지기 위해서 매일 운동해요.",en:"I exercise every day in order to get healthy.",romanization:"geon-gang-hae-ji-gi wi-hae-seo mae-il un-dong-hae-yo."},{tokens:[{pre:"한국에서",mid:"",post:"",hit:!1},{pre:"일하",mid:"기",post:"",hit:!0},{pre:"",mid:"위해",post:"",hit:!0},{pre:"한국어를",mid:"",post:"",hit:!1},{pre:"배워요.",mid:"",post:"",hit:!1}],ko:"한국에서 일하기 위해 한국어를 배워요.",en:"I'm learning Korean in order to work in Korea.",romanization:"han-gug-e-seo il-ha-gi wi-hae han-gug-eo-reul bae-wo-yo."}],rule:{name:"V-기 위해(서)",rows:[{when:"Verb purpose",add:"stem + 기 위해(서)",ex:"합격하다 → 합격하기 위해서"},{when:"Noun purpose",add:"N + 을/를 위해(서)",ex:"건강을 위해서"},{when:"Drop 서 (a touch more formal)",add:"stem + 기 위해",ex:"살을 빼기 위해 운동해요"},{when:"Written/formal style",add:"stem + 기 위하여",ex:"성공하기 위하여 노력합니다"}]},more:{func:"Use V-기 위해(서) to give the purpose of an action: 'in order to V'. The verb is nominalised with 기, then 위해(서) ('for the sake of') marks it as the goal. For a noun goal, use N을/를 위해(서) with no 기.",funcLead:"Use V-기 위해(서) to give the purpose of an action: 'in order to V'.",keyPoint:{label:"V-기 위해서 vs V-(으)려고",body:"Both mean 'in order to'. 기 위해서 states a deliberate, often weighty goal and works in writing and speech (시험에 합격하기 위해서 공부해요). V-(으)려고 is lighter and conversational. For a noun goal there is no 기 — you must use N을/를 위해서 (건강을 위해서)."},pronunciation:"위해서 [위해서]; the formal 위하여 [위하여]. The 기 still tenses after a plain-consonant stem: 먹기 위해 [먹끼 위해].",pitfall:{wrong:"한국어를 배우다 위해서 학원에 다녀요.",right:"한국어를 배우기 위해서 학원에 다녀요.",explanation:"A verb before 위해서 must be nominalised: 배우 + 기 → 배우기 위해서. You cannot put the dictionary form 배우다 straight in front of 위해서."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I exercise every day in order to get healthy."',tokens:["건강해지기","위해서","매일","운동해요."],correct:"건강해지기 위해서 매일 운동해요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm learning Korean in order to work in Korea." (한국에서 시작 · Start with 한국에서.)`,tokens:["한국에서","일하기","위해","한국어를","배워요."],correct:"한국에서 일하기 위해 한국어를 배워요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"한국어를 배우기 위해서 학원에 다녀요.",ok:!0},{text:"한국어를 배우다 위해서 학원에 다녀요.",ok:!1}],explanation:"A verb before 위해서 must be nominalised: 배우 + 기 → 배우기 위해서. You cannot put the dictionary form 배우다 straight in front of 위해서."}],canDo:"Say something happens before another action (V-기 전에) and that you start it (V-기 시작하다)",id:"chapter-60-b7",chapterId:"chapter-60",index:6},{kind:"pattern",title:"문법 Grammar · V-기 전에",cards:[{kind:"hunt",name:"V-기 전에",sub:"before doing",lines:[{tokens:[{pre:"자",mid:"기",post:"",hit:!0},{pre:"",mid:"전에",post:"",hit:!0},{pre:"휴대폰",mid:"",post:"",hit:!1},{pre:"보는",mid:"",post:"",hit:!1},{pre:"것을",mid:"",post:"",hit:!1},{pre:"줄이기로",mid:"",post:"",hit:!1},{pre:"했어요.",mid:"",post:"",hit:!1}],ko:"자기 전에 휴대폰 보는 것을 줄이기로 했어요.",en:"I decided to cut down on looking at my phone before sleeping.",romanization:"ja-gi jeon-e hyu-dae-pon bo-neun geos-eul ju-ri-gi-ro haess-eo-yo."},{tokens:[{pre:"밥을",mid:"",post:"",hit:!1},{pre:"먹",mid:"기",post:"",hit:!0},{pre:"",mid:"전에",post:"",hit:!0},{pre:"손을",mid:"",post:"",hit:!1},{pre:"씻어요.",mid:"",post:"",hit:!1}],ko:"밥을 먹기 전에 손을 씻어요.",en:"I wash my hands before eating.",romanization:"bab-eul meog-gi jeon-e son-eul ssis-eo-yo."}],rule:{name:"V-기 전에",rows:[{when:"Verb (before doing)",add:"stem + 기 전에",ex:"자다 → 자기 전에, 먹다 → 먹기 전에"},{when:"Noun (before a thing/event)",add:"N + 전에 (no 기)",ex:"수업 전에, 점심 전에"},{when:"Tense stays on the main verb",add:"...기 전에 + past/present/future main verb",ex:"먹기 전에 손을 씻었어요"}]},more:{func:"Use V-기 전에 to say one action happens before another: 'before V-ing'. The verb takes 기, then 전에 ('before') follows. The tense lives only in the main clause, never on the verb before 전에.",funcLead:"Use V-기 전에 to say one action happens before another: 'before V-ing'.",keyPoint:{label:"기 전에 vs N 전에",body:"Before a verb, you need 기: 먹기 전에, 자기 전에. Before a plain noun, there is no 기 — just add 전에: 수업 전에, 점심 전에, 운동 전에. And the opposite of 전에 is 후에 / -(으)ㄴ 후에 (after doing): 먹은 후에."},pronunciation:"전에 [저네] in fast speech, as the ㄴ links to the next vowel. The 기 still tenses after a plain-consonant stem: 먹기 전에 [먹끼 저네].",pitfall:{wrong:"밥을 먹었기 전에 손을 씻었어요.",right:"밥을 먹기 전에 손을 씻었어요.",explanation:"Do not put past tense on the verb before 전에. The verb before 전에 stays as plain 기 (먹기 전에); the past meaning goes on the main verb (씻었어요)."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I wash my hands before eating." (밥을 시작 · Start with 밥을.)',tokens:["밥을","먹기","전에","손을","씻어요."],correct:"밥을 먹기 전에 손을 씻어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"밥을 먹었기 전에 손을 씻었어요.",ok:!1},{text:"밥을 먹기 전에 손을 씻었어요.",ok:!0}],explanation:"Do not put past tense on the verb before 전에. The verb before 전에 stays as plain 기 (먹기 전에); the past meaning goes on the main verb (씻었어요)."}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b8",chapterId:"chapter-60",index:7},{kind:"pattern",title:"문법 Grammar · V-기 시작하다",cards:[{kind:"hunt",name:"V-기 시작하다",sub:"start doing",lines:[{tokens:[{pre:"한국어",mid:"",post:"",hit:!1},{pre:"뉴스를",mid:"",post:"",hit:!1},{pre:"조금씩",mid:"",post:"",hit:!1},{pre:"듣",mid:"기",post:"",hit:!0},{pre:"",mid:"시작",post:"했어요.",hit:!0}],ko:"한국어 뉴스를 조금씩 듣기 시작했어요.",en:"I started listening to Korean news little by little.",romanization:"han-gug-eo nyu-seu-reul jo-geum-ssik deud-gi si-jak-haess-eo-yo."},{tokens:[{pre:"아침에",mid:"",post:"",hit:!1},{pre:"걷",mid:"기",post:"",hit:!0},{pre:"",mid:"시작",post:"하니까",hit:!0},{pre:"잠이",mid:"",post:"",hit:!1},{pre:"덜",mid:"",post:"",hit:!1},{pre:"와요.",mid:"",post:"",hit:!1}],ko:"아침에 걷기 시작하니까 잠이 덜 와요.",en:"Since I started walking in the morning, I feel less sleepy.",romanization:"a-chim-e geod-gi si-jak-ha-ni-kka jam-i deol wa-yo."}],rule:{name:"V-기 시작하다",rows:[{when:"Start a verb action",add:"stem + 기 시작하다",ex:"듣다 → 듣기 시작하다, 읽다 → 읽기 시작하다"},{when:"Tense lives on 시작하다",add:"...기 시작했어요 / 시작해요 / 시작할 거예요",ex:"걷기 시작했어요"},{when:"Start a noun (no 기)",add:"N을/를 시작하다",ex:"운동을 시작했어요"}]},more:{func:"Use V-기 시작하다 to say you start an action. 시작하다 ('start') can take a plain noun object (운동을 시작하다), but when the thing you start is a verb, you nominalise it with 기 first. The tense goes on 시작하다.",funcLead:"Use V-기 시작하다 to say you start an action.",keyPoint:{label:"기 시작하다 vs N 시작하다",body:"If you start a verb action, nominalise it: 걷기 시작하다, 듣기 시작하다, 읽기 시작하다. If you start a thing that is already a noun, just add 을/를: 운동을 시작하다, 공부를 시작하다. So '운동하다' becomes 운동하기 시작하다 OR 운동을 시작하다 — but never 운동기 시작하다."},pronunciation:"The 기 tenses after a plain-consonant stem: 듣기 [듣끼], 읽기 [일끼], 걷기 [걷끼]. 시작하다 is [시자카다], with ㄱ + ㅎ blending into an aspirated sound.",pitfall:{wrong:"운동기 시작했어요.",right:"운동을 시작했어요. / 운동하기 시작했어요.",explanation:"Do not attach 기 to a noun. 운동 is a noun, so use 운동을 시작하다; only the verb 운동하다 can take 기 → 운동하기 시작하다."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I started listening to Korean news little by little."',tokens:["한국어","뉴스를","조금씩","듣기","시작했어요."],correct:"한국어 뉴스를 조금씩 듣기 시작했어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Since I started walking in the morning, I feel less sleepy." (아침에 시작 · Start with 아침에.)',tokens:["아침에","걷기","시작하니까","잠이","덜","와요."],correct:"아침에 걷기 시작하니까 잠이 덜 와요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"운동을 시작했어요. / 운동하기 시작했어요.",ok:!0},{text:"운동기 시작했어요.",ok:!1}],explanation:"Do not attach 기 to a noun. 운동 is a noun, so use 운동을 시작하다; only the verb 운동하다 can take 기 → 운동하기 시작하다."}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b9",chapterId:"chapter-60",index:8},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"A tutor helps a learner turn vague goals into Korean sentences using -기, -는 것, and fixed nominalized frames.",lines:[{speaker:"튜터",ko:"매일 운동하기는 어렵지만 건강을 위해 필요해요.",en:"Exercising every day is hard, but it is necessary for health.",romanization:"maeil undonghagineun eoryeopjiman geongangeul wihae piryohaeyo."},{speaker:"민서",ko:"그래서 저는 걷기부터 시작하기로 했어요.",en:"So I decided to start with walking.",romanization:"geuraeseo jeoneun geotgibuteo sijakagiro haesseoyo."},{speaker:"튜터",ko:"좋아요. 친구가 매일 걷는 것을 보고 따라 해 보기로 한 거죠?",en:"Good. You saw your friend walking every day and decided to try following along, right?",romanization:"joayo. chinguga maeil geonneun geoseul bogo ttara hae bogiro han geojyo?"},{speaker:"민서",ko:"네. 그리고 자기 전에 휴대폰 보는 것을 줄이기로 했어요.",en:"Yes. And I decided to reduce looking at my phone before sleeping.",romanization:"ne. geurigo jagi jeone hyudaepon boneun geoseul jurigiro haesseoyo."},{speaker:"튜터",ko:"단어를 외우기 전에 예문을 듣는 것도 좋아요.",en:"Listening to example sentences before memorizing words is also good.",romanization:"daneoreul oeugi jeone yemuneul deunneun geotdo joayo."},{speaker:"민서",ko:"그럼 오늘 목표는 예문을 먼저 듣고 단어를 외우는 거예요.",en:"Then today's goal is listening to the examples first and memorizing the words.",romanization:"geureom oneul mokpyoneun yemuneul meonjeo deutgo daneoreul oeuneun geoyeyo."}]},{kind:"order",prompt:"Build: 'I decided to memorize words.'",tokens:["단어를","외우기로 했어요"],correct:"단어를 외우기로 했어요",explanation:"-기로 했어요 is the fixed decision frame. 외우다 becomes 외우기로 before 했어요."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"좋아요. 친구가 매일 걷는 것을 보고 따라 해 보기로 한 거죠?",options:[{text:"튜터",ok:!0},{text:"민서",ok:!1}],explanation:"Good. You saw your friend walking every day and decided to try following along, right?"},{kind:"drill",prompt:'무엇이 들어갈까요? · "Exercising every day is hard, but it is necessary for health."',sentence:"매일 ___하기는 어렵지만 건강을 위해 필요해요.",options:[{text:"운동",ok:!0},{text:"공부",ok:!1},{text:"습관",ok:!1}],explanation:""}],canDo:"Name an action as a noun with V-기 (운동하기) and V-는 것 (운동하는 것)",id:"chapter-60-b10",chapterId:"chapter-60",index:9},{kind:"reading",title:"읽기 Reading · -기와 -는 것을 고르는 법",cards:[{kind:"read",title:"-기와 -는 것을 고르는 법",chunks:["민서는 건강을 위해 운동을 시작하고 싶었지만, 매일 운동하기는 부담스러웠다. 그래서 걷기부터 시작하기로 했다. 친구가 아침마다 걷는 것을 보고 따라 해 보기로 한 것이다. 한국어 공부도 같은 방식으로 바꿨다.",'단어를 외우기 전에 예문을 먼저 듣고, 자기 전에 휴대폰 보는 것을 줄이기로 했다. 이렇게 말하면 -기는 목표나 순서를 만들고, -는 것은 실제로 보고 줄이고 반복하는 행동을 가리킨다. 민서는 이제 "공부하기"와 "공부하는 것"을 같은 말로 외우지 않고, 문장 안에서 어떤 역할을 하는지 먼저 본다.'],translation:"Minseo wanted to start exercising for her health, but exercising every day felt burdensome. So she decided to start with walking. She saw her friend walking every morning and decided to try following along. She changed her Korean study the same way. Before memorizing words, she listens to examples first, and she decided to reduce looking at her phone before sleeping. In these sentences, -기 makes goals and sequences, while -는 것 points to actions that are seen, reduced, or repeated. Minseo no longer memorizes 공부하기 and 공부하는 것 as the same thing; she first checks what job the action has inside the sentence.",qas:[{q:"민서는 왜 걷기부터 시작하기로 했어요?",a:"매일 운동하기는 부담스러웠기 때문이에요."},{q:"단어를 외우기 전에 무엇을 먼저 해요?",a:"예문을 먼저 들어요."},{q:"-는 것은 어떤 행동을 가리킨다고 했어요?",a:"실제로 보고 줄이고 반복하는 행동을 가리킨다고 했어요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"민서는 건강을 위해 ___을 시작하고 싶었지만, 매일 운동하기는 부담스러웠다.",options:[{text:"운동",ok:!0},{text:"습관",ok:!1},{text:"공부하다",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"한국어 ___도 같은 방식으로 바꿨다.",options:[{text:"습관",ok:!1},{text:"운동하다",ok:!1},{text:"공부",ok:!0}],explanation:""}],canDo:"Express a decision or plan with V-기로 했어요 (운동하기로 했어요)",id:"chapter-60-b11",chapterId:"chapter-60",index:10},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence uses -기 as an activity label?",sentence:null,options:[{text:"매일 운동하기는 어려워요.",ok:!0},{text:"매일 운동하는 것을 봤어요.",ok:!1},{text:"매일 운동한 사람을 만났어요.",ok:!1}],explanation:"운동하기 names the activity as a general task."},{kind:"drill",prompt:"Which sentence uses -는 것 for a concrete habit being reduced?",sentence:null,options:[{text:"휴대폰 보는 것을 줄이기로 했어요.",ok:!0},{text:"휴대폰 보기 전에 줄였어요.",ok:!1},{text:"휴대폰 보기를 봤어요.",ok:!1}],explanation:"The habit being reduced is the concrete action 휴대폰 보는 것."},{kind:"drill",prompt:"Choose the correct fixed decision frame.",sentence:null,options:[{text:"매일 걷기로 했어요.",ok:!0},{text:"매일 걷는 것으로 했어요.",ok:!1},{text:"매일 걸어서 했어요.",ok:!1}],explanation:"기로 했어요 is the standard chunk for a settled decision."},{kind:"drill",prompt:"운동___ 시작했어요. (I started exercising.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"시작하다 can take the activity noun as an object, so 운동을 fits. 이 would make exercise the subject."},{kind:"drill",prompt:"Which sentence treats walking as an activity label?",sentence:null,options:[{text:"걷기는 건강에 좋아요.",ok:!0},{text:"걷는 것을 어제 봤어요.",ok:!1},{text:"걷다 건강이에요.",ok:!1}],explanation:"-기 can turn the activity into a topic label. 걷기는 means walking as an activity."}],canDo:"Give the purpose of an action with V-기 위해(서) (건강해지기 위해서)",id:"chapter-60-b12",chapterId:"chapter-60",index:11}]},{id:"chapter-61",number:61,title:`A/V-네요: realizing or noticing something right now · A/V-군요 / -구나: "I see, so that's how it is"`,goal:"Use -네요 for fresh realization from what you just noticed.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 재미있다~",cards:[{kind:"guess",word:{ko:"재미있다",romanization:"jaemiitda",en:"to be fun, interesting",pos:"adjective",nuance:"재미있다 is literally 재미 (fun, enjoyment) + 있다 (to exist) — 'fun exists [in it]' — which is exactly why it conjugates like 있다 and gives 재미있어요, and why the noun-modifying form is the 있다-style 재미있는 N (재미있는 영화), never 재미있은. It spans both English 'fun' and 'interesting': a party, a game, or a class can all be 재미있어요, so let context choose the English. The near-synonym to separate is 재미있다 vs 흥미롭다: 재미있다 is the warm, everyday 'enjoyable/entertaining' you say about a movie or a friend, while 흥미롭다 is a cooler, more bookish 'intriguing/of interest' you might use for a research finding or a phenomenon — calling a thrilling roller coaster 흥미로워요 sounds oddly academic. Its direct opposite is the single word 재미없다 (재미 + 없다, 'fun does not exist') = boring; do not say 안 재미있다 as your default negative — 재미없어요 is the natural 'it's boring', and 안 재미있어요 reads more like 'it's not [particularly] fun'. The big English-speaker pitfall is the conjugation: because the headword ends in 있다, learners over-apply -하다 or vowel rules and produce 재미있다요 or 재미있아요; the only correct polite form is 재미있어요, with past 재미있었어요."},sentence:{ko:"한국어가 생각보다 재미있네요.",en:"Korean is more fun than I expected."},target:"재미있",options:["to be difficult","to be certain, sure","to be fun, interesting"],note:"Fresh realization with -네요."},{kind:"guess",word:{ko:"생각보다",romanization:"saenggakboda",en:"more/less than expected",pos:"adverb",nuance:"생각보다 naturally pairs with 더라고요 because both talk about what you found after experience."},sentence:{ko:"생각보다 어렵지 않네요.",en:"It is not as hard as I thought."},target:"생각보다",options:["more/less than expected","already","together"],note:"This word naturally triggers realization endings because expectation changed."},{kind:"guess",word:{ko:"어렵다",romanization:"eoryeopda",en:"to be difficult",pos:"adjective",nuance:"어렵다 is ㅂ irregular: 어려워요, 어려운. It is useful in classroom repair conversations because learners often need to say a sentence or lesson is difficult."},sentence:{ko:"처음에는 어려울 줄 알았는데 생각보다 괜찮군요.",en:"I thought it would be hard at first, but it is better than expected."},target:null,options:["to be difficult","to be fun, interesting","to be certain, sure"],note:"어려울 줄 알았다 sets the old expectation."},{kind:"guess",word:{ko:"벌써",romanization:"beolsseo",en:"already",pos:"adverb",nuance:"벌써 means 'already', but its core flavor is SURPRISE that something happened sooner than you expected — 'wow, already?'. Compare its near-twin 이미: 이미 is the neutral 'already / by now' that simply reports a completed fact (이미 끝났어요 'it's already finished', stating it), whereas 벌써 adds the emotional jolt (벌써 끝났어요? 'it's done already?!'). So a flat report prefers 이미; an astonished reaction prefers 벌써. It naturally rides with past tense and with 다('all'), and often co-occurs with the exclamatory endings -네요/-군요. Register-neutral. The English-speaker pitfall: don't pair 벌써 with the future — English 'already' can sit oddly with plans, but 벌써 is about something that has ALREADY occurred, so it takes past/completed verbs (벌써 갔어요), not 벌써 갈 거예요. Use 곧/이미 곧 logic for 'soon' instead."},sentence:{ko:"벌써 도착하셨군요.",en:"Oh, they have already arrived."},target:"벌써",options:["already","more/less than expected","together"],note:"벌써 pairs well with surprise or realization."},{kind:"guess",word:{ko:"도착하다",romanization:"dochakada",en:"to arrive",pos:"verb",nuance:"도착하다 is Sino-Korean 到着(도착: 到 reach + 着 attach/touch down) plus 하다 — the moment of REACHING and touching a destination. Its mirror is 출발하다(depart), and the key is the particle: you arrive AT a place with 에 (호텔에 도착해요), whereas 출발하다 leaves FROM a place with 에서. Don't confuse it with 들어가다/들어오다(enter): 도착하다 is reaching the destination's threshold, not stepping inside a building. As a 하다 verb, 하 + 아 fuses to 해 (도착해요) and the short negative and inability split the noun off: 도착 안 해요, 도착 못 해요. The classic English-speaker error is copying 'arrive at' as 에서 — 'at' here is the static endpoint 에, so 공항에 도착해요, and 공항에서 도착해요 is wrong."},sentence:{ko:"그분은 벌써 도착하셨군요.",en:"Oh, they have already arrived."},target:"도착하셨",options:["to be late","to arrive","to expect"],note:"Past honorific 도착하셨군요 fits polite acknowledgement."},{kind:"guess",word:{ko:"늦다",romanization:"neutda",en:"to be late",pos:"verb",nuance:"늦다 is a descriptive verb, so it behaves like an adjective in Korean. Use 늦게 for the adverb 'late': 늦게 왔어요."},sentence:{ko:"지금 출발하면 조금 늦을걸요.",en:"If you leave now, you will probably be a little late."},target:"늦을",options:["to be late","to arrive","to expect"],note:"늦을걸요 is a softened prediction."},{kind:"payoff",line:{speaker:"민서",ko:"한국어가 생각보다 재미있네요.",en:"Korean is more fun than I expected."},hl:"재미있"}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b1",chapterId:"chapter-61",index:0},{kind:"pattern",title:"문법 Grammar · A/V-네요: realizing or noticing something right now",cards:[{kind:"hunt",name:"A/V-네요: realizing or noticing something right now",sub:"",lines:[{tokens:[{pre:"밖에",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"오",mid:"네요",post:".",hit:!0}],ko:"밖에 비가 오네요.",en:"Oh, it's raining outside.",romanization:"bakke biga oneyo."},{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"김치찌개",mid:"",post:"",hit:!1},{pre:"정말",mid:"",post:"",hit:!1},{pre:"맛있",mid:"네요",post:"!",hit:!0}],ko:"이 김치찌개 정말 맛있네요!",en:"Wow, this kimchi stew is really delicious!",romanization:"i gimchijjigae jeongmal masinneyo!"}],rule:{name:"A/V-네요: realizing or noticing something right now",rows:[{when:"Verb stem (present)",add:"-네요",ex:"오다 -> 오네요 (Oh, it's coming/raining)"},{when:"Adjective stem",add:"-네요",ex:"맛있다 -> 맛있네요 (Wow, this is tasty)"},{when:"Past tense",add:"-았/었네요",ex:"끝나다 -> 끝났네요 (Oh, it's already over)"},{when:"ㄹ-stem (drop ㄹ)",add:"-네요",ex:"멀다 -> 머네요 (It's far, isn't it)"},{when:"Noun + 이다",add:"(이)네요",ex:"학생이네요 / 가수네요 (Oh, you're a student/singer)"}]},more:{func:`-네요 is the on-the-spot reaction ending. You attach it when you discover, see, hear, taste, or otherwise newly notice something at the moment of speaking. It carries a light feeling of mild surprise or fresh awareness: "Oh, it's ...!" Use it when the information just hit you, not when you are reporting a fact you already knew.`,funcLead:"-네요 is the on-the-spot reaction ending.",keyPoint:{label:"-네요 = reacting to NEW information",body:"The core trigger is newness to the speaker. If you already knew the fact and are just stating it, use plain -아/어요. The moment of fresh noticing is what makes -네요 the right choice."},pronunciation:"Past tense -았네요/-었네요 has the ㅅ assimilate to ㄴ: 끝났네요 sounds like [끈난네요], 갔네요 like [간네요]. Learners who pronounce a clear [ㅅ] here sound non-native.",pitfall:{wrong:"어제 비가 왔네요. (to report yesterday's weather you already knew)",right:"어제 비가 왔어요. / (noticing puddles now) 비가 왔네요.",explanation:"English speakers reach for -네요 whenever something feels noteworthy, but it must mark information that is new to you at the moment of speaking. Reporting a fact you already knew takes plain -아/어요; -네요 only fits when you are noticing it fresh."}}},{kind:"drill",prompt:"It's already 6. Time flies.",sentence:"벌써 6시___. 시간 빠르네요.",options:[{text:"구나",ok:!1},{text:"으ㄹ걸요",ok:!1},{text:"네요",ok:!0}],explanation:"Noticing the clock and the speed of time on the spot; 빠르네요 reacts to a realization, not a stored fact."},{kind:"drill",prompt:"You really speak Korean well!",sentence:"한국어를 정말 잘하시___.",options:[{text:"구나",ok:!1},{text:"네요",ok:!0},{text:"으ㄹ걸요",ok:!1}],explanation:"A natural compliment -- you just heard them speak and are reacting, which is why -네요 sounds warm here."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Oh, it's raining outside." (밖에 시작 · Start with 밖에.)`,tokens:["밖에","비가","오네요."],correct:"밖에 비가 오네요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Wow, this kimchi stew is really delicious!"',tokens:["이","김치찌개","정말","맛있네요!"],correct:"이 김치찌개 정말 맛있네요!",explanation:""}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b2",chapterId:"chapter-61",index:1},{kind:"words",title:"단어 Words 2 · 시간~",cards:[{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"시간이 있었으면 같이 갔을 텐데요.",en:"If I had had time, I would have gone with you."},target:"시간",options:["time","to be fun, interesting","more/less than expected"],note:"시간이 있었으면 creates the missed condition."},{kind:"guess",word:{ko:"같이",romanization:"gachi",en:"together",pos:"adverb",nuance:"같이 can mean together or like/as in other contexts; here it means together."},sentence:{ko:"같이 갔을 텐데요.",en:"I would have gone together with you."},target:"같이",options:["more/less than expected","together","already"],note:"같이 makes the regret relational, not just logistical."},{kind:"guess",word:{ko:"이미",romanization:"imi",en:"already",pos:"adverb",nuance:"이미 means 'already,' emphasizing that an action or state is completed and now fixed — often colored by 'and there's no changing it now.' The sharp contrast every learner needs is 이미 vs 벌써. Both translate as 'already,' but 이미 is neutral and factual ('it is already done, that's just the situation'), while 벌써 adds emotional surprise that it happened so fast or so soon ('already?! that quick?'). 이미 끝났어요 = a calm statement of fact; 벌써 끝났어요?! = 'it's over already?!' with raised eyebrows. So choose 이미 when calmly noting that the moment/deadline has passed, and 벌써 when reacting to unexpected speed. 이미 is native Korean and is also future-blind: it only describes things already done, never things about to happen. It pairs naturally with completed clauses and with -더라고요, -았/었- past forms."},sentence:{ko:"그분은 이미 알고 있을걸요.",en:"They probably already know."},target:"이미",options:["already","more/less than expected","together"],note:"이미 often appears in hedged assertions."},{kind:"guess",word:{ko:"예상하다",romanization:"yesanghada",en:"to expect",pos:"verb",nuance:"예상하다 (Sino-Korean 豫想, 'beforehand' + 'think' — to think ahead) means to anticipate or predict an outcome from reasoning: what you calculate will happen. It is emotionally neutral, which is exactly where it splits from 기대하다 (期待, to look forward to / hope for): you can 예상하다 a bad result, but you would never 기대하다 one, because 기대 carries positive hope. It also differs from 예측하다 (豫測, to forecast), which is more technical/measured (weather, data, trends), whereas 예상하다 is the everyday 'I figured this would happen.' It collocates with -(으)ㄹ 거라고 예상하다, 예상보다, and 예상이 빗나가다. The English-speaker pitfall is that English 'expect' covers both neutral prediction AND hopeful looking-forward; in Korean those split, so 'I'm expecting good news (hoping)' is 기대하고 있어요, while 'I expect it'll rain (forecast)' is 비가 올 거라고 예상해요. Picking the wrong one makes you sound oddly hopeful about bad outcomes."},sentence:{ko:"예상보다 사람이 많네요.",en:"There are more people than expected."},target:"예상",options:["to arrive","to expect","to be late"],note:"A changed expectation naturally takes -네요."},{kind:"guess",word:{ko:"확실하다",romanization:"hwaksilhada",en:"to be certain, sure",pos:"adjective",nuance:"확실하다 (確實, 確 'firm/sure' + 實 'real/true') expresses certainty and confidence — you're sure something is true, settled, or reliable. The adverb 확실히 ('certainly, definitely, for sure') is very common when answering or confirming (확실히 그래요 'that's definitely so'). The sharp contrast is with 분명하다: 확실하다 centres on the speaker's subjective confidence ('I'm sure of it'), while 분명하다 centres on a thing being objectively obvious/unambiguous — so 나는 확실해 ('I'm certain') but 증거가 분명해 ('the evidence is clear-cut'). It also brushes against 틀림없다 ('there's no mistake / definitely'), which is even more emphatic. Crucially, 확실하다 is for certainty, not possibility: to say 'maybe' you need 아마 ('probably') or '-ㄹ지도 몰라요' ('might'), not 확실하다. The natural adverb is 확실히 in everyday speech (확실하게 is a touch stiffer)."},sentence:{ko:"아직 확실하지는 않을걸요.",en:"It probably is not certain yet."},target:"확실하",options:["to be fun, interesting","to be difficult","to be certain, sure"],note:"-ㄹ걸요 softens a cautious assertion."},{kind:"guess",word:{ko:"분명히",romanization:"bunmyeonghi",en:"clearly, definitely",pos:"adverb",nuance:"분명히 has two jobs: it can describe saying something clearly (분명히 말하다) or strengthen certainty (‘definitely’). In the certainty use it overlaps heavily with 확실히, so context and collocation are more reliable than a rigid subjective-versus-objective split."},sentence:{ko:"분명히 말했으면 오해가 없었을 텐데요.",en:"If I had said it clearly, there would have been no misunderstanding."},target:"분명히",options:["more/less than expected","clearly, definitely","already"],note:"분명히 sharpens the missed action in a regret sentence."},{kind:"payoff",line:{speaker:"민서",ko:"어제 시간이 있었으면 같이 갔을 텐데요.",en:"If I had had time yesterday, I would have gone with you."},hl:"시간"}],canDo:"Acknowledge newly understood information with A/V-군요 / -구나 (안 막혔군요)",id:"chapter-61-b3",chapterId:"chapter-61",index:2},{kind:"pattern",title:`문법 Grammar · A/V-군요 / -구나: "I see, so that's how it is"`,cards:[{kind:"hunt",name:`A/V-군요 / -구나: "I see, so that's how it is"`,sub:"",lines:[{tokens:[{pre:"아,",mid:"",post:"",hit:!1},{pre:"그래서",mid:"",post:"",hit:!1},{pre:"어제",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"왔",mid:"군요",post:".",hit:!0}],ko:"아, 그래서 어제 못 왔군요.",en:"Ah, so that's why you couldn't come yesterday.",romanization:"a, geuraeseo eoje mot watgunyo."},{tokens:[{pre:"벌써",mid:"",post:"",hit:!1},{pre:"졸업했",mid:"구나",post:".",hit:!0},{pre:"시간",mid:"",post:"",hit:!1},{pre:"진짜",mid:"",post:"",hit:!1},{pre:"빠르다.",mid:"",post:"",hit:!1}],ko:"벌써 졸업했구나. 시간 진짜 빠르다.",en:"Oh, you already graduated. Time really flies.",romanization:"beolsseo joreophaetguna. sigan jinjja ppareuda."}],rule:{name:`A/V-군요 / -구나: "I see, so that's how it is"`,rows:[{when:"Adjective stem",add:"-군요 / -구나",ex:"춥다 -> 춥군요 / 춥구나 (Ah, it's cold)"},{when:"Verb stem (present)",add:"-는군요 / -는구나",ex:"가다 -> 가는군요 / 가는구나 (I see, you're going)"},{when:"Past tense (verb & adj)",add:"-았/었군요 / -았/었구나",ex:"아프다 -> 아팠군요 / 아팠구나 (Ah, you were sick)"},{when:"Noun + 이다",add:"(이)군요 / (이)구나",ex:"동생이군요 / 동생이구나 (Oh, it's your younger sibling)"}]},more:{func:`-군요 (polite) and -구나 (casual) express the moment of understanding: you take in new information and acknowledge it, often realizing the reason or background behind something. Where -네요 is a gut reaction to what you perceive, -군요/-구나 is the click of comprehension -- "Ah, so THAT'S why / so it's like that."`,funcLead:"-군요 (polite) and -구나 (casual) express the moment of understanding: you take in new information and acknowledge it, often realizing the reason or background beh…",keyPoint:{label:"Verbs need -는군요 in the present",body:"Adjectives and nouns attach -군요 directly (춥군요, 학생이군요), but present-tense verbs insert -는-: 가는군요, 먹는군요. Past tense is uniform for both: -았/었군요. -구나 is simply the casual (반말) version."},pronunciation:'-는군요 links the final ㄴ into the 요 in fast speech, sounding like [는군뇨]. The casual -구나 is often drawn out for feeling: 그렇구나~, signaling a thoughtful "ahh, I see."',pitfall:{wrong:"민수 씨가 요리를 잘하군요.",right:"민수 씨가 요리를 잘하는군요.",explanation:"English speakers attach -군요 straight to every stem because adjectives work that way (춥군요). But present-tense verbs require the inserted -는-: 잘하다 -> 잘하는군요, 먹다 -> 먹는군요. Forgetting -는- is the single most common mistake with this ending."}}},{kind:"drill",prompt:"So THIS is that famous restaurant.",sentence:"이게 그 유명한 식당이___.",options:[{text:"군요",ok:!0},{text:"구나",ok:!1}],explanation:"You connect what you heard before with what you now see -- a moment of recognition, not just surprise."},{kind:"drill",prompt:"I see, so Minsu is good at cooking.",sentence:"민수 씨가 요리를 잘하는___.",options:[{text:"구나",ok:!1},{text:"군요",ok:!0},{text:"으ㄹ걸요",ok:!1}],explanation:"Verb 잘하다 takes -는군요 in the present; you are registering a newly learned fact about Minsu."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Ah, so that's why you couldn't come yesterday."`,tokens:["아,","그래서","어제","못","왔군요."],correct:"아, 그래서 어제 못 왔군요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Oh, you already graduated. Time really flies."',tokens:["벌써","졸업했구나.","시간","진짜","빠르다."],correct:"벌써 졸업했구나. 시간 진짜 빠르다.",explanation:""}],canDo:"Acknowledge newly understood information with A/V-군요 / -구나 (안 막혔군요)",id:"chapter-61-b4",chapterId:"chapter-61",index:3},{kind:"words",title:"단어 Words 3 · 당연하다~",cards:[{kind:"guess",word:{ko:"당연하다",romanization:"dangyeonhada",en:"to be natural, obvious, no wonder",pos:"adjective",nuance:"당연하다 can sound dismissive if used carelessly. 당연하네요 is softer than 당연해요 because it frames the comment as realization."},sentence:{ko:"연습을 많이 했으니까 잘하는 게 당연하네요.",en:"Since you practiced a lot, no wonder you are good."},target:"당연하",options:["to be fun, interesting","to be natural, obvious, no wonder","to be difficult"],note:"-네요 makes the comment a realization, not a dismissive judgment."},{kind:"guess",word:{ko:"힘들다",romanization:"himdeulda",en:"to be hard, tiring, tough",pos:"adjective",nuance:"힘들다 literally takes 힘 (strength) + 들다 ('to take/cost'), i.e. 'it costs strength', and covers anything physically OR emotionally hard, tiring, or tough — a grueling shift, single-handed childcare, a rough stretch of life. With the -기 nominalizer it labels a hard task: 공부하기 힘들어요, 참기 힘들어요 ('studying/enduring is hard'). It is a ㄹ-stem word, so the ㄹ drops before endings beginning with ㄴ/ㅅ/ㅂ: honorific 힘드세요?, attributive 힘든 일, 힘듭니다 — not 힘들세요/힘들은. The crucial contrast is with 어렵다: 어렵다 is 'difficult to understand or solve' (a hard math problem, a tricky concept), whereas 힘들다 is 'taxing — tiring or emotionally draining'. A problem can be 어렵다 without being 힘들다, and a job can be 힘들다 (exhausting) yet not 어렵다 (intellectually hard). English-speaker pitfall: English 'hard' blurs both, so learners say 어렵다 for an exhausting day — if it drains your energy or spirit, it's 힘들어요, not 어려워요."},sentence:{ko:"많이 힘들었군요.",en:"That must have been really hard for you."},target:"힘들었",options:["to be fun, interesting","to be hard, tiring, tough","to be difficult"],note:"-군요 can acknowledge someone else's experience with empathy."},{kind:"guess",word:{ko:"알다",romanization:"alda",en:"to know",pos:"verb",nuance:"For a neutral ‘I don't know,’ Korean normally uses 모르다: 몰라요 or the softer 잘 모르겠어요. 안 알아요 is not universally wrong; context can give it ‘I don't recognize/know,’ ‘I won't find out,’ or a contrastive denial, so do not treat it as an impossible form."},sentence:{ko:"그분은 이미 알고 있을걸요.",en:"They probably already know."},target:"알고",options:["to know","to arrive","to be late"],note:"알고 있을걸요 is a common hedged assertion."},{kind:"guess",word:{ko:"모르다",romanization:"moreuda",en:"to not know",pos:"verb",nuance:"모르다 is the standalone verb 'to not know / be unaware of', the lexical opposite of 알다, and it likewise takes the object marker 을/를: 길을 몰라요. It is a 르-irregular: when an 아/어 ending attaches, the 르 stem doubles the ㄹ and the vowel drops, so 모르 + 아요 → 몰라요 (never 모르아요) and the past is 몰랐어요. The crucial register tool is 겠: 잘 모르겠어요 ('I'm not quite sure') is markedly softer and more natural than a blunt 몰라요, which can sound curt or even dismissive depending on tone, so Koreans lean on the 겠 form constantly when admitting ignorance politely. Compare 모르다 with 헷갈리다 ('to be confused / mix things up'): 모르다 is having no information at all, while 헷갈리다 is having information but getting it tangled. The English-speaker pitfall is the conjugation — applying a regular pattern to get 모르아요 instead of the irregular 몰라요 — and forgetting that the smooth, courteous version is 잘 모르겠어요."},sentence:{ko:"그렇군요. 제가 모르고 있었네요.",en:"I see. I did not know that."},target:"모르",options:["to arrive","to be late","to not know"],note:"군요 accepts the fact; 네요 marks the speaker's realization."},{kind:"payoff",line:{speaker:"지훈",ko:"처음에는 어려울 줄 알았는데 생각보다 괜찮군요.",en:"I thought it would be hard at first, but it is better than expected."},hl:"알았"}],canDo:"Offer a soft, reasoned guess with V/A-(으)ㄹ걸요 (안 늦을걸요)",id:"chapter-61-b5",chapterId:"chapter-61",index:4},{kind:"pattern",title:'문법 Grammar · V/A-(으)ㄹ걸요: "probably," a soft guess',cards:[{kind:"teach",name:'V/A-(으)ㄹ걸요: "probably," a soft guess',sub:"",rows:[{when:"Verb stem ending in vowel",add:"-ㄹ걸요",ex:"오다 -> 올걸요 (They'll probably come)"},{when:"Verb stem ending in consonant",add:"-을걸요",ex:"먹다 -> 먹을걸요 (They'll probably eat / they probably do eat)"},{when:"Past tense (guessing about the past)",add:"-았/었을걸요",ex:"가다 -> 갔을걸요 (They probably already left)"},{when:"Adjective stem",add:"-(으)ㄹ걸요",ex:"비싸다 -> 비쌀걸요 / 좋다 -> 좋을걸요 (probably expensive/good)"},{when:"ㄹ-stem (drop ㄹ, add -걸요)",add:"-ㄹ걸요",ex:"멀다 -> 멀걸요 (It's probably far)"}],examples:[{ko:"지금 가게 문 닫았을걸요.",en:"The shop is probably closed now.",romanization:"jigeum gage mun dadasseulgeoryo.",note:"A soft prediction about a present situation; -았을걸요 guesses the door is already in a closed state."},{ko:"민지 씨는 매운 거 잘 먹을걸요.",en:"Minji can probably handle spicy food well.",romanization:"minji ssineun maeun geo jal meogeulgeoryo.",note:"You're guessing from what you know of her -- not stating a fact, just a confident-but-soft hunch."}],more:{func:`-(으)ㄹ걸요 offers a tentative guess based on your own reasoning or hunch, softened so it doesn't sound too sure. It means "I think probably ..." or "it's likely that ...," and is common when answering someone gently without claiming certainty. (Written the same, -(으)ㄹ걸 그랬다 with a sighing tone means regret, "I should have ...," but here we focus on the guessing use.)`,funcLead:"-(으)ㄹ걸요 offers a tentative guess based on your own reasoning or hunch, softened so it doesn't sound too sure.",keyPoint:{label:"-(으)ㄹ걸요 = your guess, not shared knowledge",body:`Use -(으)ㄹ걸요 when the conclusion comes from your own inference and you want to stay humble about it. Compare -(으)ㄹ 거예요, which sounds more confident/declarative. -걸요 always softens, as if to say "I'm fairly sure, but don't quote me."`},pronunciation:"The 걸 is tensed to [껄]: 올걸요 sounds like [올껄요], 먹을걸요 like [머글껄요]. The sentence also rises slightly at the end, giving it its tentative, musing feel.",pitfall:{wrong:"내일 비가 올 거예요. (when you only have a vague hunch, not real evidence)",right:"내일 비가 올걸요. (a soft, unsure guess) -- use 올 거예요 only when you're genuinely confident.",explanation:'English "probably" and "will" feel interchangeable, so learners default to -(으)ㄹ 거예요 even for hunches. But -(으)ㄹ 거예요 sounds like a confident claim, while -(으)ㄹ걸요 keeps it hedged. Match the ending to how sure you actually are. Also keep -(으)ㄹ걸요 (guess) separate from -(으)ㄹ걸 그랬다 (regret, "I should have").'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The shop is probably closed now."',tokens:["지금","가게","문","닫았을걸요."],correct:"지금 가게 문 닫았을걸요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Minji can probably handle spicy food well."',tokens:["민지","씨는","매운","거","잘","먹을걸요."],correct:"민지 씨는 매운 거 잘 먹을걸요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"내일 비가 올 거예요. (when you only have a vague hunch, not real evidence)",ok:!1},{text:"내일 비가 올걸요. (a soft, unsure guess) -- use 올 거예요 only when you're genuinely confident.",ok:!0}],explanation:'English "probably" and "will" feel interchangeable, so learners default to -(으)ㄹ 거예요 even for hunches. But -(으)ㄹ 거예요 sounds like a confident claim, while -(으)ㄹ걸요 keeps it hedged. Match the ending to how sure you actually are. Also keep -(으)ㄹ걸요 (guess) separate from -(으)ㄹ걸 그랬다 (regret, "I should have").'}],canDo:"Offer a soft, reasoned guess with V/A-(으)ㄹ걸요 (안 늦을걸요)",id:"chapter-61-b6",chapterId:"chapter-61",index:5},{kind:"pattern",title:'문법 Grammar · V-았/었을 텐데(요): "it would have ..., but"',cards:[{kind:"hunt",name:'V-았/었을 텐데(요): "it would have ..., but"',sub:"",lines:[{tokens:[{pre:"어제",mid:"",post:"",hit:!1},{pre:"시간이",mid:"",post:"",hit:!1},{pre:"있었으면",mid:"",post:"",hit:!1},{pre:"같이",mid:"",post:"",hit:!1},{pre:"갔",mid:"을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"어제 시간이 있었으면 같이 갔을 텐데요.",en:"If I'd had time yesterday, I would have gone with you.",romanization:"eoje sigani isseosseumyeon gachi gasseul tendeyo."},{tokens:[{pre:"조금만",mid:"",post:"",hit:!1},{pre:"일찍",mid:"",post:"",hit:!1},{pre:"왔으면",mid:"",post:"",hit:!1},{pre:"표를",mid:"",post:"",hit:!1},{pre:"살",mid:"",post:"",hit:!1},{pre:"수",mid:"",post:"",hit:!1},{pre:"있",mid:"었을",post:"",hit:!0},{pre:"",mid:"텐데요",post:".",hit:!0}],ko:"조금만 일찍 왔으면 표를 살 수 있었을 텐데요.",en:"If you'd come just a bit earlier, you could have bought a ticket.",romanization:"jogeumman iljjik wasseumyeon pyoreul sal su isseosseul tendeyo."}],rule:{name:'V-았/었을 텐데(요): "it would have ..., but"',rows:[{when:"Verb, past supposition",add:"-았/었을 텐데(요)",ex:"오다 -> 왔을 텐데요 (They would have come)"},{when:"Often after an unreal condition -았/었으면",add:"-았/었으면 ... -았/었을 텐데요",ex:"시간이 있었으면 갔을 텐데요 (If I'd had time, I'd have gone)"},{when:"Adjective, past supposition",add:"-았/었을 텐데(요)",ex:"쉽다 -> 쉬웠을 텐데요 (It would have been easy)"},{when:"Present/future concern (contrast)",add:"-(으)ㄹ 텐데(요)",ex:"바쁘다 -> 바쁠 텐데요 (They must be busy, though)"}]},more:{func:`-았/었을 텐데(요) expresses a confident guess about an unrealized past -- what surely would have happened -- usually paired with a contrasting reality, regret, or concern. It looks back and supposes: "It would have been ... (but it wasn't / but something got in the way)." The 텐데 leaves the thought hanging, inviting sympathy or a soft follow-up rather than a blunt complaint.`,funcLead:"-았/었을 텐데(요) expresses a confident guess about an unrealized past -- what surely would have happened -- usually paired with a contrasting reality, regret, or co…",keyPoint:{label:"Past -았/었을 텐데 = unreal past; present -(으)ㄹ 텐데 = current concern",body:`Add the past -았/었- when you're supposing about something that did NOT happen (regret): 갔을 텐데요. Drop it for a present/future worry or contrast: 지금 바쁠 텐데요 ("they must be busy right now, though"). Mixing these changes the meaning from regret to ongoing concern.`},pronunciation:"텐데 is [텐데] with a clear, even tone, but the sentence-final 요 trails off and drops in pitch -- that falling, unfinished melody is what signals the lingering 'but...' feeling. Don't end it sharply.",pitfall:{wrong:"시간이 있으면 같이 갔을 텐데요. (present 있으면 with a past-regret result)",right:"시간이 있었으면 같이 갔을 텐데요.",explanation:'For regret about the past, the IF-clause must also be past-unreal: 있었으면, not 있으면. English "if I had time" hides the tense, so learners use present 있으면 and clash with the past 갔을 텐데요. Match both halves to the unreal past: 있었으면 ... 갔을 텐데요.'}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "If I'd had time yesterday, I would have gone with you." (어제 시작 · Start with 어제.)`,tokens:["어제","시간이","있었으면","같이","갔을","텐데요."],correct:"어제 시간이 있었으면 같이 갔을 텐데요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"시간이 있으면 같이 갔을 텐데요. (present 있으면 with a past-regret result)",ok:!1},{text:"시간이 있었으면 같이 갔을 텐데요.",ok:!0}],explanation:'For regret about the past, the IF-clause must also be past-unreal: 있었으면, not 있으면. English "if I had time" hides the tense, so learners use present 있으면 and clash with the past 갔을 텐데요. Match both halves to the unreal past: 있었으면 ... 갔을 텐데요.'}],canDo:"Suppose about an unrealized past with V-았/었을 텐데(요) (늦었을 텐데요)",id:"chapter-61-b7",chapterId:"chapter-61",index:6},{kind:"pattern",title:"문법 Grammar · -군요 vs -네요: both react, but not the same way",cards:[{kind:"hunt",name:"-군요 vs -네요: both react, but not the same way",sub:"",lines:[{tokens:[{pre:"어,",mid:"",post:"",hit:!1},{pre:"눈이",mid:"",post:"",hit:!1},{pre:"오",mid:"네요",post:"!",hit:!0}],ko:"어, 눈이 오네요!",en:"Oh, it's snowing!",romanization:"eo, nuni oneyo!"},{tokens:[{pre:"아,",mid:"",post:"",hit:!1},{pre:"그래서",mid:"",post:"",hit:!1},{pre:"늦으셨",mid:"군요",post:".",hit:!0}],ko:"아, 그래서 늦으셨군요.",en:"Ah, so that's why you were late.",romanization:"a, geuraeseo neujeusyeotgunyo."}],rule:{name:"-군요 vs -네요: both react, but not the same way",rows:[{when:"Fresh, direct noticing (see/hear/feel now)",add:"-네요",ex:"비가 오네요 (Oh, it's raining)"},{when:"Acknowledging a fact/explanation you just learned",add:"-군요 / -구나",ex:"아, 그렇군요 (Ah, I see)"},{when:"Verb present: -네요 (no 는) vs -는군요 (needs 는)",add:"-네요 / -는군요",ex:"가네요 / 가는군요"},{when:"Reacting to a reason (그래서 ...)",add:"often -군요",ex:"그래서 못 왔군요 (So that's why you couldn't come)"}]},more:{func:`-네요 and -군요 both respond to new information, but with a different feel. -네요 is an immediate, conversational gut reaction to what you directly perceive right now ("oh, look at that"). -군요 is a slightly more composed acknowledgement -- you take in a fact or explanation and register it ("I see, so that's the case"). Knowing which one to reach for keeps your reactions sounding natural.`,funcLead:"-네요 and -군요 both respond to new information, but with a different feel.",keyPoint:{label:"Perceiving now -> -네요; registering a fact -> -군요",body:"If you're reacting to something you directly sense at this moment (taste, weather, someone's arrival), -네요 sounds warm and natural. If you're acknowledging information or a reason that just clicked, -군요 fits. -군요 can sound stiff for simple sensory reactions, and -네요 can sound under-reactive for absorbing a full explanation."},pronunciation:"그렇군요 is pronounced [그러쿠뇨] (ㅎ + ㄱ tenses/aspirates to ㅋ), and 그렇네요 is [그런네요] (ㅎ assimilates to ㄴ before ㄴ). Both are extremely common backchannels -- saying them clearly helps you sound like an engaged listener.",pitfall:{wrong:"(처음 맛보고) 와, 이거 맛있군요!",right:"(처음 맛보고) 와, 이거 맛있네요!",explanation:`For a direct, in-the-moment sensory reaction (taste, weather, a view), Korean prefers -네요; -군요 sounds too composed or bookish there. Learners over-use -군요 because it's taught as "I see," but reserve it for acknowledging facts or reasons, not for spontaneous "wow, this is good!" reactions.`}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Oh, it's snowing!"`,tokens:["어,","눈이","오네요!"],correct:"어, 눈이 오네요!",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Ah, so that's why you were late."`,tokens:["아,","그래서","늦으셨군요."],correct:"아, 그래서 늦으셨군요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"(처음 맛보고) 와, 이거 맛있네요!",ok:!0},{text:"(처음 맛보고) 와, 이거 맛있군요!",ok:!1}],explanation:`For a direct, in-the-moment sensory reaction (taste, weather, a view), Korean prefers -네요; -군요 sounds too composed or bookish there. Learners over-use -군요 because it's taught as "I see," but reserve it for acknowledging facts or reasons, not for spontaneous "wow, this is good!" reactions.`}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b8",chapterId:"chapter-61",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Friends react to a class, a late schedule, and a missed chance while choosing endings that match their stance.",lines:[{speaker:"민서",ko:"한국어가 생각보다 재미있네요.",en:"Korean is more fun than I expected.",romanization:"hangugeoga saenggakboda jaemiinneyo."},{speaker:"지훈",ko:"처음에는 어려울 줄 알았는데 생각보다 괜찮군요.",en:"I thought it would be hard at first, but it is better than expected.",romanization:"cheoeumeneun eoryeoul jul aranneunde saenggakboda gwaenchanhgunyo."},{speaker:"민서",ko:"선생님은 벌써 도착하셨네요.",en:"Oh, the teacher has already arrived.",romanization:"seonsaengnimeun beolsseo dochakhasyeonneyo."},{speaker:"지훈",ko:"지금 출발하면 우리는 조금 늦을걸요.",en:"If we leave now, we will probably be a little late.",romanization:"jigeum chulbalhamyeon urineun jogeum neujeulgeoryo."},{speaker:"민서",ko:"어제 시간이 있었으면 같이 갔을 텐데요.",en:"If I had had time yesterday, I would have gone with you.",romanization:"eoje sigani isseosseumyeon gachi gasseul tendeyo."},{speaker:"지훈",ko:"연습을 많이 했으니까 잘하는 게 당연하네요.",en:"Since you practiced a lot, no wonder you are good.",romanization:"yeonseubeul mani haesseunikka jalhaneun ge dangyeonhaneyo."}]},{kind:"order",prompt:"Build: 'Oh, they already arrived.'",tokens:["아,","벌써 도착했군요"],correct:"아, 벌써 도착했군요",explanation:"-군요 acknowledges or takes in information with a stronger “I see” feeling. 벌써 adds the surprise that it already happened."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"처음에는 어려울 줄 알았는데 생각보다 괜찮군요.",options:[{text:"지훈",ok:!0},{text:"민서",ok:!1}],explanation:"I thought it would be hard at first, but it is better than expected."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Korean is more fun than I expected."',sentence:"한국어가 ___ 재미있네요.",options:[{text:"벌써",ok:!1},{text:"같이",ok:!1},{text:"생각보다",ok:!0}],explanation:""}],canDo:"React to something noticed right now with A/V-네요 (벌써 도착했네요)",id:"chapter-61-b9",chapterId:"chapter-61",index:8},{kind:"reading",title:"읽기 Reading · 끝 어미가 태도를 바꾼다",cards:[{kind:"read",title:"끝 어미가 태도를 바꾼다",chunks:['민서는 첫 수업을 듣고 "생각보다 재미있네요"라고 말했다. 방금 느낀 놀라움이라서 -네요가 자연스러웠다. 지훈은 설명을 듣고 "그렇군요"라고 했다. 새 정보를 받아들이는 조금 더 차분한 반응이었다.','수업이 끝난 뒤 선생님이 이미 도착한 것을 보고 민서는 "벌써 도착하셨네요"라고 했고, 지훈은 시간을 보더니 "지금 출발하면 늦을걸요"라고 했다. 나중에 민서는 약속에 가지 못한 일을 떠올리며 "시간이 있었으면 같이 갔을 텐데요"라고 말했다. 같은 사실도 끝 어미가 달라지면 놀람, 인정, 예측, 아쉬움이 서로 다르게 들린다.'],translation:'After the first class, Minseo said, "It is more fun than I expected." Because it was a surprise she had just felt, -네요 was natural. Jihoon listened to an explanation and said, "I see." That was a calmer acknowledgement of new information. After class, Minseo saw that the teacher had already arrived and said, "Oh, the teacher has already arrived." Jihoon looked at the time and said, "If we leave now, we will probably be late." Later, Minseo remembered not being able to go to an appointment and said, "If I had had time, I would have gone with you." Even with the same facts, the final ending changes whether the sentence sounds like surprise, acknowledgement, prediction, or regret.',qas:[{q:"민서는 첫 수업 뒤에 어떤 어미를 사용했어요?",a:"-네요를 사용했어요."},{q:'지훈이 "늦을걸요"라고 한 이유는 무엇이에요?',a:"지금 출발하면 늦을 것 같다고 부드럽게 예측했기 때문이에요."},{q:"-았/었을 텐데요는 어떤 느낌을 나타냈어요?",a:"과거에 이루어지지 않은 일에 대한 아쉬움이나 후회를 나타냈어요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:'민서는 첫 수업을 듣고 "___ 재미있네요"라고 말했다.',options:[{text:"분명히",ok:!1},{text:"재미있다",ok:!1},{text:"생각보다",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:'수업이 끝난 뒤 선생님이 이미 도착한 것을 보고 민서는 "___ 도착하셨네요"라고 했고, 지훈은 시간을 보더니 "지금 출발하면 늦을걸요"라고 했다.',options:[{text:"분명히",ok:!1},{text:"재미있다",ok:!1},{text:"벌써",ok:!0}],explanation:""}],canDo:"Acknowledge newly understood information with A/V-군요 / -구나 (안 막혔군요)",id:"chapter-61-b10",chapterId:"chapter-61",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which ending fits a fresh realization after trying Korean class?",sentence:null,options:[{text:"생각보다 재미있네요.",ok:!0},{text:"생각보다 재미있기로 했어요.",ok:!1},{text:"생각보다 재미있을 수밖에 없었어요.",ok:!1}],explanation:"-네요 marks fresh realization."},{kind:"drill",prompt:"Which sentence is a softened prediction?",sentence:null,options:[{text:"지금 출발하면 조금 늦을걸요.",ok:!0},{text:"지금 출발하면 조금 늦었군요.",ok:!1},{text:"지금 출발하면 조금 늦었을 텐데요.",ok:!1}],explanation:"-ㄹ걸요 gives a hedged assertion or prediction."},{kind:"drill",prompt:"Which sentence expresses regret about a missed past condition?",sentence:null,options:[{text:"시간이 있었으면 같이 갔을 텐데요.",ok:!0},{text:"시간이 있으면 같이 가네요.",ok:!1},{text:"시간이 있어서 같이 갈걸요.",ok:!1}],explanation:"-았/었으면 ... -았/었을 텐데요 frames an unreal past."},{kind:"drill",prompt:"생각___ 더 재미있네요. (It is more fun than I expected.)",sentence:null,options:[{text:"보다",ok:!0},{text:"에",ok:!1},{text:"를",ok:!1}],explanation:"생각보다 means compared with what I thought or expected. -네요 then reacts to the fresh realization."},{kind:"drill",prompt:"You just tried the class and are surprised it is fun. Which fits?",sentence:null,options:[{text:"생각보다 재미있네요.",ok:!0},{text:"생각보다 재미있을걸요.",ok:!1},{text:"생각보다 재미있었을 텐데요.",ok:!1}],explanation:"-네요 fits fresh realization from direct experience. -ㄹ걸요 is a guess, and -었을 텐데요 is regret/hypothetical."}],canDo:"Offer a soft, reasoned guess with V/A-(으)ㄹ걸요 (안 늦을걸요)",id:"chapter-61-b11",chapterId:"chapter-61",index:10}]},{id:"chapter-62",number:62,title:"이/가 · 은/는",goal:"Use 이/가 for new information, focused answers, and existence predicates.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 조사~",cards:[{kind:"guess",word:{ko:"조사",romanization:"josa",en:"grammatical particle",pos:"noun",nuance:"Here 조사 means the grammatical particle 助詞 ('helping word'), not 조사 調査 ('survey/investigation'). Korean particles attach to the end of a noun or noun phrase and do more than label subject, object, or location: they also manage topic, contrast, inclusion, limitation, and the speaker's focus. That is why 은/는 and 이/가 cannot be swapped mechanically, and why 에/에서 depends on the Korean predicate rather than on one English preposition. At C1, particle choice is part of information design. 제가 맡겠습니다 selects 'me' as the person who will take the task, while 저는 맡겠습니다 sets 'me' as the topic and may contrast the speaker with others. Spoken Korean can omit predictable particles, but omission is not random: a short message may say 자료 확인했습니다, while a complex or potentially ambiguous sentence often needs 자료를 확인했습니다. Particles can also stack in a fixed order—회의에서도, 이 사안에 대해서는—so a single syllable can alter both grammar and stance without changing the vocabulary."},sentence:{ko:"은/는과 이/가는 대표적인 조사예요.",en:"은/는 and 이/가 are representative Korean particles."},target:"조사",options:["friend","grammatical particle","phone call"],note:"Here 조사 means a grammatical particle, not a survey or investigation."},{kind:"guess",word:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",nuance:"친구 can mean friend or same-age peer depending on context."},sentence:{ko:"친구가 전화했어요. 그 친구는 자주 전화하지 않아요.",en:"A friend called. That friend does not call often."},target:"친구",options:["grammatical particle","phone call","friend"],note:"First mention uses 가; continued topic uses 는."},{kind:"guess",word:{ko:"전화",romanization:"jeonhwa",en:"phone call",pos:"noun",nuance:"전화 is a noun, but 전화하다 is the verb “to call.”"},sentence:{ko:"메시지는 보내지만 전화는 잘 안 해요.",en:"I send messages, but I do not call much."},target:"전화",options:["phone call","grammatical particle","friend"],note:"전화는 contrasts calls with messages."},{kind:"guess",word:{ko:"연락",romanization:"yeollak",en:"contact, getting in touch",pos:"noun",nuance:"연락(連絡) is Sino-Korean — 連 'connect/link' + 絡 'tie, network' — literally 'to link up,' and it covers ANY channel of reaching a person: a call, a text, a message, an email. The near-synonym to contrast is 소식: 연락 is the ACT/CHANNEL of getting in touch ('drop me a line'), while 소식 is the CONTENT/word about how someone is. Compare 통화(通話) 'a phone call (specifically)' — narrower than 연락. The crucial grammar quirk for English speakers: 연락 flips between particles. When YOU reach out it's 연락을 하다 / 연락하다 (object 를), but when contact COMES to you it's 연락이 오다 and reachability is 연락이 되다 (subject 이/가) — saying 연락을 오다 is a classic error. Also, English 'contact someone' has a direct object, so learners drop the person-marking 한테/에게: it should be 친구한테 연락하다, and incoming contact is 친구한테서/에게서 연락이 오다. 연락처 (with 처) means your number/details, not the verb."},sentence:{ko:"누가 먼저 연락했어요? 제가 먼저 연락했어요.",en:"Who contacted first? I contacted first."},target:"연락",options:["contact, getting in touch","grammatical particle","friend"],note:"제가 answers 누가 with focus."},{kind:"guess",word:{ko:"메시지",romanization:"mesiji",en:"message",pos:"noun",nuance:"메시지 is the loanword from English 'message' and covers chat/app messages broadly (a KakaoTalk message, a DM); the everyday near-synonym 문자 (literally 文字 'letters/characters') specifically means an SMS text, so '문자 보내' = 'text me' while '메시지' is the wider term. There's also 카톡, the verb-able brand shorthand for a KakaoTalk message, used constantly in real life (카톡 보낼게 'I'll Kakao you'). The English-speaker pitfall is twofold: first, the recipient is marked with 한테/에게 ('to a person'), not the English bare object — 친구한테 메시지를 보내다, where 친구한테 = 'to my friend' and 메시지를 is the thing sent; second, the message arriving uses intransitive 오다 with 이/가 (메시지가 오다), but you sending it uses 보내다 with 을/를 (메시지를 보내다). Don't carry the English 'send him a message' double-object pattern straight over."},sentence:{ko:"메시지는 자주 보내지만 전화는 잘 안 해요.",en:"I send messages often, but I do not call much."},target:"메시지",options:["grammatical particle","message","friend"],note:"은/는 makes the contrast visible."},{kind:"guess",word:{ko:"문자",romanization:"munja",en:"text message",pos:"noun",nuance:"문자 (文字, 'written character/letter') in daily speech is the everyday word for an SMS text message — short for 문자 메시지. The pitfall is its double life: literally 문자 means written characters/letters (e.g. 한글은 한국의 문자예요, 'Hangul is Korea's writing system'), so context decides. Crucially, 문자 is NOT a paper letter in the mail — that is 편지 (便紙). The near-synonym 카톡 (a KakaoTalk message) is what most people actually send now; 문자 specifically implies the carrier SMS (often bank/official notices), while a casual chat is 카톡 or 메시지. Register is neutral. Habitual collocations: 문자를 보내다/받다, 문자가 오다, 문자를 확인하다, 문자로 연락하다, and the source pattern 은행/회사에서 문자가 오다. Particle traps: 'by text' is 문자로 (means); the sender/source is marked 에서 for organizations (은행에서) or 한테서/에게서 for people. English speakers often want 'text' as a verb — Korean splits it into 문자를 보내다 (send a text)."},sentence:{ko:"문자는 왔는데 전화는 안 왔어요.",en:"A text came, but no phone call came."},target:"문자",options:["grammatical particle","friend","text message"],note:"문자는 and 전화는 contrast two channels."},{kind:"guess",word:{ko:"누구",romanization:"nugu",en:"who",pos:"questionWord",nuance:"누구 changes naturally with particles: 누구를, 누구한테, 누구하고."},sentence:{ko:"누가 먼저 연락했어요?",en:"Who contacted first?"},target:null,options:["grammatical particle","friend","who"],note:"누구 + 가 contracts to 누가."},{kind:"guess",word:{ko:"먼저",romanization:"meonjeo",en:"first",pos:"adverb",nuance:"먼저 means 'first / beforehand / ahead (of others)' — it ranks one action or person EARLIER in a sequence or in time. The key contrast is 먼저 vs 처음: 먼저 is relative ('before the other thing/person', e.g. 먼저 가요 'go ahead of you'), while 처음 means 'the first time ever / the beginning' (처음 만나요 'meeting for the first time'). So 먼저 봤어요 = 'I saw it first (before you)', but 처음 봤어요 = 'I saw it for the first time'. 먼저 is also a courtesy word: 먼저 가세요 / 먼저 하세요 ('go ahead, you first') is everyday politeness, and 먼저 갈게요 / 먼저 들어가겠습니다 softens leaving before others. Register-neutral. The English-speaker pitfall is mapping every 'first' to one word — choose 먼저 for order-relative 'first/ahead', but 처음 for 'first-ever/at first', and keep 먼저 before the verb."},sentence:{ko:"오늘은 제가 먼저 연락했어요.",en:"Today, I contacted first."},target:"먼저",options:["often","first","grammatical particle"],note:"오늘은 contrasts today; 제가 identifies the actor."},{kind:"guess",word:{ko:"자주",romanization:"jaju",en:"often",pos:"adverb",nuance:"자주 means 'often / frequently' and describes how many TIMES an action repeats over a period — it answers 얼마나 자주 ('how often'), never how fast or how well. The frequency scale runs 항상(always) > 자주(often) > 가끔(sometimes) > 거의 안(hardly), and 자주 sits high but short of 'always'. Its natural opposite is 가끔; learners confuse 자주 with 빨리(quickly), but 자주 is about count of occurrences while 빨리 is about speed of one action — 빨리 먹어요 means 'eats fast', 자주 먹어요 means 'eats often'. Register-neutral, fine for everyone. The big English-speaker pitfall is word order: English lets you say 'I go there often' with the adverb last, but Korean glues 자주 immediately before the verb (자주 가요), and even before 안/못 in negatives (자주 안 가요)."},sentence:{ko:"그 친구는 자주 전화해요?",en:"Does that friend call often?"},target:"자주",options:["first","often","grammatical particle"],note:"은/는 keeps the friend as the topic while asking about habit."},{kind:"payoff",line:{speaker:"민서",ko:"어제 친구가 전화했어요.",en:"A friend called yesterday."},hl:"친구"}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b1",chapterId:"chapter-62",index:0},{kind:"pattern",title:"문법 Grammar · 이/가",cards:[{kind:"hunt",name:"이/가",sub:"a new or focused subject (new information)",lines:[{tokens:[{pre:"비",mid:"가",post:"",hit:!0},{pre:"와요.",mid:"",post:"",hit:!1}],ko:"비가 와요.",en:"It's raining.",romanization:"biga wayo."},{tokens:[{pre:"누",mid:"가",post:"",hit:!0},{pre:"한국어를",mid:"",post:"",hit:!1},{pre:"가르쳐요?",mid:"",post:"",hit:!1}],ko:"누가 한국어를 가르쳐요?",en:"Who teaches Korean?",romanization:"nuga hangugeoreul gareuchyeoyo?"}],rule:{name:"이/가",rows:[{when:"subject noun ends in a consonant",add:"+ 이",ex:"선생님 → 선생님이"},{when:"subject noun ends in a vowel",add:"+ 가",ex:"친구 → 친구가"},{when:"answering 누가/뭐가 (who/what)",add:"marked noun = the answer",ex:"누가 왔어요? → 동생이 왔어요."}]},more:{func:"The subject marker 이/가 spotlights WHO or WHAT does or is something. Use it when the subject is new to the conversation, when it answers a 'who?'/'what?' question, or when you want the listener's attention on that exact element. It introduces; it does not assume.",funcLead:"The subject marker 이/가 spotlights WHO or WHAT does or is something.",keyPoint:{label:"이/가 = new and in focus",body:"Compare 누가 왔어요? — 친구가 왔어요 (NEW: 가) with 친구는 언제 와요? (already-known friend: 는). 이/가 answers 'who/what'; 은/는 talks ABOUT a known thing."},pronunciation:"이 after a consonant links smoothly: 선생님이 sounds like 선생니미; 책이 like 채기. The final consonant slides onto 이.",pitfall:{wrong:"비는 와요.",right:"비가 와요.",explanation:"English has no topic/subject split, so learners default to one marker for everything. Brand-new, on-the-scene information (weather, sudden events, answers to 'who/what') takes 이/가, not 은/는."}}},{kind:"drill",prompt:"My friend lives in Busan.",sentence:"제 친구___ 부산에 살아요.",options:[{text:"이",ok:!1},{text:"은",ok:!1},{text:"가",ok:!0}],explanation:"Introducing the friend for the first time, so 가 presents the new subject."},{kind:"drill",prompt:"There's a problem.",sentence:"문제___ 있어요.",options:[{text:"가",ok:!0},{text:"이",ok:!1},{text:"은",ok:!1}],explanation:"Existence sentences with 있다/없다 present new info, so the thing takes 이/가."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Who teaches Korean?"',tokens:["누가","한국어를","가르쳐요?"],correct:"누가 한국어를 가르쳐요?",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"비가 와요.",ok:!0},{text:"비는 와요.",ok:!1}],explanation:"English has no topic/subject split, so learners default to one marker for everything. Brand-new, on-the-scene information (weather, sudden events, answers to 'who/what') takes 이/가, not 은/는."}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b2",chapterId:"chapter-62",index:1},{kind:"words",title:"단어 Words 2 · 평소~",cards:[{kind:"guess",word:{ko:"평소",romanization:"pyeongso",en:"usually, normally",pos:"noun",nuance:"평소 is a Sino-Korean noun, 平素 'level-plain / ordinary times', meaning your normal, everyday baseline — the way things usually are when nothing special is going on. Because it's fundamentally a noun, it leans on particles: in conversation it's overwhelmingly 평소에 'usually', or comparative 평소보다 'than usual', or 평소처럼 'as usual'. Its job is to set a default against which you contrast today (평소보다 많아요 'more than usual'). The near-synonym 보통 普通 also means 'usually/ordinarily' and overlaps heavily; the subtle feel is that 평소 points to 'one's ordinary times/baseline' while 보통 states 'as a general rule', so 평소에 운동해요 and 보통 운동해요 are both fine. The English-speaker trap is treating 평소 like a bare adverb such as 항상 and dropping the particle — 'I usually...' wants 평소에, not lonely 평소. It's also not a verb, so never conjugate it; pair it with 에, 보다, 처럼, and attributive nouns (실력, 생활)."},sentence:{ko:"평소에는 메시지를 보내는데 오늘은 전화했어요.",en:"Usually they send messages, but today they called."},target:"평소",options:["grammatical particle","usually, normally","friend"],note:"평소에는 contrasts the usual pattern with today."},{kind:"guess",word:{ko:"오늘",romanization:"oneul",en:"today",pos:"noun",nuance:"오늘 usually does not need 에. 오늘에 sounds unnatural for ordinary “today.”"},sentence:{ko:"오늘은 제가 먼저 연락했어요.",en:"Today, I contacted first."},target:"오늘",options:["grammatical particle","today","friend"],note:"오늘은 contrasts today with other days."},{kind:"guess",word:{ko:"보내다",romanization:"bonaeda",en:"to send",pos:"verb",nuance:"보내다 means to send something or someone away from you toward another place or person — a message, a parcel, even a child to school — and it also carries the everyday idiom 시간을 보내다, 'to spend/pass time'. The sharp contrast is 보내다 vs 주다: 주다 (to give) is a face-to-face hand-over where giver and receiver are together, while 보내다 implies distance — the thing travels to reach the other person. So you 줘요 a gift you hand over now, but 보내요 a gift you mail; using 주다 for a text or parcel sounds like you are physically handing it across. The recipient particle is 에게/한테 (and honorific 께): 부모님께 보내다. For the 'spend time' sense, English speakers wrongly reach for 쓰다 (to use/spend money) — but time is 보내다, not 쓰다: 좋은 시간 보내세요! is the standard 'have a good time'. It is a plain native verb, regular (stem 보내- + 어 contracts to 보내, past 보냈어요), neutral register. The means/channel takes 으로 (이메일로, 택배로). Common collocations: 문자·이메일을 보내다, 소포·택배를 보내다, 시간·세월을 보내다, 사람을 보내다."},sentence:{ko:"메시지는 자주 보내지만 전화는 잘 안 해요.",en:"I send messages often, but I do not call much."},target:"보내",options:["grammatical particle","to send","friend"],note:"The object 메시지 takes 를; the contrast uses 는."},{kind:"guess",word:{ko:"질문",romanization:"jilmun",en:"question",pos:"noun",nuance:"질문 is Sino-Korean 質問 — 質 'substance/inquire into' + 問 'ask', literally 'to inquire and ask', i.e. a question put to someone. The set verb is 질문을 하다 (or the single verb 질문하다); the person you ask takes 에게/한테 (or honorific 께 for a teacher): 선생님께 질문을 하다. Its natural partner is 대답/답(答) — a 질문 is answered by a 대답. The big redundancy trap for English speakers is 질문을 물어보다 ✗: 물어보다 already means 'to ask', so this literally says 'ask a question-asking' — say either 질문을 하다 or just 물어보다, never both. Distinguish 질문 (a question seeking information/an answer) from 문제(問題, a 'problem' or exam item) — '3 questions on the test' are 문제 세 개, but 'I have a question for you' is 질문이 있어요. Note answering takes 에: 질문에 답하다, not 질문을 답하다."},sentence:{ko:"질문은 쉬웠는데 대답이 어려웠어요.",en:"The question was easy, but the answer was difficult."},target:"질문",options:["grammatical particle","question","friend"],note:"질문은 is the contrastive topic."},{kind:"guess",word:{ko:"대답",romanization:"daedap",en:"answer, reply",pos:"noun",nuance:"대답 is Sino-Korean 對答 — 對 'face/respond-to' + 答 'reply', literally 'a facing reply', i.e. the spoken/written response to a question or call. It is the natural partner of 질문(質問): a 질문 is met by a 대답, and the verb is 대답을 하다 / 대답하다. The sharp contrast to master is 대답 vs 정답(正答, 正 'correct' + 答): 대답 is simply 'a/the response someone gives' (it can be right or wrong), while 정답 is specifically 'the correct answer' to a problem — so on a quiz '정답은 3번이에요' = 'the correct answer is number 3', but 그 학생의 대답 = 'that student's response'. Also note 답 alone is a shorter everyday form of both. The particle pitfall mirrors 질문: you answer a question with 에 — 질문에 대답하다 / 질문에 답하다, NOT 질문을 대답하다. English 'answer the phone/door' does not use 대답 either — that is 전화를 받다 / 문을 열다."},sentence:{ko:"대답이 어려웠어요.",en:"The answer was difficult."},target:"대답",options:["answer, reply","grammatical particle","friend"],note:"대답이 introduces the part that was difficult."},{kind:"guess",word:{ko:"의견",romanization:"uigyeon",en:"opinion",pos:"noun",nuance:"의견 is Sino-Korean (意見, 意 'mind/intention' + 見 'view/seeing'), literally 'how your mind sees something' — a considered position or judgment you can defend, usually about a topic, plan, or issue. The crucial contrast is with 생각: 생각 is the broad word for any 'thought' that crosses your mind, while 의견 is specifically a stance offered for discussion or evaluation, so a meeting asks for 의견 (positions), not just 생각 (musings). It is register-neutral and very common in school and workplace settings; the polite request 의견을 여쭤봐도 될까요? raises it a notch. Natural collocations: 의견을 말하다/내다/제시하다 (state/put forward), 의견이 다르다/같다 (disagree/agree), 의견을 모으다 (gather opinions), 반대 의견 (an opposing view). The English-speaker pitfall is reaching for 의견 every time you'd say 'I think' — 'I think it's good' is 좋은 것 같아요 or 좋다고 생각해요, NOT 좋은 의견이에요; 의견 is the opinion itself as a thing, not the act of thinking. Also don't say 의견하다 — there is no such verb; you 의견을 말하다."},sentence:{ko:"제 의견은 생각이 조금 달라요.",en:"As for my opinion, the thinking is a little different."},target:"의견",options:["opinion","grammatical particle","friend"],note:"의견은 frames the topic; 생각이 states what differs."},{kind:"guess",word:{ko:"생각",romanization:"saenggak",en:"thought, idea",pos:"noun",nuance:"생각 is the native Korean catch-all noun for a 'thought', 'idea', or 'opinion' — anything that happens in the mind: memories, intentions, plans, beliefs, judgments. It is far broader and softer than Sino-Korean 의견 (a defined stance for discussion): 좋은 생각이에요 praises an idea, whereas 의견 frames it as a formal position. It also overlaps with 마음 ('heart/mind' as feeling/will), but 생각 is the cognitive 'thinking' side while 마음 is the emotional/volitional side — 생각이 바뀌다 = I changed my mind (reasoning), 마음이 바뀌다 = my heart changed (feelings). Register-neutral and one of the highest-frequency nouns in the language. Key collocations: 생각이 나다 (come to mind/remember), 생각이 들다 (a thought arises), 생각해 보다 (think it over), ~라고 생각하다 (to think that ~). The big English-speaker pitfall is the verb pattern: 'I think that it's true' is 사실이라고 생각해요 with the quotative ~라고, not 사실 생각해요; and 'I remember' is most naturally 생각나요, not a literal translation. Don't confuse 생각나다 (it comes to mind, intransitive) with 생각하다 (to actively think, transitive)."},sentence:{ko:"그 생각은 좋은데 이유가 부족해요.",en:"That idea is good, but the reason is lacking."},target:"생각",options:["thought, idea","grammatical particle","friend"],note:"생각은 frames the idea; 이유가 introduces the problem."},{kind:"guess",word:{ko:"문제",romanization:"munje",en:"problem, issue",pos:"noun",nuance:"문제(問題, 'ask + topic') has two everyday senses English keeps apart: a trouble or difficulty ('we have a problem') AND a question on a test or exercise ('problem 3'). Crucially, both are solved with the same verb 풀다 (literally 'to untie/loosen') — 문제를 풀다 works for a math item and for a real-life difficulty alike, where English would switch to 'answer' vs 'solve.' Other key partners: 문제가 생기다 (a problem arises), 문제가 되다 (to become an issue), and the handy one-word 문제없어요 ('no problem'). Contrast 문제 with 질문 (a question you ASK someone to get information) — a test 문제 is a problem to solve, but raising your hand to ask is 질문하다, not 문제하다. The English-speaker pitfall is the subject/object split: existence and arising take 이 (문제가 있다/생기다), but solving takes 를 (문제를 풀다) — learners often say 문제가 풀어요."},sentence:{ko:"이 문제는 이유가 제일 중요해요.",en:"For this issue, the reason is the most important thing."},target:"문제",options:["grammatical particle","problem, issue","friend"],note:"문제는 sets the frame; 이유가 is the key subject."},{kind:"guess",word:{ko:"이유",romanization:"iyu",en:"reason",pos:"noun",nuance:"이유 is Sino-Korean (理由, 理 'principle/logic' + 由 'cause/origin'), the 'reason' or grounds behind something — the answer to 'why?'. Its sharpest contrast is with 원인 (原因, 'cause'): 이유 is the justification or motive a person gives ('the reason I'm late'), often subjective and explainable, while 원인 is the objective, often impersonal cause of a result ('the cause of the fire', 화재의 원인). So you ask a friend 무슨 이유로 늦었어? but an investigator looks for the 원인 of an accident. Also distinguish 까닭, a more native, slightly literary synonym of 이유. Register-neutral and extremely common. Core collocations: 이유가 있다/없다, 이유를 묻다/대다/설명하다, 이유 없이 (for no reason), 그런 이유로 (for that reason), ~는 이유는 (the reason that ~ is). The English-speaker pitfall: don't bolt 이유 onto a 'because' clause redundantly — Korean already has 왜냐하면 ... 때문이에요 / ~기 때문에 to say 'because', so '왜냐하면 그 이유는...' is clunky; pick one. Also, 'the reason is because...' should be ~는 이유는 ... 때문이에요, where the sentence ends in 때문이다, not a second 이유."},sentence:{ko:"무엇이 중요해요? 이유가 중요해요.",en:"What is important? The reason is important."},target:"이유",options:["grammatical particle","friend","reason"],note:"이유가 answers 무엇이."},{kind:"payoff",line:{speaker:"민서",ko:"아니요. 평소에는 메시지를 보내는데 오늘은 제가 먼저 연락했어요.",en:"No. Usually they send messages, but today I contacted them first."},hl:"평소"}],canDo:"Set up an already-known topic with 은/는 (저는 …, 그 친구는 …)",id:"chapter-62-b3",chapterId:"chapter-62",index:2},{kind:"pattern",title:"문법 Grammar · 은/는",cards:[{kind:"hunt",name:"은/는",sub:"topic continuity (an already-known topic)",lines:[{tokens:[{pre:"저",mid:"는",post:"",hit:!0},{pre:"학생이에요.",mid:"",post:"",hit:!1}],ko:"저는 학생이에요.",en:"I'm a student.",romanization:"jeoneun haksaengieyo."},{tokens:[{pre:"오늘",mid:"은",post:"",hit:!0},{pre:"날씨가",mid:"",post:"",hit:!1},{pre:"좋아요.",mid:"",post:"",hit:!1}],ko:"오늘은 날씨가 좋아요.",en:"The weather is nice today.",romanization:"oneureun nalssiga joayo."}],rule:{name:"은/는",rows:[{when:"topic noun ends in a consonant",add:"+ 은",ex:"선생님 → 선생님은"},{when:"topic noun ends in a vowel",add:"+ 는",ex:"저 → 저는"},{when:"stating a general fact",add:"topic + comment",ex:"강아지는 귀여워요. (Puppies are cute.)"}]},more:{func:"The topic marker 은/는 sets up what the sentence is ABOUT. Use it for something already known, already mentioned, or generally assumed — the shared starting point. It says 'as for X…' and then comments on it. It carries old information, not new.",funcLead:"The topic marker 은/는 sets up what the sentence is ABOUT.",keyPoint:{label:"은/는 = old, 이/가 = new",body:"First mention introduces with 이/가; once it's on the table, you keep talking about it with 은/는. 옛날에 한 남자가 살았어요. 그 남자는… (A man lived… The man…)."},pronunciation:"은 after a consonant resyllabifies: 선생님은 → 선생니믄; 책은 → 채근. Keep 는 as a clear 'neun' with no vowel reduction.",pitfall:{wrong:"저가 학생이에요.",right:"저는 학생이에요. (or focused: 제가 했어요.)",explanation:"For self-introduction the speaker is the assumed topic, so use 저는, not 저가. Also note 저 + 가 irregularly becomes 제가 when you DO need focus ('I' as the one who did it) — 저가 is never correct."}}},{kind:"drill",prompt:"That movie was really fun.",sentence:"그 영화___ 정말 재미있었어요.",options:[{text:"는",ok:!0},{text:"은",ok:!1}],explanation:"그 영화 is already known (we both know which movie), so 는 continues it as the topic."},{kind:"drill",prompt:"As for Korean, the pronunciation is hard.",sentence:"한국어___ 발음이 어려워요.",options:[{text:"은",ok:!1},{text:"가",ok:!1},{text:"는",ok:!0}],explanation:"한국어 is the established topic; the new comment is about its 발음 (which itself takes 이)."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The weather is nice today."',tokens:["오늘은","날씨가","좋아요."],correct:"오늘은 날씨가 좋아요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"저는 학생이에요. (or focused: 제가 했어요.)",ok:!0},{text:"저가 학생이에요.",ok:!1}],explanation:"For self-introduction the speaker is the assumed topic, so use 저는, not 저가. Also note 저 + 가 irregularly becomes 제가 when you DO need focus ('I' as the one who did it) — 저가 is never correct."}],canDo:"Set up an already-known topic with 은/는 (저는 …, 그 친구는 …)",id:"chapter-62-b4",chapterId:"chapter-62",index:3},{kind:"words",title:"단어 Words 3 · 차이~",cards:[{kind:"guess",word:{ko:"차이",romanization:"chai",en:"difference",pos:"noun",nuance:"차이 is Sino-Korean (差異, 差 'discrepancy/gap' + 異 'different'), the 'difference', 'gap', or 'disparity' between two or more things. It pairs with two key verbs: 차이가 있다 (a difference exists, more static) and 차이가 나다 (a difference shows up/emerges, more dynamic, often for a noticeable gap, e.g. 실력 차이가 나다 = a clear skill gap). The thing you compare with takes ~와/과 (A는 B와 차이가 있다), and the dimension of difference takes ~에(서) (의미에 차이가 있다 = a difference in meaning). Contrast 차이 with 다르다, the adjective 'to be different': 다르다 describes that two things are not the same (A와 B는 달라요), while 차이 is the noun naming the gap itself (A와 B는 차이가 있어요) — Koreans often use 다르다 for a qualitative 'different' and 차이 for a measurable/quantifiable gap (나이 차이 = age gap, 온도 차이 = temperature difference). Don't confuse 차이 with 차별 (差別, 'discrimination'), which is unfair treatment based on a difference. Register-neutral, very common. Collocations: 차이가 있다/없다/나다/크다, 차이를 느끼다 (feel a difference), 큰 차이, 별 차이 없다 (no real difference), 나이 차이/시차 (time difference). The English-speaker pitfall: 'A is different from B' is most naturally A는 B와 달라요 (using 다르다 + 와), not A는 B에서 차이예요; reach for the noun 차이 when you mean 'the difference between/in', and the verb 다르다 when you simply mean 'differs'."},sentence:{ko:"두 표현은 차이가 있어요.",en:"The two expressions have a difference."},target:"차이",options:["difference","grammatical particle","friend"],note:"은/는 frames the two expressions; 차이가 states what exists."},{kind:"guess",word:{ko:"상황",romanization:"sanghwang",en:"situation",pos:"noun",nuance:"상황 (狀況, '狀 condition/form + 況 circumstances' — the configuration of circumstances) describes the overall set of conditions surrounding a moment or event, broader than a single 경우 (a specific case or instance — 이런 경우 = 'in this one case', vs 이런 상황 = 'in this whole situation'). The reflexive phrase 상황에 따라(서) 다르다 ('it depends on the situation') is one of the most useful hedges in Korean, and 이런/그런 상황에서 sets up advice or reactions. Register is neutral. Two pitfalls: keep 상황 (the circumstances around an event) distinct from 상태 (狀態, the state/condition of a single thing or body — 건강 상태 'health condition', 배터리 상태 'battery state'); you describe a person's mood with a 상태, but the events around them with a 상황. And use 에 따라 (not 으로) for 'depending on': 상황에 따라, never 상황으로."},sentence:{ko:"이런 상황에서는 제가 먼저 말해야 해요.",en:"In this kind of situation, I should speak first."},target:"상황",options:["grammatical particle","friend","situation"],note:"상황에서는 frames the condition; 제가 identifies the actor."},{kind:"guess",word:{ko:"사실",romanization:"sasil",en:"fact, truth",pos:"noun",nuance:"사실 (事實, 事 'matter' + 實 'real/true') literally means 'the real state of a matter', so it covers both the noun 'fact' and the adverb 'actually/in fact'. Compare it with 진실: 사실 is a neutral, verifiable fact ('it rained yesterday'), while 진실 is the deeper moral 'truth' you uncover behind lies, so a courtroom seeks 진실, but a weather report states a 사실. Also distinguish 진짜, which is the casual spoken 'really/for real' and an intensifier ('진짜 맛있어!'), whereas 사실 introduces information. The phrase 사실은 / 사실 at the head of a sentence is enormously common in conversation as a gentle 'to tell the truth' before a correction or confession. The English-speaker pitfall: do not use 사실 to mean 'really' as an intensity word — '진짜 추워요' (it's really cold) is natural, but '사실 추워요' shifts the meaning to 'actually, it's cold (contrary to what you thought)'. Keep 사실 for facts and reveals, not for emphasis."},sentence:{ko:"사실은 제가 먼저 연락했어요.",en:"The truth is, I contacted first."},target:"사실",options:["grammatical particle","fact, truth","friend"],note:"사실은 frames the correction."},{kind:"guess",word:{ko:"다르다",romanization:"dareuda",en:"to be different",pos:"adjective",nuance:"다르다 is the antonym of 같다 and conjugates as a 르-irregular: the stem 다르 + 아요 doubles the ㄹ and drops 으 to give 달라요 (never 다라요); past is 달랐어요. The pre-noun form 다른 is one of the most-used words in Korean and covers both 'different' and 'another' (다른 색 = 'a different/another colour'). The dangerous trap for English speakers is 틀리다, which means 'to be wrong / incorrect' — even native speakers loosely say 틀리다 for 'different' in speech, but in correct Korean 답이 틀리다 = 'the answer is wrong' while 답이 다르다 = 'the answer is different'. Mixing them can imply someone is mistaken when you only meant they differ, which can sound rude. Pair 다르다 with 하고/와 for the thing compared: 작년하고 달라요 ('it's different from last year')."},sentence:{ko:"두 사람은 의견이 달라요.",en:"As for the two people, their opinions are different."},target:"달라",options:["to be different","to be the same","to be easy"],note:"두 사람은 is the frame; 의견이 is the differing subject."},{kind:"guess",word:{ko:"같다",romanization:"gatda",en:"to be the same",pos:"adjective",nuance:"같다 says two or more things match or are identical — 'A and B are the same'. To compare, the yardstick noun takes 하고/와·과 and the matching trait takes 이/가: 저하고 키가 같아요 ('our height is the same as mine'). Watch the sharp split from 비슷하다 ('similar'): 같다 means literally no difference, while 비슷하다 allows a gap — friends who 'look alike but aren't twins' are 비슷하다, not 같다. A second trap is the homophone-feeling N 같다 ('seems like N', as in 학생 같아요 'seems to be a student'), which drops 하고 and shifts meaning entirely; 같이 (together / -like) shares the root but is an adverb. English speakers also over-apply 'the same as' with 처럼 — but 처럼 means 'like/as', not 'identical', so keep 같다 for true equality."},sentence:{ko:"뜻은 같지만 느낌이 달라요.",en:"The meaning is the same, but the feeling is different."},target:"같지",options:["to be different","to be the same","to be easy"],note:"은/는 contrasts meaning and feeling."},{kind:"guess",word:{ko:"쉽다",romanization:"swipda",en:"to be easy",pos:"adjective",nuance:"쉽다 is ㅂ irregular: 쉬워요, 쉬운. It helps learners talk about difficulty level, but the opposite 어렵다 is often needed in the same lesson."},sentence:{ko:"질문은 쉬웠는데 대답이 어려웠어요.",en:"The question was easy, but the answer was difficult."},target:"쉬웠",options:["to be easy","to be different","to be the same"],note:"쉬웠는데 sets up contrast."},{kind:"guess",word:{ko:"중요하다",romanization:"jungyohada",en:"to be important",pos:"adjective",nuance:"중요하다 means 'important, significant, crucial' — carrying weight, mattering a great deal. It is Sino-Korean 重要 (중/重 'heavy' + 요/要 'essential, vital'), a vivid literal image of 'heavy and essential', i.e. weighty and indispensable. The sharp contrast is with 필요하다 ('necessary/needed'): 중요하다 ranks how much something MATTERS in significance, while 필요하다 says something is REQUIRED to get a result — an exam can be 중요한 (it matters a lot) and a pencil 필요한 (you need it to take the test); they are not interchangeable. Also distinguish 소중하다 ('precious, dear'), which is emotional preciousness rather than functional weight. The collocation 중요하게 생각하다 / 중요하게 여기다 means 'to value, to prioritize'. It conjugates regularly (중요해요). English-speaker pitfall: learners blur 'important' and 'necessary' — for 'I need it' use 필요하다, reserving 중요하다 for 'it matters'; and never say 중요하요 (contract to 중요해요)."},sentence:{ko:"이 문제는 이유가 제일 중요해요.",en:"For this issue, the reason is most important."},target:"중요해",options:["to be different","to be important","to be the same"],note:"중요하다 often appears with the focused subject marked by 이/가."},{kind:"payoff",line:{speaker:"지훈",ko:"그럼 이 문제는 이유가 제일 중요하네요.",en:"Then for this issue, the reason is the most important thing."},hl:"중요하"}],canDo:"Mark contrast or limited scope with 은/는 (평소에는 …)",id:"chapter-62-b5",chapterId:"chapter-62",index:4},{kind:"pattern",title:"문법 Grammar · 은/는",cards:[{kind:"hunt",name:"은/는",sub:"contrast and limited scope",lines:[{tokens:[{pre:"형",mid:"은",post:"",hit:!0},{pre:"키가",mid:"",post:"",hit:!1},{pre:"커요.",mid:"",post:"",hit:!1},{pre:"저",mid:"는",post:"",hit:!0},{pre:"작아요.",mid:"",post:"",hit:!1}],ko:"형은 키가 커요. 저는 작아요.",en:"My older brother is tall. I'm short.",romanization:"hyeongeun kiga keoyo. jeoneun jagayo."},{tokens:[{pre:"커피",mid:"는",post:"",hit:!0},{pre:"좋아하는데",mid:"",post:"",hit:!1},{pre:"차",mid:"는",post:"",hit:!0},{pre:"안",mid:"",post:"",hit:!1},{pre:"좋아해요.",mid:"",post:"",hit:!1}],ko:"커피는 좋아하는데 차는 안 좋아해요.",en:"I like coffee but not tea.",romanization:"keopineun joahaneunde chaneun an joahaeyo."}],rule:{name:"은/는",rows:[{when:"contrasting two nouns",add:"both take 은/는",ex:"커피는 마셔요. 차는 안 마셔요."},{when:"attaching contrast to an object",add:"은/는 replaces 을/를",ex:"고기는 안 먹어요. (meat, at least, I don't eat)"},{when:"limiting / 'this one, at least' nuance",add:"noun + 는 with implied 'others differ'",ex:"이건 알아요. (this one I do know — others maybe not)"}]},more:{func:"Beyond topic-setting, 은/는 marks CONTRAST: 'X (but as for something else, it's different).' It quietly implies a comparison, even when the other side is unspoken. Use it to set one item against another, or to limit a statement to just that item.",funcLead:"Beyond topic-setting, 은/는 marks CONTRAST: 'X (but as for something else, it's different).' It quietly implies a comparison, even when the other side is unspoke…",keyPoint:{label:"는 over 가/를 = contrast is intended",body:"커피를 마셔요 = plain 'I drink coffee.' 커피는 마셔요 = 'Coffee I drink (but something else, no).' Swapping 를→는 (or 가→는) adds an unspoken 'unlike the rest.'"},pronunciation:"In the contrast reading, 는/은 often carries a slight emphatic stress: 저'는 작아요. That extra stress is what flags the contrast aloud.",pitfall:{wrong:"커피를 좋아하는데 차를 안 좋아해요.",right:"커피는 좋아하는데 차는 안 좋아해요.",explanation:"English shows contrast with 'but' and word order, so learners keep 을/를 on both objects. Korean signals the contrast on the noun itself by switching 을/를 to 는 — leaving 를 there flattens the intended comparison."}}},{kind:"drill",prompt:"Korean, at least, I can speak.",sentence:"한국어___ 할 수 있어요.",options:[{text:"은",ok:!1},{text:"는",ok:!0}],explanation:"는 here limits the claim to Korean, implying 'other languages, maybe not.'"},{kind:"drill",prompt:"Today I'm not busy (other days, I am).",sentence:"오늘___ 안 바빠요.",options:[{text:"은",ok:!0},{text:"는",ok:!1},{text:"이",ok:!1}],explanation:"는 on 오늘 contrasts today against the implied busy other days."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "My older brother is tall. I'm short."`,tokens:["형은","키가","커요.","저는","작아요."],correct:"형은 키가 커요. 저는 작아요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I like coffee but not tea."',tokens:["커피는","좋아하는데","차는","안","좋아해요."],correct:"커피는 좋아하는데 차는 안 좋아해요.",explanation:""}],canDo:"Mark contrast or limited scope with 은/는 (평소에는 …)",id:"chapter-62-b6",chapterId:"chapter-62",index:5},{kind:"pattern",title:"문법 Grammar · 이/가",cards:[{kind:"hunt",name:"이/가",sub:"'this exact one' (exclusive identification)",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"사람",mid:"이",post:"",hit:!0},{pre:"제",mid:"",post:"",hit:!1},{pre:"선생님이에요.",mid:"",post:"",hit:!1}],ko:"이 사람이 제 선생님이에요.",en:"THIS person is my teacher.",romanization:"i sarami je seonsaengnimieyo."},{tokens:[{pre:"누",mid:"가",post:"",hit:!0},{pre:"했어요?",mid:"",post:"",hit:!1},{pre:"—",mid:"",post:"",hit:!1},{pre:"제",mid:"가",post:"",hit:!0},{pre:"했어요.",mid:"",post:"",hit:!1}],ko:"누가 했어요? — 제가 했어요.",en:"Who did it? — I did.",romanization:"nuga haesseoyo? — jega haesseoyo."}],rule:{name:"이/가",rows:[{when:"answering with the exact identity",add:"answer + 이/가",ex:"누가 반장이에요? → 민수가 반장이에요."},{when:"'it is X' exclusive focus",add:"X + 이/가 + verb",ex:"이 책이 제일 좋아요. (THIS book is the best.)"},{when:"picking one out of several",add:"chosen item + 이/가",ex:"이게 제 거예요. (THIS one is mine.)"}]},more:{func:"When you single out ONE item as the answer — 'it is THIS one, not the others' — the identified subject takes 이/가. This exclusive-focus use is why 이/가 (not 은/는) appears in answers, in 'who/what' replies, and in 'it's X that…' sentences. It pins down the exact one.",funcLead:"When you single out ONE item as the answer — 'it is THIS one, not the others' — the identified subject takes 이/가.",keyPoint:{label:"이/가 identifies, 은/는 describes",body:"이 사람이 김 선생님이에요 = 'THIS (one) is Mr. Kim' (picks him out). 이 사람은 김 선생님이에요 = 'As for this person, he's Mr. Kim' (just tells you about him). Use 이/가 to single out the exact one."},pronunciation:"이것이 commonly contracts to 이게, 그것이 → 그게, 저것이 → 저게 in speech. Learn the contracted 이게/그게/저게 as the everyday spoken forms.",pitfall:{wrong:"누가 했어요? — 저는 했어요.",right:"누가 했어요? — 제가 했어요.",explanation:"Answering a 'who' question identifies the exact doer, which demands 이/가, but English speakers reach for the topic-like 저는. 저는 했어요 sounds like 'As for me, I did (but talk about others separately)' — not a clean answer to 'who.'"}}},{kind:"drill",prompt:"Which bag do you like?",sentence:"어느 가방___ 마음에 들어요?",options:[{text:"이",ok:!0},{text:"가",ok:!1}],explanation:"어느 (which) forces a one-out-of-many choice, so the subject takes 이."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "THIS person is my teacher."',tokens:["이","사람이","제","선생님이에요."],correct:"이 사람이 제 선생님이에요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Who did it? — I did."',tokens:["누가","했어요?","—","제가","했어요."],correct:"누가 했어요? — 제가 했어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"누가 했어요? — 저는 했어요.",ok:!1},{text:"누가 했어요? — 제가 했어요.",ok:!0}],explanation:"Answering a 'who' question identifies the exact doer, which demands 이/가, but English speakers reach for the topic-like 저는. 저는 했어요 sounds like 'As for me, I did (but talk about others separately)' — not a clean answer to 'who.'"}],canDo:"Combine topic and inner subject in one sentence (N은/는 N이/가 …)",id:"chapter-62-b7",chapterId:"chapter-62",index:6},{kind:"pattern",title:"문법 Grammar · N은/는 N이/가 …",cards:[{kind:"teach",name:"N은/는 N이/가 …",sub:"topic + inner subject in one sentence",rows:[{when:"describing a body part / trait",add:"Topic은/는 + part이/가 + adj",ex:"코끼리는 코가 길어요. (The elephant's nose is long.)"},{when:"saying what someone likes/has",add:"Person은/는 + thing이/가 + 좋다/있다",ex:"저는 강아지가 좋아요. (As for me, I like dogs.)"},{when:"stating an ability/condition",add:"Topic은/는 + thing이/가 + 어렵다/많다",ex:"한국어는 발음이 어려워요. (Korean — its pronunciation is hard.)"}],examples:[{ko:"코끼리는 코가 길어요.",en:"An elephant's nose is long.",romanization:"kokkiri-neun ko-ga gireoyo.",note:"코끼리 is the topic (은/는); 코 is the inner subject (이/가) that 길어요 actually describes."},{ko:"저는 시간이 없어요.",en:"I don't have time.",romanization:"jeoneun sigani eopseoyo.",note:"Literally 'As for me, time doesn't exist.' 저 = topic (는), 시간 = subject of 없다 (이)."}],more:{func:"Korean often uses BOTH markers in a single sentence: 은/는 names the big-picture topic, then 이/가 names the specific thing the comment is really about. Pattern: '[Topic]은/는 [inner subject]이/가 [adjective/verb].' This is the natural way to describe a part, trait, or condition of something — 'As for the elephant, its nose is long.'",funcLead:"Korean often uses BOTH markers in a single sentence: 은/는 names the big-picture topic, then 이/가 names the specific thing the comment is really about.",keyPoint:{label:"The clearest beginner frame: topic + inner subject",body:"For a neutral description, mark the big topic with 은/는 and the specific part or condition with 이/가: 저는 머리가 아파요. Korean can also use repeated 이/가 in double-subject constructions or repeated 은/는 for contrast, so this is a reliable default pattern rather than an absolute ban on other combinations."},pronunciation:"코가 = ko-ga (smooth, no stop); 키가 = ki-ga; 시간이 = sigani (final ㄴ links onto 이). Keep both syllables of 이/가 light — the stress sits on the predicate (길어요, 커요).",pitfall:{wrong:"코끼리가 코가 길어요 and 저는 시간은 없어요 are always ungrammatical.",right:"코끼리는 코가 길어요. / 저는 시간이 없어요. (neutral defaults)",explanation:"The right-hand sentences are the safest neutral forms for beginners. 코끼리가 코가 길어요 can occur as a double-subject construction, and 저는 시간은 없어요 can contrast time with something else ('I don't have time, at least'). Do not mark those forms wrong without context; teach the difference in focus."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "An elephant's nose is long."`,tokens:["코끼리는","코가","길어요."],correct:"코끼리는 코가 길어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I don't have time."`,tokens:["저는","시간이","없어요."],correct:"저는 시간이 없어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"코끼리가 코가 길어요 and 저는 시간은 없어요 are always ungrammatical.",ok:!1},{text:"코끼리는 코가 길어요. / 저는 시간이 없어요. (neutral defaults)",ok:!0}],explanation:"The right-hand sentences are the safest neutral forms for beginners. 코끼리가 코가 길어요 can occur as a double-subject construction, and 저는 시간은 없어요 can contrast time with something else ('I don't have time, at least'). Do not mark those forms wrong without context; teach the difference in focus."}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b8",chapterId:"chapter-62",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends analyze a call and a message while the particles track new information, topic, contrast, and focus.",lines:[{speaker:"민서",ko:"어제 친구가 전화했어요.",en:"A friend called yesterday.",romanization:"eoje chinguga jeonhwahaesseoyo."},{speaker:"지훈",ko:"그 친구는 자주 전화해요?",en:"Does that friend call often?",romanization:"geu chinguneun jaju jeonhwahaeyo?"},{speaker:"민서",ko:"아니요. 평소에는 메시지를 보내는데 오늘은 제가 먼저 연락했어요.",en:"No. Usually they send messages, but today I contacted them first.",romanization:"aniyo. pyeongsoeneun mesijireul bonaeneunde oneureun jega meonjeo yeollakaesseoyo."},{speaker:"지훈",ko:"누가 먼저 연락했어요?",en:"Who contacted first?",romanization:"nuga meonjeo yeollakaesseoyo?"},{speaker:"민서",ko:"제가 먼저 연락했어요. 질문은 쉬웠는데 대답이 어려웠어요.",en:"I contacted first. The question was easy, but the answer was difficult.",romanization:"jega meonjeo yeollakaesseoyo. jilmuneun swiwonneunde daedabi eoryeowosseoyo."},{speaker:"지훈",ko:"그럼 이 문제는 이유가 제일 중요하네요.",en:"Then for this issue, the reason is the most important thing.",romanization:"geureom i munjeneun iyuga jeil jungyohaneyo."}]},{kind:"order",prompt:"Build: 'My friend called first.'",tokens:["친구가","먼저 전화했어요"],correct:"친구가 먼저 전화했어요",explanation:"When answering 누가 first acted, the focused subject takes 가. 먼저 tells who acted first."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"아니요. 평소에는 메시지를 보내는데 오늘은 제가 먼저 연락했어요.",options:[{text:"민서",ok:!0},{text:"지훈",ok:!1}],explanation:"No. Usually they send messages, but today I contacted them first."},{kind:"drill",prompt:'무엇이 들어갈까요? · "A friend called yesterday."',sentence:"어제 ___가 전화했어요.",options:[{text:"조사",ok:!1},{text:"친구",ok:!0},{text:"연락",ok:!1}],explanation:""}],canDo:"Spotlight a new or focused subject with 이/가 (친구가 보냈어요)",id:"chapter-62-b9",chapterId:"chapter-62",index:8},{kind:"reading",title:"읽기 Reading · ‘친구가’에서 ‘그 친구는’으로",cards:[{kind:"read",title:"‘친구가’에서 ‘그 친구는’으로",chunks:['어제 민서에게 친구가 전화했다. 처음 말할 때는 누가 전화했는지가 새 정보였기 때문에 ‘친구가’가 자연스러웠다. 그다음 지훈은 "그 친구는 자주 전화해?"라고 물었다. 이미 말한 친구를 다시 주제로 삼았기 때문에 ‘그 친구는’이 맞았다. 민서는 평소에는 메시지를 보내는데 오늘은 제가 먼저 연락했다고 설명했다.','여기서 ‘평소에는’과 ‘오늘은’은 서로 대비된다. 지훈이 "누가 먼저 연락했어?"라고 묻자 민서는 "제가 먼저 연락했어"라고 답했다. ‘제가’는 다른 사람이 아니라 바로 민서가 했다는 뜻이다. 마지막으로 "이 문제는 이유가 중요해"처럼 말하면, 문제는 이야기의 틀이고 이유가 그 안에서 중요한 새 정보가 된다.'],translation:'Yesterday, a friend called Minseo. On the first mention, who called was new information, so 친구가 was natural. Then Jihoon asked, "Does that friend call often?" Because the friend had already been mentioned and was now the topic, 그 친구는 was right. Minseo explained that usually the friend sends messages, but today she contacted first. Here 평소에는 and 오늘은 contrast with each other. When Jihoon asked, "Who contacted first?" Minseo answered, "I contacted first." 제가 means it was specifically Minseo, not someone else. Finally, in a sentence like "For this issue, the reason is important," 문제는 is the frame of the discussion and 이유가 is the important new information inside it.',qas:[{q:"처음에는 왜 친구가를 썼어요?",a:"누가 전화했는지가 새 정보였기 때문이에요."},{q:"‘평소에는’과 ‘오늘은’은 어떤 역할을 해요?",a:"평소와 오늘을 서로 대비해요."},{q:"이 문제는 이유가 중요해요에서 문제와 이유의 역할은 무엇이에요?",a:"문제는 이야기의 틀이고, 이유가 그 안에서 중요한 새 정보예요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"어제 민서에게 ___가 전화했다.",options:[{text:"조사",ok:!1},{text:"친구",ok:!0},{text:"문자",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"민서는 평소에는 ___를 보내는데 오늘은 제가 먼저 연락했다고 설명했다.",options:[{text:"조사",ok:!1},{text:"문자",ok:!1},{text:"메시지",ok:!0}],explanation:""}],canDo:"Set up an already-known topic with 은/는 (저는 …, 그 친구는 …)",id:"chapter-62-b10",chapterId:"chapter-62",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence introduces the caller as new information?",sentence:null,options:[{text:"친구가 전화했어요.",ok:!0},{text:"친구는 전화했어요.",ok:!1},{text:"친구에게 전화했어요.",ok:!1}],explanation:"친구가 answers who called."},{kind:"drill",prompt:"Which sentence contrasts messages and calls?",sentence:null,options:[{text:"메시지는 자주 보내지만 전화는 잘 안 해요.",ok:!0},{text:"메시지가 자주 보내지만 전화가 잘 안 해요.",ok:!1},{text:"메시지에게 자주 보내지만 전화에게 안 해요.",ok:!1}],explanation:"은/는 marks the two contrasted communication methods."},{kind:"drill",prompt:"Which answer fits 누가 먼저 연락했어요?",sentence:null,options:[{text:"제가 먼저 연락했어요.",ok:!0},{text:"저는 먼저 연락했어요.",ok:!1},{text:"저에게 먼저 연락했어요.",ok:!1}],explanation:"제가 gives the focused who-answer."},{kind:"drill",prompt:"Which particles complete the topic-plus-subject sentence: 이 문제____ 이유____ 중요해요?",sentence:null,options:[{text:"는 / 가",ok:!0},{text:"가 / 는",ok:!1},{text:"에게 / 를",ok:!1}],explanation:"이 문제는 sets the frame; 이유가 is the important subject inside it."},{kind:"drill",prompt:"이 문제___ 이유___ 중요해요. (As for this problem, the reason is important.)",sentence:null,options:[{text:"는 / 가",ok:!0},{text:"가 / 는",ok:!1},{text:"를 / 이",ok:!1}],explanation:"The outer topic is 이 문제는, and the inner subject is 이유가. This topic-plus-subject structure is common in Korean."},{kind:"drill",prompt:"Which sentence introduces the caller as new information?",sentence:null,options:[{text:"친구가 전화했어요.",ok:!0},{text:"친구는 전화했어요.",ok:!1},{text:"친구를 전화했어요.",ok:!1}],explanation:"New or focused subject information uses 이/가. 은/는 would frame or contrast the friend."}],canDo:"Mark contrast or limited scope with 은/는 (평소에는 …)",id:"chapter-62-b11",chapterId:"chapter-62",index:10}]},{id:"chapter-63",number:63,title:"V-아/어 주세요 / V-(으)면 연락 주세요 · N도 있으세요? / V-(으)세요",goal:"Read common delivery requests and confirmations without translating word by word.",biteCount:10,bites:[{kind:"words",title:"단어 Words 1 · 공동현관~",cards:[{kind:"guess",word:{ko:"공동현관",romanization:"gongdonghyeongwan",en:"shared building entrance",pos:"noun"},sentence:{ko:"공동현관 앞에서 연락 주세요.",en:"Please contact me from the shared building entrance."},target:"공동현관",options:["security office; guard station","shared building entrance","after a meal"],note:"Common in apartment delivery instructions."},{kind:"guess",word:{ko:"경비실",romanization:"gyeongbisil",en:"security office; guard station",pos:"noun"},sentence:{ko:"택배는 경비실에 맡겨 주세요.",en:"Please leave the parcel with the security office."},target:"경비실",options:["security office; guard station","shared building entrance","after a meal"],note:"맡기다 is used when leaving something in another person's care."},{kind:"guess",word:{ko:"식후",romanization:"sikhu",en:"after a meal",pos:"noun",nuance:"식후 is concise and label-like. In casual speech you can also say 밥 먹고, but at a clinic or pharmacy 식후 is the expected word. 식후 usually pairs with 에 or a time amount: 식후에, 식후 30분."},sentence:{ko:"이 약은 식후에 드세요.",en:"Take this medicine after meals."},target:"식후",options:["shared building entrance","security office; guard station","after a meal"],note:"Often paired with a number of minutes."},{kind:"guess",word:{ko:"복용",romanization:"bogyong",en:"taking medicine; dosage use",pos:"noun"},sentence:{ko:"복용 방법을 확인하세요.",en:"Check the directions for taking the medicine."},target:"복용",options:["shared building entrance","security office; guard station","taking medicine; dosage use"],note:"A label word seen on medicine packages."},{kind:"guess",word:{ko:"관리실",romanization:"gwallisil",en:"building management office",pos:"noun"},sentence:{ko:"문제가 있으면 관리실로 연락하세요.",en:"Contact the management office if there is a problem."},target:"관리실",options:["after a meal","taking medicine; dosage use","building management office"],note:"Used in apartments and office buildings."},{kind:"payoff",line:{speaker:"택배 기사",ko:"공동현관 앞입니다. 어디에 놓아 드릴까요?",en:"I'm at the building entrance. Where should I leave it?"},hl:"공동현관"}],canDo:"Understand delivery requests and locate a parcel from a driver message",id:"chapter-63-b1",chapterId:"chapter-63",index:0},{kind:"pattern",title:"문법 Grammar · V-아/어 주세요 / V-(으)면 연락 주세요",cards:[{kind:"teach",name:"V-아/어 주세요 / V-(으)면 연락 주세요",sub:"delivery requests and updates",rows:[{when:"A direct but polite delivery request",add:"verb stem + -아/어 주세요",ex:"놓다 → 문 앞에 놓아 주세요 (Please leave it at the door.)"},{when:"A condition followed by a request",add:"verb stem + -(으)면 + request",ex:"도착하다 → 도착하면 연락 주세요 (Please contact me when you arrive.)"},{when:"A more careful request to the driver",add:"V-아/어 주실 수 있을까요?",ex:"보내다 → 사진을 보내 주실 수 있을까요?"},{when:"A completed delivery update",add:"V-았/었습니다 / V-아/어 두었습니다",ex:"배송했습니다 / 문 앞에 두었습니다"}],examples:[{ko:"문 앞에 놓아 주세요.",en:"Please leave it at the door.",romanization:"mun ape noa juseyo.",note:"문 앞 is the location; 놓아 주세요 is the requested action. 놓아 is often shortened to 놔 in casual messages."},{ko:"도착하면 전화하지 말고 문자 주세요.",en:"When you arrive, please text instead of calling.",romanization:"dochakamyeon jeonhwahaji malgo munja juseyo.",note:"-지 말고 replaces one action with another: not a call, but a text."}],more:{func:"Delivery messages usually contain one concrete request and one condition. V-아/어 주세요 asks someone to do an action, while V-(으)면 marks the condition that triggers the next action: 도착하면 연락 주세요 means 'Please contact me when you arrive.' Look for the action closest to 주세요 to find what the sender wants.",funcLead:"Delivery messages usually contain one concrete request and one condition.",keyPoint:{label:"Find location, trigger, and requested action",body:"In 문 앞에 놓아 주세요, the location is 문 앞 and the action is 놓다. In 도착하면 문자 주세요, the trigger is 도착하면 and the requested action is 문자 주세요. Reading these parts separately lets you understand the message even when particles are omitted."},pronunciation:"놓아 주세요 is carefully [노아 주세요] and is often contracted to 놔 주세요 [놔 주세요] in speech. 맡겨 is pronounced [맏껴], with the following ㄱ becoming tense.",pitfall:{wrong:"도착하면 연락해요. = a clear request to the driver",right:"도착하면 연락 주세요. / 도착하면 연락해 주세요.",explanation:"A plain -해요 sentence can sound like a statement about what normally happens. In a delivery instruction, 주세요 or 해 주세요 makes the requested action explicit."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please leave it at the door." (문 시작 · Start with 문.)',tokens:["문","앞에","놓아","주세요."],correct:"문 앞에 놓아 주세요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "When you arrive, please text instead of calling."',tokens:["도착하면","전화하지","말고","문자","주세요."],correct:"도착하면 전화하지 말고 문자 주세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"도착하면 연락 주세요. / 도착하면 연락해 주세요.",ok:!0},{text:"도착하면 연락해요. = a clear request to the driver",ok:!1}],explanation:"A plain -해요 sentence can sound like a statement about what normally happens. In a delivery instruction, 주세요 or 해 주세요 makes the requested action explicit."}],canDo:"Understand delivery requests and locate a parcel from a driver message",id:"chapter-63-b2",chapterId:"chapter-63",index:1},{kind:"words",title:"단어 Words 2 · 단수~",cards:[{kind:"guess",word:{ko:"단수",romanization:"dansu",en:"water shutoff",pos:"noun"},sentence:{ko:"배관 공사로 두 시간 동안 단수예요.",en:"The water will be shut off for two hours due to plumbing work."},target:"단수",options:["water shutoff","shared building entrance","security office; guard station"],note:"Check the time range that follows."},{kind:"guess",word:{ko:"점검",romanization:"jeomgeom",en:"inspection; maintenance check",pos:"noun"},sentence:{ko:"엘리베이터 정기 점검이 있습니다.",en:"There will be a regular elevator inspection."},target:"점검",options:["shared building entrance","inspection; maintenance check","security office; guard station"],note:"정기 means regularly scheduled."},{kind:"guess",word:{ko:"지연",romanization:"jiyeon",en:"delay",pos:"noun",nuance:"지연 sounds more official than 늦다. Use 늦다 for a person being late and 지연 for a service, schedule, or system delay."},sentence:{ko:"열차 지연 안내가 나왔어요.",en:"A train-delay notice was announced."},target:"지연",options:["shared building entrance","delay","security office; guard station"],note:"Often appears with 운행 or 열차."},{kind:"guess",word:{ko:"환승",romanization:"hwanseung",en:"transfer between transit lines",pos:"noun",nuance:"환승 means transferring between buses and subways. If you tap the same transit card, transfers within a time limit are usually discounted or free."},sentence:{ko:"이 역에서 버스로 환승하세요.",en:"Transfer to a bus at this station."},target:"환승",options:["shared building entrance","security office; guard station","transfer between transit lines"],note:"환승하다 and 갈아타다 express the same practical action."},{kind:"guess",word:{ko:"재개",romanization:"jaegae",en:"resumption; restart",pos:"noun"},sentence:{ko:"운행이 오후에 재개될 예정입니다.",en:"Service is scheduled to resume in the afternoon."},target:"재개",options:["resumption; restart","shared building entrance","security office; guard station"],note:"The opposite status is 중단."},{kind:"payoff",line:{speaker:"친구",ko:"관리실 공지 봤어요? 내일 오전에 단수래요.",en:"Did you see the management-office notice? They say the water will be off tomorrow morning."},hl:"단수"}],canDo:"Read symptom questions and medicine frequency, timing, and warnings",id:"chapter-63-b3",chapterId:"chapter-63",index:2},{kind:"pattern",title:"문법 Grammar · N도 있으세요? / V-(으)세요",cards:[{kind:"hunt",name:"N도 있으세요? / V-(으)세요",sub:"clinic questions and medicine instructions",lines:[{tokens:[{pre:"기침",mid:"",post:"",hit:!1},{pre:"말고",mid:"",post:"",hit:!1},{pre:"열",mid:"도",post:"",hit:!0},{pre:"",mid:"있으세요",post:"?",hit:!0}],ko:"기침 말고 열도 있으세요?",en:"Besides the cough, do you also have a fever?",romanization:"gichim malgo yeoldo isseuseyo?"},{tokens:[{pre:"어디가",mid:"",post:"",hit:!1},{pre:"제일",mid:"",post:"",hit:!1},{pre:"불편하",mid:"세요",post:"?",hit:!0}],ko:"어디가 제일 불편하세요?",en:"Where are you feeling the most discomfort?",romanization:"eodiga jeil bulpyeonhaseyo?"}],rule:{name:"N도 있으세요? / V-(으)세요",rows:[{when:"Asking whether another symptom is present",add:"symptom + 도 있으세요?",ex:"열도 있으세요? (Do you also have a fever?)"},{when:"Asking which body part feels wrong",add:"어디가 + 불편하세요/아프세요?",ex:"어디가 제일 아프세요?"},{when:"Giving a medicine instruction",add:"verb stem + -(으)세요",ex:"먹다 → 식후에 드세요 (Take it after meals.)"},{when:"Giving frequency",add:"하루에 + number + 번",ex:"하루에 세 번 드세요 (Take it three times a day.)"}]},more:{func:"At a clinic or pharmacy, staff often ask whether an additional symptom is present with N도 있으세요? and ask about your condition with 어디가 불편하세요? Instructions usually end in -(으)세요: 식후에 드세요 means 'Take it after meals.' The ending is polite, but the message may be a question, an instruction, or a recommendation depending on intonation and context.",funcLead:"At a clinic or pharmacy, staff often ask whether an additional symptom is present with N도 있으세요?",keyPoint:{label:"Separate symptom, frequency, timing, and warning",body:"A medicine message can contain four different facts: what symptom it treats, how often to take it, when to take it, and what to avoid. In 하루에 세 번 식후에 드세요, 세 번 is frequency and 식후에 is timing. Never treat the whole line as one memorized block."},pronunciation:"식후 is pronounced [시쿠] because ㄱ and ㅎ combine into ㅋ. 드세요 is [드세요]; it is the honorific everyday form used instead of 먹으세요 for medicine and food.",pitfall:{wrong:"열이 나요 is the only possible way to mention a fever.",right:"열이 나요. (reporting the symptom) / 열도 있으세요? (checking its presence)",explanation:"나다 is the most useful pairing when you report that a fever developed. 있다 is also natural when a medical worker checks whether the fever is present. The surrounding task changes the preferred verb."}}},{kind:"drill",prompt:"Take this medicine three times a day after meals.",sentence:"이 약은 하루에 세 번 식후에 드___.",options:[{text:"도 있으세요",ok:!1},{text:"세요",ok:!0}],explanation:"Read the frequency and timing separately: 하루에 세 번 + 식후에."},{kind:"drill",prompt:"It may make you drowsy, so do not drive.",sentence:"졸릴 수 있으니까 운전하지 마___.",options:[{text:"세요",ok:!0},{text:"동안",ok:!1}],explanation:"The first clause gives a possible side effect; -지 마세요 gives the restriction."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Besides the cough, do you also have a fever?"',tokens:["기침","말고","열도","있으세요?"],correct:"기침 말고 열도 있으세요?",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Where are you feeling the most discomfort?"',tokens:["어디가","제일","불편하세요?"],correct:"어디가 제일 불편하세요?",explanation:""}],canDo:"Read symptom questions and medicine frequency, timing, and warnings",id:"chapter-63-b4",chapterId:"chapter-63",index:3},{kind:"pattern",title:"문법 Grammar · V-아/어야 해요 / V-지 마세요",cards:[{kind:"teach",name:"V-아/어야 해요 / V-지 마세요",sub:"housing notices and building rules",rows:[{when:"A required resident action",add:"verb stem + -아/어야 해요",ex:"버리다 → 화요일에 버려야 해요"},{when:"A prohibited action",add:"verb stem + -지 마세요",ex:"이용하다 → 이용하지 마세요"},{when:"A facility is being checked or repaired",add:"noun + 중 / V-는 중",ex:"점검 중 / 수리 중"},{when:"A service stops temporarily",add:"N이/가 중단돼요 / 단수예요",ex:"오전 10시부터 수도 공급이 중단돼요"}],examples:[{ko:"내일 오전 10시부터 두 시간 동안 단수예요.",en:"The water will be shut off for two hours starting at 10 a.m. tomorrow.",romanization:"naeil ojeon yeol sibuteo du sigan dongan dansuyeyo.",note:"부터 gives the start; 두 시간 동안 gives the duration; 단수 gives the service interruption."},{ko:"점검 중에는 엘리베이터를 이용하지 마세요.",en:"Do not use the elevator during the inspection.",romanization:"jeomgeom jungeneun ellibeiteoreul iyonghaji maseyo.",note:"중에는 defines the restricted period; -지 마세요 states the prohibited action."}],more:{func:"Apartment and management-office notices tell you what is required, prohibited, or temporarily unavailable. V-아/어야 해요 marks an obligation, V-지 마세요 marks a prohibition, and N 중 marks an activity currently in progress. First find the date and time, then find the action ending.",funcLead:"Apartment and management-office notices tell you what is required, prohibited, or temporarily unavailable.",keyPoint:{label:"Read notices in this order: when → what changes → what you must do",body:"내일 오전 10시부터 / 단수 / 물을 미리 받아 두세요 means: start time / service change / preparation. Korean notices often omit a personal subject, so focus on time words and the final action ending rather than looking for 'you.'"},pronunciation:"단수예요 is pronounced [단수예요]. 점검 is [점검], and 관리실로 links as [괄리실로] in standard pronunciation because ㄴ before ㄹ becomes ㄹ.",pitfall:{wrong:"단수예요 means the building has no water permanently.",right:"단수예요 means the water supply is temporarily shut off; check the stated start and duration.",explanation:"Housing notices normally pair 단수 with a time range. Missing 부터, 까지, or 동안 can make you misunderstand a temporary interruption as a permanent condition."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Do not use the elevator during the inspection." (점검 시작 · Start with 점검.)',tokens:["점검","중에는","엘리베이터를","이용하지","마세요."],correct:"점검 중에는 엘리베이터를 이용하지 마세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"단수예요 means the water supply is temporarily shut off; check the stated start and duration.",ok:!0},{text:"단수예요 means the building has no water permanently.",ok:!1}],explanation:"Housing notices normally pair 단수 with a time range. Missing 부터, 까지, or 동안 can make you misunderstand a temporary interruption as a permanent condition."}],canDo:"Find the time and required action in a building-management notice",id:"chapter-63-b5",chapterId:"chapter-63",index:4},{kind:"pattern",title:"문법 Grammar · N부터 N까지 / N 동안",cards:[{kind:"teach",name:"N부터 N까지 / N 동안",sub:"finding time ranges in notices",rows:[{when:"Starting point",add:"time + 부터",ex:"오전 10시부터"},{when:"Endpoint or deadline",add:"time + 까지",ex:"오후 1시까지"},{when:"Complete time range",add:"start + 부터 + end + 까지",ex:"오전 10시부터 오후 1시까지"},{when:"Length of time",add:"duration + 동안",ex:"세 시간 동안"}],examples:[{ko:"오전 10시부터 오후 1시까지 단수예요.",en:"The water will be shut off from 10 a.m. to 1 p.m.",romanization:"ojeon yeol sibuteo ohu han sikkaji dansuyeyo.",note:"The 부터…까지 frame gives the full service-interruption window."},{ko:"점검은 세 시간 동안 진행됩니다.",en:"The inspection will continue for three hours.",romanization:"jeomgeomeun se sigan dongan jinhaengdoemnida.",note:"동안 gives the duration, not the finishing clock time."}],more:{func:"Notices often place the time before the main event. 부터 marks the starting point, 까지 marks the endpoint, and 동안 marks the duration. First find these time markers, then read what service changes or what action is required.",funcLead:"Notices often place the time before the main event.",keyPoint:{label:"Range and duration answer different questions",body:"오전 10시부터 오후 1시까지 answers 'from when until when?' 세 시간 동안 answers 'for how long?' A notice may show both, but either one can be enough to plan what to do."},pronunciation:"부터 is [부터]. 시간 동안 is pronounced as written, [시간 동안], with each word kept clear. 까지 is [까지] with a tense ㄲ.",pitfall:{wrong:"두 시간까지 점검해요. = The inspection lasts for two hours.",right:"두 시간 동안 점검해요. = The inspection lasts for two hours.",explanation:"까지 marks an endpoint or limit. To state how long an event continues, use 동안. Use 까지 only when 'up to two hours' or a deadline is the intended meaning."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The water will be shut off from 10 a.m. to 1 p.m." (오전 시작 · Start with 오전.)',tokens:["오전","10시부터","오후","1시까지","단수예요."],correct:"오전 10시부터 오후 1시까지 단수예요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The inspection will continue for three hours."',tokens:["점검은","세","시간","동안","진행됩니다."],correct:"점검은 세 시간 동안 진행됩니다.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"두 시간까지 점검해요. = The inspection lasts for two hours.",ok:!1},{text:"두 시간 동안 점검해요. = The inspection lasts for two hours.",ok:!0}],explanation:"까지 marks an endpoint or limit. To state how long an event continues, use 동안. Use 까지 only when 'up to two hours' or a deadline is the intended meaning."}],canDo:"Distinguish a transit delay, suspension, resumption, and transfer instruction",id:"chapter-63-b6",chapterId:"chapter-63",index:5},{kind:"pattern",title:"문법 Grammar · N이/가 지연되다 / V-는 중이다",cards:[{kind:"teach",name:"N이/가 지연되다 / V-는 중이다",sub:"transit delays and transfers",rows:[{when:"A train or bus is delayed",add:"N이/가 지연되고 있습니다",ex:"2호선 열차가 지연되고 있습니다"},{when:"An operation is currently in progress",add:"N 중입니다 / V-는 중입니다",ex:"운행 중입니다 / 출발 준비 중입니다"},{when:"Changing to another line",add:"line + (으)로 갈아타세요",ex:"다음 역에서 3호선으로 갈아타세요"},{when:"Leaving through an exit",add:"number + 번 출구로 나가세요",ex:"5번 출구로 나가세요"}],examples:[{ko:"현재 2호선 열차가 지연되고 있습니다.",en:"Line 2 trains are currently delayed.",romanization:"hyeonjae ihoseon yeolchaga jiyeondoego itseumnida.",note:"현재 marks the current status; 지연되고 있습니다 is a formal announcement style."},{ko:"다음 역에서 3호선으로 갈아타세요.",en:"Transfer to Line 3 at the next station.",romanization:"daeum yeogeseo samhoseoneuro garataseyo.",note:"에서 marks the transfer location; 으로 marks the new line."}],more:{func:"Transit announcements describe current status before giving the next action. 지연되다 means 'be delayed,' 운행이 중단되다 means service has stopped, and 운행 중이다 means service is operating. Transfer instructions use N으로 갈아타세요 and exit instructions use N번 출구로 나가세요.",funcLead:"Transit announcements describe current status before giving the next action.",keyPoint:{label:"Status first, action second",body:"현재 열차가 지연되고 있습니다 only reports status. 다른 교통편을 이용해 주세요 adds the action expected from passengers. Do not assume every delay announcement means service has stopped; distinguish 지연, 중단, and 재개."},pronunciation:"지연 is [지연]. 갈아타세요 is pronounced [가라타세요] as the final ㄹ of 갈 links to 아. 중단됐습니다 is commonly heard as [중단됟씀니다].",pitfall:{wrong:"지연되다 and 중단되다 both mean the service has completely stopped.",right:"지연되다 = be delayed / 중단되다 = be suspended or stopped",explanation:"A delayed train may still arrive and operate. 중단 signals that service is not operating on the stated section. This distinction changes whether you wait or find another route."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Line 2 trains are currently delayed."',tokens:["현재","2호선","열차가","지연되고","있습니다."],correct:"현재 2호선 열차가 지연되고 있습니다.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Transfer to Line 3 at the next station." (다음 시작 · Start with 다음.)',tokens:["다음","역에서","3호선으로","갈아타세요."],correct:"다음 역에서 3호선으로 갈아타세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"지연되다 and 중단되다 both mean the service has completely stopped.",ok:!1},{text:"지연되다 = be delayed / 중단되다 = be suspended or stopped",ok:!0}],explanation:"A delayed train may still arrive and operate. 중단 signals that service is not operating on the stated section. This distinction changes whether you wait or find another route."}],canDo:"Understand delivery requests and locate a parcel from a driver message",id:"chapter-63-b7",chapterId:"chapter-63",index:6},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Alex is handling four ordinary messages during one day in Seoul and checks the important details with a Korean friend.",lines:[{speaker:"택배 기사",ko:"공동현관 앞입니다. 어디에 놓아 드릴까요?",en:"I'm at the building entrance. Where should I leave it?",romanization:"gongdonghyeongwan apimnida. eodie noa deurilkkayo?"},{speaker:"알렉스",ko:"문 앞에 놓아 주시고 사진도 보내 주세요.",en:"Please leave it at my door and send a photo too.",romanization:"mun ape noa jusigo sajindo bonae juseyo."},{speaker:"약사",ko:"기침 말고 열도 있으세요?",en:"Besides the cough, do you also have a fever?",romanization:"gichim malgo yeoldo isseuseyo?"},{speaker:"알렉스",ko:"네, 어젯밤부터 열이 조금 나요.",en:"Yes, I've had a slight fever since last night.",romanization:"ne, eojetbambuteo yeori jogeum nayo."},{speaker:"친구",ko:"관리실 공지 봤어요? 내일 오전에 단수래요.",en:"Did you see the management-office notice? They say the water will be off tomorrow morning.",romanization:"gwallisil gongji bwasseoyo? naeil ojeone dansuraeyo."},{speaker:"알렉스",ko:"네, 물을 미리 받아 두려고요.",en:"Yes, I'm planning to store some water in advance.",romanization:"ne, mureul miri bada duryeogoyo."},{speaker:"안내 방송",ko:"2호선 운행이 지연되고 있으니 다른 교통편을 이용해 주세요.",en:"Line 2 service is delayed, so please use another form of transportation.",romanization:"ihoseon unhaengi jiyeondoego isseuni dareun gyotongpyeoneul iyonghae juseyo."}]},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"2호선 운행이 지연되고 있으니 다른 교통편을 이용해 주세요.",options:[{text:"택배 기사",ok:!1},{text:"안내 방송",ok:!0}],explanation:"Line 2 service is delayed, so please use another form of transportation."},{kind:"drill",prompt:`무엇이 들어갈까요? · "I'm at the building entrance. Where should I leave it?"`,sentence:"___ 앞입니다. 어디에 놓아 드릴까요?",options:[{text:"공동현관",ok:!0},{text:"경비실",ok:!1},{text:"식후",ok:!1}],explanation:""}],canDo:"Understand delivery requests and locate a parcel from a driver message",id:"chapter-63-b8",chapterId:"chapter-63",index:7},{kind:"reading",title:"읽기 Reading · 오늘 받은 생활 안내 네 개",cards:[{kind:"read",title:"오늘 받은 생활 안내 네 개",chunks:["[배달] 고객님, 문 앞에 택배를 두었습니다. 배송 완료 사진을 확인해 주세요. [약국] 이 약은 하루에 세 번 식후에 드세요. 졸릴 수 있으니 운전하지 마세요.","[관리실] 내일 오전 10시부터 12시까지 배관 점검으로 단수됩니다. 사용할 물을 미리 받아 두세요. [교통] 현재 2호선 열차가 지연되고 있습니다. 시청역에서 1호선으로 환승해 주세요."],translation:"[Delivery] Your parcel has been left at your door. Please check the delivery-completion photo. [Pharmacy] Take this medicine three times a day after meals. It may make you drowsy, so do not drive. [Management office] The water will be shut off tomorrow from 10 a.m. to noon for plumbing inspection. Store the water you need in advance. [Transit] Line 2 trains are currently delayed. Please transfer to Line 1 at City Hall Station.",qas:[{q:"택배는 어디에 있나요?",a:"문 앞에 있습니다."},{q:"약을 먹은 뒤에 피해야 하는 행동은 무엇인가요?",a:"졸릴 수 있으므로 운전을 피해야 합니다."},{q:"단수는 언제이고 무엇을 준비해야 하나요?",a:"내일 오전 10시부터 12시까지이고, 사용할 물을 미리 받아 두어야 합니다."},{q:"열차가 지연될 때 어느 노선으로 환승해야 하나요?",a:"시청역에서 1호선으로 환승해야 합니다."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"[약국] 이 약은 하루에 세 번 ___에 드세요.",options:[{text:"공동현관",ok:!1},{text:"식후",ok:!0},{text:"경비실",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"[___] 내일 오전 10시부터 12시까지 배관 점검으로 단수됩니다.",options:[{text:"관리실",ok:!0},{text:"공동현관",ok:!1},{text:"경비실",ok:!1}],explanation:""}],canDo:"Read symptom questions and medicine frequency, timing, and warnings",id:"chapter-63-b9",chapterId:"chapter-63",index:8},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"도착하면 전화하지 말고 문자 주세요. What should you do?",sentence:null,options:[{text:"Send a text",ok:!0},{text:"Make a call",ok:!1},{text:"Leave immediately",ok:!1}],explanation:"-지 말고 rejects the call and replaces it with 문자 주세요."},{kind:"drill",prompt:"택배를 경비실에 맡겨 두었습니다. Where is the parcel?",sentence:null,options:[{text:"At the security office",ok:!0},{text:"Inside the elevator",ok:!1},{text:"At the pharmacy",ok:!1}],explanation:"경비실에 gives the current parcel location."},{kind:"drill",prompt:"이 약은 식후에 드세요. When should you take it?",sentence:null,options:[{text:"After meals",ok:!0},{text:"Before sleeping",ok:!1},{text:"On an empty stomach",ok:!1}],explanation:"식후 means after a meal."},{kind:"drill",prompt:"Which question checks for an additional fever?",sentence:null,options:[{text:"열도 있으세요?",ok:!0},{text:"열을 버리세요?",ok:!1},{text:"열로 갈아타세요?",ok:!1}],explanation:"도 adds fever to symptoms already mentioned."},{kind:"drill",prompt:"오전 10시부터 두 시간 동안 단수예요. When does it start?",sentence:null,options:[{text:"10 a.m.",ok:!0},{text:"Noon",ok:!1},{text:"Two days later",ok:!1}],explanation:"부터 marks the starting point."},{kind:"drill",prompt:"점검 중에는 이용하지 마세요. What does the notice prohibit?",sentence:null,options:[{text:"Using it during inspection",ok:!0},{text:"Calling the office",ok:!1},{text:"Reading the notice",ok:!1}],explanation:"-지 마세요 marks the prohibited action."},{kind:"drill",prompt:"열차가 지연되고 있습니다. What is the status?",sentence:null,options:[{text:"Delayed",ok:!0},{text:"Completely cancelled forever",ok:!1},{text:"Already resumed",ok:!1}],explanation:"지연 means delay, not full suspension."},{kind:"drill",prompt:"3호선으로 갈아타세요. What action is required?",sentence:null,options:[{text:"Transfer to Line 3",ok:!0},{text:"Exit through Gate 3",ok:!1},{text:"Wait three hours",ok:!1}],explanation:"갈아타다 means transfer to another vehicle or line."},{kind:"drill",prompt:"Which word means service will start again?",sentence:null,options:[{text:"재개",ok:!0},{text:"중단",ok:!1},{text:"단수",ok:!1}],explanation:"재개 is resumption; 중단 is suspension."},{kind:"drill",prompt:"Which reading order is most useful for a practical notice?",sentence:null,options:[{text:"Time → status → required action",ok:!0},{text:"Romanization → punctuation → font",ok:!1},{text:"Subject → article → plural",ok:!1}],explanation:"These three anchors reveal what changed and what you must do."}],canDo:"Find the time and required action in a building-management notice",id:"chapter-63-b10",chapterId:"chapter-63",index:9}]},{id:"chapter-64",number:64,title:"Chat abbreviations: ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ · Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",goal:"Recognize Korean consonant reactions such as ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, and ㅇㅈ.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · ㅋㅋ~",cards:[{kind:"guess",word:{ko:"ㅋㅋ",romanization:"kk",en:"haha; lol",pos:"expression",nuance:"ㅋㅋ is the texted shape of the snicker 크크/큭큭 (ㅋ is the consonant for the 'k' giggle), and among Korean 20-30s it is the default 'I'm-relaxed-and-friendly' marker — even more than a real laugh, it signals you're at ease, so chats feel cold without it. Length is meaning: ㅋㅋ is a polite chuckle, ㅋㅋㅋㅋㅋ is genuine laughter, and you stretch the string to match how funny something is (it helps that ㅋ sits under one key, so spamming it is effortless). Its near-rival ㅎㅎ is the softer cousin (a smile, not a laugh), so swapping them shifts tone — ㅋㅋ is funny, ㅎㅎ is gentle/warm. The sharp English-speaker pitfall is the lone ㅋ: in English a solo 'lol' is harmless, but a single ㅋ (or ㅋ.. / ㅋ?) can read as cold, sarcastic, even passive-aggressive — the texting equivalent of a flat 'ha,' so never go below ㅋㅋ. And keep all of it out of messages to a boss, professor, or stranger, where laughter letters look unserious; there you write plain-polite sentences with no ㅋ at all."},sentence:{ko:"이 댓글 완전 웃겨 ㅋㅋ.",en:"This comment is so funny lol."},target:"ㅋㅋ",options:["crying; T_T","yeah; yep","haha; lol"],note:"Casual digital laughter."},{kind:"guess",word:{ko:"ㅠㅠ",romanization:"yuyu",en:"crying; T_T",pos:"expression",nuance:"ㅠㅠ is a visual crying marker used for real sadness or playful frustration. Both 취소됐어ㅠㅠ and 취소됐어 ㅠㅠ are common: no space feels tightly attached, while a space treats it more like an emoji. Keep it to casual messages rather than formal or work writing."},sentence:{ko:"과제 제출 내일까지래 ㅠㅠ.",en:"They say the assignment is due tomorrow T_T."},target:"ㅠㅠ",options:["haha; lol","crying; T_T","yeah; yep"],note:"Sad, frustrated, or playfully distressed reaction."},{kind:"guess",word:{ko:"ㅇㅇ",romanization:"ngng",en:"yeah; yep",pos:"expression",nuance:"ㅇㅇ is the texted form of 응 (eung, casual 'yeah'), doubled to 응응, so it carries pure banmal — the informal register you'd use with people you speak 반말 to out loud. That register IS the meaning: it broadcasts 'we're equals/close.' Its near-neighbor is the polite 네/넵, and the gap between them is exactly the politeness gap, which is why the English-speaker pitfall is severe: English 'yeah' is fine to almost anyone, but firing ㅇㅇ at a boss, professor, or older stranger skips every layer of politeness and reads as blunt, even disrespectful — like grunting 'uh-huh' at a superior. The safe upgrade ladder for seniors is 네 (polite) → 넵 (cheerful-polite) → 네네 (warm). Don't confuse ㅇㅇ (yes/agreement, from 응응) with ㅇㅋ (okay/got it, from 오케이): you ANSWER a yes/no question with ㅇㅇ, but you CONFIRM an instruction with ㅇㅋ. And length carries warmth — a bare ㅇㅇ to a friend who's clearly excited can read as flat, even reluctant, so match their energy with ㅇㅇㅇㅇ or 응응!!; worse, a single curt ㅇ alone can feel like an annoyed 'k.'"},sentence:{ko:"ㅇㅇ 알겠어.",en:"Yeah, got it."},target:"ㅇㅇ",options:["haha; lol","crying; T_T","yeah; yep"],note:"Quick casual yes to a close peer."},{kind:"guess",word:{ko:"ㄹㅇ",romanization:"rieol",en:"for real; seriously",pos:"expression",nuance:"ㄹㅇ is the consonant skeleton of 리얼, Korea's borrowing of English 'real,' and it works two ways: as a reply it's emphatic agreement ('for real / no joke / facts'), and dropped inside a sentence it's an intensifier meaning 'genuinely/seriously' (이거 ㄹㅇ 웃겨 = 'this is genuinely funny'). It's very current 20-30s slang, at home in friend chats and comments, and frequently fused with ㅋㅋ as ㄹㅇㅋㅋ. Its native-Korean cousins are 진짜 and 정말 ('really/truly'), which carry the same meaning but sound a notch less slangy — and those are what you'd upgrade to in polite contexts (진짜요/정말요). Two English-speaker pitfalls: first, don't decode ㄹㅇ as 'right now' or any English-acronym guess — it's strictly '리얼/real (for real).' Second, ㄹㅇ overlaps heavily with the agreement word ㅇㅈ (인정, 'agreed'), but they aren't identical: ㄹㅇ asserts 'that's TRUE,' while ㅇㅈ concedes 'I ADMIT/agree' — close enough to stack (ㄹㅇ ㅇㅈ) but ㄹㅇ also works as a standalone intensifier where ㅇㅈ can't. And keep it casual: this is young-person slang, so with seniors say 진짜요/정말요, not ㄹㅇ. Note too that position rewrites the meaning — bare ㄹㅇ is 'true,' ㄹㅇ? is 'seriously?!', and mid-sentence ㄹㅇ is just 'really' — so the same two letters do three different jobs."},sentence:{ko:"이 노래 ㄹㅇ 좋아.",en:"This song is seriously good."},target:"ㄹㅇ",options:["for real; seriously","haha; lol","crying; T_T"],note:"Truth/intensity marker from 리얼."},{kind:"guess",word:{ko:"ㅇㅈ",romanization:"injeong",en:"agreed; true that",pos:"expression",nuance:"ㅇㅈ is the consonant frame of 인정 (Sino-Korean 認定, 'recognize + fix/settle'), literally 'to acknowledge/admit something as so' — and as slang it became young Koreans' punchy way to say 'agreed, that's facts.' Its polite equivalents are 맞아요 ('that's right'), 동의해요 ('I agree'), and very formal 동의합니다, which are what you'd use with seniors. Two English-speaker pitfalls. First, the literal core is 'acknowledge/admit,' so beyond cheerful agreement it can carry a faint flavor of conceding a point ('okay, I'll grant you that') — and the bare-noun 인정 even works as a real verb (그 실수는 인정 = 'I admit that mistake'); reading it as only upbeat 'yes!' misses that edge. Second, don't blur it with ㄹㅇ: ㅇㅈ = 'I agree/admit (인정),' a stance toward what you said; ㄹㅇ = 'for real/genuinely (리얼),' a claim about truth that can also intensify a sentence. They pair (ㄹㅇ ㅇㅈ) but aren't swappable everywhere. As always, keep ㅇㅈ casual — to a boss write 맞습니다 / 동의합니다. And mind the function: ㅇㅈ endorses an OPINION/take, so it fits 'good song / weekdays are better' — it is not a plain factual 'yeah' to a yes/no (that's ㅇㅇ)."},sentence:{ko:"A: 이 댓글이 제일 웃겨. / B: ㅇㅈ.",en:"A: This comment is the funniest. / B: Agreed."},target:"ㅇㅈ",options:["haha; lol","agreed; true that","crying; T_T"],note:"Endorses an opinion or take."},{kind:"guess",word:{ko:"완전",romanization:"wanjeon",en:"totally; really",pos:"adverb",nuance:"완전 literally means complete, but in casual speech it works as a general booster. It can sound youthful, excited, or blunt depending on context."},sentence:{ko:"그 영상 완전 웃겨.",en:"That video is totally funny."},target:"완전",options:["haha; lol","crying; T_T","totally; really"],note:"Casual intensifier, not formal writing."},{kind:"payoff",line:{speaker:"민서",ko:"그 댓글 봤어? 완전 웃겨 ㅋㅋㅋ.",en:"Did you see that comment? It's so funny lol."},hl:"ㅋㅋ"}],canDo:"Read and use chat tokens like ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ in casual messages",id:"chapter-64-b1",chapterId:"chapter-64",index:0},{kind:"pattern",title:"문법 Grammar · Chat abbreviations: ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ",cards:[{kind:"teach",name:"Chat abbreviations: ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ",sub:"",rows:[{when:"Something is funny; softening a message; showing you're amused",add:"ㅋㅋ (more ㅋ = harder laugh: ㅋㅋㅋㅋ)",ex:"아 진짜 웃겨 ㅋㅋㅋ (lol that's so funny)"},{when:"Crying, sad, disappointed, or begging cutely",add:"ㅠㅠ (also ㅜㅜ); pure emotion, no laugh",ex:"나 시험 망했어 ㅠㅠ (I bombed the test)"},{when:"A short 'yeah / yes / ok' reply between friends",add:"ㅇㅇ (= 응응, a casual yes)",ex:"ㅇㅇ 나도 갈게 (yeah, I'll go too)"},{when:"Stressing 'for real / seriously / no joke'",add:"ㄹㅇ (= 레알, from English 'real')",ex:"ㄹㅇ 그 카페 맛있어 (that cafe's legit good)"},{when:"Agreeing hard with what someone said",add:"ㅇㅈ (= 인정, 'I acknowledge it')",ex:"ㅇㅈ 그 영화 별로였음 (agreed, that movie was meh)"}],examples:[{ko:"ㅋㅋㅋ 너 진짜 웃긴다",en:"lololol you're so funny",romanization:"kkk neo jinjja utginda",note:"Repeating ㅋ = a bigger laugh; a single ㅋ can read as cold or sarcastic."},{ko:"비 와서 약속 취소됐어 ㅠㅠ",en:"It rained so the plan got cancelled",romanization:"bi waseo yaksok chwiso-dwaesseo",note:"ㅠㅠ carries the disappointment, so you don't need extra sad words."}],more:{func:"These are consonant-only shorthand 'reaction' tokens Koreans type in chat (KakaoTalk, comments, DMs). They're not words you pronounce out loud; they're typed signals, almost like emoji. ㅋㅋ shows laughter, ㅠㅠ shows crying/sadness, and ㅇㅇ / ㄹㅇ / ㅇㅈ are clipped one-shot replies (yeah / for real / agreed). They make a message feel casual and friendly, which is exactly why you use them with friends and peers, never with a boss, teacher, or stranger.",funcLead:"These are consonant-only shorthand 'reaction' tokens Koreans type in chat (KakaoTalk, comments, DMs).",keyPoint:{label:"Typed sound vs spoken word",body:"ㅋㅋ and ㅠㅠ are typed, not spoken — you don't say 'kuh-kuh' out loud. ㅇㅇ / ㄹㅇ / ㅇㅈ are clipped spellings of 응응 / 레알 / 인정, so reading them aloud means saying the full word, not naming the letters."},pronunciation:"",pitfall:{wrong:"ㅋㅋ 알겠습니다, 부장님.",right:"네, 알겠습니다, 부장님.",explanation:"English speakers treat 'haha/lol' as harmless filler, but dropping ㅋㅋ or ㅇㅇ into a message to a superior reads as flippant and too casual. Keep these for friends and peers only."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "lololol you're so funny"`,tokens:["ㅋㅋㅋ","너","진짜","웃긴다"],correct:"ㅋㅋㅋ 너 진짜 웃긴다",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "It rained so the plan got cancelled"',tokens:["비","와서","약속","취소됐어","ㅠㅠ"],correct:"비 와서 약속 취소됐어 ㅠㅠ",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"네, 알겠습니다, 부장님.",ok:!0},{text:"ㅋㅋ 알겠습니다, 부장님.",ok:!1}],explanation:"English speakers treat 'haha/lol' as harmless filler, but dropping ㅋㅋ or ㅇㅇ into a message to a superior reads as flippant and too casual. Keep these for friends and peers only."}],canDo:"Read and use chat tokens like ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ in casual messages",id:"chapter-64-b2",chapterId:"chapter-64",index:1},{kind:"words",title:"단어 Words 2 · 레전드~",cards:[{kind:"guess",word:{ko:"레전드",romanization:"rejeondeu",en:"legendary; iconic",pos:"noun",nuance:"레전드 can praise something impressive, but it can also be ironic when something is absurd or unbelievably bad."},sentence:{ko:"오늘 라이브 채팅 레전드였어.",en:"Today's live chat was legendary."},target:"레전드",options:["online comment","like button","legendary; iconic"],note:"Can be praise or ironic reaction."},{kind:"guess",word:{ko:"개웃겨",romanization:"gaeutgyeo",en:"hilarious; so funny",pos:"expression",nuance:"개웃겨 is stronger and rougher than 너무 웃겨 or 진짜 웃겨. It can sound friendly, but it can also sound careless if the relationship is not close."},sentence:{ko:"이 댓글 개웃겨 ㅋㅋㅋ.",en:"This comment is hilarious lolol."},target:"개웃겨",options:["haha; lol","hilarious; so funny","crying; T_T"],note:"Very casual and rougher than 진짜 웃겨."},{kind:"guess",word:{ko:"댓글",romanization:"daetgeul",en:"online comment",pos:"noun",nuance:"댓글 is online. For a spoken comment or opinion, 말 or 의견 may fit better."},sentence:{ko:"그 게시물에 댓글 달았어.",en:"I left a comment on that post."},target:"댓글",options:["legendary; iconic","online comment","like button"],note:"댓글을 달다 is the standard collocation."},{kind:"guess",word:{ko:"좋아요",romanization:"joayo",en:"like button",pos:"noun",nuance:"좋아요 is the 해요체 form of the adjective 좋다 'to be good, nice, likeable', but standing alone as a reply it works as a reaction expression: 'sounds good / I like it / okay, let's do that.' As a response to a suggestion (같이 갈까요? 내일 만날까요?) it's an enthusiastic yes — warmer and more committed than a bare 네, which just confirms. The critical dividing line is 괜찮아요. As a reply to an OFFER, 괜찮아요 usually means 'no thanks, I'm fine as I am' — it's a polite refusal — while 좋아요 means 'yes please.' English 'okay', 'fine', and 'that's good' map onto both of them, which is exactly why beginners accidentally decline the coffee, the bag, or the second helping they actually wanted. If someone offers you something and you want it, say 좋아요 or 네, 주세요; 괜찮아요 will get it taken away. 좋아요 also keeps its plain adjective sense ('it's good/nice': 날씨가 좋아요, 이 카페 좋아요), and it's the Korean name of the social-media Like button — 좋아요(를) 누르다 'to like a post.' Register ladder: 좋아 (banmal) → 좋아요 (polite) → 좋습니다 (formal); 좋네요 reacts in the moment to something in front of you. One caution upward: a bare 좋아요 in reply to a senior's proposal can read as you evaluating their idea, so with a boss the natural answers are 네, 좋습니다 or 네, 그렇게 하겠습니다. The second English-speaker pitfall is the 좋아요 / 좋아해요 split: 좋다 is an ADJECTIVE, so the thing takes 이/가 (김치가 좋아요 'I like kimchi / kimchi is good'), while 좋아하다 is a VERB, so the thing takes 을/를 (김치를 좋아해요 'I like kimchi'). 김치를 좋아요 is simply wrong — pick one pattern and match the particle to it."},sentence:{ko:"방금 좋아요 눌렀어.",en:"I just hit like."},target:"좋아요",options:["legendary; iconic","online comment","like button"],note:"The button is pressed, so use 누르다."},{kind:"guess",word:{ko:"공유하다",romanization:"gongyuhada",en:"to share",pos:"verb",nuance:"공유하다 is broader than sending. 보내다 is to send; 공유하다 emphasizes making content available or passing it along."},sentence:{ko:"재미있어서 친구한테 공유했어.",en:"It was funny, so I shared it with a friend."},target:"공유했",options:["to share","haha; lol","crying; T_T"],note:"The recipient takes 한테 or 에게."},{kind:"guess",word:{ko:"라이브 채팅",romanization:"raibeu chaeting",en:"live chat",pos:"noun",nuance:"라이브 채팅 is a channel, not a writing style. It invites short reactions, abbreviations, and fast turn-taking."},sentence:{ko:"라이브 채팅이 너무 빨라서 댓글을 다 못 읽었어.",en:"The live chat was so fast that I couldn't read all the comments."},target:"라이브 채팅",options:["live chat","legendary; iconic","online comment"],note:"A natural place for short reactions."},{kind:"payoff",line:{speaker:"민서",ko:"그 댓글 봤어? 완전 웃겨 ㅋㅋㅋ.",en:"Did you see that comment? It's so funny lol."},hl:"댓글"}],canDo:"Crank up the feeling with colloquial intensifiers (완전 / 진짜 / 대박 / 레전드)",id:"chapter-64-b3",chapterId:"chapter-64",index:2},{kind:"pattern",title:"문법 Grammar · Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",cards:[{kind:"hunt",name:"Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",sub:"",lines:[{tokens:[{pre:"이",mid:"",post:"",hit:!1},{pre:"카페",mid:"",post:"",hit:!1},{pre:"분위기",mid:"",post:"",hit:!1},{pre:"",mid:"완전",post:"",hit:!0},{pre:"좋아",mid:"",post:"",hit:!1}],ko:"이 카페 분위기 완전 좋아",en:"This cafe's vibe is totally great",romanization:"i kape bunwigi wanjeon joa"},{tokens:[{pre:"나",mid:"",post:"",hit:!1},{pre:"",mid:"진짜",post:"",hit:!0},{pre:"배고파",mid:"",post:"",hit:!1},{pre:"죽겠어",mid:"",post:"",hit:!1}],ko:"나 진짜 배고파 죽겠어",en:"I'm seriously starving",romanization:"na jinjja baegopa jukgesseo"}],rule:{name:"Colloquial intensifiers: 완전 / 진짜 / 너무 / 대박 / 레전드",rows:[{when:"'so / totally' before an adjective; very common in casual talk",add:"완전 + adjective",ex:"이거 완전 맛있어 (this is so good)"},{when:"'really / seriously'; the most neutral, works almost anywhere",add:"진짜 + adjective/verb",ex:"진짜 피곤해 (I'm really tired)"},{when:"'so (much)'; in casual speech often just means 'very', not 'excessively'",add:"너무 + adjective",ex:"너무 좋아 (I love it / it's so nice)"},{when:"'awesome / no way!'; exclamation for shocking-good (or shocking-bad) news",add:"대박 (standalone or 대박이다)",ex:"헐 대박 (omg no way!)"},{when:"'legendary / epic'; calling something unforgettably great (or hilariously bad)",add:"레전드 (standalone or 레전드 + 이다)",ex:"어제 공연 레전드였어 (last night's show was legendary)"}]},more:{func:"These are casual booster words meaning roughly 'so / totally / really / insanely (good)'. Speakers drop them in front of an adjective or verb, or use them alone as an exclamation, to crank up the feeling. 진짜 and 너무 are everyday-neutral; 완전 sounds breezy and young; 대박 and 레전드 are slangy hype words for something amazing or unforgettable. They live in speech, chat, and reviews, and they carry the emotion that flat, polite sentences leave out.",funcLead:"These are casual booster words meaning roughly 'so / totally / really / insanely (good)'.",keyPoint:{label:"너무: textbook 'too much' vs real-life 'very'",body:"Textbooks teach 너무 = 'too (excessively)', but in everyday speech 너무 좋아 just means 'I love it', not 'I like it too much'. Context, not the word itself, decides whether it's negative."},pronunciation:"대박 is often stretched as 대애박~ for emphasis, and 헐 frequently leads into it (헐 대박). 완전 is written 완전 but in fast speech can sound like a quick 완젼.",pitfall:{wrong:"그 영화 매우 대박이었습니다.",right:"그 영화 완전 대박이었어. / 그 영화 정말 좋았습니다.",explanation:"Don't mix slang (대박, 완전) with formal endings (-습니다) or stiff adverbs (매우). Slang intensifiers belong with casual endings; when you need to sound polite or formal, switch to 정말/아주/매우 and drop the slang."}}},{kind:"drill",prompt:"Whoa, no way — is that for real?",sentence:"헐 ___, 그거 진짜야?",options:[{text:"완전",ok:!1},{text:"진짜",ok:!1},{text:"대박",ok:!0}],explanation:"대박 works as a one-word reaction to surprising news, good or bad."},{kind:"drill",prompt:"Did you watch the game? It was an absolute legend lol",sentence:"어제 경기 봤어? ___ 레전드였어 ㅋㅋ",options:[{text:"진짜",ok:!1},{text:"완전",ok:!0},{text:"대박",ok:!1}],explanation:"레전드 + 이다 turns the noun into 'was epic'; 완전 stacks on top for extra hype."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "This cafe's vibe is totally great"`,tokens:["이","카페","분위기","완전","좋아"],correct:"이 카페 분위기 완전 좋아",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm seriously starving"`,tokens:["나","진짜","배고파","죽겠어"],correct:"나 진짜 배고파 죽겠어",explanation:""}],canDo:"Crank up the feeling with colloquial intensifiers (완전 / 진짜 / 대박 / 레전드)",id:"chapter-64-b4",chapterId:"chapter-64",index:3},{kind:"pattern",title:"문법 Grammar · Platform verbs: 댓글 달다, 좋아요 누르다, 공유하다, 구독하다",cards:[{kind:"teach",name:"Platform verbs: 댓글 달다, 좋아요 누르다, 공유하다, 구독하다",sub:"",rows:[{when:"Leaving / writing a comment on a post or video",add:"댓글(을) 달다 (lit. 'hang a comment')",ex:"영상에 댓글 달았어 (I left a comment on the video)"},{when:"Tapping the like button / heart",add:"좋아요(를) 누르다 (lit. 'press the like')",ex:"사진에 좋아요 눌러 줘 (hit like on the photo)"},{when:"Forwarding / reposting content to others",add:"공유하다 (share)",ex:"이 글 친구한테 공유했어 (I shared this post with a friend)"},{when:"Following a channel/creator to get new uploads",add:"구독하다 (subscribe)",ex:"그 채널 구독했어 (I subscribed to that channel)"}],examples:[{ko:"구독하고 좋아요 눌러 주세요!",en:"Please subscribe and hit like!",romanization:"gudok-hago joayo nulleo juseyo!",note:"The set phrase every Korean YouTuber says; note 좋아요 pairs with 누르다, never 하다."},{ko:"내 사진에 누가 댓글 달았어",en:"Someone left a comment on my photo",romanization:"nae sajin-e nuga daetgeul darasseo",note:"달다 conjugates to 달았어 (darasseo); the 을 is dropped, which is normal in casual speech."}],more:{func:"Every social-media action in Korean has a fixed noun + verb pairing you have to memorize rather than translate from English. You 'hang' a comment (댓글을 달다), 'press' a like (좋아요를 누르다), 'share' (공유하다), and 'subscribe' (구독하다). The object particle 을/를 is often dropped in casual chat (댓글 달았어), but the verb pairing is fixed — pick the wrong verb and it sounds off even when every word is technically correct.",funcLead:"Every social-media action in Korean has a fixed noun + verb pairing you have to memorize rather than translate from English.",keyPoint:{label:"좋아요 누르다, not 좋아요 하다",body:"English 'like' is one word, so learners reach for 좋아요 하다 — but Korean fixes each action to its own verb: a like is pressed (누르다), a comment is hung (달다). Memorize the pair instead of translating the verb."},pronunciation:"",pitfall:{wrong:"사진을 좋아요 했어요. / 댓글을 썼어요.",right:"사진에 좋아요 눌렀어요. / 댓글을 달았어요.",explanation:"Two traps: (1) 좋아요 takes 누르다, not 하다; (2) for posting a comment Koreans say 댓글을 달다, not the literal 댓글을 쓰다. 쓰다 is fine for 'writing' the text itself, but 달다 is the platform action of posting it."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Please subscribe and hit like!" (구독하고 시작 · Start with 구독하고.)',tokens:["구독하고","좋아요","눌러","주세요!"],correct:"구독하고 좋아요 눌러 주세요!",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Someone left a comment on my photo" (내 시작 · Start with 내.)',tokens:["내","사진에","누가","댓글","달았어"],correct:"내 사진에 누가 댓글 달았어",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"사진을 좋아요 했어요. / 댓글을 썼어요.",ok:!1},{text:"사진에 좋아요 눌렀어요. / 댓글을 달았어요.",ok:!0}],explanation:"Two traps: (1) 좋아요 takes 누르다, not 하다; (2) for posting a comment Koreans say 댓글을 달다, not the literal 댓글을 쓰다. 쓰다 is fine for 'writing' the text itself, but 달다 is the platform action of posting it."}],canDo:"Use fixed platform verb pairings (좋아요 누르다, 댓글 달다, 공유하다)",id:"chapter-64-b5",chapterId:"chapter-64",index:4},{kind:"pattern",title:"문법 Grammar · Register: ㅇㅇ vs 네 / 알겠어요",cards:[{kind:"teach",name:"Register: ㅇㅇ vs 네 / 알겠어요",sub:"",rows:[{when:"Close friend / peer, in chat — quick 'yeah'",add:"ㅇㅇ / 응",ex:"ㅇㅇ 거기서 보자 (yeah, see you there)"},{when:"Close friend / peer — strong 'agreed, true'",add:"ㅇㅈ / 인정",ex:"ㅇㅈ 그건 좀 너무했어 (agreed, that was a bit much)"},{when:"Anyone you respect — polite 'yes'",add:"네 (not ㅇㅇ)",ex:"네, 알겠어요 (yes, got it)"},{when:"Boss / teacher / customer — polite 'understood'",add:"알겠어요 / 알겠습니다",ex:"네, 알겠습니다 (yes, understood)"}],examples:[{ko:"A: 내일 회의 2시야 / B: ㅇㅇ 알았어",en:"A: tomorrow's meeting is at 2 / B: yep, got it",romanization:"naeil hoeui du-siya / eung-eung arasseo",note:"Friend-to-friend, so ㅇㅇ + 반말 (알았어) is natural and warm."},{ko:"네, 알겠습니다. 바로 처리할게요",en:"Yes, understood. I'll take care of it right away",romanization:"ne, algetseumnida. baro cheori-halgeyo",note:"To a boss or client; 네 + 알겠습니다 is the safe default at work."}],more:{func:"The same meaning ('yes / got it / agreed') wears very different clothes depending on who you're talking to. ㅇㅇ, 응, ㅇㅈ, and 반말 belong to text chat with close friends and peers. 네 / 알겠어요 / 알겠습니다 are what you say or type to anyone you respect — a teacher, a customer, an older person, a boss. Picking the wrong register isn't a grammar mistake; it's a social one. So before you reply, read the relationship: is this someone you'd speak 반말 to, or someone you owe 존댓말?",funcLead:"The same meaning ('yes / got it / agreed') wears very different clothes depending on who you're talking to.",keyPoint:{label:"Register is a relationship choice, not a vocab choice",body:"ㅇㅇ and 네 mean the same thing; what differs is who you're allowed to say it to. When unsure, default to 네/알겠어요 — being slightly too polite is invisible, but being too casual is rude."},pronunciation:"",pitfall:{wrong:"(부장님께) ㅇㅇ 알겠어요.",right:"네, 알겠습니다.",explanation:"Learners who finally feel comfortable with chat slang start sprinkling ㅇㅇ everywhere, including replies to a boss or teacher. ㅇㅇ is 반말-level casual; to a superior it reads as curt and disrespectful. Match the register to the person: 존댓말 gets 네, not ㅇㅇ."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Yes, understood. I'll take care of it right away"`,tokens:["네,","알겠습니다.","바로","처리할게요"],correct:"네, 알겠습니다. 바로 처리할게요",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"네, 알겠습니다.",ok:!0},{text:"(부장님께) ㅇㅇ 알겠어요.",ok:!1}],explanation:"Learners who finally feel comfortable with chat slang start sprinkling ㅇㅇ everywhere, including replies to a boss or teacher. ㅇㅇ is 반말-level casual; to a superior it reads as curt and disrespectful. Match the register to the person: 존댓말 gets 네, not ㅇㅇ."}],canDo:"Switch register correctly — ㅇㅇ with friends vs 네 / 알겠어요 in formal replies",id:"chapter-64-b6",chapterId:"chapter-64",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Friends react to a comment thread, then rewrite the same reaction for a formal setting.",lines:[{speaker:"민서",ko:"그 댓글 봤어? 완전 웃겨 ㅋㅋㅋ.",en:"Did you see that comment? It's so funny lol.",romanization:"geu daetgeul bwasseo? wanjeon utgyeo kkk."},{speaker:"지훈",ko:"ㅇㅇ 봤어. 헐, 좋아요 눌렀어?",en:"Yeah, I saw it. Whoa, did you hit like?",romanization:"ngng bwasseo. heol, joayo nulleosseo?"},{speaker:"민서",ko:"응, 친구한테 공유했어. 댓글 반응도 레전드야.",en:"Yeah, I shared it with a friend. The comment reactions are legendary too.",romanization:"eung, chinguhante gongyuhaesseo. daetgeul baneungdo rejeondeuya."},{speaker:"지훈",ko:"공식 글에는 ㅋㅋ 빼고 재미있었습니다처럼 써야 해.",en:"In an official post, you should leave out ㅋㅋ and write something like 'it was interesting.'",romanization:"gongsik geureneneun kk ppaego jaemiisseotseumnidacheoreom sseoya hae."}]},{kind:"order",prompt:"Build a close-friend chat reply: 'Yep, see you tomorrow.'",tokens:["ㅇㅇ","내일 봐"],correct:"ㅇㅇ 내일 봐",explanation:"ㅇㅇ is a casual yes/yeah used with close friends. It should not be used with teachers or formal contacts."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"공식 글에는 ㅋㅋ 빼고 재미있었습니다처럼 써야 해.",options:[{text:"민서",ok:!1},{text:"지훈",ok:!0}],explanation:"In an official post, you should leave out ㅋㅋ and write something like 'it was interesting.'"},{kind:"drill",prompt:`무엇이 들어갈까요? · "Did you see that comment? It's so funny lol."`,sentence:"그 댓글 봤어? 완전 웃겨 ___ㅋ.",options:[{text:"ㅠㅠ",ok:!1},{text:"ㅇㅇ",ok:!1},{text:"ㅋㅋ",ok:!0}],explanation:""}],canDo:"Read and use chat tokens like ㅋㅋ, ㅠㅠ, ㅇㅇ, ㄹㅇ, ㅇㅈ in casual messages",id:"chapter-64-b7",chapterId:"chapter-64",index:6},{kind:"reading",title:"읽기 Reading · 친구 단톡방과 공식 글 구분하기",cards:[{kind:"read",title:"친구 단톡방과 공식 글 구분하기",chunks:["친구 단톡방에서는 이 댓글 완전 웃겨 ㅋㅋㅋ처럼 짧고 감정적인 표현이 자연스럽다. ㅇㅇ은 빠른 대답이고, ㄹㅇ ㅇㅈ은 상대의 의견에 강하게 동의하는 반응이다. 라이브 채팅에서는 이런 표현이 빠르게 올라오기 때문에 글이 문장보다 반응에 가깝다.","그러나 교수님께 보내는 메시지나 회사 계정의 공식 글에서는 같은 표현을 그대로 쓰면 가볍거나 무례하게 들릴 수 있다. 이때는 네, 확인했습니다, 정말 재미있었습니다, 저도 그렇게 생각합니다처럼 완전한 문장으로 바꾸는 것이 안전하다."],translation:"In a friend group chat, short emotional lines like 'this comment is so funny lol' feel natural. ㅇㅇ is a quick answer, and ㄹㅇ ㅇㅈ strongly agrees with someone's opinion. In live chat, these forms appear quickly, so the writing feels more like reactions than full sentences. However, if you use the same expressions in a message to a professor or an official company post, they can sound too casual or rude. In those settings, it is safer to rewrite them as full sentences such as 'Yes, I have confirmed it,' 'It was really interesting,' or 'I also think so.'",qas:[{q:"친구 단톡방에서 자연스러운 표현은 무엇인가요?",a:"이 댓글 완전 웃겨 ㅋㅋㅋ 같은 짧고 감정적인 표현입니다."},{q:"ㄹㅇ ㅇㅈ은 어떤 반응인가요?",a:"상대의 의견에 강하게 동의하는 반응입니다."},{q:"공식 글에서는 왜 표현을 바꿔야 하나요?",a:"그대로 쓰면 가볍거나 무례하게 들릴 수 있기 때문입니다."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"친구 단톡방에서는 이 댓글 완전 웃겨 ___ㅋ처럼 짧고 감정적인 표현이 자연스럽다.",options:[{text:"ㅋㅋ",ok:!0},{text:"ㅠㅠ",ok:!1},{text:"개웃겨",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___은 빠른 대답이고, ㄹㅇ ㅇㅈ은 상대의 의견에 강하게 동의하는 반응이다.",options:[{text:"ㅠㅠ",ok:!1},{text:"ㅇㅇ",ok:!0},{text:"개웃겨",ok:!1}],explanation:""}],canDo:"Crank up the feeling with colloquial intensifiers (완전 / 진짜 / 대박 / 레전드)",id:"chapter-64-b8",chapterId:"chapter-64",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"A close friend asks, 내일 7시에 볼까? Which reply fits casual chat?",sentence:null,options:[{text:"ㅇㅇ 알겠어.",ok:!0},{text:"네, 확인했습니다.",ok:!1},{text:"따라서 참석하겠습니다.",ok:!1}],explanation:"ㅇㅇ is natural only with close peers."},{kind:"drill",prompt:"Which sentence is safest for a professor after a funny class video?",sentence:null,options:[{text:"정말 재미있었습니다.",ok:!0},{text:"개웃겨요 ㅋㅋ.",ok:!1},{text:"ㄹㅇ 레전드였어요.",ok:!1}],explanation:"The polite/formal sentence keeps the reaction respectful."},{kind:"drill",prompt:"Which verb naturally goes with 좋아요?",sentence:null,options:[{text:"누르다",ok:!0},{text:"하다",ok:!1},{text:"치다",ok:!1}],explanation:"좋아요 is treated as a button, so Koreans press it."},{kind:"drill",prompt:"Which expression agrees with someone's opinion?",sentence:null,options:[{text:"ㅇㅈ",ok:!0},{text:"ㅠㅠ",ok:!1},{text:"ㅋㅋ",ok:!1}],explanation:"ㅇㅈ comes from 인정 and means agreed or true that."},{kind:"drill",prompt:"Which expression is the roughest, most casual way to say something is hilarious?",sentence:null,options:[{text:"개웃겨",ok:!0},{text:"정말 재미있습니다",ok:!1},{text:"너무 웃겨요",ok:!1}],explanation:"개웃겨 is natural in close peer chat but too rough for formal settings."},{kind:"drill",prompt:"댓글___ 달았어요. (I left a comment.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"댓글을 달다 is the natural verb phrase for leaving a comment. 이 would make the comment the subject."},{kind:"drill",prompt:"Which abbreviation means “for real / seriously” in casual chat?",sentence:null,options:[{text:"ㄹㅇ",ok:!0},{text:"ㅠㅠ",ok:!1},{text:"ㅇㅈ",ok:!1}],explanation:"ㄹㅇ is shorthand for real/seriously. ㅠㅠ shows crying, and ㅇㅈ means agreed."}],canDo:"Use fixed platform verb pairings (좋아요 누르다, 댓글 달다, 공유하다)",id:"chapter-64-b9",chapterId:"chapter-64",index:8}]},{id:"chapter-65",number:65,title:"아직 있나요? / 거래 가능할까요? · V-아/어 놓다 / V-아/어 두다",goal:"Understand availability, condition, price, and pickup details in secondhand-market chats.",biteCount:9,bites:[{kind:"words",title:"단어 Words 1 · 판매 중~",cards:[{kind:"guess",word:{ko:"판매 중",romanization:"panmae jung",en:"currently for sale",pos:"phrase",nuance:"중 feels more immediate than broad -고 있어요. It often sounds like 'right in the middle of it.'"},sentence:{ko:"네, 아직 판매 중이에요.",en:"Yes, it is still for sale."},target:"판매 중",options:["in-person transaction","currently for sale","signs of use; wear"],note:"The opposite status may be 예약 중 or 판매 완료."},{kind:"guess",word:{ko:"직거래",romanization:"jikgeorae",en:"in-person transaction",pos:"noun",nuance:"'직거래' 直去來 는 한자로 '곧바로(直) 오가며(去來) 거래한다', 곧 중개나 택배 없이 사는 사람과 파는 사람이 직접 만나 물건과 돈을 주고받는 걸 뜻해요. 헷갈리기 쉬운 짝은 발음이 비슷한 '직구'(直購, 직접 구매)인데, '직구'는 해외 사이트에서 중간상 없이 사들이는 해외 직접구매고, '직거래'는 보통 국내 중고 거래에서 얼굴 보고 만나는 방식이에요 — 하나는 해외 온라인, 하나는 국내 대면이라 방향이 정반대입니다. 또 영어 화자가 자주 빠지는 함정은 'direct'를 '직접 깎아 주는 직거래가니까 싸다'처럼 가격 개념으로 오해하는 것인데, 직거래는 가격이 아니라 '거래 방식'(대면)을 가리킵니다. 안전을 위해 사람 많은 지하철역·편의점 앞에서 만나는 게 보통이고, 멀면 '택배 거래'를 해요."},sentence:{ko:"역 앞에서 직거래하고 싶어요.",en:"I'd like to meet in front of the station for the exchange."},target:"직거래",options:["in-person transaction","signs of use; wear","defect; flaw"],note:"Confirm both time and public meeting place."},{kind:"guess",word:{ko:"예약 중",romanization:"yeyak jung",en:"currently reserved",pos:"phrase",nuance:"중 feels more immediate than broad -고 있어요. It often sounds like 'right in the middle of it.'"},sentence:{ko:"지금은 다른 분이 예약 중이에요.",en:"It is currently reserved by another person."},target:"예약 중",options:["in-person transaction","currently reserved","signs of use; wear"],note:"The sale may not yet be complete."},{kind:"guess",word:{ko:"사용감",romanization:"sayonggam",en:"signs of use; wear",pos:"noun"},sentence:{ko:"사용감은 조금 있지만 깨끗해요.",en:"It shows a little wear, but it is clean."},target:"사용감",options:["signs of use; wear","in-person transaction","defect; flaw"],note:"A common condition word in used-item listings."},{kind:"guess",word:{ko:"하자",romanization:"haja",en:"defect; flaw",pos:"noun"},sentence:{ko:"작동에는 하자가 없어요.",en:"There is no defect in how it works."},target:"하자",options:["in-person transaction","signs of use; wear","defect; flaw"],note:"Ask whether the defect affects appearance or function."},{kind:"payoff",line:{speaker:"알렉스",ko:"안녕하세요. 이 조명 아직 판매 중인가요?",en:"Hello. Is this lamp still for sale?"},hl:"판매 중"}],canDo:"Understand whether a secondhand item is available, reserved, defective, or negotiable",id:"chapter-65-b1",chapterId:"chapter-65",index:0},{kind:"pattern",title:"문법 Grammar · 아직 있나요? / 거래 가능할까요?",cards:[{kind:"hunt",name:"아직 있나요? / 거래 가능할까요?",sub:"checking a secondhand listing",lines:[{tokens:[{pre:"안녕하세요.",mid:"",post:"",hit:!1},{pre:"이",mid:"",post:"",hit:!1},{pre:"의자",mid:"",post:"",hit:!1},{pre:"",mid:"아직",post:"",hit:!0},{pre:"",mid:"있나요",post:"?",hit:!0}],ko:"안녕하세요. 이 의자 아직 있나요?",en:"Hello. Is this chair still available?",romanization:"annyeonghaseyo. i uija ajik innayo?"},{tokens:[{pre:"오늘",mid:"",post:"",hit:!1},{pre:"저녁",mid:"",post:"",hit:!1},{pre:"7시에",mid:"",post:"",hit:!1},{pre:"직",mid:"거래",post:"",hit:!0},{pre:"",mid:"가능할까요",post:"?",hit:!0}],ko:"오늘 저녁 7시에 직거래 가능할까요?",en:"Would an in-person exchange at 7 this evening be possible?",romanization:"oneul jeonyeok ilgopsie jikgeorae ganeunghalkkayo?"}],rule:{name:"아직 있나요? / 거래 가능할까요?",rows:[{when:"Checking whether the item is still available",add:"아직 + 있나요? / 판매 중인가요?",ex:"이 책 아직 있나요?"},{when:"Checking whether an arrangement is possible",add:"noun/action + 가능할까요?",ex:"오늘 저녁에 직거래 가능할까요?"},{when:"Asking carefully about condition",add:"N은/는 어떤가요? / N이/가 있나요?",ex:"상태는 어떤가요? / 하자가 있나요?"},{when:"Asking whether price adjustment is possible",add:"가격 조정 + 가능할까요?",ex:"가격 조금 조정 가능할까요?"}]},more:{func:"A secondhand-market chat usually begins by checking whether the item is still available, then asks about time, place, price, or condition. 아직 있나요? is direct and neutral. N 가능할까요? asks whether an arrangement is possible and sounds more considerate than a flat 가능해요? when contacting a stranger.",funcLead:"A secondhand-market chat usually begins by checking whether the item is still available, then asks about time, place, price, or condition.",keyPoint:{label:"Availability, condition, and arrangement are separate questions",body:"아직 있나요? checks availability. 상태는 어떤가요? checks condition. 직거래 가능할까요? checks the arrangement. Asking one clear question at a time makes a short marketplace chat easier to understand and answer."},pronunciation:"있나요 is pronounced [인나요] because ㅆ before ㄴ becomes [ㄴ]. 가능할까요 has a tense ㄲ: [가능할까요].",pitfall:{wrong:"이거 있어요? 얼마?",right:"안녕하세요. 아직 판매 중인가요? 가격은 얼마인가요?",explanation:"The clipped version can sound abrupt when contacting a stranger. A short greeting and one complete availability question keep the message polite without making it formal or wordy."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Hello. Is this chair still available?"',tokens:["안녕하세요.","이","의자","아직","있나요?"],correct:"안녕하세요. 이 의자 아직 있나요?",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Would an in-person exchange at 7 this evening be possible?" (오늘 시작 · Start with 오늘.)',tokens:["오늘","저녁","7시에","직거래","가능할까요?"],correct:"오늘 저녁 7시에 직거래 가능할까요?",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"안녕하세요. 아직 판매 중인가요? 가격은 얼마인가요?",ok:!0},{text:"이거 있어요? 얼마?",ok:!1}],explanation:"The clipped version can sound abrupt when contacting a stranger. A short greeting and one complete availability question keep the message polite without making it formal or wordy."}],canDo:"Understand whether a secondhand item is available, reserved, defective, or negotiable",id:"chapter-65-b2",chapterId:"chapter-65",index:1},{kind:"words",title:"단어 Words 2 · 가격 조정~",cards:[{kind:"guess",word:{ko:"가격 조정",romanization:"gagyeok jojeong",en:"price adjustment; negotiation",pos:"noun",nuance:"가격(價格) is Sino-Korean — 價 'value/price' + 格 'standard' — so it literally means the 'value-standard' set on a thing, the official posted price. Its native-Korean twin is 값, and the line is feel and register: 값 is shorter, warmer, and used in fixed everyday phrases (값이 싸다, 값을 치르다), while 가격 sounds more neutral and 'tag/system' (가격표 price tag, 가격 인상 price hike) and is what you read on signs. The biggest English-speaker trap is the adjective: a high price is 비싸요 (expensive), a low price is 싸요 (cheap) — Koreans do NOT say 가격이 높아요/낮아요 the way English says 'high/low price', so importing 'high' here sounds off. Note too that to ask a clerk you rarely say the noun at all: the natural line is just 얼마예요? ('how much?'). 가격 collocates with 비싸다, 싸다, 오르다 (rise), 내리다 (drop), and 깎다 (haggle down)."},sentence:{ko:"가격 조정은 조금 어려워요.",en:"It is a little difficult to adjust the price."},target:"가격 조정은",options:["in-person transaction","price adjustment; negotiation","signs of use; wear"],note:"A polite way to refuse bargaining."},{kind:"guess",word:{ko:"무인 택배함",romanization:"muin taekbaeham",en:"unmanned parcel locker",pos:"noun"},sentence:{ko:"택배는 무인 택배함에 있습니다.",en:"The parcel is in the unmanned parcel locker."},target:"무인 택배함",options:["in-person transaction","unmanned parcel locker","signs of use; wear"],note:"Often found in apartment buildings."},{kind:"guess",word:{ko:"수령",romanization:"suryeong",en:"receipt; pickup",pos:"noun"},sentence:{ko:"오늘 안에 수령해 주세요.",en:"Please pick it up by the end of today."},target:"수령",options:["in-person transaction","signs of use; wear","receipt; pickup"],note:"Common in parcel and store-pickup messages."},{kind:"guess",word:{ko:"부재중",romanization:"bujaejung",en:"away; no one present",pos:"noun"},sentence:{ko:"부재중이라 배송하지 못했습니다.",en:"Delivery could not be completed because no one was present."},target:"부재중",options:["in-person transaction","signs of use; wear","away; no one present"],note:"Often followed by a redelivery or pickup instruction."},{kind:"guess",word:{ko:"완곡한 거절",romanization:"wangokhan geojeol",en:"softened; indirect refusal",pos:"noun phrase"},sentence:{ko:"어려울 것 같아요는 완곡한 거절에 자주 쓰여요.",en:"어려울 것 같아요 is often used for a softened refusal."},target:"완곡한 거절",options:["currently for sale","in-person transaction","softened; indirect refusal"],note:"The refusal becomes clearer when paired with a specific condition."},{kind:"payoff",line:{speaker:"택배 알림",ko:"주문하신 상품을 무인 택배함에 넣어 두었습니다.",en:"Your ordered item has been placed in the unmanned parcel locker."},hl:"무인 택배함"}],canDo:"Locate a parcel and identify a failed delivery or pickup deadline",id:"chapter-65-b3",chapterId:"chapter-65",index:2},{kind:"pattern",title:"문법 Grammar · V-아/어 놓다 / V-아/어 두다",cards:[{kind:"teach",name:"V-아/어 놓다 / V-아/어 두다",sub:"parcel storage and pickup status",rows:[{when:"A completed placement whose result remains",add:"verb stem + -아/어 놓다",ex:"찍다 → 사진을 찍어 놓다 / 넣다 → 택배함에 넣어 놓다"},{when:"Something is stored or prepared for later",add:"verb stem + -아/어 두다",ex:"보관하다 → 경비실에 보관해 두다"},{when:"Formal completed delivery update",add:"-아/어 놓았습니다 / -아/어 두었습니다",ex:"택배함에 넣어 두었습니다"},{when:"Current storage status",add:"N에 보관 중입니다",ex:"편의점에 보관 중입니다"}],examples:[{ko:"택배를 무인 택배함에 넣어 두었습니다.",en:"The parcel has been placed in the unmanned parcel locker.",romanization:"taekbaereul muin taekbaehame neoeo dueotseumnida.",note:"넣어 두었습니다 tells you the action is complete and the parcel remains there."},{ko:"부재중이라 경비실에 보관해 놓았습니다.",en:"Because you were away, it has been stored at the security office.",romanization:"bujaejungira gyeongbisire bogwanhae noasseumnida.",note:"부재중 gives the reason; 경비실 gives the pickup location."}],more:{func:"Parcel messages often describe an action whose result remains: a package was placed in a locker, left at the door, or stored at a pickup point. V-아/어 놓다 highlights the completed result you can now see or use. V-아/어 두다 highlights leaving something prepared or stored for later. In many delivery messages they overlap, but the practical result is the same: the item is waiting at the stated location.",funcLead:"Parcel messages often describe an action whose result remains: a package was placed in a locker, left at the door, or stored at a pickup point.",keyPoint:{label:"Find the current location before worrying about the grammar label",body:"넣어 두었습니다, 보관해 놓았습니다, and 보관 중입니다 all tell you that the parcel is currently waiting somewhere. The location phrase marked by 에 is the most important information: 택배함에, 경비실에, 편의점에."},pronunciation:"In 놓았습니다, the ㅎ is not heard before the vowel-initial ending. 넣어 is [너어], and 수령 is pronounced [수령].",pitfall:{wrong:"보관 중입니다 means someone is putting the parcel away right now.",right:"보관 중입니다 usually means the parcel is currently being kept at that location.",explanation:"N 중 can describe an ongoing status, not only an action happening at this second. In a parcel notice, it usually tells you where the item remains available for pickup."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The parcel has been placed in the unmanned parcel locker." (택배를 시작 · Start with 택배를.)',tokens:["택배를","무인","택배함에","넣어","두었습니다."],correct:"택배를 무인 택배함에 넣어 두었습니다.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Because you were away, it has been stored at the security office." (부재중이라 시작 · Start with 부재중이라.)',tokens:["부재중이라","경비실에","보관해","놓았습니다."],correct:"부재중이라 경비실에 보관해 놓았습니다.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"보관 중입니다 means someone is putting the parcel away right now.",ok:!1},{text:"보관 중입니다 usually means the parcel is currently being kept at that location.",ok:!0}],explanation:"N 중 can describe an ongoing status, not only an action happening at this second. In a parcel notice, it usually tells you where the item remains available for pickup."}],canDo:"Locate a parcel and identify a failed delivery or pickup deadline",id:"chapter-65-b4",chapterId:"chapter-65",index:3},{kind:"pattern",title:"문법 Grammar · 혹시 / 좀 / 괜찮으면",cards:[{kind:"hunt",name:"혹시 / 좀 / 괜찮으면",sub:"softening a request in chat",lines:[{tokens:[{pre:"",mid:"혹시",post:"",hit:!0},{pre:"오늘",mid:"",post:"",hit:!1},{pre:"저녁에",mid:"",post:"",hit:!1},{pre:"시간",mid:"",post:"",hit:!1},{pre:"돼요?",mid:"",post:"",hit:!1}],ko:"혹시 오늘 저녁에 시간 돼요?",en:"Do you happen to have time this evening?",romanization:"hoksi oneul jeonyeoge sigan dwaeyo?"},{tokens:[{pre:"",mid:"괜찮으면",post:"",hit:!0},{pre:"역",mid:"",post:"",hit:!1},{pre:"앞에서",mid:"",post:"",hit:!1},{pre:"만날까요?",mid:"",post:"",hit:!1}],ko:"괜찮으면 역 앞에서 만날까요?",en:"If that works for you, shall we meet in front of the station?",romanization:"gwaenchanheumyeon yeok apeseo mannalkkayo?"}],rule:{name:"혹시 / 좀 / 괜찮으면",rows:[{when:"Checking a possibility carefully",add:"혹시 + question",ex:"혹시 오늘 시간 돼요?"},{when:"Making a request less blunt",add:"object/action + 좀 + request",ex:"사진 좀 보내 줄래요?"},{when:"Leaving the choice open",add:"괜찮으면 + suggestion/request",ex:"괜찮으면 같이 먹어요"},{when:"Combining softeners naturally",add:"혹시 + time/condition + 좀 + request",ex:"혹시 시간 되면 이것 좀 봐 줄래요?"}]},more:{func:"Korean chat often softens a request before the main grammar appears. 혹시 signals that the speaker is checking a possibility, 좀 makes the request less blunt, and 괜찮으면 means 'if it is okay with you.' These words do not change the core action, but they show that the listener has room to say no.",funcLead:"Korean chat often softens a request before the main grammar appears.",keyPoint:{label:"Soften the assumption, not the important detail",body:"혹시 and 괜찮으면 leave room for refusal, while 좀 softens the size or force of the request. Keep the practical detail clear: when, where, and what action. A vague request is not automatically polite."},pronunciation:"괜찮으면 is pronounced [괜차느면]: ㅎ is not heard before the vowel-initial ending, and the final consonant links forward. 혹시 is [혹씨] with a tense ㅆ.",pitfall:{wrong:"혹시 means 'by any chance,' so it must appear in every polite request.",right:"Use 혹시 when you genuinely check a possibility; use 좀 or a polite ending when the possibility itself is not in question.",explanation:"혹시 is useful but not a universal politeness marker. Overusing it can make a simple message hesitant. Match the softener to what you are actually leaving open."}}},{kind:"drill",prompt:"Could you let me know if you receive the parcel?",sentence:"___ 택배 받으면 알려 줄 수 있어요?",options:[{text:"혹시",ok:!0},{text:"괜찮으면",ok:!1}],explanation:"-아/어 줄 수 있어요? asks whether the listener can do the favor."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Do you happen to have time this evening?" (혹시 시작 · Start with 혹시.)',tokens:["혹시","오늘","저녁에","시간","돼요?"],correct:"혹시 오늘 저녁에 시간 돼요?",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "If that works for you, shall we meet in front of the station?" (괜찮으면 시작 · Start with 괜찮으면.)',tokens:["괜찮으면","역","앞에서","만날까요?"],correct:"괜찮으면 역 앞에서 만날까요?",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"혹시 means 'by any chance,' so it must appear in every polite request.",ok:!1},{text:"Use 혹시 when you genuinely check a possibility; use 좀 or a polite ending when the possibility itself is not in question.",ok:!0}],explanation:"혹시 is useful but not a universal politeness marker. Overusing it can make a simple message hesitant. Match the softener to what you are actually leaving open."}],canDo:"Recognize how 혹시, 좀, and 괜찮으면 soften a chat request",id:"chapter-65-b5",chapterId:"chapter-65",index:4},{kind:"pattern",title:"문법 Grammar · V-기는 어려울 것 같아요 / V-기 힘들 것 같아요",cards:[{kind:"teach",name:"V-기는 어려울 것 같아요 / V-기 힘들 것 같아요",sub:"a soft refusal with an alternative",rows:[{when:"A careful, neutral refusal",add:"verb stem + -기는 어려울 것 같아요",ex:"만나다 → 오늘 만나기는 어려울 것 같아요"},{when:"A conversational difficulty statement",add:"verb stem + -기 힘들 것 같아요",ex:"가다 → 이번 주에는 가기 힘들 것 같아요"},{when:"Soft apology before refusal",add:"미안하지만 / 죄송하지만 + refusal",ex:"미안하지만 오늘은 못 갈 것 같아요"},{when:"Offering a practical alternative",add:"refusal + 대신 / 다음에 / N은 어때요?",ex:"오늘은 어렵고 내일 저녁은 어때요?"}],examples:[{ko:"미안하지만 오늘 만나기는 어려울 것 같아요.",en:"I'm sorry, but I don't think I can meet today.",romanization:"mianhajiman oneul mannagineun eoryeoul geot gatayo.",note:"-기는 highlights the proposed action; 어려울 것 같아요 softens the refusal."},{ko:"이번 주는 시간이 안 될 것 같아요. 다음 주는 어때요?",en:"I don't think this week will work. How about next week?",romanization:"ibeon juneun sigani an doel geot gatayo. daeum juneun eottaeyo?",note:"The alternative makes the answer useful instead of merely vague."}],more:{func:"Korean often turns down a plan by describing difficulty rather than saying a flat 싫어요 or 안 돼요. V-기는 어려울 것 같아요 means 'I don't think it will be easy/possible to V.' V-기 힘들 것 같아요 is slightly more conversational. A considerate refusal usually adds a short reason or a workable alternative.",funcLead:"Korean often turns down a plan by describing difficulty rather than saying a flat 싫어요 or 안 돼요.",keyPoint:{label:"A soft refusal still needs a clear answer",body:"어려울 것 같아요 lowers the force, but the listener still needs to know whether the plan is possible. Add 오늘은, 그 가격에는, or 이번 주에는 to show exactly what is difficult. If you want the relationship to continue, add a real alternative rather than an empty 다음에 봐요."},pronunciation:"어려울 것 같아요 is commonly heard as [어려울 걷 까타요]. The final ㅅ of 것 becomes [ㄷ], and the following ㄱ becomes tense.",pitfall:{wrong:"다음에 봐요 always promises a specific future meeting.",right:"다음 주 토요일은 어때요? gives a real alternative; 다음에 봐요 may simply close the conversation politely.",explanation:"A vague 다음에 can be sincere or can be a soft social closing. If you need an actual plan, look for or propose a concrete day, time, or place."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I'm sorry, but I don't think I can meet today."`,tokens:["미안하지만","오늘","만나기는","어려울","것","같아요."],correct:"미안하지만 오늘 만나기는 어려울 것 같아요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"다음 주 토요일은 어때요? gives a real alternative; 다음에 봐요 may simply close the conversation politely.",ok:!0},{text:"다음에 봐요 always promises a specific future meeting.",ok:!1}],explanation:"A vague 다음에 can be sincere or can be a soft social closing. If you need an actual plan, look for or propose a concrete day, time, or place."}],canDo:"Distinguish a vague social closing from a refusal that offers a concrete alternative",id:"chapter-65-b6",chapterId:"chapter-65",index:5},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Alex buys a used lamp, checks the parcel message, and then answers a friend's invitation.",lines:[{speaker:"알렉스",ko:"안녕하세요. 이 조명 아직 판매 중인가요?",en:"Hello. Is this lamp still for sale?",romanization:"annyeonghaseyo. i jomyeong ajik panmae jungingayo?"},{speaker:"판매자",ko:"네, 아직 있어요. 사용감은 조금 있지만 하자는 없어요.",en:"Yes, it is. It shows a little wear, but it has no defects.",romanization:"ne, ajik isseoyo. sayonggameun jogeum itjiman hajaneun eopseoyo."},{speaker:"알렉스",ko:"오늘 저녁에 역 앞에서 직거래 가능할까요?",en:"Would an in-person exchange in front of the station this evening be possible?",romanization:"oneul jeonyeoge yeok apeseo jikgeorae ganeunghalkkayo?"},{speaker:"판매자",ko:"오늘은 어렵고 내일 7시는 괜찮아요.",en:"Today is difficult, but tomorrow at 7 works.",romanization:"oneureun eoryeopgo naeil ilgopsineun gwaenchanayo."},{speaker:"택배 알림",ko:"주문하신 상품을 무인 택배함에 넣어 두었습니다.",en:"Your ordered item has been placed in the unmanned parcel locker.",romanization:"jumunhasin sangpumeul muin taekbaehame neoeo dueotseumnida."},{speaker:"친구",ko:"혹시 오늘 저녁에 같이 영화 볼래요?",en:"Would you happen to want to watch a movie together tonight?",romanization:"hoksi oneul jeonyeoge gachi yeonghwa bollaeyo?"},{speaker:"알렉스",ko:"미안하지만 오늘은 가기 힘들 것 같아요. 토요일은 어때요?",en:"I'm sorry, but I don't think I can go today. How about Saturday?",romanization:"mianhajiman oneureun gagi himdeul geot gatayo. toyoireun eottaeyo?"}]},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"미안하지만 오늘은 가기 힘들 것 같아요. 토요일은 어때요?",options:[{text:"판매자",ok:!1},{text:"알렉스",ok:!0}],explanation:"I'm sorry, but I don't think I can go today. How about Saturday?"},{kind:"drill",prompt:'무엇이 들어갈까요? · "Hello. Is this lamp still for sale?"',sentence:"안녕하세요. 이 조명 아직 ___인가요?",options:[{text:"예약 중",ok:!1},{text:"판매 중",ok:!0},{text:"직거래",ok:!1}],explanation:""}],canDo:"Understand whether a secondhand item is available, reserved, defective, or negotiable",id:"chapter-65-b7",chapterId:"chapter-65",index:6},{kind:"reading",title:"읽기 Reading · 세 가지 메시지에서 필요한 정보 찾기",cards:[{kind:"read",title:"세 가지 메시지에서 필요한 정보 찾기",chunks:["[중고 거래] 안녕하세요. 자전거 아직 판매 중인가요? 상태가 괜찮으면 이번 주 토요일에 직거래하고 싶어요. 가격 조정도 조금 가능할까요? [택배] 고객님이 부재중이어서 상품을 경비실에 보관해 놓았습니다.","오늘 오후 10시 전까지 수령해 주세요. [친구 카톡] 오늘 만나기는 조금 어려울 것 같아요. 미안해요. 대신 토요일 오후에는 시간이 되는데 그때는 어때요?"],translation:"[Secondhand transaction] Hello. Is the bicycle still for sale? If its condition is good, I'd like to meet for an in-person exchange this Saturday. Would a small price adjustment also be possible? [Parcel] Because you were away, your item has been stored at the security office. Please pick it up before 10 p.m. today. [Friend chat] I don't think I can meet today. Sorry. I am free Saturday afternoon instead; would that work?",qas:[{q:"구매자는 물건에 대해 어떤 세 가지를 확인하나요?",a:"판매 여부, 상태, 가격 조정 가능 여부를 확인합니다."},{q:"택배는 어디에 있고 언제까지 찾아야 하나요?",a:"경비실에 있고 오늘 오후 10시 전까지 찾아야 합니다."},{q:"친구 메시지는 완전한 거절인가요, 다른 제안이 있나요?",a:"오늘 만나는 것은 거절하지만 토요일 오후라는 다른 제안을 합니다."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"자전거 아직 ___인가요?",options:[{text:"예약 중",ok:!1},{text:"사용감",ok:!1},{text:"판매 중",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"상태가 괜찮으면 이번 주 토요일에 ___하고 싶어요.",options:[{text:"사용감",ok:!1},{text:"직거래",ok:!0},{text:"하자",ok:!1}],explanation:""}],canDo:"Locate a parcel and identify a failed delivery or pickup deadline",id:"chapter-65-b8",chapterId:"chapter-65",index:7},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which opening is best for checking a stranger's listing?",sentence:null,options:[{text:"안녕하세요. 아직 판매 중인가요?",ok:!0},{text:"이거 줘.",ok:!1},{text:"얼마? 빨리 답해.",ok:!1}],explanation:"It is brief, complete, and appropriately polite."},{kind:"drill",prompt:"사용감은 있지만 하자는 없어요. What does this mean?",sentence:null,options:[{text:"It shows wear but has no defects",ok:!0},{text:"It is brand new and sealed",ok:!1},{text:"It cannot be used",ok:!1}],explanation:"사용감 is wear; 하자 is a defect."},{kind:"drill",prompt:"예약 중이에요. What is the likely status?",sentence:null,options:[{text:"Another buyer has reserved it",ok:!0},{text:"It has never been listed",ok:!1},{text:"Delivery failed",ok:!1}],explanation:"예약 중 means a transaction has been arranged but may not be complete."},{kind:"drill",prompt:"택배함에 넣어 두었습니다. Where is the parcel now?",sentence:null,options:[{text:"In the parcel locker",ok:!0},{text:"Still on the truck",ok:!1},{text:"At the subway station",ok:!1}],explanation:"-아/어 두었습니다 tells you the completed result remains."},{kind:"drill",prompt:"배송하지 못했습니다. Was delivery completed?",sentence:null,options:[{text:"No",ok:!0},{text:"Yes",ok:!1},{text:"The message does not concern delivery",ok:!1}],explanation:"-지 못했습니다 means the action could not be completed."},{kind:"drill",prompt:"혹시 오늘 시간 돼요? What does 혹시 do?",sentence:null,options:[{text:"Checks a possibility carefully",ok:!0},{text:"Makes the sentence past tense",ok:!1},{text:"Cancels the invitation",ok:!1}],explanation:"혹시 leaves room for the listener not to be available."},{kind:"drill",prompt:"이것 좀 봐 줄래요? What does 좀 do here?",sentence:null,options:[{text:"Softens the request",ok:!0},{text:"Means the object is broken",ok:!1},{text:"Marks a future schedule",ok:!1}],explanation:"좀 often lowers the force of an everyday request."},{kind:"drill",prompt:"오늘은 어렵고 내일은 어때요? What is the alternative?",sentence:null,options:[{text:"Tomorrow",ok:!0},{text:"Today",ok:!1},{text:"No future meeting",ok:!1}],explanation:"The message refuses today and proposes tomorrow."},{kind:"drill",prompt:"그 가격에는 판매하기 어려울 것 같아요. What is being refused?",sentence:null,options:[{text:"Selling at that price",ok:!0},{text:"Selling the item at all",ok:!1},{text:"Meeting on Saturday",ok:!1}],explanation:"그 가격에는 limits the refusal to the proposed price."},{kind:"drill",prompt:"Which reply gives a real alternative?",sentence:null,options:[{text:"오늘은 못 가요. 토요일 오후는 어때요?",ok:!0},{text:"싫어요.",ok:!1},{text:"언젠가요.",ok:!1}],explanation:"It clearly refuses today and proposes a concrete new time."}],canDo:"Recognize how 혹시, 좀, and 괜찮으면 soften a chat request",id:"chapter-65-b9",chapterId:"chapter-65",index:8}]},{id:"chapter-66",number:66,title:"V-이/히/리/기- · N에/에게 + 피동",goal:"Build passive verbs with -이/히/리/기- and re-mark the sentence so the affected thing takes 이/가.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 보이다~",cards:[{kind:"guess",word:{ko:"보이다",romanization:"boida",en:"to be visible; to show",pos:"verb",nuance:"보이다 is the passive/spontaneous counterpart of 보다 (to look): something enters your field of vision on its own, so the thing seen takes 이/가 (산이 보여요 = 'the mountain is visible'), NOT 을/를. The 요-form contracts 보이-+-어요 → 보여요 (past 보였어요). The sharp contrast learners need is 보이다 vs 보다: 보다 is an active choice ('I look at / watch'), 보이다 is involuntary ('it is seen / comes into view'). A second, very frequent meaning is 'to look/seem' — adjective stem + 보이다 (행복해 보여요 'you look happy'; 비싸 보여요 'it looks expensive'); here English 'looks' maps cleanly. With 주다 it flips to active 'show' (보여 주다). The English-speaker pitfall: saying 산을 보여요 to mean 'I see the mountain' — that is wrong; use 산이 보여요 (it is visible) or 산을 봐요 (I look at it)."},sentence:{ko:"안경을 쓰니까 칠판 글씨가 훨씬 잘 보여요.",en:"With my glasses on I can see the writing on the board much better."},target:"보여",options:["to be heard, to be audible","to be visible; to show","to open, to be opened"],note:"With 이/가 and no object it is the passive of 보다."},{kind:"guess",word:{ko:"들리다",romanization:"deullida",en:"to be heard, to be audible",pos:"verb",nuance:"들리다 is the passive/spontaneous partner of 듣다 (to listen): a sound reaches your ears without effort, so what is heard takes 이/가 (음악이 들려요 = 'music is audible'), not 을/를. Note 들리다 is a regular -이다 derived verb, NOT the ㄷ-irregular 듣다 — the 요-form is 들려요 (듣-+-이-+-어요 → 들려요), and crucially it never becomes 들어요 (that would collide with 듣다's own form 들어요). The dividing line is 듣다 vs 들리다: 듣다 is deliberate ('I listen to / hear it on purpose'), 들리다 is involuntary ('it is heard, it comes through'). A second common sense is 'to sound (a certain way)': adverb + 들리다 (좋게 들려요 'sounds good'). With 주다 it means 'let/make someone hear' (노래를 들려 주다). The pitfall for English speakers: 소리를 안 들려요 — wrong particle; the sound is the subject, so 소리가 안 들려요."},sentence:{ko:"밖이 시끄러워서 목소리가 잘 안 들려요.",en:"It's noisy outside, so I can't hear your voice well."},target:"들려",options:["to be visible; to show","to open, to be opened","to be heard, to be audible"],note:"듣다 is ㄷ-irregular, so its passive is 들리다."},{kind:"guess",word:{ko:"열리다",romanization:"yeollida",en:"to open, to be opened",pos:"verb",nuance:"열다 needs an actor opening something. 열리다 lets the opened thing become the subject."},sentence:{ko:"이 문은 사원증을 대야 열려요.",en:"This door only opens if you tap your employee card."},target:"열려",options:["to open, to be opened","to be visible; to show","to be heard, to be audible"],note:"Never say 열려지다 — that stacks two passives."},{kind:"guess",word:{ko:"닫히다",romanization:"dachida",en:"to shut, to be closed",pos:"verb",nuance:"Use 닫히다 when you care about the closed state/result more than the person closing it."},sentence:{ko:"지하철 문이 눈앞에서 닫혀서 한 대를 놓쳤어요.",en:"The subway door shut right in front of me, so I missed a train."},target:"닫혀",options:["to shut, to be closed","to be visible; to show","to be heard, to be audible"],note:"Pronounced [다치다]: ㄷ plus ㅎ fuse and then palatalize."},{kind:"guess",word:{ko:"막히다",romanization:"makida",en:"to get blocked, to be jammed",pos:"verb",nuance:"막히다 is the passive/intransitive partner of the transitive 막다 ('to block'): the -히- infix turns 'someone blocks X' into 'X gets blocked', so 막히다 is something that HAPPENS to a road, drain, or nose rather than something you do. For traffic this is the single most useful verb — 길이 막히다 / 차가 막히다 — and its opposite is 뚫리다 ('to open up/clear'), with 안 막히다 the everyday 'no traffic'. Do not confuse it with 막다 itself: 'I block the road' is 길을 막다, but 'the road is jammed' is 길이 막히다, and the particle flips from 을 to 이/가 accordingly. Register is plain and universal. Because the subject is a non-person, the polite/imperative-looking forms (막혀 주세요, 막힐까요?) are essentially never used about traffic. The big English-speaker trap is treating it as transitive: there is no 'I am blocked by traffic' with you as subject — Korean puts the ROAD in the subject slot (길이 막혀요), and you simply say 길이 막혀서 늦었어요 ('I was late because the road was jammed')."},sentence:{ko:"주말이라 고속도로가 많이 막혀요.",en:"It's the weekend, so the highway is really jammed."},target:"막혀",options:["to be visible; to show","to get blocked, to be jammed","to be heard, to be audible"],note:"길이 막히다 is the everyday way to talk about traffic."},{kind:"guess",word:{ko:"팔리다",romanization:"pallida",en:"to be sold, to sell out",pos:"verb",nuance:"Use 팔리다 when the seller is not important or not known."},sentence:{ko:"인기 메뉴라서 점심 전에 다 팔려요.",en:"It's a popular item, so it sells out before lunch."},target:"팔려",options:["to be visible; to show","to be heard, to be audible","to be sold, to sell out"],note:"The goods are the subject; the seller is not mentioned."},{kind:"payoff",line:{speaker:"유진",ko:"네? 저는 그 공지가 안 보이는데요.",en:"Huh? I don't see that notice."},hl:"보이"}],canDo:"Turn an active sentence into a passive one with -이/히/리/기- (직원이 문을 닫았어요 → 문이 닫혔어요)",id:"chapter-66-b1",chapterId:"chapter-66",index:0},{kind:"pattern",title:"문법 Grammar · V-이/히/리/기-",cards:[{kind:"teach",name:"V-이/히/리/기-",sub:"the built-in passive (it happened, nobody to blame)",rows:[{when:"Stem ends in a vowel or ㅎ",add:"-이-",ex:"보다 → 보이다 (to be visible), 놓다 → 놓이다 (to be placed)"},{when:"Stem ends in ㄱ, ㄷ, ㅂ",add:"-히-",ex:"막다 → 막히다 (to get blocked), 잡다 → 잡히다 (to get caught)"},{when:"Stem ends in ㄹ (and ㄷ-irregular 듣다)",add:"-리-",ex:"팔다 → 팔리다 (to be sold), 듣다 → 들리다 (to be heard)"},{when:"Stem ends in ㄴ, ㅁ, ㅅ, ㅊ",add:"-기-",ex:"끊다 → 끊기다 (to get cut off), 쫓다 → 쫓기다 (to be chased)"},{when:"Rewriting an active sentence",add:"N을/를 V → N이/가 V-피동",ex:"직원이 문을 닫았어요 → 문이 닫혔어요"}],examples:[{ko:"지금 출근 시간이라 도로가 꽉 막혔어요.",en:"It's rush hour, so the road is completely jammed right now.",romanization:"jigeum chulgeun siganira doroga kkwak makyeosseoyo.",note:"막다 (to block) → 막히다. Nobody blocked the road on purpose, and 막히다 is simply the word Koreans use for traffic."},{ko:"지하철에서 통화하다가 갑자기 전화가 끊겼어요.",en:"I was on a call on the subway and it suddenly got cut off.",romanization:"jihacheoreseo tonghwahadaga gapjagi jeonhwaga kkeunkyeosseoyo.",note:"끊다 (to cut) → 끊기다. The phone is the subject; no one is accused of hanging up."}],more:{func:"A set of transitive verbs takes an inner suffix -이-, -히-, -리-, or -기- and becomes intransitive. The thing that was acted on moves into the 이/가 subject slot, the object particle 을/를 disappears, and the doer usually drops out of the sentence completely. This is the passive Koreans actually use in daily speech — one word, not a construction.",funcLead:"A set of transitive verbs takes an inner suffix -이-, -히-, -리-, or -기- and becomes intransitive.",keyPoint:{label:"The object particle has to go",body:"When a verb turns passive, 을/를 disappears with it. 문을 닫았어요 (someone shut the door) becomes 문이 닫혔어요 — never 문을 닫혔어요. If you still see 을/를 in front of a passive verb, the sentence is broken. The one regular exception is a body part or a possession you were affected through: 지하철에서 발을 밟혔어요 (I got my foot stepped on)."},pronunciation:"Three of these hide a sound change. 막히다 is [마키다] and 잡히다 is [자피다] — the ㅎ fuses with the stop into an aspirate. 끊기다 is [끈키다] for the same reason. 밟히다 is [발피다].",pitfall:{wrong:"문을 닫혔어요.",right:"문이 닫혔어요.",explanation:'In English "the door was closed," the door still feels like the thing being acted on, so learners keep 을/를 on it. A Korean passive verb cannot take an object at all — the affected thing becomes the 이/가 subject. The moment you swap 닫다 for 닫히다, swap 문을 for 문이.'}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "It's rush hour, so the road is completely jammed right now."`,tokens:["지금","출근","시간이라","도로가","꽉","막혔어요."],correct:"지금 출근 시간이라 도로가 꽉 막혔어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I was on a call on the subway and it suddenly got cut off." (지하철에서 시작 · Start with 지하철에서.)',tokens:["지하철에서","통화하다가","갑자기","전화가","끊겼어요."],correct:"지하철에서 통화하다가 갑자기 전화가 끊겼어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"문을 닫혔어요.",ok:!1},{text:"문이 닫혔어요.",ok:!0}],explanation:'In English "the door was closed," the door still feels like the thing being acted on, so learners keep 을/를 on it. A Korean passive verb cannot take an object at all — the affected thing becomes the 이/가 subject. The moment you swap 닫다 for 닫히다, swap 문을 for 문이.'}],canDo:"Turn an active sentence into a passive one with -이/히/리/기- (직원이 문을 닫았어요 → 문이 닫혔어요)",id:"chapter-66-b2",chapterId:"chapter-66",index:1},{kind:"words",title:"단어 Words 2 · 걸리다~",cards:[{kind:"guess",word:{ko:"걸리다",romanization:"geollida",en:"to be hung; to get caught; to take (time)",pos:"verb",nuance:"걸리다 is a high-frequency verb that fans out into three everyday senses learners meet fast: (1) time being needed — 시간이 걸리다; (2) catching an illness — 감기에 걸리다; and (3) getting caught/busted — 경찰한테 걸리다, 거짓말이 걸리다. The thread linking them is its origin as the passive of 걸다 ('to hang/hook'): something gets hooked — by time, by sickness, by the law — so 벽에 그림이 걸려 있어요 ('a picture is hung on the wall') is the same word. The number-one English-speaker pitfall is the subject/particle: for 'take time' the *time* is the subject (시간이 걸려요), never 시간을 걸려요; and for illness you must use 에 (감기에 걸리다), not the object 를. Compare 걸리다 ('take/require time') with 들다, which is used for cost/effort/money (돈이 들다) — 시간이 걸리다 vs 돈이 들다 is a pairing Koreans keep distinct. It is a regular ㅣ-stem verb: 걸리 + 어 contracts to 걸려요."},sentence:{ko:"저 그림은 작년부터 저 벽에 걸려 있어요.",en:"That painting has been hanging on that wall since last year."},target:"걸려",options:["to be visible; to show","to be heard, to be audible","to be hung; to get caught; to take (time)"],note:"걸다 → 걸리다. The same verb also gives 감기에 걸리다 and 시간이 걸리다."},{kind:"guess",word:{ko:"잡히다",romanization:"japida",en:"to be caught",pos:"verb",nuance:"잡히다 is natural for appointments, schedules, reservations, and plans."},sentence:{ko:"소매치기가 지하철역에서 경찰한테 잡혔어요.",en:"The pickpocket was caught by the police at the subway station."},target:"잡혔",options:["to be caught","to be visible; to show","to be heard, to be audible"],note:"A human agent, so 한테 in speech and 에게 in writing."},{kind:"guess",word:{ko:"끊기다",romanization:"kkeunkida",en:"to be cut off, to be disconnected",pos:"verb",nuance:"끊기다 is passive/intransitive: the video or connection cuts out. 끊다 is what someone actively cuts or ends."},sentence:{ko:"터널에 들어가면 전화가 끊겨요.",en:"The call cuts out when you go into a tunnel."},target:"끊겨",options:["to be cut off, to be disconnected","to be visible; to show","to be heard, to be audible"],note:"Pronounced [끈키다]. Also used for 연락이 끊기다 (to lose touch)."},{kind:"guess",word:{ko:"쓰이다",romanization:"sseuida",en:"to be used; to be written",pos:"verb",nuance:"쓰이다 focuses on the written/used item. 쓰다 focuses on the person writing or using it."},sentence:{ko:"이 단어는 요즘 뉴스에서 자주 쓰여요.",en:"This word gets used a lot in the news these days."},target:"쓰여",options:["to be visible; to show","to be used; to be written","to be heard, to be audible"],note:'쓰다 covers both "use" and "write," and so does 쓰이다.'},{kind:"guess",word:{ko:"켜지다",romanization:"kyeojida",en:"to come on, to be turned on",pos:"verb",nuance:"켜다 is the action of turning something on. 켜지다 focuses on the thing becoming or being on."},sentence:{ko:"센서가 있어서 사람이 지나가면 불이 켜져요.",en:"There's a sensor, so the light comes on when someone walks past."},target:"켜져",options:["to come on, to be turned on","to be visible; to show","to be heard, to be audible"],note:"켜다 has no -이/히/리/기- passive, so it uses -어지다."},{kind:"guess",word:{ko:"바뀌다",romanization:"bakkwida",en:"to be changed, to change",pos:"verb",nuance:"바뀌다 is the intransitive twin of 바꾸다: the thing that changes is itself the subject (이/가) and nobody is named as the doer, so it covers things getting switched, replaced, or mixed up on their own. The dividing line vs 변하다 is key — 변하다 means a thing's inner nature transforms (사람이 변했다 = he's become a different person), while 바뀌다 means one item is swapped out for another (번호가 바뀌었다 = the number was replaced). Use 바꾸다 when YOU actively swap something (번호를 바꿨어요) and 바뀌다 when it simply ends up different (번호가 바뀌었어요). The 요-form is 바뀌어요 because the stem ends in the vowel 위, which won't contract — so spelling matters: it's 바뀌-, and the polite past is 바뀌었어요, never the wrong 바껴요/바꼈어요 that English speakers reach for by analogy."},sentence:{ko:"회의 장소가 갑자기 3층으로 바뀌었어요.",en:"The meeting room was suddenly changed to the third floor."},target:"바뀌",options:["to be changed, to change","to be visible; to show","to be heard, to be audible"],note:"바꾸다 plus -이- gives 바뀌다; nobody has to be blamed for the change."},{kind:"payoff",line:{speaker:"지원",ko:"아니요, 안 하셔도 돼요. 회의 장소가 3층으로 바뀌었어요. 방금 공지가 올라왔거든요.",en:"No, you don't have to. The meeting room got changed to the third floor — the notice just went up."},hl:"바뀌"}],canDo:"Mark the cause correctly: 경찰한테 잡혔어요 for a person, 바람에 닫혔어요 for a force",id:"chapter-66-b3",chapterId:"chapter-66",index:2},{kind:"pattern",title:"문법 Grammar · N에/에게 + 피동",cards:[{kind:"teach",name:"N에/에게 + 피동",sub:'naming what caused it ("by")',rows:[{when:"A person or animal caused it",add:"N에게 / N한테 (spoken)",ex:"경찰 → 도둑이 경찰한테 잡혔어요"},{when:"A thing, force, or event caused it",add:"N에",ex:"바람 → 창문이 바람에 닫혔어요"},{when:"Formal writing or news",add:"N에 의해(서)",ex:"국회 → 이 법은 국회에 의해 개정되었다"},{when:"No cause named — the normal case",add:"(just leave it out)",ex:"문이 닫혔어요 (the door shut)"}],examples:[{ko:"도둑이 경찰한테 바로 잡혔어요.",en:"The thief was caught by the police right away.",romanization:"dodugi gyeongchalhante baro japyeosseoyo.",note:"A person did it, so 한테 in speech (에게 if you are writing)."},{ko:"창문이 바람에 쾅 닫혔어요.",en:"The window slammed shut in the wind.",romanization:"changmuni barame kwang dachyeosseoyo.",note:"바람 cannot decide anything, so it takes 에 — 바람에게 is the classic learner error."}],more:{func:"Korean usually leaves the doer out of a passive sentence entirely. When you do name it, the particle depends on what it is: a person or an animal takes 에게, or 한테 in speech, while a thing, a force, or an event takes plain 에. Formal writing has a third option, N에 의해(서), but in conversation it sounds like you are reading a news bulletin.",funcLead:"Korean usually leaves the doer out of a passive sentence entirely.",keyPoint:{label:"에게 is only for something alive",body:'The single most common passive error is copying English "by" onto 에게/한테 for everything. 에게 and 한테 attach only to a person or an animal — something that could have acted on purpose. Wind, rain, noise, traffic, time, a deadline, an accident: all take 에. 바람에 닫혔어요, 마감에 쫓겨요, 소음에 시달려요.'},pronunciation:"에게 and 한테 mean the same thing; 한테 is what you say out loud and 에게 is what you write. 잡혔어요 is [자펴써요] and 쫓겨서 is [쫃껴서].",pitfall:{wrong:"창문이 바람에게 닫혔어요.",right:"창문이 바람에 닫혔어요.",explanation:'English has one word, "by," for people and for weather alike, so learners map it straight onto 에게/한테. Korean splits them, and 에게/한테 need something animate. 바람, 비, 소음, 시간, 사고 all take plain 에. If you cannot picture it deciding to act, use 에.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The thief was caught by the police right away." (도둑이 시작 · Start with 도둑이.)',tokens:["도둑이","경찰한테","바로","잡혔어요."],correct:"도둑이 경찰한테 바로 잡혔어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The window slammed shut in the wind." (창문이 시작 · Start with 창문이.)',tokens:["창문이","바람에","쾅","닫혔어요."],correct:"창문이 바람에 쾅 닫혔어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"창문이 바람에 닫혔어요.",ok:!0},{text:"창문이 바람에게 닫혔어요.",ok:!1}],explanation:'English has one word, "by," for people and for weather alike, so learners map it straight onto 에게/한테. Korean splits them, and 에게/한테 need something animate. 바람, 비, 소음, 시간, 사고 all take plain 에. If you cannot picture it deciding to act, use 에.'}],canDo:"Mark the cause correctly: 경찰한테 잡혔어요 for a person, 바람에 닫혔어요 for a force",id:"chapter-66-b4",chapterId:"chapter-66",index:3},{kind:"words",title:"단어 Words 3 · 놓이다~",cards:[{kind:"guess",word:{ko:"놓이다",romanization:"nohida",en:"to be placed, to be set down",pos:"verb"},sentence:{ko:"책상 위에 처음 보는 봉투가 놓여 있었어요.",en:"There was an envelope I'd never seen sitting on the desk."},target:"놓여",options:["to be visible; to show","to be placed, to be set down","to be heard, to be audible"],note:"놓이다 usually appears as 놓여 있다 for a state that stays."},{kind:"guess",word:{ko:"밟히다",romanization:"balpida",en:"to get stepped on",pos:"verb"},sentence:{ko:"출근길 지하철에서 발을 밟혔어요.",en:"I got my foot stepped on in the subway on the way to work."},target:"밟혔",options:["to be visible; to show","to be heard, to be audible","to get stepped on"],note:"One of the few passives that keeps a 을/를 — the body part you were affected through."},{kind:"guess",word:{ko:"쫓기다",romanization:"jjotgida",en:"to be chased; to be pressed (for time)",pos:"verb"},sentence:{ko:"마감에 쫓겨서 점심도 못 먹었어요.",en:"I was so pressed by the deadline that I couldn't even eat lunch."},target:"쫓겨",options:["to be visible; to show","to be heard, to be audible","to be chased; to be pressed (for time)"],note:"시간에 쫓기다 and 마감에 쫓기다 take 에, because neither is alive."},{kind:"guess",word:{ko:"정해지다",romanization:"jeonghaejida",en:"to be decided, to be set",pos:"verb"},sentence:{ko:"메뉴는 이미 정해졌으니까 그냥 오시면 돼요.",en:"The menu's already been decided, so just come on over."},target:"정해졌",options:["to be visible; to show","to be decided, to be set","to be heard, to be audible"],note:"정하다 → 정해지다. Extremely common for schedules and plans at work."},{kind:"guess",word:{ko:"알려지다",romanization:"allyeojida",en:"to become known, to get out",pos:"verb"},sentence:{ko:"그 가게는 방송에 나온 뒤로 널리 알려졌어요.",en:"That shop became widely known after it appeared on TV."},target:"알려졌",options:["to be visible; to show","to become known, to get out","to be heard, to be audible"],note:"알리다 (to inform) plus -어지다. Use 알려지다 for reputations and news."},{kind:"guess",word:{ko:"지워지다",romanization:"jiwojida",en:"to get erased, to come off",pos:"verb"},sentence:{ko:"이 펜으로 쓰면 잘 안 지워져요.",en:"If you write with this pen it doesn't come off easily."},target:"지워져",options:["to get erased, to come off","to be visible; to show","to be heard, to be audible"],note:"지우다 has no built-in passive, so -어지다 does the work."}],canDo:"Use -아/어지다 for verbs with no built-in passive (지워지다, 정해지다) and avoid double passives like 열려지다",id:"chapter-66-b5",chapterId:"chapter-66",index:4},{kind:"pattern",title:"문법 Grammar · V-아/어지다",cards:[{kind:"teach",name:"V-아/어지다",sub:"it gets done, it turns out that way",rows:[{when:"Verb stem ends in ㅏ/ㅗ",add:"-아지다",ex:"닦다 → 닦아지다 (to come clean)"},{when:"Verb stem ends in any other vowel",add:"-어지다",ex:"지우다 → 지워지다 (to get erased)"},{when:"하다 verbs",add:"-해지다",ex:"정하다 → 정해지다 (to be decided)"},{when:'On an adjective the meaning changes to "become"',add:"A-아/어지다",ex:"따뜻하다 → 따뜻해지다 (to get warm)"}],examples:[{ko:"칠판에 쓴 글씨가 잘 안 지워져요.",en:"The writing on the board won't come off properly.",romanization:"chilpane sseun geulssiga jal an jiwojyeoyo.",note:"지우다 has no -이/히/리/기- passive, so it uses 지워지다."},{ko:"회식 날짜가 다음 주 금요일로 정해졌어요.",en:"The date for the team dinner has been set for next Friday.",romanization:"hoesik naljjaga daeum ju geumyoillo jeonghaejyeosseoyo.",note:"Office Korean at its most typical: the date got decided, and nobody is named as deciding it."}],more:{func:'The -이/히/리/기- passive exists only for a closed list of verbs. -아/어지다 covers almost everything else: it takes a transitive verb and makes the action something that simply happens to the thing. 지우다 (to erase) → 지워지다 (to get erased). It carries a shade of "it came out this way on its own," which is why Korean uses it for schedules, decisions, and settings.',funcLead:"The -이/히/리/기- passive exists only for a closed list of verbs.",keyPoint:{label:"-아/어지다 does two different jobs",body:'On a transitive verb it builds a passive: 지우다 (erase) → 지워지다 (get erased). On an adjective it means "become": 따뜻하다 (be warm) → 따뜻해지다 (get warm). That second job is the 좋아졌어요 / 추워졌어요 you already know. Look at the base word, not the ending, to know which reading you have.'},pronunciation:"The 져 in these forms flattens after ㅈ: 지워져요 is [지워저요], 만들어져요 is [만드러저요], 정해졌어요 is [정해저써요]. Never pronounce a full [여] there.",pitfall:{wrong:"문이 안 열려져서 한참 서 있었어요.",right:"문이 안 열려서 한참 서 있었어요.",explanation:'열리다 is already the passive of 열다, so -어지다 stacks a second passive on top of it. English "was opened" feels like it needs a helper verb, which is what tempts learners into this. Pick one route: either the -이/히/리/기- verb (열리다, 닫히다, 보이다) or -아/어지다 on the plain verb — never both. The same trap produces 잊혀지다 and 쓰여지다, which careful speakers avoid.'}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "The writing on the board won't come off properly." (칠판에 시작 · Start with 칠판에.)`,tokens:["칠판에","쓴","글씨가","잘","안","지워져요."],correct:"칠판에 쓴 글씨가 잘 안 지워져요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The date for the team dinner has been set for next Friday."',tokens:["회식","날짜가","다음","주","금요일로","정해졌어요."],correct:"회식 날짜가 다음 주 금요일로 정해졌어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"문이 안 열려서 한참 서 있었어요.",ok:!0},{text:"문이 안 열려져서 한참 서 있었어요.",ok:!1}],explanation:'열리다 is already the passive of 열다, so -어지다 stacks a second passive on top of it. English "was opened" feels like it needs a helper verb, which is what tempts learners into this. Pick one route: either the -이/히/리/기- verb (열리다, 닫히다, 보이다) or -아/어지다 on the plain verb — never both. The same trap produces 잊혀지다 and 쓰여지다, which careful speakers avoid.'}],canDo:"Use -아/어지다 for verbs with no built-in passive (지워지다, 정해지다) and avoid double passives like 열려지다",id:"chapter-66-b6",chapterId:"chapter-66",index:5},{kind:"pattern",title:"문법 Grammar · V-게 되다",cards:[{kind:"teach",name:"V-게 되다",sub:"how it ended up (circumstances took the decision)",rows:[{when:"Any verb stem",add:"V-게 되다",ex:"알다 → 알게 되다 (to come to know)"},{when:"Past — by far the most common form",add:"V-게 됐어요",ex:"가다 → 가게 됐어요 (I ended up going)"},{when:"Announcing news politely",add:"V-게 됐습니다",ex:"일하다 → 부산에서 일하게 됐습니다"},{when:"Ended up NOT doing it",add:"못 V-게 되다 / V-지 않게 되다",ex:"가다 → 못 가게 됐어요 (it turns out I can't go)"}],examples:[{ko:"일이 갑자기 생겨서 이번 모임에는 못 가게 됐어요.",en:"Something came up, so it turns out I can't make this meetup.",romanization:"iri gapjagi saenggyeoseo ibeon moimeneun mot gage dwaesseoyo.",note:"The standard polite way to cancel: circumstances, not you, cancelled it."},{ko:"한국 드라마를 보다가 한국어를 배우게 됐어요.",en:"I got into watching Korean dramas and ended up learning Korean.",romanization:"hanguk deuramareul bodaga hangugeoreul baeuge dwaesseoyo.",note:"You are still the one learning — 게 되다 only says it wasn't a plan."}],more:{func:'-게 되다 does not move an object into the subject slot. It changes WHY. The same person still performs the action, but circumstances, not their own choice, brought it about. English reaches for "ended up," "came to," or "it turns out that." It is also the polite way to announce your own news without sounding boastful or blaming.',funcLead:"-게 되다 does not move an object into the subject slot.",keyPoint:{label:"피동 vs 사동 vs -게 되다",body:"Three jobs that blur together. 피동 (문이 닫혔어요) removes the doer — the thing is simply affected. 사동, the causative chapter's 아이에게 옷을 입혔어요, adds a doer — you make someone else act. -게 되다 keeps the same doer but hands the decision to circumstances (부산에서 일하게 됐어요 — I am the one working, but I did not pick it). Ask yourself: did the doer disappear, get added, or just stop being in charge?"},pronunciation:"게 되다 is spoken as one chunk with no pause: 하게 됐어요 is [하게 돼써요], 못 가게 됐어요 is [몯 까게 돼써요].",pitfall:{wrong:"문이 닫게 됐어요.",right:"문이 닫혔어요.",explanation:`Because 되다 means "become," learners treat -게 되다 as a general-purpose passive. It is not. -게 되다 keeps the doer and only says the decision wasn't theirs, so it needs a subject that could in principle decide. A door decides nothing — it needs the real passive 닫히다.`}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I got into watching Korean dramas and ended up learning Korean."',tokens:["한국","드라마를","보다가","한국어를","배우게","됐어요."],correct:"한국 드라마를 보다가 한국어를 배우게 됐어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"문이 닫게 됐어요.",ok:!1},{text:"문이 닫혔어요.",ok:!0}],explanation:`Because 되다 means "become," learners treat -게 되다 as a general-purpose passive. It is not. -게 되다 keeps the doer and only says the decision wasn't theirs, so it needs a subject that could in principle decide. A door decides nothing — it needs the real passive 닫히다.`}],canDo:"Say how something ended up with -게 되다 without mistaking it for a passive",id:"chapter-66-b7",chapterId:"chapter-66",index:6},{kind:"pattern",title:"문법 Grammar · 보이다·읽히다",cards:[{kind:"teach",name:"보이다·읽히다",sub:"one form, passive or causative",rows:[{when:"보다 → 보이다, passive",add:"N이/가 보이다",ex:"바다 → 여기서 바다가 보여요 (the sea is visible from here)"},{when:"보다 → 보이다, causative",add:"N에게 N을/를 보이다",ex:"손 → 의사에게 손을 보였어요 (I showed the doctor my hand)"},{when:"읽다 → 읽히다, passive",add:"N이/가 읽히다",ex:"소설 → 그 소설이 많이 읽혀요 (that novel gets read a lot)"},{when:"읽다 → 읽히다, causative",add:"N에게 N을/를 읽히다",ex:"동화책 → 아이에게 동화책을 읽혔어요 (I had my child read a storybook)"}],examples:[{ko:"옥상에 올라가면 한강이 다 보여요.",en:"If you go up to the roof, you can see the whole Han River.",romanization:"oksange ollagamyeon hangangi da boyeoyo.",note:"Passive: 한강이 takes 이/가 and there is no object anywhere."},{ko:"병원에서 의사 선생님한테 다친 손을 보였어요.",en:"At the hospital I showed the doctor my injured hand.",romanization:"byeongwoneseo uisa seonsaengnimhante dachin soneul boyeosseoyo.",note:'Causative: 손을 is an object, so this is "show," not "be visible."'}],more:{func:'Several -이/히/리/기- verbs are the passive AND the causative of the same root, and only the particles tell them apart. 보이다 is "be visible" and "show"; 읽히다 is "be read" and "make someone read"; 안기다 is "be held" and "hand over to be held." Read the particles: a 이/가 subject with no object is passive, while a 을/를 object is causative.',funcLead:"Several -이/히/리/기- verbs are the passive AND the causative of the same root, and only the particles tell them apart.",keyPoint:{label:"The object particle decides",body:'When one form does both jobs, look for 을/를. 사진이 잘 보여요 has no object → passive, "the photo shows up clearly." 사진을 보여 줬어요 has an object → causative, "I showed the photo." 에게/한테 turns up in both, so it can never settle the question; only 을/를 can. And for "show," everyday Korean almost always adds 주다: 보여 주다, not bare 보이다.'},pronunciation:"읽히다 is [일키다]: the ㄺ and the ㅎ fuse into [ㅋ]. So 읽혀요 is [일켜요] and 읽혔어요 is [일켜써요].",pitfall:{wrong:"친구에게 사진이 보였어요.",right:"친구에게 사진을 보여 줬어요.",explanation:'Learners learn 보이다 as "be visible," then discover it can also mean "show," and build the "show" sentence with 이/가 out of habit. If YOU are doing the showing, the photo is an object (사진을) and natural Korean adds 주다. Keep 사진이 보여요 for "the photo is visible."'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "If you go up to the roof, you can see the whole Han River." (옥상에 시작 · Start with 옥상에.)',tokens:["옥상에","올라가면","한강이","다","보여요."],correct:"옥상에 올라가면 한강이 다 보여요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "At the hospital I showed the doctor my injured hand." (병원에서 시작 · Start with 병원에서.)',tokens:["병원에서","의사","선생님한테","다친","손을","보였어요."],correct:"병원에서 의사 선생님한테 다친 손을 보였어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구에게 사진을 보여 줬어요.",ok:!0},{text:"친구에게 사진이 보였어요.",ok:!1}],explanation:'Learners learn 보이다 as "be visible," then discover it can also mean "show," and build the "show" sentence with 이/가 out of habit. If YOU are doing the showing, the photo is an object (사진을) and natural Korean adds 주다. Keep 사진이 보여요 for "the photo is visible."'}],canDo:"Tell passive 보이다/읽히다 from causative 보이다/읽히다 by looking for a 을/를 object",id:"chapter-66-b8",chapterId:"chapter-66",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two colleagues at the office on a Monday morning. One of them has just arrived late and everything on the way in happened TO her.",lines:[{speaker:"지원",ko:"얼굴이 왜 그래요? 무슨 일 있었어요?",en:"What's with your face? Did something happen?",romanization:"eolguri wae geuraeyo? museun il isseosseoyo?"},{speaker:"유진",ko:"출근길에 지하철 문이 눈앞에서 닫혔어요. 다음 열차는 사람이 너무 많아서 발까지 밟혔고요.",en:"The subway door shut right in front of me on the way in. And the next train was so packed I even got my foot stepped on.",romanization:"chulgeungire jihacheol muni nunapeseo dachyeosseoyo. daeum yeolchaneun sarami neomu manaseo balkkaji balpyeotgoyo."},{speaker:"지원",ko:"아이고. 그래도 지하철이 나아요. 지금 도로는 사고 때문에 꽉 막혔어요.",en:"Oh no. Still, the subway's better — the roads are completely jammed because of an accident right now.",romanization:"aigo. geuraedo jihacheori naayo. jigeum doroneun sago ttaemune kkwak makyeosseoyo."},{speaker:"유진",ko:"그러게요. 아, 아까 팀장님이랑 통화하다가 터널에서 전화가 끊겼는데, 다시 걸어야 할까요?",en:"Right? Oh, and my call with the team lead got cut off in the tunnel earlier — should I call back?",romanization:"geureugeyo. a, akka timjangnimirang tonghwahadaga teoneoreseo jeonhwaga kkeunkyeonneunde, dasi georeoya halkkayo?"},{speaker:"지원",ko:"아니요, 안 하셔도 돼요. 회의 장소가 3층으로 바뀌었어요. 방금 공지가 올라왔거든요.",en:"No, you don't have to. The meeting room got changed to the third floor — the notice just went up.",romanization:"aniyo, an hasyeodo dwaeyo. hoeui jangsoga sam cheungeuro bakkwieosseoyo. banggeum gongjiga ollawatgeodeunyo."},{speaker:"유진",ko:"네? 저는 그 공지가 안 보이는데요.",en:"Huh? I don't see that notice.",romanization:"ne? jeoneun geu gongjiga an boineundeyo."},{speaker:"지원",ko:"사내 게시판에 올라와 있어요. 새로고침하면 보일 거예요.",en:"It's up on the company board. It should show up if you refresh.",romanization:"sanae gesipane ollawa isseoyo. saerogochimhamyeon boil geoyeyo."},{speaker:"유진",ko:"아, 이제 보이네요. 오늘은 뭐 하나도 제 뜻대로 안 되네요.",en:"Ah, now I see it. Nothing's going my way today.",romanization:"a, ije boineyo. oneureun mwo hanado je tteutdaero an doeneyo."}]},{kind:"order",prompt:"Build: 'The call got cut off in the tunnel.' (Start with 터널에서.)",tokens:["터널에서","전화가","끊겼어요"],correct:"터널에서 전화가 끊겼어요",explanation:"The phone is the subject of the passive verb, so it takes 이/가. 끊기다 is pronounced [끈키다]."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"출근길에 지하철 문이 눈앞에서 닫혔어요. 다음 열차는 사람이 너무 많아서 발까지 밟혔고요.",options:[{text:"유진",ok:!0},{text:"지원",ok:!1}],explanation:"The subway door shut right in front of me on the way in. And the next train was so packed I even got my foot stepped on."}],canDo:"Turn an active sentence into a passive one with -이/히/리/기- (직원이 문을 닫았어요 → 문이 닫혔어요)",id:"chapter-66-b9",chapterId:"chapter-66",index:8},{kind:"reading",title:"읽기 Reading · 문이 닫히고, 길이 막히고",cards:[{kind:"read",title:"문이 닫히고, 길이 막히고",chunks:["한국어를 배우다 보면 한국 사람들이 '누가 했다'보다 '그렇게 됐다'를 훨씬 자주 말한다는 것을 알게 된다. 길이 막히고, 전화가 끊기고, 표가 다 팔린다. 누가 그렇게 만들었는지는 굳이 밝히지 않는다. 이런 문장에서는 행동을 당한 쪽이 주어가 되고, 목적격 조사 '을/를'은 사라진다.","원인이 사람이나 동물이면 '에게'나 '한테'를 쓰지만, 바람이나 시간처럼 사람이 아닌 것이면 '에'를 쓴다. 여기까지 익히면 신문 기사도 훨씬 쉽게 읽힌다. 기사 문장은 대부분 피동으로 쓰여 있기 때문이다."],translation:'Once you have been learning Korean for a while, you notice that Korean speakers say "it turned out that way" far more often than "someone did it." The road gets blocked, the call gets cut off, the tickets all sell out. Who made it happen is simply not spelled out. In sentences like these, the thing that was acted on becomes the subject, and the object particle 을/를 disappears. If the cause is a person or an animal you use 에게 or 한테, but if it is something inanimate like wind or time you use 에. Once you have this much, newspaper articles read much more easily too — because most sentences in an article are written in the passive.',qas:[{q:"피동 문장이 되면 목적격 조사 '을/를'은 어떻게 되나요?",a:"사라져요. 그리고 행동을 당한 쪽이 '이/가' 주어가 돼요."},{q:"원인이 바람이나 시간일 때는 어떤 조사를 써요?",a:"'에'를 써요. '에게'와 '한테'는 사람이나 동물에만 써요."},{q:"피동을 알면 신문 기사를 읽을 때 왜 도움이 돼요?",a:"기사 문장이 대부분 피동으로 쓰여 있기 때문이에요."}]},{kind:"order",prompt:"지문 문장을 다시 조립하세요 · Rebuild a line from the passage",tokens:["누가","그렇게","만들었는지는","굳이","밝히지","않는다."],correct:"누가 그렇게 만들었는지는 굳이 밝히지 않는다.",explanation:""}],canDo:"Mark the cause correctly: 경찰한테 잡혔어요 for a person, 바람에 닫혔어요 for a force",id:"chapter-66-b10",chapterId:"chapter-66",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence is correct Korean for 'The window suddenly closed'?",sentence:null,options:[{text:"창문이 갑자기 닫혔어요.",ok:!0},{text:"창문을 갑자기 닫혔어요.",ok:!1},{text:"창문이 갑자기 닫게 됐어요.",ok:!1}],explanation:"A passive verb cannot take 을/를, which rules out 창문을. -게 되다 needs a subject that could decide something, and a window cannot. 닫히다 is the passive of 닫다."},{kind:"drill",prompt:"창문이 바람___ 닫혔어요. (The window was blown shut by the wind.)",sentence:null,options:[{text:"에",ok:!0},{text:"한테",ok:!1},{text:"이",ok:!1}],explanation:"바람 is not alive, so the cause takes 에. 한테 is only for people and animals, and 바람이 would make the wind the thing that got shut."},{kind:"drill",prompt:"Choose the natural way to say 'The tickets all sold out in ten minutes.'",sentence:null,options:[{text:"표가 십 분 만에 다 팔렸어요.",ok:!0},{text:"표를 십 분 만에 다 팔렸어요.",ok:!1},{text:"표가 십 분 만에 다 팔아졌어요.",ok:!1}],explanation:"팔다 already has a built-in passive, 팔리다, so 팔아지다 is not used. And a passive subject takes 이/가, never 을/를."},{kind:"drill",prompt:"Which one means 'I showed the doctor my hand' (not 'my hand was visible')?",sentence:null,options:[{text:"의사 선생님한테 손을 보였어요.",ok:!0},{text:"의사 선생님한테 손이 보였어요.",ok:!1},{text:"의사 선생님한테 손이 보여졌어요.",ok:!1}],explanation:"Only 을/를 separates the two readings of 보이다. 손을 보였어요 is causative, 'I showed my hand'; 손이 보였어요 is passive, 'the hand was visible'. 보여졌어요 stacks two passives and is not used."},{kind:"drill",prompt:"Which sentence uses -게 되다 correctly for 'something came up, so I can't go to this meetup'?",sentence:null,options:[{text:"일이 생겨서 이번 모임에는 못 가게 됐어요.",ok:!0},{text:"일이 생겨서 이번 모임에는 못 가게 했어요.",ok:!1},{text:"일이 생겨서 이번 모임이 못 가게 됐어요.",ok:!1}],explanation:"-게 되다 means circumstances decided it. -게 했어요 is causative, 'I made someone not go'. And the person, not the meetup, is the one who cannot go, so 모임에는 stays."},{kind:"drill",prompt:"Which verb needs -아/어지다 because it has no -이/히/리/기- passive?",sentence:null,options:[{text:"지우다",ok:!0},{text:"닫다",ok:!1},{text:"팔다",ok:!1}],explanation:"닫다 → 닫히다 and 팔다 → 팔리다 have built-in passives. 지우다 has none, so it uses 지워지다."}],canDo:"Use -아/어지다 for verbs with no built-in passive (지워지다, 정해지다) and avoid double passives like 열려지다",id:"chapter-66-b11",chapterId:"chapter-66",index:10}]},{id:"chapter-67",number:67,title:"V/A-대요 · N(이)래요 vs V-(으)래요",goal:"Contract the four reported-speech frames you already know into -대요, -래요, -냬요, and -재요.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 전하다~",cards:[{kind:"guess",word:{ko:"전하다",romanization:"jeonhada",en:"to pass on, to convey (a message)",pos:"verb",nuance:"전하다 (Sino-Korean 傳, 'transmit/hand down') means relaying something from a sender to a receiver: a message, regards, an item, news, or even a feeling, so the receiver takes 에게/한테 or honorific 께 while the thing passed takes 을/를. The nearest rival is 말하다, but 말하다 is you simply saying something yourself, whereas 전하다 stresses that you are the go-between carrying someone else's words or goods to a third party — '사장님이 잘했다고 전하래요' (the boss told me to tell you 'well done'). Everyday set phrases include 안부를 전하다 (send one's regards), 말씀 전해 주세요 (please pass on the message), and 소식을 전하다 (deliver news). The big English-speaker trap is hearing 전 and thinking 전화하다 ('to make a phone call'): they share the 전 syllable but are unrelated, so '전해 주세요' is 'please relay it', not 'please call them'."},sentence:{ko:"팀장님이 회의 시간이 바뀌었다고 팀원들한테 전하래요.",en:"The team lead says to tell the team members that the meeting time has changed."},target:"전하",options:["to pass on, to convey (a message)","to take along, to look after","to check, to confirm"],note:"전하다 is the verb for being the messenger, which is exactly what these endings do."},{kind:"guess",word:{ko:"소식",romanization:"sosik",en:"news, word (from someone)",pos:"noun",nuance:"소식(消息) is Sino-Korean — 消 'disappear/wane' + 息 'breath/rest' — and originally meant the ebb and flow of things; today it means 'news, word, tidings,' especially personal news about how a person or situation is faring. The sharp contrast is with 뉴스: 뉴스 is the English loanword reserved for broadcast/press news (TV, newspapers, current events), whereas 소식 is the news of individuals and private matters — a friend's wedding, a relative's health. Compare also 정보(情報) 'information/data,' which is impersonal facts you look up. Natural partners are 좋은/나쁜 소식, 소식을 전하다/듣다, and the poignant 소식이 없다/끊기다 ('haven't heard from them'). The pitfall for English speakers: 'I watched the news' tempts 소식을 봤어요, but media news is 뉴스를 봤어요; reserve 소식 for word about people, and remember you 듣다 (hear) personal news rather than 보다 it."},sentence:{ko:"지훈이 소식 들었어요? 다음 달에 부산으로 간대요.",en:"Did you hear about Jihoon? They say he's going to Busan next month."},target:"소식",options:["news, word (from someone)","notice, announcement","contact, getting in touch"],note:"소식 + -대요 is the standard shape for relaying news about a person."},{kind:"guess",word:{ko:"공지",romanization:"gongji",en:"notice, announcement",pos:"noun",nuance:"공지 is more official than a casual message. It often hides the actor and foregrounds the posted information."},sentence:{ko:"공지 확인하셨어요? 마감이 하루 미뤄졌대요.",en:"Did you check the notice? They say the deadline got pushed back a day."},target:"공지",options:["news, word (from someone)","notice, announcement","contact, getting in touch"],note:"Notices are almost always relayed with -대요 rather than claimed directly."},{kind:"guess",word:{ko:"연락",romanization:"yeollak",en:"contact, getting in touch",pos:"noun",nuance:"연락(連絡) is Sino-Korean — 連 'connect/link' + 絡 'tie, network' — literally 'to link up,' and it covers ANY channel of reaching a person: a call, a text, a message, an email. The near-synonym to contrast is 소식: 연락 is the ACT/CHANNEL of getting in touch ('drop me a line'), while 소식 is the CONTENT/word about how someone is. Compare 통화(通話) 'a phone call (specifically)' — narrower than 연락. The crucial grammar quirk for English speakers: 연락 flips between particles. When YOU reach out it's 연락을 하다 / 연락하다 (object 를), but when contact COMES to you it's 연락이 오다 and reachability is 연락이 되다 (subject 이/가) — saying 연락을 오다 is a classic error. Also, English 'contact someone' has a direct object, so learners drop the person-marking 한테/에게: it should be 친구한테 연락하다, and incoming contact is 친구한테서/에게서 연락이 오다. 연락처 (with 처) means your number/details, not the verb."},sentence:{ko:"엄마가 도착하면 꼭 연락하래요.",en:"Mom says to be sure to get in touch when I arrive."},target:"연락",options:["contact, getting in touch","news, word (from someone)","notice, announcement"],note:"연락하다 is one of the most common verbs inside a reported command."},{kind:"guess",word:{ko:"회식",romanization:"hoesik",en:"team dinner, company get-together",pos:"noun",nuance:"회식 (會食, 會 'gather/meet' + 食 'eat') is Sino-Korean, literally 'a gathering to eat,' and means a meal that coworkers share together as a team, usually after work and often with drinks — a defining feature of Korean company culture. The contrast to nail is 회식 vs 모임: a 회식 is specifically a work/organization meal you attend as part of your job, with an implicit hierarchy (your 부장 'department head' is there), whereas a 모임 is any casual social gathering by choice. It is also not a 파티 — a 회식 centers on eating and bonding under workplace norms, not festive celebration. Common collocations: 부서 회식 'department dinner', 회식 자리 'the dinner setting', 1차/2차 (the 'first/second round' of venues a 회식 moves through). Register is neutral but the concept itself is loaded with social obligation. The English-speaker pitfall is the usual particle slip (회식에서 가요 ✗ → 회식에 가요) and assuming it is optional fun; culturally it can carry expectation, though that is changing."},sentence:{ko:"동기들이 회식 끝나고 이차 가재요.",en:"My colleagues say let's go for a second round after the team dinner."},target:"회식",options:["news, word (from someone)","notice, announcement","team dinner, company get-together"],note:"회식 plans travel through the group chat, so -재요 fits naturally."},{kind:"guess",word:{ko:"야근",romanization:"yageun",en:"working late, overtime",pos:"noun",nuance:"야근 specifically means staying at the office working late into the night — the iconic symbol of old-school Korean work culture. It is Sino-Korean 夜勤, literally 'night-duty', sharing the 勤 ('duty/labor') of 외근 and 출근. The contrast to nail: 야근 is overtime that runs LATE/at night, whereas 특근 (特勤, 'special duty') and 추가 근무 cover extra work generally, including daytime, weekends, or holidays — so weekend morning work is 특근, not 야근. Its cultural foil is the slang 칼퇴 ('knife-exit' = leaving on the dot at quitting time), the thing everyone dreams of instead. And the carrot is 야근 수당 (overtime pay), which is 나오다 (paid out), not 받다-only. The English-speaker pitfall is using 야근 as a blanket word for all 'overtime' — keep the time-of-day nuance — and saying 야근을 가다 ('go to overtime'); you don't go to it, you 야근을 하다."},sentence:{ko:"요즘 그 팀은 매일 야근한대요.",en:"They say that team works late every single day."},target:"야근",options:["working late, overtime","news, word (from someone)","notice, announcement"],note:"야근하다 is a verb, so the present tense needs -ㄴ대요."},{kind:"guess",word:{ko:"챙기다",romanization:"chaenggida",en:"to take along, to look after",pos:"verb",nuance:"챙기다 is one of the most useful 'caring' verbs in daily Korean, with a cluster of related senses: (1) gather/pack the things you need (짐을 챙기다), (2) make sure not to skip something, especially food (밥 챙겨 먹어 'make sure you eat'), and (3) look after a person attentively (동생 좀 챙겨 'keep an eye on your sibling'). Set it against 돌보다 (care for over time, like nursing a child or the sick): 챙기다 is quicker, more about 'making sure / not letting slip', while 돌보다 is sustained nurturing. It also contrasts with 챙겨 주다, where adding 주다 makes the care explicitly a favour for someone. The English trap is reaching for 들다 'lift' or 가지다 'have' when you mean 'grab/remember to bring' — that everyday act is 챙기다. Native warmth: 잘 챙겨 먹어요 is a standard way to say 'take care of yourself'."},sentence:{ko:"선배가 신분증 꼭 챙기래요.",en:"My senior says to be sure to bring your ID."},target:"챙기",options:["to pass on, to convey (a message)","to take along, to look after","to check, to confirm"],note:"Reminders from a senior almost always arrive as -래요."},{kind:"payoff",line:{speaker:"유진",ko:"오늘요? 저는 야근할 것 같은데요. 어디서 먹재요?",en:"Tonight? I think I'll be working late. Where do they say we're eating?"},hl:"야근"}],canDo:"Contract -다고 해요 into -대요 and keep the -ㄴ/는- on present-tense verbs (운동한대요)",id:"chapter-67-b1",chapterId:"chapter-67",index:0},{kind:"pattern",title:"문법 Grammar · V/A-대요",cards:[{kind:"hunt",name:"V/A-대요",sub:'the contracted "they say…"',lines:[{tokens:[{pre:"지훈이",mid:"",post:"",hit:!1},{pre:"오늘",mid:"",post:"",hit:!1},{pre:"회식에",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"온",mid:"대요",post:".",hit:!0}],ko:"지훈이 오늘 회식에 못 온대요.",en:"Jihoon says he can't make the team dinner today.",romanization:"jihuni oneul hoesige mot ondaeyo."},{tokens:[{pre:"요즘",mid:"",post:"",hit:!1},{pre:"그",mid:"",post:"",hit:!1},{pre:"카페는",mid:"",post:"",hit:!1},{pre:"사람이",mid:"",post:"",hit:!1},{pre:"진짜",mid:"",post:"",hit:!1},{pre:"많",mid:"대요",post:".",hit:!0}],ko:"요즘 그 카페는 사람이 진짜 많대요.",en:"They say that café is really packed these days.",romanization:"yojeum geu kapeneun sarami jinjja mantaeyo."}],rule:{name:"V/A-대요",rows:[{when:"Verb, present, stem with no 받침",add:"-ㄴ대요",ex:"가다 → 간대요 (they say he's going)"},{when:"Verb, present, stem with 받침",add:"-는대요",ex:"먹다 → 먹는대요 (they say she eats it)"},{when:"Adjective, present",add:"-대요",ex:"바쁘다 → 바쁘대요 (they say he's busy)"},{when:"Any past tense",add:"-았/었대요",ex:"보다 → 봤대요 (they say she saw it)"},{when:"Future or plan",add:"-(으)ㄹ 거래요",ex:"가다 → 갈 거래요 (they say he'll go)"}]},more:{func:"In real speech the full -다고 해요 squeezes down to -대요. What comes BEFORE the ending does not change at all: a present-tense verb still needs its -ㄴ/는-, an adjective still attaches bare, and any past tense still uses -았/었-. Only the tail is shorter.",funcLead:"In real speech the full -다고 해요 squeezes down to -대요.",keyPoint:{label:"-대요 vs -데요 — one letter, a completely different source",body:`-대요 passes on somebody else's words: 그 집 맛있대요 means "they say it's good." -데요 reports what YOU saw or experienced yourself and is short for -더라고요: 그 집 맛있데요 means "I tried it, and it was good." Korean adults mix these two up in writing constantly, so lock it in now: 대 = 다른 사람 말, 데 = 내가 본 것.`},pronunciation:"After a ㅎ-final adjective the two sounds fuse: 많대요 is [만태요] and 좋대요 is [조태요]. 봤대요 tenses to [봗때요].",pitfall:{wrong:"친구가 매일 운동하대요.",right:"친구가 매일 운동한대요.",explanation:`With a present-tense VERB, -대요 keeps the -ㄴ/는- that -다고 하다 always carried: 운동한대요, 먹는대요. Only ADJECTIVES attach bare, as in 바쁘대요. English speakers drop the -ㄴ/는- because English draws no line between "he exercises" and "it's busy."`}}},{kind:"drill",prompt:"My younger sibling says he did well on yesterday's exam.",sentence:"동생이 어제 시험을 잘 봤___.",options:[{text:"이래요",ok:!1},{text:"대요",ok:!0},{text:"으래요",ok:!1}],explanation:"Past tense keeps 았/었 and simply adds -대요."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Jihoon says he can't make the team dinner today." (지훈이 시작 · Start with 지훈이.)`,tokens:["지훈이","오늘","회식에","못","온대요."],correct:"지훈이 오늘 회식에 못 온대요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "They say that café is really packed these days."',tokens:["요즘","그","카페는","사람이","진짜","많대요."],correct:"요즘 그 카페는 사람이 진짜 많대요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구가 매일 운동하대요.",ok:!1},{text:"친구가 매일 운동한대요.",ok:!0}],explanation:`With a present-tense VERB, -대요 keeps the -ㄴ/는- that -다고 하다 always carried: 운동한대요, 먹는대요. Only ADJECTIVES attach bare, as in 바쁘대요. English speakers drop the -ㄴ/는- because English draws no line between "he exercises" and "it's busy."`}],canDo:"Contract -다고 해요 into -대요 and keep the -ㄴ/는- on present-tense verbs (운동한대요)",id:"chapter-67-b2",chapterId:"chapter-67",index:1},{kind:"words",title:"단어 Words 2 · 확인하다~",cards:[{kind:"guess",word:{ko:"확인하다",romanization:"hwaginhada",en:"to check, to confirm",pos:"verb",nuance:"확인하다 (確認하다, 確 'certain/firm' + 認 'recognize') means to check, verify, or confirm that something is correct or true — facts, times, reservations, messages — making sure reality matches what you expect. The crucial contrast is with 찾다, which English 'check' can blur: 찾다 is 'to look FOR / search' something not yet located (열쇠를 찾다, 'look for the keys'), whereas 확인하다 is 'to verify' something you can already see (열쇠가 있는지 확인하다, 'check whether the keys are there'). It also differs from 알아보다 ('look into/inquire to find out', 가격을 알아보다). It's a regular noun+하다 verb: 확인하 + 여요 → 확인해요, past 확인했어요, with 안/못 splitting before 하다 (확인 안 해요, 확인 못 해요). English-speaker pitfall: 'check the box' or 'check off' is NOT 확인하다 — ticking a box is 체크하다/표시하다; and 'check out a book/check out (a hotel)' uses 빌리다 or 체크아웃하다, not 확인하다, which strictly means 'verify/confirm'."},sentence:{ko:"지훈이가 예매 시간 다시 확인해 보래요.",en:"Jihoon says to double-check the booking time."},target:"확인해",options:["to check, to confirm","to pass on, to convey (a message)","to take along, to look after"],note:"-아/어 보라고 해요 contracts to -아/어 보래요."},{kind:"guess",word:{ko:"물어보다",romanization:"mureoboda",en:"to ask (a question)",pos:"verb",nuance:"묻다 is the dictionary/base verb. 물어보다 is often the natural spoken choice for asking someone."},sentence:{ko:"손님이 주차가 되냬요. 제가 물어볼까요?",en:"A customer is asking whether there's parking. Shall I go ask?"},target:"물어볼",options:["to pass on, to convey (a message)","to take along, to look after","to ask (a question)"],note:'-냬요 already means "is asking", so you rarely need 물어보다 twice in one sentence.'},{kind:"guess",word:{ko:"대답하다",romanization:"daedapada",en:"to answer, to reply",pos:"verb",nuance:"대답하다 is 對答(대답)하다, the hanja 對 'facing' + 答 'reply', so it literally means to 'reply facing' a question — you give a verbal response back to something someone asked. The key boundary is against 답하다 and 응답하다: 대답하다 is the everyday spoken word (a child 대답해요 when called), 답하다 is more clipped and written (편지에 답하다 'reply to a letter'), and 응답하다 is formal/technical (서버가 응답하다 'the server responds'). The single biggest English-speaker trap is the particle: in English you 'answer the question' (direct object), but in Korean the question is the target you reply toward, so it MUST be 질문에 대답하다 with 에 — 질문을 대답하다 sounds clearly wrong to natives. Also note this is a 하다 verb, so every form is regular: 대답 + 해요, and the negative cleanly splits the noun off as 대답 안 해요 / 대답 못 해요. Do not stretch it to phones (use 전화를 받다) or to 'responding to email,' which Koreans handle with 답장하다."},sentence:{ko:"친구가 언제 오냬요. 뭐라고 대답할까요?",en:"My friend is asking when you're coming. What should I tell them?"},target:"대답할",options:["to pass on, to convey (a message)","to take along, to look after","to answer, to reply"],note:"The natural pair for -냬요: relay the question, then decide the answer."},{kind:"guess",word:{ko:"바쁘다",romanization:"bappeuda",en:"to be busy",pos:"adjective",nuance:"바쁘다 becomes 바빠요 in polite speech. It is a high-frequency reason word because 바빠서 못 가요 politely explains why a plan is impossible."},sentence:{ko:"지훈이는 요즘 프로젝트 때문에 진짜 바쁘대요.",en:"They say Jihoon is really busy these days because of a project."},target:"바쁘",options:["to be free, to have time on one's hands","to be busy","to pass on, to convey (a message)"],note:"An adjective, so -대요 attaches bare: 바쁘대요, never 바쁜대요."},{kind:"guess",word:{ko:"마감",romanization:"magam",en:"deadline, closing",pos:"noun",nuance:"마감 is a native Korean noun (from the verb 막다 'to block/close off') meaning the point at which something is sealed shut: a report's due date, an application cutoff, a shop's last order, even a magazine going to press. The near-synonym confusion is with 기한 and 데드라인: 기한 (期限) is the dry, official 'time limit/term' you see on documents (제출 기한), while 마감 feels more like the live moment things close, and 데드라인 is a borrowed buzzword. Its signature collocation is the idiom 마감에 쫓기다 (chased by the deadline), the universal way to describe last-minute panic. The English-speaker pitfall is mapping 'meet a deadline' onto 만나다 ('meet a person'): you do NOT 마감을 만나다 — you 마감을 지키다 (keep/protect it). Note 지키다 is the same verb used for keeping a promise (약속을 지키다), which is the right mental image."},sentence:{ko:"마감이 이번 주 금요일이래요.",en:"They say the deadline is this Friday."},target:"마감",options:["news, word (from someone)","deadline, closing","notice, announcement"],note:"A noun, so the contraction is 이래요 — the 래요 that comes from -이라고 해요."},{kind:"guess",word:{ko:"발표",romanization:"balpyo",en:"presentation; announcement",pos:"noun",nuance:"발표(發表)는 '필 발 + 겉 표', 곧 '안에 있던 것을 겉으로 드러내 알림'이라는 뜻으로, 여러 사람 앞에서 자기 생각이나 조사한 내용을 말로 알리는 것을 가리켜요. 비슷한 '연설'은 정치인·대표가 청중에게 행하는 더 공식적이고 일방적인 말하기라 학교 과제에는 안 어울리고, '공지'는 '날짜·결과를 알리는 통보'라 말로 설명하는 발표와 다르며, '보고'는 윗사람에게 결과를 전달하는 데 초점이 있어요. 그래서 학생이 수업에서 하는 것은 '발표'가 딱 맞아요. '발표하다' 동사와 '발표를 하다' 형태가 둘 다 자연스럽고, '발표 준비/자료/순서'와 잘 어울려요. 한 가지 더, '합격자 발표'처럼 결과를 공표한다는 뜻도 있어 영어 announce와 겹치지만, 수업 맥락에서는 말로 설명하는 presentation을 뜻한다는 점을 구분하세요."},sentence:{ko:"교수님이 발표를 다음 주로 미루래요.",en:"The professor says to push the presentation back to next week."},target:"발표",options:["news, word (from someone)","presentation; announcement","contact, getting in touch"],note:"An instruction from above arrives as -래요, not -재요."},{kind:"guess",word:{ko:"세일",romanization:"seil",en:"sale (discount period)",pos:"noun",nuance:"세일 is a loanword from English 'sale', but Korean has narrowed it to mean specifically a store-wide markdown EVENT — a period when a whole shop or department store cuts prices (백화점 세일, 시즌 오프 세일). It is not the general word for 'selling': 'to sell' is the native verb 팔다, and a one-item price cut is 할인 (discount). So the sharp contrast is 세일 (the event/season) vs 할인 (the act/amount of discounting a given item): a bag inside a 세일 might have a 30% 할인. Grammatically 세일 pairs with 하다 (세일을 하다 'hold a sale') and lives in time phrases (세일 중, 세일 기간, 세일 때). The English-speaker pitfall is double: (1) don't use 세일 to mean 'sell' — 'I sold my phone' is 폰을 팔았어요, never 세일했어요; and (2) for a discount on a single product prefer 할인. Note also Korean keeps the borrowed -ㄹ sound, so it's 세일 (se-il), two syllables. Collocations: 세일을 하다, 세일 중이다, 세일 기간/때, 시즌 오프 세일."},sentence:{ko:"그 브랜드가 다음 주부터 세일한다던데요.",en:"I hear that brand starts a sale next week."},target:"세일",options:["sale (discount period)","news, word (from someone)","notice, announcement"],note:"Shopping tips are usually floated as hearsay with -다던데요."}],canDo:"Choose between N(이)래요 ('they say it's N') and V-(으)래요 ('they told me to V')",id:"chapter-67-b3",chapterId:"chapter-67",index:2},{kind:"pattern",title:"문법 Grammar · N(이)래요 vs V-(으)래요",cards:[{kind:"hunt",name:"N(이)래요 vs V-(으)래요",sub:"one shape, two jobs",lines:[{tokens:[{pre:"저분이",mid:"",post:"",hit:!1},{pre:"이",mid:"",post:"",hit:!1},{pre:"식당",mid:"",post:"",hit:!1},{pre:"사장님",mid:"이래요",post:".",hit:!0}],ko:"저분이 이 식당 사장님이래요.",en:"They say that person is the owner of this restaurant.",romanization:"jeobuni i sikdang sajangnimiraeyo."},{tokens:[{pre:"의사",mid:"",post:"",hit:!1},{pre:"선생님이",mid:"",post:"",hit:!1},{pre:"이",mid:"",post:"",hit:!1},{pre:"약을",mid:"",post:"",hit:!1},{pre:"하루에",mid:"",post:"",hit:!1},{pre:"두",mid:"",post:"",hit:!1},{pre:"번",mid:"",post:"",hit:!1},{pre:"먹",mid:"으래요",post:".",hit:!0}],ko:"의사 선생님이 이 약을 하루에 두 번 먹으래요.",en:"The doctor says to take this medicine twice a day.",romanization:"uisa seonsaengnimi i yageul harue du beon meogeuraeyo."}],rule:{name:"N(이)래요 vs V-(으)래요",rows:[{when:"Noun with no 받침",add:"N래요",ex:"의사 → 저분이 의사래요 (they say she's a doctor)"},{when:"Noun with 받침",add:"N이래요",ex:"학생 → 옆집 사람이 학생이래요"},{when:"Verb stem with no 받침 — reported command",add:"V-래요",ex:"가다 → 지금 가래요 (they're telling me to go now)"},{when:"Verb stem with 받침 — reported command",add:"V-으래요",ex:"먹다 → 약을 먹으래요 (they say to take the medicine)"},{when:"Negative command",add:"V-지 말래요",ex:"가다 → 오늘은 가지 말래요 (they say not to go today)"}]},more:{func:'래요 is the contraction of two different things. After a NOUN it comes from -(이)라고 해요 and means "they say it IS N." After a VERB STEM it comes from -(으)라고 해요 and reports a command: "they told (me) to V." Nothing but the word in front of it tells them apart, so Korean listeners rely entirely on that.',funcLead:"래요 is the contraction of two different things.",keyPoint:{label:"래요 vs ㄹ래요 — whose idea is it?",body:`저는 갈래요 means "I'll go / I want to go" — your own will, and it takes a first-person subject. 가래요 means "they're telling me to go" — someone else's instruction. One ㄹ flips the sentence from your decision to theirs. Quick test: if you could put 저는 in front of it, you need 갈래요.`},pronunciation:"말래요 doubles the ㄹ as [말래요]. 먹으래요 links straight through as [머그래요], and 연락하래요 is [열라카래요].",pitfall:{wrong:"친구가 의사대요.",right:"친구가 의사래요.",explanation:"A noun never takes -대요. The full form behind it is 의사라고 해요, not 의사다고 해요, so the contraction has to be 의사래요 — or 학생이래요 after a 받침. Learners default to -대요 because it is the contraction they met first."}}},{kind:"drill",prompt:"Mom says to be sure to call if I'm going to be late.",sentence:"엄마가 늦으면 꼭 연락하___.",options:[{text:"이래요",ok:!1},{text:"으래요",ok:!1},{text:"래요",ok:!0}],explanation:"하다 verbs simply become 하래요; the person giving the order is the subject."},{kind:"drill",prompt:"The team lead says not to work late today.",sentence:"팀장님이 오늘은 야근하지 말___.",options:[{text:"래요",ok:!0},{text:"대요",ok:!1},{text:"냬요",ok:!1}],explanation:"A negative instruction goes through -지 말라고 해요 → -지 말래요."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "They say that person is the owner of this restaurant."',tokens:["저분이","이","식당","사장님이래요."],correct:"저분이 이 식당 사장님이래요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"친구가 의사래요.",ok:!0},{text:"친구가 의사대요.",ok:!1}],explanation:"A noun never takes -대요. The full form behind it is 의사라고 해요, not 의사다고 해요, so the contraction has to be 의사래요 — or 학생이래요 after a 받침. Learners default to -대요 because it is the contraction they met first."}],canDo:"Choose between N(이)래요 ('they say it's N') and V-(으)래요 ('they told me to V')",id:"chapter-67-b4",chapterId:"chapter-67",index:3},{kind:"words",title:"단어 Words 3 · 소문~",cards:[{kind:"guess",word:{ko:"소문",romanization:"somun",en:"rumour, word going around",pos:"noun"},sentence:{ko:"소문으로는 그 가게가 다음 달에 문 닫는대요.",en:"Word going around is that the shop is closing next month."},target:"소문",options:["rumour, word going around","notice, announcement","contact, getting in touch"],note:"소문 and the -대요 family belong together: neither claims to be first-hand."},{kind:"guess",word:{ko:"미루다",romanization:"miruda",en:"to postpone, to push back",pos:"verb"},sentence:{ko:"지훈이가 약속을 이번 주말로 미루재요.",en:"Jihoon says let's push our plans to this weekend."},target:"미루",options:["to pass on, to convey (a message)","to postpone, to push back","to take along, to look after"],note:"A proposal to postpone, so -재요; an order to postpone would be 미루래요."},{kind:"guess",word:{ko:"한가하다",romanization:"hangahada",en:"to be free, to have time on one's hands",pos:"adjective"},sentence:{ko:"친구가 이번 주말에는 한가하대요.",en:"My friend says she's free this weekend."},target:"한가하",options:["to be busy","to be free, to have time on one's hands","to pass on, to convey (a message)"],note:"An adjective, so 한가하대요 — 한가하재요 would be nonsense."},{kind:"guess",word:{ko:"맛집",romanization:"matjip",en:"a really good place to eat",pos:"noun"},sentence:{ko:"회사 앞에 새로 생긴 데가 진짜 맛집이라던데요.",en:"I hear the new place in front of the office is a real find."},target:"맛집",options:["news, word (from someone)","a really good place to eat","notice, announcement"],note:"A noun, so hearsay about it takes 이라던데요."},{kind:"guess",word:{ko:"예매",romanization:"yemae",en:"advance booking (tickets)",pos:"noun"},sentence:{ko:"지훈이가 예매는 자기가 한대요.",en:"Jihoon says he'll handle the booking himself."},target:"예매",options:["advance booking (tickets)","news, word (from someone)","notice, announcement"],note:"자기가 marks that the reported speaker means himself, not you."},{kind:"payoff",line:{speaker:"지원",ko:"회사 앞에 새로 생긴 데래요. 거기가 요즘 진짜 맛집이라던데요.",en:"They say it's the new place in front of the office. I hear it's really good these days."},hl:"맛집"}],canDo:"Relay someone else's question with -냬요 and someone else's proposal with -재요",id:"chapter-67-b5",chapterId:"chapter-67",index:4},{kind:"pattern",title:"문법 Grammar · V/A-냬요",cards:[{kind:"hunt",name:"V/A-냬요",sub:"passing on someone else's question",lines:[{tokens:[{pre:"팀장님이",mid:"",post:"",hit:!1},{pre:"보고서",mid:"",post:"",hit:!1},{pre:"언제",mid:"",post:"",hit:!1},{pre:"끝나",mid:"냬요",post:".",hit:!0}],ko:"팀장님이 보고서 언제 끝나냬요.",en:"The team lead is asking when the report will be done.",romanization:"timjangnimi bogoseo eonje kkeunnanaeyo."},{tokens:[{pre:"친구가",mid:"",post:"",hit:!1},{pre:"이번",mid:"",post:"",hit:!1},{pre:"주말에",mid:"",post:"",hit:!1},{pre:"시간",mid:"",post:"",hit:!1},{pre:"있",mid:"냬요",post:".",hit:!0}],ko:"친구가 이번 주말에 시간 있냬요.",en:"My friend is asking whether you're free this weekend.",romanization:"chinguga ibeon jumare sigan innaeyo."}],rule:{name:"V/A-냬요",rows:[{when:"Verb or adjective, present",add:"-냬요",ex:"가다 → 어디 가냬요 (they're asking where you're going)"},{when:"Any past tense",add:"-았/었냬요",ex:"오다 → 언제 왔냬요 (they're asking when you came)"},{when:"Noun",add:"N(이)냬요",ex:"학생 → 학생이냬요 (they're asking if you're a student)"},{when:"Full form, for writing or careful speech",add:"-냐고 해요 / -냐고 물어봐요",ex:"가다 → 어디 가냐고 물어봐요"}]},more:{func:"-냬요 is -냐고 해요 squeezed down. Use it when you are relaying a question somebody asked, usually to the person who can actually answer it. The question word — 뭐, 언제, 어디, 왜 — stays exactly where it stood in the original question, and the polite 요 of that question disappears.",funcLead:"-냬요 is -냐고 해요 squeezed down.",keyPoint:{label:"냬요 is for somebody else's question, never your own",body:"If you want to ask the question yourself, just ask it: 언제 끝나요? Use -냬요 only when you are the middleman — A asked, and you are handing the question to B. That is why almost every -냬요 sentence names the asker up front: 팀장님이…, 친구가…, 손님이…"},pronunciation:"The ㄴ of 냬 nasalizes whatever closes the syllable before it: 있냬요 is [인내요], 먹었냬요 is [머건내요], and 끝나냬요 is [끈나내요].",pitfall:{wrong:"팀장님이 보고서 언제 끝나요라고 해요.",right:"팀장님이 보고서 언제 끝나냬요.",explanation:"Learners quote the question word for word, the way English uses quotation marks: 'He asked, when is it done?' Korean reported questions strip the polite ending first and run through -냐고 해요, which contracts to -냬요. The 요 of the original question always disappears."}}},{kind:"drill",prompt:"A customer is asking whether it's okay to sit here.",sentence:"손님이 이 자리 앉아도 되___.",options:[{text:"냬요",ok:!0},{text:"대요",ok:!1},{text:"이래요",ok:!1}],explanation:"-아/어도 돼요? becomes -아/어도 되냬요 when relayed."},{kind:"drill",prompt:"Mom is asking whether you've eaten.",sentence:"어머니가 밥은 먹었___.",options:[{text:"냬요",ok:!0},{text:"대요",ok:!1},{text:"이래요",ok:!1}],explanation:"The past stays inside: 먹었냐고 해요 → 먹었냬요."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The team lead is asking when the report will be done."',tokens:["팀장님이","보고서","언제","끝나냬요."],correct:"팀장님이 보고서 언제 끝나냬요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "My friend is asking whether you're free this weekend." (친구가 시작 · Start with 친구가.)`,tokens:["친구가","이번","주말에","시간","있냬요."],correct:"친구가 이번 주말에 시간 있냬요.",explanation:""}],canDo:"Relay someone else's question with -냬요 and someone else's proposal with -재요",id:"chapter-67-b6",chapterId:"chapter-67",index:5},{kind:"pattern",title:"문법 Grammar · V-재요",cards:[{kind:"hunt",name:"V-재요",sub:"passing on someone's suggestion",lines:[{tokens:[{pre:"친구들이",mid:"",post:"",hit:!1},{pre:"이번",mid:"",post:"",hit:!1},{pre:"주말에",mid:"",post:"",hit:!1},{pre:"등산",mid:"",post:"",hit:!1},{pre:"가",mid:"재요",post:".",hit:!0}],ko:"친구들이 이번 주말에 등산 가재요.",en:"My friends say let's go hiking this weekend.",romanization:"chingudeuri ibeon jumare deungsan gajaeyo."},{tokens:[{pre:"동기들이",mid:"",post:"",hit:!1},{pre:"점심은",mid:"",post:"",hit:!1},{pre:"구내식당에서",mid:"",post:"",hit:!1},{pre:"먹",mid:"재요",post:".",hit:!0}],ko:"동기들이 점심은 구내식당에서 먹재요.",en:"My colleagues say let's eat lunch in the cafeteria.",romanization:"donggideuri jeomsimeun gunaesikdangeseo meokjaeyo."}],rule:{name:"V-재요",rows:[{when:"Any verb stem",add:"-재요",ex:"가다 → 같이 가재요 (they say let's go together)"},{when:"Verb stem with 받침 — the ending does not change",add:"-재요",ex:"먹다 → 점심 먹재요 (they say let's have lunch)"},{when:"Negative proposal",add:"V-지 말재요",ex:"가다 → 오늘은 가지 말재요 (they say let's not go today)"},{when:"Full form, for writing or careful speech",add:"V-자고 해요",ex:"가다 → 같이 가자고 해요"}]},more:{func:`-재요 is -자고 해요 contracted: somebody proposed doing something together, and you are relaying the proposal. Because 자 is the "let's" ending, -재요 can only ever attach to an action verb — never to an adjective, and never to a noun.`,funcLead:"-재요 is -자고 해요 contracted: somebody proposed doing something together, and you are relaying the proposal.",keyPoint:{label:"The four contractions in one line",body:"-대요 for a statement (간대요 — they say he's going), -래요 for a command or a noun (가래요 — they say to go / 학생이래요 — they say he's a student), -냬요 for a question (가냬요 — they're asking if you're going), -재요 for a proposal (가재요 — they say let's go). They are the same four sentence types you already learned with -다고/-라고/-냐고/-자고 하다, just squeezed."},pronunciation:"After a ㄱ or ㅂ final the ㅈ of 재 tenses: 먹재요 is [먹째요] and 입재요 is [입째요]. A ㄹ-final stem does not tense it — 말재요 stays [말재요].",pitfall:{wrong:"친구가 주말에 한가하재요.",right:"친구가 주말에 한가하대요.",explanation:`-재요 comes from -자고, the "let's" ending, so it only attaches to an action verb. 한가하다 is an adjective — you cannot propose "let's be free" — so a statement about it takes -대요. Rule of thumb: if the English is "let's…", use -재요; if it is "they say it is…", use -대요.`}}},{kind:"drill",prompt:"Jihoon says let's not drink tonight.",sentence:"지훈이가 오늘은 술은 마시지 말___.",options:[{text:"대요",ok:!1},{text:"재요",ok:!0},{text:"이래요",ok:!1}],explanation:"The negative goes inside: -지 말자고 해요 → -지 말재요."},{kind:"drill",prompt:"The team says let's push the dinner back to next week.",sentence:"팀에서 회식 날짜를 다음 주로 미루___.",options:[{text:"대요",ok:!1},{text:"이래요",ok:!1},{text:"재요",ok:!0}],explanation:"팀에서 marks a group acting as one, which is common with relayed proposals."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "My friends say let's go hiking this weekend." (친구들이 시작 · Start with 친구들이.)`,tokens:["친구들이","이번","주말에","등산","가재요."],correct:"친구들이 이번 주말에 등산 가재요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "My colleagues say let's eat lunch in the cafeteria." (동기들이 시작 · Start with 동기들이.)`,tokens:["동기들이","점심은","구내식당에서","먹재요."],correct:"동기들이 점심은 구내식당에서 먹재요.",explanation:""}],canDo:"Tell 갈래요 (my own will) apart from 가래요 (their instruction)",id:"chapter-67-b7",chapterId:"chapter-67",index:6},{kind:"pattern",title:"문법 Grammar · -다던데(요)",cards:[{kind:"hunt",name:"-다던데(요)",sub:"hearsay you drop in as background",lines:[{tokens:[{pre:"그",mid:"",post:"",hit:!1},{pre:"집",mid:"",post:"",hit:!1},{pre:"칼국수가",mid:"",post:"",hit:!1},{pre:"그렇게",mid:"",post:"",hit:!1},{pre:"맛있",mid:"다던데요",post:".",hit:!0},{pre:"한번",mid:"",post:"",hit:!1},{pre:"가",mid:"",post:"",hit:!1},{pre:"볼까요?",mid:"",post:"",hit:!1}],ko:"그 집 칼국수가 그렇게 맛있다던데요. 한번 가 볼까요?",en:"I hear the kalguksu there is really something. Shall we try it?",romanization:"geu jip kalguksuga geureoke masitdadeondeyo. hanbeon ga bolkkayo?"},{tokens:[{pre:"내일부터",mid:"",post:"",hit:!1},{pre:"비가",mid:"",post:"",hit:!1},{pre:"온",mid:"다던데요",post:".",hit:!0},{pre:"우산",mid:"",post:"",hit:!1},{pre:"챙기세요.",mid:"",post:"",hit:!1}],ko:"내일부터 비가 온다던데요. 우산 챙기세요.",en:"I hear it's going to rain from tomorrow. Bring an umbrella.",romanization:"naeilbuteo biga ondadeondeyo. usan chaenggiseyo."}],rule:{name:"-다던데(요)",rows:[{when:"Verb, present",add:"-ㄴ/는다던데요",ex:"오다 → 내일부터 비가 온다던데요"},{when:"Adjective, present",add:"-다던데요",ex:"맛있다 → 거기 맛있다던데요"},{when:"Any past tense",add:"-았/었다던데요",ex:"닫다 → 벌써 문을 닫았다던데요"},{when:"Noun",add:"N(이)라던데요",ex:"맛집 → 거기가 유명한 맛집이라던데요"},{when:"Casual (반말)",add:"-다더라",ex:"편하다 → 그 앱이 제일 편하다더라"}]},more:{func:"-다던데요 is -다고 하던데요: you heard it somewhere, you are passing it on, and the 던데요 tail leaves room for the other person to react. It turns hearsay into background information rather than a flat claim, which is exactly why Koreans use it to suggest things without pushing. The casual version is -다더라.",funcLead:"-다던데요 is -다고 하던데요: you heard it somewhere, you are passing it on, and the 던데요 tail leaves room for the other person to react.",keyPoint:{label:"Why Koreans suggest things with 던데요",body:`-다던데요 lets you float an idea without owning it. 거기 맛있다던데요 says "apparently it's good" and hands the decision to the listener, whereas 거기 맛있어요 is your own claim and 거기 가요 is a direct proposal. It is the natural move when you are the junior person in the room and do not want to decide for everyone.`},pronunciation:"던데요 is [던데요]. After a past 았/었 the ㄷ tenses: 닫았다던데요 is [다닫따던데요] and 맛있다던데요 is [마싣따던데요].",pitfall:{wrong:"제가 어제 거기 갔다던데요.",right:"제가 어제 거기 갔는데요.",explanation:"-다던데요 says you heard it from somebody else, so it cannot report your own first-hand experience. Learners reach for it as a general softener because the 던데요 tail sounds friendly. For something you did yourself, use plain -는데요."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I hear it's going to rain from tomorrow. Bring an umbrella." (내일부터 시작 · Start with 내일부터.)`,tokens:["내일부터","비가","온다던데요.","우산","챙기세요."],correct:"내일부터 비가 온다던데요. 우산 챙기세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"제가 어제 거기 갔는데요.",ok:!0},{text:"제가 어제 거기 갔다던데요.",ok:!1}],explanation:"-다던데요 says you heard it from somebody else, so it cannot report your own first-hand experience. Learners reach for it as a general softener because the 던데요 tail sounds friendly. For something you did yourself, use plain -는데요."}],canDo:"Float something you heard with -다던데요 instead of claiming it yourself",id:"chapter-67-b8",chapterId:"chapter-67",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two colleagues at their desks. One of them missed the team lead's announcement and the group chat, so everything has to be relayed second-hand.",lines:[{speaker:"유진",ko:"지원 씨, 팀장님이 방금 뭐라고 하셨어요?",en:"Jiwon, what did the team lead just say?",romanization:"jiwon ssi, timjangnimi banggeum mworago hasyeosseoyo?"},{speaker:"지원",ko:"오후 회의가 세 시로 미뤄졌대요. 그리고 자료는 미리 올려 놓으래요.",en:"She says the afternoon meeting got pushed to three. And she says to upload the materials in advance.",romanization:"ohu hoeuiga se siro mirwojyeotdaeyo. geurigo jaryoneun miri ollyeo noeuraeyo."},{speaker:"유진",ko:"네. 아, 그리고 지훈 씨가 저한테 회의 자료 다 됐냬요.",en:"Okay. Oh, and Jihoon was asking me whether the meeting materials are ready.",romanization:"ne. a, geurigo jihun ssiga jeohante hoeui jaryo da dwaennaeyo."},{speaker:"지원",ko:"거의 다 됐다고 전해 주세요. 아, 그리고 동기들이 오늘 저녁에 같이 밥 먹재요.",en:"Tell him it's almost done. Oh, and the others say let's have dinner together tonight.",romanization:"geoui da dwaetdago jeonhae juseyo. a, geurigo donggideuri oneul jeonyeoge gachi bap meokjaeyo."},{speaker:"유진",ko:"오늘요? 저는 야근할 것 같은데요. 어디서 먹재요?",en:"Tonight? I think I'll be working late. Where do they say we're eating?",romanization:"oneuryo? jeoneun yageunhal geot gateundeyo. eodiseo meokjaeyo?"},{speaker:"지원",ko:"회사 앞에 새로 생긴 데래요. 거기가 요즘 진짜 맛집이라던데요.",en:"They say it's the new place in front of the office. I hear it's really good these days.",romanization:"hoesa ape saero saenggin deraeyo. geogiga yojeum jinjja matjibiradeondeyo."},{speaker:"유진",ko:"그럼 가야죠. 몇 시에 모이재요?",en:"Then I have to go. What time do they say we're meeting?",romanization:"geureom gayajyo. myeot sie moijaeyo?"},{speaker:"지원",ko:"일곱 시래요. 늦으면 먼저 시작한다던데요.",en:"They say seven. And apparently they'll start without us if we're late.",romanization:"ilgop siraeyo. neujeumyeon meonjeo sijakandadeondeyo."}]},{kind:"order",prompt:"Build: 'The doctor says to take this medicine twice a day.' (Start with 의사 선생님이.)",tokens:["의사 선생님이","이 약을 하루에 두 번","먹으래요"],correct:"의사 선생님이 이 약을 하루에 두 번 먹으래요",explanation:"A reported command from a person: 먹으라고 해요 → 먹으래요, with the doctor as the subject."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"거의 다 됐다고 전해 주세요. 아, 그리고 동기들이 오늘 저녁에 같이 밥 먹재요.",options:[{text:"유진",ok:!1},{text:"지원",ok:!0}],explanation:"Tell him it's almost done. Oh, and the others say let's have dinner together tonight."},{kind:"drill",prompt:`무엇이 들어갈까요? · "Tonight? I think I'll be working late. Where do they say we're eating?"`,sentence:"오늘요? 저는 ___할 것 같은데요. 어디서 먹재요?",options:[{text:"소식",ok:!1},{text:"공지",ok:!1},{text:"야근",ok:!0}],explanation:""}],canDo:"Contract -다고 해요 into -대요 and keep the -ㄴ/는- on present-tense verbs (운동한대요)",id:"chapter-67-b9",chapterId:"chapter-67",index:8},{kind:"reading",title:"읽기 Reading · 전하는 사람의 말",cards:[{kind:"read",title:"전하는 사람의 말",chunks:["한국 사람들은 하루에도 몇 번씩 다른 사람의 말을 옮긴다. 그럴 때 -다고 해요를 그대로 말하는 경우는 거의 없다. 말이 빨라지면서 -대요, -래요, -냬요, -재요로 줄어들기 때문이다. 네 가지는 원래 문장의 종류를 그대로 따라간다.","설명하는 말은 -대요, 시키는 말은 -래요, 묻는 말은 -냬요, 같이 하자는 말은 -재요가 된다. 명사 뒤에는 -이래요를 쓴다는 것도 잊으면 안 된다. 여기에 -다던데요까지 익히면, 들은 이야기를 조심스럽게 꺼내면서 판단은 상대방에게 맡길 수 있다."],translation:`Koreans relay other people's words several times a day. When they do, they almost never say the full -다고 해요. As speech speeds up it shrinks into -대요, -래요, -냬요, and -재요. All four follow the type of the original sentence exactly: a statement becomes -대요, an instruction becomes -래요, a question becomes -냬요, and a "let's" becomes -재요. You also must not forget that after a noun you use -이래요. Add -다던데요 on top of that, and you can raise something you heard carefully while leaving the judgement to the other person.`,qas:[{q:"설명하는 말을 옮길 때는 어떤 어미를 써요?",a:"-대요를 써요. 예를 들어 '간다고 해요'는 '간대요'가 돼요."},{q:"명사 뒤에는 무엇을 써요?",a:"-이래요를 써요. '학생이라고 해요'가 '학생이래요'가 돼요."},{q:"-다던데요는 왜 써요?",a:"들은 이야기를 조심스럽게 꺼내고 판단은 상대방에게 맡기려고 써요."}]}],canDo:"Choose between N(이)래요 ('they say it's N') and V-(으)래요 ('they told me to V')",id:"chapter-67-b10",chapterId:"chapter-67",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Contract this into everyday speech: '친구가 매일 운동한다고 해요.'",sentence:null,options:[{text:"친구가 매일 운동한대요.",ok:!0},{text:"친구가 매일 운동하대요.",ok:!1},{text:"친구가 매일 운동이래요.",ok:!1}],explanation:"A present-tense verb keeps the -ㄴ/는- it had in -다고 하다: 운동한다고 해요 → 운동한대요. Bare -대요 belongs to adjectives only."},{kind:"drill",prompt:"'They say she's a student' — which contraction is right?",sentence:null,options:[{text:"학생이래요.",ok:!0},{text:"학생이대요.",ok:!1},{text:"학생인대요.",ok:!1}],explanation:"Nouns run through -(이)라고 해요, so the contraction is -(이)래요. A noun never takes -대요."},{kind:"drill",prompt:"Which one means 'they told me to go' (not 'I want to go')?",sentence:null,options:[{text:"가래요",ok:!0},{text:"갈래요",ok:!1},{text:"가재요",ok:!1}],explanation:"가래요 is 가라고 해요, somebody else's instruction. 갈래요 is your own will ('I'll go'). 가재요 is 가자고 해요 ('they say let's go')."},{kind:"drill",prompt:"The team lead asked '언제 끝나요?'. Relay it.",sentence:null,options:[{text:"팀장님이 언제 끝나냬요.",ok:!0},{text:"팀장님이 언제 끝난대요.",ok:!1},{text:"팀장님이 언제 끝나재요.",ok:!1}],explanation:"A reported question uses -냐고 해요 → -냬요. -ㄴ대요 would report a statement, and -재요 a proposal."},{kind:"drill",prompt:"A colleague said '같이 점심 먹자.' Relay it.",sentence:null,options:[{text:"같이 점심 먹재요.",ok:!0},{text:"같이 점심 먹는대요.",ok:!1},{text:"같이 점심 먹으래요.",ok:!1}],explanation:"-자고 해요 contracts to -재요 for a proposal. -는대요 would report a statement and -으래요 an order."},{kind:"drill",prompt:"팀장님___ 회의 시간이 바뀌었대요. (The team lead says the meeting time changed.)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에서",ok:!1}],explanation:"The person whose words you are relaying is the subject of -대요, so 팀장님이. 을 would make the team lead the object, and 에서 marks a place or an organisation."}],canDo:"Relay someone else's question with -냬요 and someone else's proposal with -재요",id:"chapter-67-b11",chapterId:"chapter-67",index:10}]},{id:"chapter-68",number:68,title:"V-느라고 · V-는 바람에",goal:"Excuse a failure with V-느라고, keeping one subject across both clauses and no tense marker on the ending.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 숙제~",cards:[{kind:"guess",word:{ko:"숙제",romanization:"sukje",en:"homework, assignment",pos:"noun",nuance:"숙제 is Sino-Korean 宿題 — 宿 'lodging/stay overnight' + 題 'topic/problem', literally a 'problem to take home overnight', i.e. work a teacher assigns to be done outside class. The verb is locked: Koreans say 숙제를 하다 'do homework', and 숙제를 내다 means a student turns it in (while a teacher 내다 a 숙제 means 'assign/set' it — context decides). Contrast 숙제 with 공부(工夫, 'study') and 과제(課題, 'assignment/coursework'): 공부하다 is the broad act of studying anything, whereas 숙제 is a specific assigned task, and 과제 is the more formal university word for a project or paper. The big English-speaker pitfall is translating 'do my homework' as 숙제를 만들다 'make homework' (✗ — that sounds like you created the assignment) or 숙제를 공부하다 (✗); the only natural pairing is 숙제를 하다."},sentence:{ko:"친구랑 노느라고 숙제를 하나도 못 했어요.",en:"I was messing around with a friend, so I didn't do any of my homework."},target:"숙제",options:["aches and exhaustion (from overdoing it)","homework, assignment","a sudden shower, a downpour"],note:"놀다 loses its ㄹ before -느라고, giving 노느라고."},{kind:"guess",word:{ko:"서두르다",romanization:"seodureuda",en:"to hurry, to rush",pos:"verb",nuance:"서두르다 means to hurry / rush / get a move on, acting on yourself to do things fast because time is short. Distinguish it from 급하다, the ADJECTIVE 'to be urgent / be in a rush' (마음이 급해요 = 'I feel rushed'): 급하다 describes the pressured state, while 서두르다 is the action you take in response — you 서두르다 because something is 급하다. It is plainly conjugated speech, fine in any everyday register, and softens to a gentle 서두르지 마세요 ('don't rush') when reassuring someone. The grammar heart of this word is that it is a 르 irregular: before a vowel ending the 르 sheds its ㅡ and an extra ㄹ appears, so 서두르 + 어요 → 서둘러요, and the past is 서둘렀어요 — anchor everything on 서둘러요. The classic English-speaker mistake is regularizing it to 서두러요 (no doubled ㄹ). Collocations: 서둘러 나가다 (hurry out), 서두르다가 넘어지다 (trip from rushing), 서두를 거 없어요 (no need to rush)."},sentence:{ko:"늦잠을 자는 바람에 아침 내내 서둘렀어요.",en:"I overslept, so I was rushing the whole morning."},target:"서둘렀",options:["to hurry, to rush","to be crowded, to be packed","to miss (a train, a chance, a stop)"],note:"서두르다 is a 르-irregular verb: 서둘러요, 서둘렀어요."},{kind:"guess",word:{ko:"몸살",romanization:"momsal",en:"aches and exhaustion (from overdoing it)",pos:"noun",nuance:"몸살은 과로나 감기 때문에 온몸이 쑤시고 무겁고 기운 없는 상태를 통째로 가리키는 순우리말이라, 영어에 일대일로 맞는 단어가 없어 'body aches' 또는 'feeling run-down'으로 풀어 설명해야 한다. 단순 근육통(근육통)이 특정 근육 하나가 뻐근한 것이라면, 몸살은 전신의 나른함·오한·미열까지 포함하는 훨씬 넓은 개념이라는 점이 핵심 차이다. 기본형은 '몸살이 나다'이고, 회사에 결근·조퇴 사유로 '몸살 났어요'라고 하면 누구나 바로 알아듣는 매우 일상적인 캐주얼 단어다. 본격적으로 아프기 전 단계는 '몸살 기운이 있다'로 표현하는데, 여기서 '기운'은 '에너지'가 아니라 '~할 것 같은 조짐'이라는 뜻이라 영어권 학습자가 헷갈리기 쉽다. 또 하나 흔한 함정은 '몸살이 아프다'인데, 몸살은 '아픈 상태' 자체를 가리키는 명사라 '아프다'와 겹쳐 어색해지니 '몸살이 났어요 / 몸살이 심해요'라고 해야 한다."},sentence:{ko:"며칠 계속 야근하더니 결국 몸살이 났어요.",en:"He kept working late for days, and in the end he came down with aches all over."},target:"몸살",options:["aches and exhaustion (from overdoing it)","homework, assignment","a sudden shower, a downpour"],note:"몸살이 나다 is the fixed phrase, and 결국 pairs naturally with -더니."},{kind:"guess",word:{ko:"붐비다",romanization:"bumbida",en:"to be crowded, to be packed",pos:"verb",nuance:"붐비다 describes the place or route becoming crowded. 사람이 많다 describes the number of people more directly."},sentence:{ko:"지하철이 너무 붐비는 바람에 한 대를 그냥 보냈어요.",en:"The subway was so packed that I just let one train go."},target:"붐비",options:["to be crowded, to be packed","to hurry, to rush","to miss (a train, a chance, a stop)"],note:"A crowd is not your doing, so -는 바람에 is the natural connector."},{kind:"guess",word:{ko:"놓치다",romanization:"nochida",en:"to miss (a train, a chance, a stop)",pos:"verb",nuance:"놓치다 is for missing something you were actively trying to catch or hold — a bus, a train, a flight, a chance, or even the thread of a conversation (요점을 놓치다 = 'miss the point') — and it always takes a 을/를 object. Its make-up shows the meaning: 놓다 ('to let go/release') + 치다, so it literally pictures something slipping out of your grasp. The single biggest English-speaker pitfall is using it for missing a *person*: English 'I miss you' is NOT 놓치다 — that is 보고 싶다 ('want to see'), so 엄마가 보고 싶어요, never 엄마를 놓쳐요. Contrast 놓치다 ('fail to catch what was within reach') with 지나가다/지나치다 ('let pass / pass by'): you 놓치다 a bus you ran for, but a chance that quietly 지나가다 simply went by. It is a regular ㅣ-stem verb: 놓치 + 어 → 놓쳐요, and it frequently appears alongside 늦다 ('be late')."},sentence:{ko:"통화하느라고 내릴 역을 놓쳤어요.",en:"I was on the phone, so I missed my stop."},target:"놓쳤",options:["to hurry, to rush","to be crowded, to be packed","to miss (a train, a chance, a stop)"],note:"One subject, one absorbing activity, one thing that went wrong — textbook -느라고."},{kind:"guess",word:{ko:"쏟다",romanization:"ssotda",en:"to spill, to pour out",pos:"verb",nuance:"쏟다 means to spill or pour out a sizable amount of liquid or contents all at once, usually by knocking something over — it feels stronger and more sudden than 흘리다, which is a small trickling spill (a few drops on your shirt). So 컵을 쏟다 = the whole cup goes over, 국물을 흘리다 = you dribbled a bit of broth. Figuratively 쏟다 is 'pour out' effort or emotion: 정성을 쏟다 'pour in devotion', 노력을 쏟다 'pour in effort', 눈물을 쏟다 'burst into tears'. Its intransitive/spontaneous partner is 쏟아지다 'to gush/pour down' (비가 쏟아지다 'rain pours'), so 쏟다 = someone spills it, 쏟아지다 = it pours by itself. Particles: the spilled thing takes 를, the surface it lands on takes 에 (바닥에 쏟다). The English-speaker spelling pitfall is the ㄷ batchim — write 쏟다/쏟아요 (stem 쏟-), never 쏘다요; and don't confuse it with 쏘다 'to shoot'."},sentence:{ko:"서두르다가 국물을 쏟는 바람에 옷을 갈아입었어요.",en:"I was rushing and spilled soup, so I had to change clothes."},target:"쏟는",options:["to hurry, to rush","to be crowded, to be packed","to spill, to pour out"],note:"쏟다 is transitive; the intransitive 쏟아지다 is what rain does."},{kind:"guess",word:{ko:"넘어지다",romanization:"neomeojida",en:"to fall over, to trip",pos:"verb",nuance:"넘어지다 means a standing person (or upright thing) loses balance and topples to the ground, built on 넘다 'to go over' + -어지다 'to come to be', literally 'to come to fall over'. The line to draw is against 떨어지다 ('to fall FROM a height / to drop'): a person on their feet 넘어지다, but a cup off a table or a leaf from a tree 떨어지다 — and against 쓰러지다, which is to collapse from illness/exhaustion (fainting) rather than from tripping. Register is plain and used for everyone. The place where you fall takes 에서 (action location), and the cause is usually chained with -어서: 미끄러져서 넘어졌어요. Natural collocations: 넘어져서 무릎이 까지다 (scrape a knee falling), 넘어질 뻔하다 (almost fall), 넘어지지 않게 조심하다. The English-speaker pitfall is reaching for 떨어지다 because English uses 'fall' for both — but 'I fell (down)' on flat ground is always 넘어지다; save 떨어지다 for dropping or falling off something."},sentence:{ko:"앞사람이 갑자기 멈추는 바람에 넘어질 뻔했어요.",en:"The person in front stopped suddenly, so I nearly fell over."},target:"넘어질",options:["to hurry, to rush","to fall over, to trip","to be crowded, to be packed"],note:"Near-misses and -는 바람에 belong together: sudden cause, bad near-outcome."}],canDo:"Excuse a failure with V-느라고 while keeping one subject and no tense marker (숙제하느라고 못 갔어요)",id:"chapter-68-b1",chapterId:"chapter-68",index:0},{kind:"pattern",title:"문법 Grammar · V-느라고",cards:[{kind:"hunt",name:"V-느라고",sub:`"I was busy V-ing," and what didn't get done`,lines:[{tokens:[{pre:"어제",mid:"",post:"",hit:!1},{pre:"보고서",mid:"",post:"",hit:!1},{pre:"쓰",mid:"느라고",post:"",hit:!0},{pre:"한숨도",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"잤어요.",mid:"",post:"",hit:!1}],ko:"어제 보고서 쓰느라고 한숨도 못 잤어요.",en:"I was writing a report yesterday, so I didn't sleep a wink.",romanization:"eoje bogoseo sseuneurago hansumdo mot jasseoyo."},{tokens:[{pre:"게임하",mid:"느라고",post:"",hit:!0},{pre:"엄마가",mid:"",post:"",hit:!1},{pre:"부르는",mid:"",post:"",hit:!1},{pre:"소리를",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"들었어요.",mid:"",post:"",hit:!1}],ko:"게임하느라고 엄마가 부르는 소리를 못 들었어요.",en:"I was gaming, so I didn't hear my mom calling me.",romanization:"geimhaneurago eommaga bureuneun sorireul mot deureosseoyo."}],rule:{name:"V-느라고",rows:[{when:"Any action verb stem",add:"-느라고",ex:"쓰다 → 보고서를 쓰느라고 (busy writing the report)"},{when:"ㄹ-final stem — the ㄹ drops",add:"-느라고",ex:"놀다 → 노느라고 (busy playing around)"},{when:"Never take a tense marker",add:"V-느라고 (the tense lives in clause 2)",ex:"쓰다 → 썼느라고 ✗ / 쓰느라고 못 잤어요 ✓"},{when:"Thanking someone for their effort",add:"V-느라고 고생하셨어요",ex:"오다 → 오시느라고 고생하셨어요"}]},more:{func:"-느라고 names a time-consuming activity you were absorbed in, and the second clause says what suffered for it. Three conditions have to hold at once: both clauses share the same subject, the first action genuinely eats the time the second one needed, and the second clause is normally something that failed to happen. Only action verbs qualify.",funcLead:"-느라고 names a time-consuming activity you were absorbed in, and the second clause says what suffered for it.",keyPoint:{label:"One subject, one stretch of time, one thing that failed",body:"All three conditions have to hold. 동생이 떠드느라고 제가 못 잤어요 breaks the first one — the noisy person is 동생 and the sleepless one is 저 — so it needs -는 바람에 instead. And 배가 아프느라고 breaks the third: 아프다 is an adjective, not something you spend time doing."},pronunciation:"In fast speech the 고 often drops: 쓰느라 못 잤어요. After a ㄹ-stem the ㄹ disappears entirely — 놀다 → 노느라고, 만들다 → 만드느라고 — the same drop you see in 노는, 만드는.",pitfall:{wrong:"어제 보고서를 썼느라고 못 잤어요.",right:"어제 보고서를 쓰느라고 못 잤어요.",explanation:`English marks the past on both halves — "I was writing… so I couldn't sleep" — so learners add -았/었- to 느라고 as well. Korean marks the tense only once, in the final clause. -느라고 always sits on the bare stem: 쓰느라고, 하느라고, 보느라고.`}}},{kind:"drill",prompt:"Thank you for making the trip all the way here.",sentence:"여기까지 오시___ 고생하셨어요.",options:[{text:"느라고",ok:!0},{text:"더니",ok:!1},{text:"아서",ok:!1}],explanation:"The warm use of -느라고: naming the effort somebody spent on you."},{kind:"drill",prompt:"I was busy getting ready to move this month, so I was all over the place.",sentence:"이번 달에는 이사 준비하___ 정신이 없었어요.",options:[{text:"더니",ok:!1},{text:"아서",ok:!1},{text:"느라고",ok:!0}],explanation:"정신이 없다 is one of the most common results after -느라고."},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I was writing a report yesterday, so I didn't sleep a wink."`,tokens:["어제","보고서","쓰느라고","한숨도","못","잤어요."],correct:"어제 보고서 쓰느라고 한숨도 못 잤어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I was gaming, so I didn't hear my mom calling me."`,tokens:["게임하느라고","엄마가","부르는","소리를","못","들었어요."],correct:"게임하느라고 엄마가 부르는 소리를 못 들었어요.",explanation:""}],canDo:"Excuse a failure with V-느라고 while keeping one subject and no tense marker (숙제하느라고 못 갔어요)",id:"chapter-68-b2",chapterId:"chapter-68",index:1},{kind:"words",title:"단어 Words 2 · 지각하다~",cards:[{kind:"guess",word:{ko:"지각하다",romanization:"jigakada",en:"to be late (for school or work)",pos:"verb",nuance:"지각하다 is Sino-Korean 지각 (遲刻, 'late-moment') + 하다, meaning specifically to arrive late to an appointed place like school, work, or a meeting — it is the institutional 'tardy', the kind a teacher or boss notes. The vital contrast is with the adjective 늦다 ('to be late' in general): 늦다 covers ANY lateness ('the bus is late', 'I'm running late', 늦어서 미안해요), whereas 지각하다 is narrowly being tardy to a fixed obligation. So 'sorry I'm late' to a friend is 늦어서 미안해요, never 지각해서; save 지각하다 for school/office tardiness. Register is neutral-formal, with a school/workplace flavor. The place you're late to takes 에 (회사에 지각하다). As a 하다 verb, the negative and potential split the noun off: 지각 안 해요, 지각 못 해요 — not 안 지각해요. The English-speaker pitfall is exactly using 지각하다 for every 'I'm late', when most casual lateness should be plain 늦다."},sentence:{ko:"알람을 못 듣는 바람에 오늘도 지각했어요.",en:"I didn't hear my alarm, so I was late again today."},target:"지각했",options:["to hurry, to rush","to be crowded, to be packed","to be late (for school or work)"],note:"지각하다 is specifically institutional lateness; 늦다 is the general word."},{kind:"guess",word:{ko:"결국",romanization:"gyeolguk",en:"in the end, finally",pos:"adverb",nuance:"결국 means 'in the end / eventually / after all' and sums up the FINAL outcome reached after a process, delay, or struggle. It is Sino-Korean, 결 (結, 'to conclude/tie up') + 국 (局, 'situation/end stage'), literally 'the concluding stage' — so it inherently looks back over a whole drawn-out affair to its settling point. The dividing line from near-synonym 드디어 is important: 드디어 celebrates a happy, long-awaited result with relief and excitement ('finally, at last!'), whereas 결국 is emotionally NEUTRAL and frequently tinged with resignation or a sense that the outcome was inevitable ('it came to this after all'). A second contrast English speakers stumble on: 결국 is NOT the 'finally/lastly' that orders items in a list — that ordinal sense ('firstly... finally...') is 마지막으로. 결국 is about how a story RESOLVED, not where an item sits in a sequence. It commonly follows a lead-in clause with -지만 or -는데 sketching the struggle, and the variant 결국엔 (with topic 은) adds extra weight to the final beat."},sentence:{ko:"계속 미루더니 결국 마감을 넘겼어요.",en:"He kept putting it off, and in the end he blew the deadline."},target:"결국",options:["in the end, finally","homework, assignment","to hurry, to rush"],note:"결국 marks the outcome of a build-up, which is why -더니 loves it."},{kind:"guess",word:{ko:"소나기",romanization:"sonagi",en:"a sudden shower, a downpour",pos:"noun",nuance:"소나기 is a pure native Korean word for a brief, intense burst of rain that arrives and departs suddenly — the classic summer-afternoon downpour. The dividing line from plain 비 is duration and character: 비 is rain in general (steady, all-day, or light), while 소나기 is specifically short-lived and abrupt, so Koreans typically wait it out under an awning rather than buy an umbrella. It contrasts too with 장맛비 (the long monsoon rains) and 이슬비 (drizzle). Natural partners are 내리다/오다, 그치다 (the proper verb for rain stopping — not 끝나다), and 만나다 ('get caught in'). The English-speaker pitfall is using 소나기 for any rain: it must be brief and sudden, and remember it takes the ordinary rain verbs 오다/내리다, with no special verb of its own."},sentence:{ko:"소나기가 갑자기 쏟아지는 바람에 빨래가 다 젖었어요.",en:"A downpour came out of nowhere, so all the laundry got soaked."},target:"소나기",options:["a sudden shower, a downpour","homework, assignment","aches and exhaustion (from overdoing it)"],note:"Weather is the purest -는 바람에 cause: sudden and entirely outside your control."},{kind:"guess",word:{ko:"재택근무",romanization:"jaetaekgeunmu",en:"working from home",pos:"noun",nuance:"재택근무 is the formal term for working from home, very commonly clipped to just 재택 in speech (오늘 재택이에요). It is fully Sino-Korean 在宅勤務, parsing as 在 'be located' + 宅 'home/residence' + 근무 'duty/work' — literally 'home-located work duty'. It exploded into daily vocabulary after COVID, so 재택근무 가능해요? is now a normal thing to ask when job hunting. The synonym field: 재택근무 (at home specifically) sits inside the broader 원격근무 (遠隔, 'remote work' from anywhere), while 외근 (off-site duty) is its near-opposite — leaving to go OUT, not staying in. The English-speaker pitfall is inventing a descriptive phrase like 집에서 근무 or 집에서 일해요 as if it were the term: those describe the activity, but the fixed noun is 재택근무. Also keep it apart from 외근 — both involve not sitting at your assigned office desk, but 재택은 home, 외근 is the field."},sentence:{ko:"지하철이 멈추는 바람에 그냥 재택근무로 바꿨어요.",en:"The subway stopped running, so I just switched to working from home."},target:"재택근무",options:["working from home","homework, assignment","a sudden shower, a downpour"],note:"The outcome here is a fallback, not a good result, so 바람에 still fits."},{kind:"guess",word:{ko:"다치다",romanization:"dachida",en:"to get hurt, to injure oneself",pos:"verb",nuance:"다치다 is the everyday verb for getting physically injured — bumps, cuts, sprains, breaks — and crucially the injured body part takes 을/를, not 이/가 (무릎을 다쳤어요, not 무릎이). Although it translates as 'to hurt', it behaves like an intransitive 'to GET hurt' aimed at yourself, so you cannot use it to mean 'I hurt someone else' — that is 다치게 하다 or 상처를 입히다. The nearest neighbor is 아프다, and the dividing line matters: 다치다 is the one-time event of getting injured (넘어져서 다쳤어요), while 아프다 is the lingering pain or sickness that follows (지금도 아파요). It pairs habitually with 크게 다치다 (badly hurt), 살짝/조금 다치다 (slightly hurt), and 다친 데 (the injured spot). At a hospital, 다치다 plus the exact body part (발목, 허리, 손목) gets you to the right department fast."},sentence:{ko:"무리해서 운동하더니 결국 무릎을 다쳤어요.",en:"He pushed too hard at the gym, and in the end he hurt his knee."},target:"다쳤",options:["to get hurt, to injure oneself","to hurry, to rush","to be crowded, to be packed"],note:"You watched the overtraining, so -더니 carries the whole build-up."},{kind:"guess",word:{ko:"쉬다",romanization:"swida",en:"to rest, to take a break",pos:"verb",nuance:"쉬다 is used for taking a break, resting, or being off work/school."},sentence:{ko:"이틀 푹 쉬었더니 몸이 훨씬 가벼워졌어요.",en:"I rested properly for two days, and my body feels much lighter."},target:"쉬었",options:["to hurry, to rush","to be crowded, to be packed","to rest, to take a break"],note:"A discovery about what worked — exactly what -았/었더니 is for."},{kind:"guess",word:{ko:"끝내다",romanization:"kkeunnaeda",en:"to finish (something)",pos:"verb",nuance:"끝내다 is the active, everyday verb for finishing or wrapping something up — you make it end. It is the transitive causative of 끝나다: the pair 끝내다 / 끝나다 is the cleanest minimal contrast in the whole 'finish' family, and getting it right is the core skill here. 끝내다 takes an object and means YOU end it (숙제를 끝냈어요 'I finished the homework'); 끝나다 is intransitive and means it ends by itself (수업이 끝났어요 'class ended'). Against 마치다, 끝내다 is the more casual, task-focused choice — perfect for daily office lines like 이것만 끝내고 갈게요 — whereas 마치다 is bookish and ceremonial. (Note 끝내다 also has a slang sense: 끝내주다 / 끝내준다 = 'awesome', literally 'it finishes you off'.) Conjugation is easy and regular: stem 끝내- gives past 끝냈어요. Habitual collocations: 일을 끝내다, 숙제를 끝내다, 빨리 끝내다, 오늘 안에 끝내다."},sentence:{ko:"밤늦게까지 보고서를 끝내느라고 한숨도 못 잤어요.",en:"I was finishing the report until late at night, so I didn't sleep at all."},target:"끝내",options:["to finish (something)","to hurry, to rush","to be crowded, to be packed"],note:"끝내다 is transitive ('finish it'); 끝나다 is what the thing itself does."},{kind:"payoff",line:{speaker:"유진",ko:"왜 이렇게 피곤해 보여요? 주말에 못 쉬었어요?",en:"Why do you look so wiped out? Didn't you get any rest this weekend?"},hl:"쉬었"}],canDo:"Blame a sudden outside cause with V-는 바람에 (엘리베이터가 고장 나는 바람에 늦었어요)",id:"chapter-68-b3",chapterId:"chapter-68",index:2},{kind:"pattern",title:"문법 Grammar · V-는 바람에",cards:[{kind:"hunt",name:"V-는 바람에",sub:"a sudden cause that derailed you",lines:[{tokens:[{pre:"앞차가",mid:"",post:"",hit:!1},{pre:"갑자기",mid:"",post:"",hit:!1},{pre:"서",mid:"는",post:"",hit:!0},{pre:"",mid:"바람에",post:"",hit:!0},{pre:"뒤에서",mid:"",post:"",hit:!1},{pre:"부딪힐",mid:"",post:"",hit:!1},{pre:"뻔했어요.",mid:"",post:"",hit:!1}],ko:"앞차가 갑자기 서는 바람에 뒤에서 부딪힐 뻔했어요.",en:"The car in front stopped suddenly, so I nearly hit it from behind.",romanization:"apchaga gapjagi seoneun barame dwieseo budichil ppeonhaesseoyo."},{tokens:[{pre:"엘리베이터가",mid:"",post:"",hit:!1},{pre:"고장",mid:"",post:"",hit:!1},{pre:"나",mid:"는",post:"",hit:!0},{pre:"",mid:"바람에",post:"",hit:!0},{pre:"십오",mid:"",post:"",hit:!1},{pre:"층까지",mid:"",post:"",hit:!1},{pre:"걸어",mid:"",post:"",hit:!1},{pre:"올라갔어요.",mid:"",post:"",hit:!1}],ko:"엘리베이터가 고장 나는 바람에 십오 층까지 걸어 올라갔어요.",en:"The lift broke down, so I walked all the way up to the fifteenth floor.",romanization:"ellibeiteoga gojang naneun barame sibo cheungkkaji georeo ollagasseoyo."}],rule:{name:"V-는 바람에",rows:[{when:"Verb stem, no 받침",add:"-는 바람에",ex:"서다 → 앞차가 갑자기 서는 바람에"},{when:"Verb stem with 받침",add:"-는 바람에",ex:"먹다 → 급하게 먹는 바람에"},{when:"ㄹ-final stem — the ㄹ drops",add:"-는 바람에",ex:"울다 → 아이가 우는 바람에"},{when:"The result clause is past and unwelcome",add:"-는 바람에 + -았/었어요",ex:"고장 나다 → 고장 나는 바람에 늦었어요"},{when:"Never an order or a proposal after it",add:"✗ -는 바람에 + -(으)세요 / -(으)ㅂ시다",ex:"늦는 바람에 서두르세요 ✗"}]},more:{func:"-는 바람에 blames something that happened TO you: abrupt, outside your control, and it wrecked the outcome. Unlike -느라고 the two clauses may have different subjects, and the second clause is almost always past tense and unwelcome. The ending stays in the -는 shape no matter when the event happened.",funcLead:"-는 바람에 blames something that happened TO you: abrupt, outside your control, and it wrecked the outcome.",keyPoint:{label:"-는 바람에 vs -느라고 — who is responsible",body:"-느라고 pins it on your own absorbing activity: 게임하느라고 못 들었어요 — you chose to play. -는 바람에 pins it on something that hit you: 엘리베이터가 고장 나는 바람에 늦었어요 — the lift broke, not you. That is also why the subjects may differ with -는 바람에 and never may with -느라고."},pronunciation:"바람에 links as [바라메], and the whole chunk runs together with no pause: 고장 나는 바람에 is [고장나는 바라메].",pitfall:{wrong:"동생이 떠드느라고 제가 잠을 못 잤어요.",right:"동생이 떠드는 바람에 제가 잠을 못 잤어요.",explanation:"-느라고 demands one subject across both clauses. Here the noisy one is 동생 and the sleepless one is 저, so -느라고 is simply ungrammatical. Whenever somebody else's action is what ruined your plan, switch to -는 바람에."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"동생이 떠드느라고 제가 잠을 못 잤어요.",ok:!1},{text:"동생이 떠드는 바람에 제가 잠을 못 잤어요.",ok:!0}],explanation:"-느라고 demands one subject across both clauses. Here the noisy one is 동생 and the sleepless one is 저, so -느라고 is simply ungrammatical. Whenever somebody else's action is what ruined your plan, switch to -는 바람에."}],canDo:"Blame a sudden outside cause with V-는 바람에 (엘리베이터가 고장 나는 바람에 늦었어요)",id:"chapter-68-b4",chapterId:"chapter-68",index:3},{kind:"words",title:"단어 Words 3 · 늦잠~",cards:[{kind:"guess",word:{ko:"늦잠",romanization:"neutjam",en:"oversleeping, a lie-in",pos:"noun"},sentence:{ko:"늦잠을 자는 바람에 첫차를 놓쳤어요.",en:"I overslept, so I missed the first train."},target:"늦잠",options:["oversleeping, a lie-in","homework, assignment","aches and exhaustion (from overdoing it)"],note:"늦잠을 자다 keeps its 을 even inside -는 바람에."},{kind:"guess",word:{ko:"정신없다",romanization:"jeongsineopda",en:"to be hectic, to be all over the place",pos:"adjective"},sentence:{ko:"이사 준비하느라고 이번 주 내내 정신이 없었어요.",en:"I was getting ready to move, so I was frazzled all week."},target:null,options:["to be hectic, to be all over the place","homework, assignment","to hurry, to rush"],note:"정신이 없다 is the most common result clause after -느라고."},{kind:"guess",word:{ko:"배탈",romanization:"baetal",en:"an upset stomach",pos:"noun"},sentence:{ko:"찬 음식을 많이 먹었더니 배탈이 났어요.",en:"I ate a lot of cold food, and I ended up with an upset stomach."},target:"배탈",options:["an upset stomach","homework, assignment","aches and exhaustion (from overdoing it)"],note:"배탈이 나다, like 몸살이 나다, uses 나다 rather than 하다."},{kind:"guess",word:{ko:"지치다",romanization:"jichida",en:"to be worn out, to be drained",pos:"verb"},sentence:{ko:"며칠 무리하더니 완전히 지쳐 보여요.",en:"He overdid it for a few days, and now he looks completely drained."},target:"지쳐",options:["to hurry, to rush","to be crowded, to be packed","to be worn out, to be drained"],note:"지치다 describes a state you can see, so it sits well in a -더니 result."},{kind:"guess",word:{ko:"취소되다",romanization:"chwisodoeda",en:"to be cancelled",pos:"verb",nuance:"취소되다 is the passive/intransitive side of 취소하다. The event, appointment, order, or reservation that no longer happens becomes the subject with 이/가: 행사가 취소됐어요, 예약이 취소됐어요. If a person actively cancels something, use 을/를 + 취소하다: 제가 예약을 취소했어요. Do not confuse cancellation with postponement: 연기되다 means it will happen later, while 취소되다 means the plan is no longer going ahead. 변경되다 means details changed but the event may still happen."},sentence:{ko:"태풍이 오는 바람에 항공편이 취소됐어요.",en:"A typhoon came in, so the flight was cancelled."},target:"취소됐",options:["to hurry, to rush","to be cancelled","to be crowded, to be packed"],note:"취소되다 is itself a passive, which is why nobody is blamed for the cancellation."},{kind:"guess",word:{ko:"고장",romanization:"gojang",en:"a breakdown, a malfunction",pos:"noun"},sentence:{ko:"엘리베이터가 고장 나는 바람에 계단으로 올라갔어요.",en:"The lift broke down, so I took the stairs up."},target:"고장",options:["homework, assignment","a breakdown, a malfunction","aches and exhaustion (from overdoing it)"],note:"고장 나다 (it breaks) and 고장 내다 (you break it) are worth keeping apart."},{kind:"payoff",line:{speaker:"지원",ko:"짐 싸느라고 못 봤어요. 그리고 오늘 아침엔 늦잠까지 자는 바람에 첫차를 놓쳤고요.",en:"I was packing, so I didn't see it. And this morning I overslept on top of that, so I missed the first train."},hl:"늦잠"}],canDo:"Report what you watched somebody else do, and its outcome, with -더니",id:"chapter-68-b5",chapterId:"chapter-68",index:4},{kind:"pattern",title:"문법 Grammar · V/A-더니",cards:[{kind:"hunt",name:"V/A-더니",sub:"what I watched happen, and what came of it",lines:[{tokens:[{pre:"아침에는",mid:"",post:"",hit:!1},{pre:"하늘이",mid:"",post:"",hit:!1},{pre:"맑",mid:"더니",post:"",hit:!0},{pre:"오후에",mid:"",post:"",hit:!1},{pre:"갑자기",mid:"",post:"",hit:!1},{pre:"소나기가",mid:"",post:"",hit:!1},{pre:"쏟아졌어요.",mid:"",post:"",hit:!1}],ko:"아침에는 하늘이 맑더니 오후에 갑자기 소나기가 쏟아졌어요.",en:"The sky was clear in the morning, and then a shower came down out of nowhere in the afternoon.",romanization:"achimeneun haneuri makdeoni ohue gapjagi sonagiga ssodajyeosseoyo."},{tokens:[{pre:"지훈",mid:"",post:"",hit:!1},{pre:"씨가",mid:"",post:"",hit:!1},{pre:"요즘",mid:"",post:"",hit:!1},{pre:"계속",mid:"",post:"",hit:!1},{pre:"야근하",mid:"더니",post:"",hit:!0},{pre:"결국",mid:"",post:"",hit:!1},{pre:"몸살이",mid:"",post:"",hit:!1},{pre:"났어요.",mid:"",post:"",hit:!1}],ko:"지훈 씨가 요즘 계속 야근하더니 결국 몸살이 났어요.",en:"Jihoon has been working late constantly, and in the end he came down with something.",romanization:"jihun ssiga yojeum gyesok yageunhadeoni gyeolguk momsari nasseoyo."}],rule:{name:"V/A-더니",rows:[{when:"Verb stem — an action you watched",add:"-더니",ex:"야근하다 → 계속 야근하더니"},{when:"Adjective stem — a state you observed",add:"-더니",ex:"맑다 → 아침에는 하늘이 맑더니"},{when:"Then versus now",add:"A/V-더니 지금은 …",ex:"춥다 → 아까는 춥더니 지금은 괜찮네요"},{when:"The subject is normally not 저/제가",add:"(for yourself, use -았/었더니)",ex:"제가 야근하더니 ✗ / 제가 야근했더니 ✓"}]},more:{func:"-더니 links something you personally observed in the past to what followed from it. Because you had to be watching, the subject is nearly always somebody or something other than yourself. It also handles then-versus-now contrast: 아까는 춥더니 지금은 괜찮네요.",funcLead:"-더니 links something you personally observed in the past to what followed from it.",keyPoint:{label:"-더니 needs a witness",body:'-더니 says "I saw this happen, and then this followed." Since you have to have been watching, the subject is almost always somebody or something else — 지훈 씨가, 하늘이, 그 가게가. You cannot stand outside yourself and watch yourself, which is exactly why Korean switches to -았/었더니 for your own actions.'},pronunciation:"The ㄷ tenses after a stop: 없더니 is [업떠니] and 맑더니 is [막떠니]. After a vowel it stays plain, as in 사더니 [사더니].",pitfall:{wrong:"제가 어제 늦게 자더니 오늘 너무 피곤해요.",right:"제가 어제 늦게 잤더니 오늘 너무 피곤해요.",explanation:`-더니 reports something you observed happening to someone else, so it clashes with a 저/제가 subject. Your own past action leading to a present result takes -았/었더니. Learners pick 더니 because English says "I stayed up late and now I'm tired" with no such distinction.`}}},{kind:"drill",prompt:"That shop had no customers for a while, and then it closed last month.",sentence:"그 가게가 한동안 손님이 없___ 지난달에 문을 닫았어요.",options:[{text:"느라고",ok:!1},{text:"아서",ok:!1},{text:"더니",ok:!0}],explanation:"The subject can be a thing, as long as you were the one observing it."},{kind:"drill",prompt:"My younger sibling bought new shoes, and now wears nothing else.",sentence:"동생이 새 신발을 사___ 매일 그것만 신고 다녀요.",options:[{text:"느라고",ok:!1},{text:"더니",ok:!0},{text:"아서",ok:!1}],explanation:"The result clause can stay in the present when the state is still going on."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"제가 어제 늦게 잤더니 오늘 너무 피곤해요.",ok:!0},{text:"제가 어제 늦게 자더니 오늘 너무 피곤해요.",ok:!1}],explanation:`-더니 reports something you observed happening to someone else, so it clashes with a 저/제가 subject. Your own past action leading to a present result takes -았/었더니. Learners pick 더니 because English says "I stayed up late and now I'm tired" with no such distinction.`}],canDo:"Report what you watched somebody else do, and its outcome, with -더니",id:"chapter-68-b6",chapterId:"chapter-68",index:5},{kind:"pattern",title:"문법 Grammar · V-았/었더니",cards:[{kind:"hunt",name:"V-았/었더니",sub:"I did it, and then I found out",lines:[{tokens:[{pre:"아침을",mid:"",post:"",hit:!1},{pre:"안",mid:"",post:"",hit:!1},{pre:"먹",mid:"었더니",post:"",hit:!0},{pre:"지금",mid:"",post:"",hit:!1},{pre:"배가",mid:"",post:"",hit:!1},{pre:"너무",mid:"",post:"",hit:!1},{pre:"고파요.",mid:"",post:"",hit:!1}],ko:"아침을 안 먹었더니 지금 배가 너무 고파요.",en:"I skipped breakfast, and now I'm starving.",romanization:"achimeul an meogeotdeoni jigeum baega neomu gopayo."},{tokens:[{pre:"오랜만에",mid:"",post:"",hit:!1},{pre:"등산했",mid:"더니",post:"",hit:!0},{pre:"다음",mid:"",post:"",hit:!1},{pre:"날",mid:"",post:"",hit:!1},{pre:"다리가",mid:"",post:"",hit:!1},{pre:"너무",mid:"",post:"",hit:!1},{pre:"아팠어요.",mid:"",post:"",hit:!1}],ko:"오랜만에 등산했더니 다음 날 다리가 너무 아팠어요.",en:"I went hiking for the first time in ages, and the next day my legs were killing me.",romanization:"oraenmane deungsanhaetdeoni daeum nal dariga neomu apasseoyo."}],rule:{name:"V-았/었더니",rows:[{when:"Your own past action (stem + 았/었)",add:"-았/었더니",ex:"먹다 → 아침을 안 먹었더니"},{when:"하다 verbs",add:"-했더니",ex:"등산하다 → 오랜만에 등산했더니"},{when:"The result may be present or past",add:"-았/었더니 + 어요 / 았어요",ex:"가다 → 일찍 갔더니 아무도 없었어요"},{when:"Contrast with -더니 (somebody else)",add:"V-더니 / V-았/었더니",ex:"지훈 씨가 야근하더니 / 제가 야근했더니"}]},more:{func:"-았/었더니 reports your own past action and the consequence you discovered from it. The first clause is normally 제가/저는, and the second clause is the result — often a small revelation rather than a plain cause and effect. Like -더니, it cannot be followed by an order or a suggestion.",funcLead:"-았/었더니 reports your own past action and the consequence you discovered from it.",keyPoint:{label:"-았/었더니 vs -아서/어서 — result or discovery",body:'아침을 안 먹어서 배가 고파요 states a cause and its effect, and everyone could have predicted it. 아침을 안 먹었더니 배가 고파요 adds that you noticed the consequence afterwards — "I skipped breakfast, and sure enough…". Use -아서/어서 when the link is obvious and -았/었더니 when you are reporting what you found out by doing it.'},pronunciation:"The ㄷ tenses after 았/었 every time: 먹었더니 is [머걷떠니], 갔더니 is [갇떠니], 했더니 is [핻떠니].",pitfall:{wrong:"약을 먹었더니 푹 쉬세요.",right:"약을 먹었더니 좀 나아졌어요.",explanation:`-았/었더니 reports a result you have already observed, so the clause after it cannot be a command or a suggestion. Learners try to give advice with it because English "once you've taken the medicine, get some rest" is fine. For advice, use -(으)면 or -고 나서 instead.`}}},{kind:"drill",prompt:"I took cold medicine, and I was fine within a day.",sentence:"감기약을 먹___ 하루 만에 괜찮아졌어요.",options:[{text:"느라고",ok:!1},{text:"었더니",ok:!0},{text:"아서",ok:!1}],explanation:"A discovery about what worked, not just a bare cause."},{kind:"drill",prompt:"I got to the office early, and there was nobody there.",sentence:"사무실에 일찍 갔___ 아무도 없었어요.",options:[{text:"느라고",ok:!1},{text:"더니",ok:!0},{text:"아서",ok:!1}],explanation:"A pure discovery: going early is what let you find that out."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"약을 먹었더니 푹 쉬세요.",ok:!1},{text:"약을 먹었더니 좀 나아졌어요.",ok:!0}],explanation:`-았/었더니 reports a result you have already observed, so the clause after it cannot be a command or a suggestion. Learners try to give advice with it because English "once you've taken the medicine, get some rest" is fine. For advice, use -(으)면 or -고 나서 instead.`}],canDo:"Report your own past action and what you discovered with -았/었더니",id:"chapter-68-b7",chapterId:"chapter-68",index:6},{kind:"pattern",title:"문법 Grammar · -느라고 vs -는 바람에 vs -아서/어서",cards:[{kind:"hunt",name:"-느라고 vs -는 바람에 vs -아서/어서",sub:'picking the right "because"',lines:[{tokens:[{pre:"발표",mid:"",post:"",hit:!1},{pre:"준비하",mid:"느라고",post:"",hit:!0},{pre:"점심도",mid:"",post:"",hit:!1},{pre:"못",mid:"",post:"",hit:!1},{pre:"먹었어요.",mid:"",post:"",hit:!1}],ko:"발표 준비하느라고 점심도 못 먹었어요.",en:"I was preparing my presentation, so I didn't even get lunch.",romanization:"balpyo junbihaneurago jeomsimdo mot meogeosseoyo."},{tokens:[{pre:"노트북이",mid:"",post:"",hit:!1},{pre:"갑자기",mid:"",post:"",hit:!1},{pre:"꺼지",mid:"는",post:"",hit:!0},{pre:"",mid:"바람에",post:"",hit:!0},{pre:"쓰던",mid:"",post:"",hit:!1},{pre:"걸",mid:"",post:"",hit:!1},{pre:"다",mid:"",post:"",hit:!1},{pre:"날렸어요.",mid:"",post:"",hit:!1}],ko:"노트북이 갑자기 꺼지는 바람에 쓰던 걸 다 날렸어요.",en:"My laptop died out of nowhere, so I lost everything I'd been writing.",romanization:"noteubugi gapjagi kkeojineun barame sseudeon geol da nallyeosseoyo."}],rule:{name:"-느라고 vs -는 바람에 vs -아서/어서",rows:[{when:"Neutral reason, any kind of result",add:"V/A-아서/어서",ex:"오다 → 눈이 많이 와서 재택근무를 했어요"},{when:"My own absorbing activity, a result that failed",add:"V-느라고",ex:"준비하다 → 발표 준비하느라고 점심도 못 먹었어요"},{when:"A sudden outside cause, a spoiled result",add:"V-는 바람에",ex:"꺼지다 → 노트북이 꺼지는 바람에 다 날렸어요"},{when:"A welcome result — credit the cause instead",add:"V/A-아서/어서, or N 덕분에",ex:"도착하다 → 일찍 도착한 덕분에 좋은 자리를 잡았어요"}]},more:{func:"All three give a reason, and they are not interchangeable. -아서/어서 is the neutral default and fits almost anywhere. -느라고 says the reason was your own time-consuming activity and the result is what you failed to do. -는 바람에 says something sudden hit you and spoiled the outcome. Choose by asking who caused it and whether the result was bad.",funcLead:"All three give a reason, and they are not interchangeable.",keyPoint:{label:"A three-question test",body:"Ask in this order. Did something fail to happen, and was the cause your own activity? → -느라고. Did something sudden happen to you and spoil it? → -는 바람에. Neither, or the result is fine? → -아서/어서, and 덕분에 when you want to credit the cause for a good outcome."},pronunciation:"-느라고 and -는 바람에 both attach to the plain stem, so nothing in front of them changes shape. Only -아서/어서 reshapes the stem: 오다 → 와서, 먹다 → 먹어서, 도착하다 → 도착해서.",pitfall:{wrong:"배가 아프느라고 학교에 못 갔어요.",right:"배가 아파서 학교에 못 갔어요.",explanation:"-느라고 only attaches to ACTION verbs, never to adjectives. 아프다 is an adjective, so a reason built on it uses -아서/어서. Learners reach for -느라고 whenever the result is negative, but a negative result is not what licenses it — a deliberate, time-consuming action is."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "I was preparing my presentation, so I didn't even get lunch."`,tokens:["발표","준비하느라고","점심도","못","먹었어요."],correct:"발표 준비하느라고 점심도 못 먹었어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"배가 아파서 학교에 못 갔어요.",ok:!0},{text:"배가 아프느라고 학교에 못 갔어요.",ok:!1}],explanation:"-느라고 only attaches to ACTION verbs, never to adjectives. 아프다 is an adjective, so a reason built on it uses -아서/어서. Learners reach for -느라고 whenever the result is negative, but a negative result is not what licenses it — a deliberate, time-consuming action is."}],canDo:"Fall back on -아서/어서 or 덕분에 when the result is actually fine",id:"chapter-68-b8",chapterId:"chapter-68",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Monday morning at the office. Two colleagues compare how their weekend and their commute went, and neither of them is having a good day.",lines:[{speaker:"유진",ko:"왜 이렇게 피곤해 보여요? 주말에 못 쉬었어요?",en:"Why do you look so wiped out? Didn't you get any rest this weekend?",romanization:"wae ireoke pigonhae boyeoyo? jumare mot swieosseoyo?"},{speaker:"지원",ko:"네. 이사 준비하느라고 주말 내내 정신이 없었어요.",en:"Right. I was getting ready to move, so I was frazzled all weekend.",romanization:"ne. isa junbihaneurago jumal naenae jeongsini eopseosseoyo."},{speaker:"유진",ko:"아, 그래서 어제 전화를 안 받으셨군요.",en:"Ah, so that's why you didn't pick up yesterday.",romanization:"a, geuraeseo eoje jeonhwareul an badeusyeotgunyo."},{speaker:"지원",ko:"짐 싸느라고 못 봤어요. 그리고 오늘 아침엔 늦잠까지 자는 바람에 첫차를 놓쳤고요.",en:"I was packing, so I didn't see it. And this morning I overslept on top of that, so I missed the first train.",romanization:"jim ssaneurago mot bwasseoyo. geurigo oneul achimen neutjamkkaji janeun barame cheotchareul notchyeotgoyo."},{speaker:"유진",ko:"저도 오늘 엘리베이터가 고장 나는 바람에 십오 층까지 걸어 올라왔어요.",en:"Same here — the lift broke down, so I walked up to the fifteenth floor.",romanization:"jeodo oneul ellibeiteoga gojang naneun barame sibo cheungkkaji georeo ollawasseoyo."},{speaker:"지원",ko:"진짜요? 그 엘리베이터가 요즘 자꾸 멈추더니 결국 고장 났네요.",en:"Really? That lift kept stopping lately, and now it's finally gone and broken.",romanization:"jinjjayo? geu ellibeiteoga yojeum jakku meomchudeoni gyeolguk gojang nanneyo."},{speaker:"유진",ko:"그러니까요. 아침부터 십오 층을 걸어 올라왔더니 다리가 후들거려요.",en:"Tell me about it. Walking up fifteen floors first thing has left my legs shaking.",romanization:"geureonikkayo. achimbuteo sibo cheungeul georeo ollawatdeoni dariga hudeulgeoryeoyo."},{speaker:"지원",ko:"점심 먹고 좀 쉬세요. 저도 커피 마셨더니 이제야 좀 살 것 같아요.",en:"Get some rest after lunch. I had a coffee, and I'm only now starting to feel human.",romanization:"jeomsim meokgo jom swiseyo. jeodo keopi masyeotdeoni ijeya jom sal geot gatayo."}]},{kind:"order",prompt:"Build: 'The lift broke down, so I walked up to the fifteenth floor.' (Start with 엘리베이터가.)",tokens:["엘리베이터가","고장 나는 바람에","십오 층까지","걸어 올라갔어요"],correct:"엘리베이터가 고장 나는 바람에 십오 층까지 걸어 올라갔어요",explanation:"The cause names its own subject (엘리베이터가) and the result clause is past — the standard -는 바람에 shape."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"짐 싸느라고 못 봤어요. 그리고 오늘 아침엔 늦잠까지 자는 바람에 첫차를 놓쳤고요.",options:[{text:"유진",ok:!1},{text:"지원",ok:!0}],explanation:"I was packing, so I didn't see it. And this morning I overslept on top of that, so I missed the first train."},{kind:"drill",prompt:'무엇이 들어갈까요? · "Same here — the lift broke down, so I walked up to the fifteenth floor."',sentence:"저도 오늘 엘리베이터가 ___ 나는 바람에 십오 층까지 걸어 올라왔어요.",options:[{text:"숙제",ok:!1},{text:"고장",ok:!0},{text:"몸살",ok:!1}],explanation:""}],canDo:"Excuse a failure with V-느라고 while keeping one subject and no tense marker (숙제하느라고 못 갔어요)",id:"chapter-68-b9",chapterId:"chapter-68",index:8},{kind:"reading",title:"읽기 Reading · 핑계와 원인 사이",cards:[{kind:"read",title:"핑계와 원인 사이",chunks:["한국어에는 '왜'를 말하는 방법이 여러 가지다. 그중에서 -느라고와 -는 바람에가 자주 헷갈린다. -느라고는 내가 무언가에 매달려 있어서 다른 일을 못 했을 때 쓴다. 그래서 두 문장의 주어가 같아야 하고, 뒤에는 보통 '못 했다'가 온다.","-는 바람에는 반대로 갑자기 벌어진 일이 내 계획을 망쳤을 때 쓴다. 주어가 달라도 되고, 결과는 대개 나쁘다. -더니와 -았더니는 순서를 말한다. 남이 하는 일을 지켜보고 그 결과를 말할 때는 -더니, 내가 한 일과 그 결과를 말할 때는 -았더니를 쓴다."],translation:`Korean has several ways of saying "why." Among them, -느라고 and -는 바람에 get mixed up constantly. -느라고 is for when you were tied up in something and therefore failed to do something else. That is why both clauses have to share a subject, and why what follows is usually "couldn't." -는 바람에 is the opposite: something that happened out of nowhere wrecked your plan. The subjects may differ, and the result is generally bad. -더니 and -았더니 are about sequence. When you watched somebody else do something and are reporting what came of it, you use -더니; when it was your own action and your own result, you use -았더니.`,qas:[{q:"-느라고를 쓰려면 두 문장의 주어가 어때야 해요?",a:"같아야 해요. 주어가 다르면 -는 바람에를 써요."},{q:"-는 바람에 뒤에는 보통 어떤 결과가 와요?",a:"갑자기 벌어진 일 때문에 생긴 나쁜 결과가 와요."},{q:"내가 한 일과 그 결과를 말할 때는 무엇을 써요?",a:"-았/었더니를 써요. 남이 하는 일을 지켜본 경우에는 -더니를 써요."}]},{kind:"order",prompt:"지문 문장을 다시 조립하세요 · Rebuild a line from the passage (한국어에는 시작 · Start with 한국어에는.)",tokens:["한국어에는","'왜'를","말하는","방법이","여러","가지다."],correct:"한국어에는 '왜'를 말하는 방법이 여러 가지다.",explanation:""}],canDo:"Blame a sudden outside cause with V-는 바람에 (엘리베이터가 고장 나는 바람에 늦었어요)",id:"chapter-68-b10",chapterId:"chapter-68",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence is correct Korean?",sentence:null,options:[{text:"보고서를 쓰느라고 한숨도 못 잤어요.",ok:!0},{text:"보고서를 썼느라고 한숨도 못 잤어요.",ok:!1},{text:"보고서를 쓰느라고 한숨도 못 자세요.",ok:!1}],explanation:"-느라고 never carries a tense marker, so 썼느라고 is out; the tense belongs in the final clause. And the clause after -느라고 cannot be a command, which rules out 못 자세요."},{kind:"drill",prompt:"동생이 떠들었어요. 그래서 제가 잠을 못 잤어요. Which connector fits?",sentence:null,options:[{text:"떠드는 바람에",ok:!0},{text:"떠드느라고",ok:!1},{text:"떠들었느라고",ok:!1}],explanation:"-느라고 requires both clauses to share one subject. Here 동생 makes the noise and 저 loses the sleep, so only -는 바람에 works."},{kind:"drill",prompt:"Which one can follow 제가 (a first-person subject)?",sentence:null,options:[{text:"어제 늦게 잤더니",ok:!0},{text:"어제 늦게 자더니",ok:!1},{text:"어제 늦게 잤느라고",ok:!1}],explanation:"-더니 reports what you watched somebody else do, so it clashes with 제가. Your own past action leading to a present result takes -았/었더니, and -느라고 never carries a tense marker."},{kind:"drill",prompt:"You want to report what you watched happen to 지훈 씨. Which is natural?",sentence:null,options:[{text:"지훈 씨가 계속 야근하더니 몸살이 났어요.",ok:!0},{text:"지훈 씨가 계속 야근했더니 몸살이 났어요.",ok:!1},{text:"제가 계속 야근하더니 몸살이 났어요.",ok:!1}],explanation:"-더니 needs a subject you observed from the outside, so 지훈 씨가 …하더니 is right. -았/었더니 belongs to your own action (제가 야근했더니), and 제가 …하더니 mixes the two."},{kind:"drill",prompt:"늦잠___ 자는 바람에 첫차를 놓쳤어요. (I overslept, so I missed the first train.)",sentence:null,options:[{text:"을",ok:!0},{text:"이",ok:!1},{text:"에",ok:!1}],explanation:"늦잠을 자다 is a fixed phrase, and the object particle stays put inside -는 바람에."},{kind:"drill",prompt:"Which ending fits a welcome result: '일찍 도착___ 좋은 자리를 잡았어요'?",sentence:null,options:[{text:"해서",ok:!0},{text:"하느라고",ok:!1},{text:"하는 바람에",ok:!1}],explanation:"-느라고 and -는 바람에 both point at something that went wrong. A good outcome takes plain -아서/어서, or 덕분에 if you want to credit the cause."}],canDo:"Report what you watched somebody else do, and its outcome, with -더니",id:"chapter-68-b11",chapterId:"chapter-68",index:10}]},{id:"chapter-69",number:69,title:"V-아/어 버리다 · V-고 말다",goal:"Carry an action right through with V-아/어 버리다 and hear whether it lands as relief or as regret.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 버리다~",cards:[{kind:"guess",word:{ko:"버리다",romanization:"beorida",en:"to throw away; (auxiliary) to do completely",pos:"verb",nuance:"버리다 means to discard something as no longer wanted — to throw it out as trash or to abandon it. Don't confuse it with 던지다, which is to throw an object through the air toward a target (공을 던지다 'throw a ball'); 버리다 is about getting rid of, not about the flying motion. A second hugely important use is as an auxiliary verb -아/어 버리다, which colors the main verb with 'completely' or 'regrettably/finally': 잊어버리다 'forget (clean out of mind)', 가 버리다 '(someone) just left'. So a learner must read context: 버려요 alone = throw away, but 먹어 버려요 = eat it all up. The English-speaker pitfall is reaching for 던지다 whenever they see 'throw' — but 'throw away/out' in the disposal sense is always 버리다. Also note Korea's strict 분리수거 (recycling separation) culture, so 버리다 in daily life often pairs with sorting."},sentence:{ko:"옛날 사진을 다 지워 버렸어요.",en:"I deleted all the old photos."},target:"버렸",options:["to endure, to hold back","to throw away; (auxiliary) to do completely","to cry"],note:"As an auxiliary, -아/어 버리다 means the action went right through to the end."},{kind:"guess",word:{ko:"참다",romanization:"chamda",en:"to endure, to hold back",pos:"verb",nuance:"참다 is a native verb meaning to ENDURE, BEAR, or HOLD BACK — both physical discomfort (아픔을 참다 'endure pain') and inner urges you suppress (화를 참다 'hold back anger', 눈물을 참다 'hold back tears', 웃음을 참다 'stifle a laugh'). The stem ends in ㅁ, so it is a REGULAR verb: add 아 → 참아요, past 참았어요 — never 참어요 (the bright ㅏ vowel governs the ending). Contrast it with 견디다, which is to withstand a prolonged hardship or pressure over time (고통을 견디다 'endure suffering', 더위를 견디다 'bear the heat'); 참다 leans toward actively restraining a momentary impulse, while 견디다 leans toward holding up under sustained strain. 참다 carries cultural weight — patience and self-restraint (참을성) are prized virtues. Pitfall: choose 참아요 not 참어요, and for an ongoing battle against hardship 견디다 often fits better than 참다."},sentence:{ko:"끝까지 참다가 결국 울고 말았어요.",en:"I held out to the very end, and then broke down anyway."},target:"참다",options:["to throw away; (auxiliary) to do completely","to endure, to hold back","to forget (completely)"],note:"참다 supplies exactly the resistance that -고 말다 requires."},{kind:"guess",word:{ko:"하마터면",romanization:"hamateomyeon",en:"very nearly, by a hair",pos:"adverb",nuance:"하마터면 is dramatic but natural when the speaker feels relieved that the event did not happen."},sentence:{ko:"하마터면 여권을 두고 공항에 갈 뻔했어요.",en:"I very nearly went to the airport without my passport."},target:"하마터면",options:["to throw away; (auxiliary) to do completely","to endure, to hold back","very nearly, by a hair"],note:"하마터면 almost always goes first and demands -(으)ㄹ 뻔했어요 at the end."},{kind:"guess",word:{ko:"아쉽다",romanization:"aswipda",en:"to feel it's a shame, to feel a pang of regret",pos:"adjective",nuance:"아쉽다 is mild, wistful regret — 'that's a shame / I wish it were otherwise' — the feeling when something nice didn't happen, ended too soon, or fell just short. It's soft; it's NOT deep sadness. The variant ladder: 아쉽다/아쉬워 (casual) → 아쉬워요 (polite) → 아쉽네(요) (in-the-moment reaction to news) → 좀 아쉽다 (softened, noting a small lack). Note the conjugation: 아쉽다 is a -ㅂ irregular adjective, so the polite stem is 아쉬워요 (아쉽+어요 → 아쉬워요), never 아쉽어요. The dividing line against 슬프다 and 속상하다: 아쉽다 is a gentle 'aw, too bad' about a missed chance or something pleasant ending; 슬프다 is real sadness (loss, grief); 속상하다 is being genuinely hurt or upset inside (frustration, heartache). Sold-out tickets → 아쉽다; a pet dying → 슬프다; your work criticized unfairly → 속상하다. 아쉽다 also covers the sense of 'feeling a lack / something's missing' (뭔가 아쉽다 'something feels lacking'), so context decides. The English-speaker pitfall is reaching for 슬프다 for everyday letdowns — to a Korean ear that's melodramatic."},sentence:{ko:"다 끝내 버리고 나니까 시원하면서도 좀 아쉬워요.",en:"Now that I've finished it all off, I feel relieved but also a little wistful."},target:"아쉬워",options:["to throw away; (auxiliary) to do completely","to feel it's a shame, to feel a pang of regret","to endure, to hold back"],note:"아쉽다 is the mild regret that often trails -아/어 버리다."},{kind:"guess",word:{ko:"잊어버리다",romanization:"ijeobeorida",en:"to forget (completely)",pos:"verb",nuance:"잊어버리다 is the native compound 잊다 ('forget') + -어 버리다 (the auxiliary 버리다, 'throw away / do completely'), so it means to forget thoroughly, with the nuance that the memory is gone for good — often tinged with regret ('darn, it's gone'). Plain 잊다 states the bare fact of forgetting; 잊어버리다 adds finality and emotional color, which is why everyday speech overwhelmingly uses 잊어버리다. The object takes 을/를. Conjugation: the 리 stem contracts with 어 to 려, hence 잊어버려요 / 잊어버렸어요. The most dangerous English-speaker pitfall is the near-twin 잃어버리다 ('to lose a physical object'): 잊다 (forget, from the mind) vs 잃다 (lose, from your possession) differ by one jamo and one meaning — you 잊어버리다 a name but 잃어버리다 your wallet. Mixing them is the classic learner error. Also note: to tell someone 'don't forget', say 잊어버리지 마세요 or just 잊지 마세요; and writing the uncontracted 잊어버리었어요 is wrong — it must be 잊어버렸어요."},sentence:{ko:"하마터면 약속을 잊어버릴 뻔했어요.",en:"I very nearly forgot our plans."},target:"잊어버릴",options:["to forget (completely)","to endure, to hold back","to cry"],note:"One of the lexicalized 버리다 verbs — written as a single word."},{kind:"guess",word:{ko:"울다",romanization:"ulda",en:"to cry",pos:"verb",nuance:"울다 means to cry and is a ㄹ irregular verb: the stem ㄹ drops before endings starting with ㅂ, ㄴ, or ㅅ, so the formal present is 웁니다 (not 울습니다) and the honorific is 우세요; before a plain vowel the ㄹ stays, giving 울어요 and 울었어요, and the future keeps it too in 울 거예요. The crier is the subject and takes 이/가 (아기가 울어요), unlike English where 'cry' can feel transitive. Its natural opposite is 웃다 (laugh), and its near-synonyms split by intensity and register: 눈물을 흘리다 ('shed tears', literally, more composed/quiet) describes tears running down without sobbing, while 흐느끼다 ('to sob') is heavier and more literary; plain 울다 is the everyday all-purpose word, often boosted by mimetics like 펑펑 울다 (bawl) or 엉엉 울다. Note 울다 also describes animals making their cry/call (새가 울다 = a bird sings/cries) and even a phone or alarm 'ringing/sounding'. The English-speaker pitfall is the conjugation — writing 울습니다 by habit when the ㄹ must drop to 웁니다 — plus confusing 울다 with 웃다, which differ by a single jamo."},sentence:{ko:"영화가 너무 슬퍼서 참다가 울고 말았어요.",en:"The film was so sad that I held out and then cried anyway."},target:"울고",options:["to throw away; (auxiliary) to do completely","to endure, to hold back","to cry"],note:"울고 말다 is one of the most frequent pairings of this ending."},{kind:"guess",word:{ko:"모르다",romanization:"moreuda",en:"to not know",pos:"verb",nuance:"모르다 is the standalone verb 'to not know / be unaware of', the lexical opposite of 알다, and it likewise takes the object marker 을/를: 길을 몰라요. It is a 르-irregular: when an 아/어 ending attaches, the 르 stem doubles the ㄹ and the vowel drops, so 모르 + 아요 → 몰라요 (never 모르아요) and the past is 몰랐어요. The crucial register tool is 겠: 잘 모르겠어요 ('I'm not quite sure') is markedly softer and more natural than a blunt 몰라요, which can sound curt or even dismissive depending on tone, so Koreans lean on the 겠 form constantly when admitting ignorance politely. Compare 모르다 with 헷갈리다 ('to be confused / mix things up'): 모르다 is having no information at all, while 헷갈리다 is having information but getting it tangled. The English-speaker pitfall is the conjugation — applying a regular pattern to get 모르아요 instead of the irregular 몰라요 — and forgetting that the smooth, courteous version is 잘 모르겠어요."},sentence:{ko:"다 알면서 모르는 척하지 마세요.",en:"Don't act clueless when you know perfectly well."},target:"모르",options:["to throw away; (auxiliary) to do completely","to endure, to hold back","to not know"],note:"모르는 척하다 also means deliberately ignoring somebody you recognise."},{kind:"payoff",line:{speaker:"지원",ko:"잘했어요. 오늘은 밀린 일 다 끝내 버리고 일찍 들어가세요.",en:"Good. Today, get all your backlog done and dusted and go home early."},hl:"버리"}],canDo:"Carry an action right through with V-아/어 버리다, and hear whether it lands as relief or as regret",id:"chapter-69-b1",chapterId:"chapter-69",index:0},{kind:"pattern",title:"문법 Grammar · V-아/어 버리다",cards:[{kind:"teach",name:"V-아/어 버리다",sub:"finish it off, for better or worse",rows:[{when:"Stem ends in ㅏ/ㅗ",add:"-아 버리다",ex:"팔다 → 팔아 버리다 (to sell it off)"},{when:"Stem ends in any other vowel",add:"-어 버리다",ex:"쓰다 → 써 버리다 (to use it all up)"},{when:"하다 verbs",add:"-해 버리다",ex:"말하다 → 말해 버리다 (to just come out and say it)"},{when:"Lexicalized — written as one word",add:"잊어버리다 / 잃어버리다",ex:"잊다 → 약속을 잊어버렸어요"}],examples:[{ko:"고민하다가 그냥 다 말해 버렸어요.",en:"I agonised over it and then just came out with the whole thing.",romanization:"gominhadaga geunyang da malhae beoryeosseoyo.",note:"그냥 is the giveaway for the impulsive version — you stopped holding back."},{ko:"지훈 씨가 인사도 없이 가 버렸어요.",en:"Jihoon left without so much as a goodbye.",romanization:"jihun ssiga insado eopsi ga beoryeosseoyo.",note:"가 버리다 adds the sting of finality: he's gone, and that's that."}],more:{func:'버리다 on its own means "to throw away." As an auxiliary after the -아/어 form it means the action was carried all the way through, with nothing left over — and it always leaves an emotional trace. Finish a burden and it feels like relief; use up something you wanted to keep and it feels like loss.',funcLead:'버리다 on its own means "to throw away." As an auxiliary after the -아/어 form it means the action was carried all the way through, with nothing left over — and it…',keyPoint:{label:"Relief or regret — what got used up decides",body:'-아/어 버리다 always means "and it is completely done." The feeling comes from the object, not the ending. Finish a burden and it is relief (다 끝내 버렸어요); finish something you wanted to keep and it is regret (다 써 버렸어요). Korean adds 그냥 for the impulsive reading and 다 for the exhaustive one.'},pronunciation:"버리다 contracts hard in speech: 해 버렸어요 comes out as [해버려써요] with no gap, and 팔아 버렸어요 as [파라버려써요] with the ㄹ linking through.",pitfall:{wrong:"월급을 다 쓰다 버렸어요.",right:"월급을 다 써 버렸어요.",explanation:'버리다 is an auxiliary, so it attaches to the -아/어 form, never to the dictionary form. 쓰다 becomes 써, giving 써 버렸어요. Learners leave the base verb intact because English "spend it all" does not reshape the verb at all.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I agonised over it and then just came out with the whole thing."',tokens:["고민하다가","그냥","다","말해","버렸어요."],correct:"고민하다가 그냥 다 말해 버렸어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Jihoon left without so much as a goodbye."',tokens:["지훈","씨가","인사도","없이","가","버렸어요."],correct:"지훈 씨가 인사도 없이 가 버렸어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"월급을 다 쓰다 버렸어요.",ok:!1},{text:"월급을 다 써 버렸어요.",ok:!0}],explanation:'버리다 is an auxiliary, so it attaches to the -아/어 form, never to the dictionary form. 쓰다 becomes 써, giving 써 버렸어요. Learners leave the base verb intact because English "spend it all" does not reshape the verb at all.'}],canDo:"Carry an action right through with V-아/어 버리다, and hear whether it lands as relief or as regret",id:"chapter-69-b2",chapterId:"chapter-69",index:1},{kind:"words",title:"단어 Words 2 · 자다~",cards:[{kind:"guess",word:{ko:"자다",romanization:"jada",en:"to sleep",pos:"verb",nuance:"자다 becomes 잘 before some future or ability forms: 잘 거예요, 잘 수 있어요."},sentence:{ko:"동생은 눈을 감고 자는 척하고 있었어요.",en:"My sibling had their eyes shut, pretending to be asleep."},target:"자는",options:["to throw away; (auxiliary) to do completely","to sleep","to endure, to hold back"],note:"A verb in progress, so it takes -는 척하다 rather than -(으)ㄴ."},{kind:"guess",word:{ko:"깨지다",romanization:"kkaejida",en:"to break, to get broken",pos:"verb",nuance:"깨지다 is the verb for hard, brittle things shattering or cracking — glass, dishes, phone screens, eggs — and the key is matching the verb to the material: it contrasts with 부러지다 (long, rigid things snapping: 팔이/연필이 부러지다) and 찢어지다 (paper or fabric tearing: 종이가/옷이 찢어지다). Figuratively it covers promises, deals, records, and moods 'breaking' (약속이/기록이/분위기가 깨지다), and in casual speech 둘이 깨졌어 means a couple split up. It's intransitive (the broken thing takes 이/가); to smash something yourself, use the transitive 깨다 (컵을 깼어요 = I broke the cup) — note the e/ae spelling difference, 깨다 vs 깨지다. The 요-form is 깨져요 (지 + 어 → 져). English speakers habitually say 'I broke the glass' with the intransitive form; you must use 깨다 when there's an agent."},sentence:{ko:"조심했는데도 컵이 깨지고 말았어요.",en:"I was careful, and the cup still ended up broken."},target:"깨지",options:["to throw away; (auxiliary) to do completely","to endure, to hold back","to break, to get broken"],note:"깨지다 takes 이/가 (it breaks); the transitive 깨다 takes 을/를."},{kind:"guess",word:{ko:"후회하다",romanization:"huhoehada",en:"to regret",pos:"verb",nuance:"후회하다 is Sino-Korean — 後悔 literally stacks 後 'after' + 悔 'regret/remorse', i.e. the regret that comes AFTER the deed — and names the painful wish that you had chosen differently. It typically points backward (그 결정을 후회해요 'I regret that decision') and frequently pairs with a reason clause in -아서/어서 or with a past-action nominalizer -(으)ㄴ 걸: 그렇게 말한 걸 후회해. Distinguish it from 아쉽다, which is a milder 'it's a shame / I wish it were a bit different' about things often outside your control, whereas 후회하다 carries genuine self-reproach over your own past action. Also separate it from 미안하다 ('to be sorry' TO someone) — 후회하다 is regret felt inside, not an apology directed at another person. Pitfall: 'I regret to inform you' has no 후회하다 equivalent; that polite-letter formula becomes 안타깝게도 or 죄송하지만. Keep the object with 를, and remember the negative splits as 후회 안 해요."},sentence:{ko:"화가 나서 다 말해 버렸는데 지금은 후회해요.",en:"I was angry and blurted it all out, and now I regret it."},target:"후회해",options:["to throw away; (auxiliary) to do completely","to regret","to endure, to hold back"],note:"The regret reading of -아/어 버리다 often gets spelled out this way."},{kind:"guess",word:{ko:"다치다",romanization:"dachida",en:"to get hurt, to injure oneself",pos:"verb",nuance:"다치다 is the everyday verb for getting physically injured — bumps, cuts, sprains, breaks — and crucially the injured body part takes 을/를, not 이/가 (무릎을 다쳤어요, not 무릎이). Although it translates as 'to hurt', it behaves like an intransitive 'to GET hurt' aimed at yourself, so you cannot use it to mean 'I hurt someone else' — that is 다치게 하다 or 상처를 입히다. The nearest neighbor is 아프다, and the dividing line matters: 다치다 is the one-time event of getting injured (넘어져서 다쳤어요), while 아프다 is the lingering pain or sickness that follows (지금도 아파요). It pairs habitually with 크게 다치다 (badly hurt), 살짝/조금 다치다 (slightly hurt), and 다친 데 (the injured spot). At a hospital, 다치다 plus the exact body part (발목, 허리, 손목) gets you to the right department fast."},sentence:{ko:"빙판길에서 미끄러져서 크게 다칠 뻔했어요.",en:"I slipped on the icy path and nearly hurt myself badly."},target:"다칠",options:["to get hurt, to injure oneself","to throw away; (auxiliary) to do completely","to endure, to hold back"],note:"Injuries are the most common thing to almost happen."},{kind:"guess",word:{ko:"포기하다",romanization:"pogihada",en:"to give up",pos:"verb",nuance:"포기하다 = to give up, abandon, or relinquish a goal, plan, claim, or even a person. The hanja 抛棄 is vivid: 抛 'to throw/hurl away' + 棄 'to discard, abandon', so the image is hurling something aside and walking off — a decisive letting-go, not a gentle fade. Contrast 포기하다 (stop pursuing a goal entirely) with 그만두다 (stop/quit an ongoing activity — a job, a habit) and with 단념하다 (a more bookish 'resign oneself to abandoning hope'); in speech 포기하다 is the everyday choice. Grammar: it pairs with 을/를 (목표를 포기하다) or with 는 거 / 는 걸 (사는 걸 포기하다 = 'give up on buying'). Culturally the word is loaded: N포세대, the 'give-up generation', names young Koreans said to have surrendered dating, marriage, and kids to economic pressure. English-speaker pitfall: the negative is 포기 안 해 / 포기 못 해 (noun + 안/못 + 해), NOT 안 포기해."},sentence:{ko:"여기까지 왔는데 지금 포기해 버리면 너무 아깝잖아요.",en:"It'd be such a waste to just give up now after coming this far."},target:"포기해",options:["to throw away; (auxiliary) to do completely","to endure, to hold back","to give up"],note:"-아/어 버리다 makes giving up sound abrupt and final."},{kind:"guess",word:{ko:"화내다",romanization:"hwanaeda",en:"to get angry, to lose one's temper",pos:"verb",nuance:"화내다 literally combines 화 (火, Sino-Korean 'fire' = anger) + 내다 ('to put out, let out'), so it pictures LETTING THE FIRE OUT — to OUTWARDLY SHOW or express anger (raising your voice, scolding). The essential contrast is with 화나다 (화 + 나다 'to arise'): 화나다 is the anger RISING inside you, an involuntary feeling ('I'm angry / I got mad', 화났어요), while 화내다 is the active VENTING of it toward someone ('he got angry at me', 나한테 화냈어요). So 화났어요 = 'I feel angry' (inner state), but 화냈어요 = 'I lashed out' (outward act). The target of 화내다 takes 한테/에게 (나한테 화내다), and the trigger takes 에 (작은 일에 화내다). Pitfall: English 'I'm angry' is the feeling — use 화났어요, NOT 화냈어요, which would mean you displayed anger at someone. Keep 내다 (let out) and 나다 (arise) straight; one letter flips agent vs experiencer."},sentence:{ko:"참으려고 했는데 회의에서 결국 화를 내고 말았어요.",en:"I tried to hold back, but in the end I lost my temper in the meeting."},target:null,options:["to throw away; (auxiliary) to do completely","to get angry, to lose one's temper","to endure, to hold back"],note:"화를 내다 splits into 화 + 를 + 내다 inside a sentence."},{kind:"guess",word:{ko:"미끄러지다",romanization:"mikkeureojida",en:"to slip, to slide",pos:"verb",nuance:"미끄러지다 is the VERB 'to slip / slide / lose footing', describing the motion of your foot or body sliding on a slick surface. Its single most important confusion is with the look-alike ADJECTIVE 미끄럽다 ('to be slippery'): the surface IS 미끄럽다 (길이 미끄러워요 — a state, ㅂ-irregular), but a person DOES 미끄러지다 (제가 미끄러졌어요 — an event). Mixing the two is the number-one English-speaker error here. Keep it apart from 넘어지다 too: 미끄러지다 is the slide itself, 넘어지다 is hitting the ground, and they chain naturally — 미끄러져서 넘어졌어요. The slippery place takes 에서. Register is plain. Useful collocations: 발이 미끄러지다 (foot slips), 차가 미끄러지다 (a car skids), 미끄럼 주의 (the 'caution: slippery' floor sign, using the noun 미끄럼). The verb itself is regular (미끄러지다 → 미끄러져요), but its adjective cousin 미끄럽다 is ㅂ-irregular (미끄러워요), so don't carry the irregularity over."},sentence:{ko:"계단에서 미끄러져서 넘어질 뻔했어요.",en:"I slipped on the stairs and nearly went down."},target:"미끄러져",options:["to throw away; (auxiliary) to do completely","to slip, to slide","to endure, to hold back"],note:"The slip is real; only what follows it is the near miss."},{kind:"payoff",line:{speaker:"유진",ko:"네. 오늘은 무슨 일이 있어도 일찍 자고 말겠어요.",en:"Okay. Tonight I'm getting to bed early no matter what happens."},hl:"자고"}],canDo:"Report an outcome that beat you with V-고 말다, and flip it to resolve with -고 말겠어요",id:"chapter-69-b3",chapterId:"chapter-69",index:2},{kind:"pattern",title:"문법 Grammar · V-고 말다",cards:[{kind:"teach",name:"V-고 말다",sub:"it ended up happening after all",rows:[{when:"Verb stem + 고 말다, usually past",add:"-고 말았어요",ex:"울다 → 울고 말았어요 (I ended up in tears)"},{when:"With 결국 for the build-up",add:"결국 V-고 말았어요",ex:"포기하다 → 결국 포기하고 말았어요"},{when:"Future — determination, not regret",add:"-고 말겠어요",ex:"따다 → 자격증을 따고 말겠어요"},{when:"Casual past",add:"-고 말았어 / -고 말았다",ex:"깨다 → 컵을 깨고 말았어"}],examples:[{ko:"참으려고 했는데 결국 울고 말았어요.",en:"I tried to hold it in, but in the end I broke down.",romanization:"chameuryeogo haenneunde gyeolguk ulgo marasseoyo.",note:"참으려고 했는데 supplies the resistance that -고 말다 needs."},{ko:"조심했는데도 컵을 깨고 말았어요.",en:"I was careful, and I still went and broke the cup.",romanization:"josimhaenneundedo keobeul kkaego marasseoyo.",note:'-는데도 ("even though") is a natural lead-in for this ending.'}],more:{func:"-고 말다 reports an outcome that arrived DESPITE what you wanted or what you tried. It nearly always appears in the past as -고 말았어요, and it carries resignation or regret — never relief. In the future, -고 말겠어요 flips to fierce determination: it WILL happen, whatever stands in the way.",funcLead:"-고 말다 reports an outcome that arrived DESPITE what you wanted or what you tried.",keyPoint:{label:"-고 말다 needs something you were resisting",body:"-고 말다 only works when the outcome went against your effort or your wish. 참으려고 했는데 울고 말았어요 makes sense because you were fighting it. An ordinary action cannot take it: 점심을 먹고 말았어요 sounds absurd unless lunch was somehow a defeat. If nothing was being resisted, plain past tense is all you need."},pronunciation:"말았어요 links as [마라써요]. In casual speech it shortens to 말았어 [마라써], and the future 말겠어요 tenses to [말게써요].",pitfall:{wrong:"어제 점심을 먹고 말았어요.",right:"어제 점심을 먹었어요.",explanation:'-고 말다 marks an outcome you were trying to avoid, so an ordinary action cannot carry it. Learners use it as a general-purpose "ended up" because that is how the English gloss reads. When nothing was being resisted, plain past tense is the whole answer.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I tried to hold it in, but in the end I broke down."',tokens:["참으려고","했는데","결국","울고","말았어요."],correct:"참으려고 했는데 결국 울고 말았어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I was careful, and I still went and broke the cup."',tokens:["조심했는데도","컵을","깨고","말았어요."],correct:"조심했는데도 컵을 깨고 말았어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"어제 점심을 먹고 말았어요.",ok:!1},{text:"어제 점심을 먹었어요.",ok:!0}],explanation:'-고 말다 marks an outcome you were trying to avoid, so an ordinary action cannot carry it. Learners use it as a general-purpose "ended up" because that is how the English gloss reads. When nothing was being resisted, plain past tense is the whole answer.'}],canDo:"Report an outcome that beat you with V-고 말다, and flip it to resolve with -고 말겠어요",id:"chapter-69-b4",chapterId:"chapter-69",index:3},{kind:"words",title:"단어 Words 3 · 후련하다~",cards:[{kind:"guess",word:{ko:"후련하다",romanization:"huryeonhada",en:"to feel relieved, to feel unburdened",pos:"adjective",nuance:"후련하다 names the clean, lightened sensation right after a burden or pent-up stress is released — finishing exams, finally venting, crying it out. Its near-synonym is 시원하다: 시원하다 is the broader word that also covers physical coolness (시원한 바람, a cool breeze) and refreshing drinks, while 후련하다 is reserved almost entirely for emotional/internal release, so '속이 후련하다' and '속이 시원하다' overlap but 바람이 후련하다 is wrong. It is NOT general happiness (기쁘다/행복하다) — it strictly presupposes something heavy was weighing on you and is now gone. As a 하다-adjective it conjugates 후련해요 / 후련했어요 / 후련해서, and it collocates above all with 속이, 가슴이, and the adverb 후련하게. English-speaker pitfall: learners reach for it as a synonym of 'happy', but if there was no preceding pressure to discharge, a Korean ear hears it as odd — 'I'm 후련해' out of plain good cheer sounds like a non sequitur."},sentence:{ko:"밀린 일을 다 끝내 버리니까 정말 후련해요.",en:"Now that I've finished off all the backlog, I feel genuinely unburdened."},target:"후련해",options:["to throw away; (auxiliary) to do completely","to feel relieved, to feel unburdened","to endure, to hold back"],note:"후련하다 is the feeling that marks the relief reading of -아/어 버리다."},{kind:"guess",word:{ko:"들키다",romanization:"deulkida",en:"to be caught out, to be found out",pos:"verb"},sentence:{ko:"자는 척하다가 결국 들키고 말았어요.",en:"I was pretending to be asleep, and in the end I got caught."},target:"들키",options:["to be caught out, to be found out","to throw away; (auxiliary) to do completely","to endure, to hold back"],note:"들키다 is itself a passive-shaped verb — you are the one found out."},{kind:"guess",word:{ko:"잃어버리다",romanization:"ireobeorida",en:"to lose (an object)",pos:"verb"},sentence:{ko:"하마터면 여권을 잃어버릴 뻔했어요.",en:"I very nearly lost my passport."},target:"잃어버릴",options:["to lose (an object)","to throw away; (auxiliary) to do completely","to endure, to hold back"],note:"Another lexicalized 버리다 verb; 잊어버리다 is for facts, 잃어버리다 for things."},{kind:"guess",word:{ko:"실수하다",romanization:"silsuhada",en:"to make a mistake, to slip up",pos:"verb"},sentence:{ko:"안 그러려고 했는데 또 실수하고 말았어요.",en:"I meant not to, and I went and slipped up again."},target:"실수하",options:["to make a mistake, to slip up","to throw away; (auxiliary) to do completely","to endure, to hold back"],note:"안 그러려고 했는데 is the standard lead-in for a -고 말다 confession."},{kind:"guess",word:{ko:"부딪히다",romanization:"budichida",en:"to bump into, to collide with",pos:"verb"},sentence:{ko:"앞차가 급정거하는 바람에 부딪힐 뻔했어요.",en:"The car in front braked hard, and I nearly hit it."},target:"부딪힐",options:["to bump into, to collide with","to throw away; (auxiliary) to do completely","to endure, to hold back"],note:"부딪히다 is the passive of 부딪다 — the collision happens to you."},{kind:"guess",word:{ko:"숨기다",romanization:"sumgida",en:"to hide (something), to keep something from someone",pos:"verb"},sentence:{ko:"숨기려고 했는데 표정에서 다 드러나 버렸어요.",en:"I meant to hide it, but my face gave the whole thing away."},target:"숨기",options:["to hide (something), to keep something from someone","to throw away; (auxiliary) to do completely","to endure, to hold back"],note:"숨기다 is the causative-shaped partner of 숨다 (to hide oneself)."},{kind:"payoff",line:{speaker:"유진",ko:"말하면 걱정하실까 봐 숨기려고 했는데, 결국 말하고 말았네요.",en:"I wanted to keep it from you in case you worried, but in the end it came out anyway."},hl:"숨기"}],canDo:"Describe a near miss with 하마터면 …-(으)ㄹ 뻔했어요, always in the past",id:"chapter-69-b5",chapterId:"chapter-69",index:4},{kind:"pattern",title:"문법 Grammar · V-(으)ㄹ 뻔했다",cards:[{kind:"teach",name:"V-(으)ㄹ 뻔했다",sub:"the thing that almost happened",rows:[{when:"Verb stem, no 받침",add:"-ㄹ 뻔했어요",ex:"가다 → 갈 뻔했어요 (I almost went)"},{when:"Verb stem with 받침",add:"-을 뻔했어요",ex:"죽다 → 죽을 뻔했어요 (I almost died)"},{when:"Always past — never 뻔해요",add:"-(으)ㄹ 뻔했어요",ex:"넘어지다 → 넘어질 뻔해요 ✗ / 넘어질 뻔했어요 ✓"},{when:"The set collocation",add:"하마터면 V-(으)ㄹ 뻔했어요",ex:"두다 → 하마터면 지갑을 두고 나올 뻔했어요"}],examples:[{ko:"하마터면 지갑을 두고 나올 뻔했어요.",en:"I very nearly walked out and left my wallet behind.",romanization:"hamateomyeon jigabeul dugo naol ppeonhaesseoyo.",note:"하마터면 signals the near miss before the verb even arrives."},{ko:"계단에서 미끄러져서 크게 다칠 뻔했어요.",en:"I slipped on the stairs and nearly hurt myself badly.",romanization:"gyedaneseo mikkeureojyeoseo keuge dachil ppeonhaesseoyo.",note:"The slipping did happen; only the injury is the near miss."}],more:{func:"-(으)ㄹ 뻔했다 reports a near miss: the event came close and then did NOT happen. It is always past — 뻔했어요, never 뻔해요 — because a near miss is by definition already over. The event is nearly always something bad, and 하마터면 is its fixed partner at the front of the sentence.",funcLead:"-(으)ㄹ 뻔했다 reports a near miss: the event came close and then did NOT happen.",keyPoint:{label:"뻔하다 has a completely separate life as an adjective",body:`V-(으)ㄹ 뻔했다 is a near miss: 늦을 뻔했어요 means you almost were late, but you weren't. Standalone 뻔하다 is an unrelated adjective meaning "obvious, predictable": 결말이 너무 뻔해요, 뻔한 변명. The giveaway is the -(으)ㄹ in front — with it, near miss; without it, obvious.`},pronunciation:"뻔했어요 is [뻔해써요]. Because 뻔 already begins with a tense ㅃ, nothing tenses further: 갈 뻔했어요 is simply [갈 뻔해써요].",pitfall:{wrong:"어제 계단에서 넘어질 뻔해요.",right:"어제 계단에서 넘어질 뻔했어요.",explanation:`A near miss is already over, so -(으)ㄹ 뻔하다 lives in the past: 뻔했어요. Learners write 뻔해요 because English "I almost fall" feels present-shaped while telling the story. Worse, present-tense 뻔해요 is a different word entirely — the adjective meaning "that's so predictable."`}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I very nearly walked out and left my wallet behind."',tokens:["하마터면","지갑을","두고","나올","뻔했어요."],correct:"하마터면 지갑을 두고 나올 뻔했어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I slipped on the stairs and nearly hurt myself badly." (계단에서 시작 · Start with 계단에서.)',tokens:["계단에서","미끄러져서","크게","다칠","뻔했어요."],correct:"계단에서 미끄러져서 크게 다칠 뻔했어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"어제 계단에서 넘어질 뻔했어요.",ok:!0},{text:"어제 계단에서 넘어질 뻔해요.",ok:!1}],explanation:`A near miss is already over, so -(으)ㄹ 뻔하다 lives in the past: 뻔했어요. Learners write 뻔해요 because English "I almost fall" feels present-shaped while telling the story. Worse, present-tense 뻔해요 is a different word entirely — the adjective meaning "that's so predictable."`}],canDo:"Describe a near miss with 하마터면 …-(으)ㄹ 뻔했어요, always in the past",id:"chapter-69-b6",chapterId:"chapter-69",index:5},{kind:"pattern",title:"문법 Grammar · A/V-(으)ㄴ/는 척하다",cards:[{kind:"teach",name:"A/V-(으)ㄴ/는 척하다",sub:"putting on an act",rows:[{when:"Verb — action in progress",add:"V-는 척하다",ex:"자다 → 자는 척하다 (to pretend to be asleep)"},{when:"Verb — action already finished",add:"V-(으)ㄴ 척하다",ex:"듣다 → 못 들은 척하다 (to pretend not to have heard)"},{when:"Adjective",add:"A-(으)ㄴ 척하다",ex:"바쁘다 → 바쁜 척하다 (to pretend to be busy)"},{when:"Noun",add:"N인 척하다",ex:"전문가 → 전문가인 척하다"},{when:"Interchangeable variant",add:"-(으)ㄴ/는 체하다",ex:"알다 → 아는 체하다"}],examples:[{ko:"부장님이 지나가시길래 바쁜 척했어요.",en:"The department head was walking past, so I acted busy.",romanization:"bujangnimi jinagasigillae bappeun cheokaesseoyo.",note:"바쁘다 is an adjective, so the modifier is -(으)ㄴ: 바쁜 척."},{ko:"다 들었으면서 못 들은 척하지 마세요.",en:"Don't pretend you didn't hear when you heard every word.",romanization:"da deureosseumyeonseo mot deureun cheokaji maseyo.",note:"The hearing is already finished, so the modifier is -(으)ㄴ: 못 들은 척."}],more:{func:"척하다 says the outward behaviour did not match the inside. The modifier in front follows the ordinary rules you already know: -는 for a verb happening now, -(으)ㄴ for a finished action or for any adjective, and 인 for a noun. -(으)ㄴ/는 체하다 is an interchangeable variant.",funcLead:"척하다 says the outward behaviour did not match the inside.",keyPoint:{label:"Adjectives take -(으)ㄴ, not -는",body:'This is where English speakers slip. "Pretend to be sick" is 아픈 척하다, not 아프는 척하다, because 아프다 is an adjective and adjectives take -(으)ㄴ. Only verbs describing an ongoing action take -는: 자는 척하다, 일하는 척하다. Check what the base word is before you pick the modifier.'},pronunciation:"척하다 is [처카다] — the ㄱ of 척 and the ㅎ of 하 fuse into an aspirated [ㅋ]. So 척했어요 is [처캐써요] and 바쁜 척해요 is [바쁜 처캐요].",pitfall:{wrong:"사실 아픈데 안 아프는 척했어요.",right:"사실 아픈데 안 아픈 척했어요.",explanation:'아프다 is an adjective, so it takes -(으)ㄴ 척하다: 아픈 척, 안 아픈 척. Learners attach -는 because English "pretending" looks continuous. Keep -는 척하다 for verbs describing an action in progress, like 자는 척 and 일하는 척.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The department head was walking past, so I acted busy."',tokens:["부장님이","지나가시길래","바쁜","척했어요."],correct:"부장님이 지나가시길래 바쁜 척했어요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Don't pretend you didn't hear when you heard every word."`,tokens:["다","들었으면서","못","들은","척하지","마세요."],correct:"다 들었으면서 못 들은 척하지 마세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"사실 아픈데 안 아프는 척했어요.",ok:!1},{text:"사실 아픈데 안 아픈 척했어요.",ok:!0}],explanation:'아프다 is an adjective, so it takes -(으)ㄴ 척하다: 아픈 척, 안 아픈 척. Learners attach -는 because English "pretending" looks continuous. Keep -는 척하다 for verbs describing an action in progress, like 자는 척 and 일하는 척.'}],canDo:"Pick the right modifier for 척하다: 자는 척, 못 들은 척, 아픈 척, 전문가인 척",id:"chapter-69-b7",chapterId:"chapter-69",index:6},{kind:"pattern",title:"문법 Grammar · -아/어 버리다 vs -고 말다",cards:[{kind:"teach",name:"-아/어 버리다 vs -고 말다",sub:"same event, different feeling",rows:[{when:"You did it on purpose; often relief",add:"V-아/어 버리다",ex:"끝내다 → 다 끝내 버렸어요 (and good riddance)"},{when:"It happened against your will; always regret",add:"V-고 말았어요",ex:"울다 → 결국 울고 말았어요"},{when:"Same verb, two readings",add:"말해 버렸어요 / 말하고 말았어요",ex:"말하다 → 그냥 말해 버렸어요 (I let it out) vs 결국 말하고 말았어요 (it got out despite me)"},{when:"Determination — only -고 말다 does this",add:"V-고 말겠어요",ex:"붙다 → 이번엔 꼭 붙고 말겠어요"}],examples:[{ko:"미련 없이 그 가방을 팔아 버렸어요.",en:"I sold that bag off without a second thought.",romanization:"miryeon eopsi geu gabangeul para beoryeosseoyo.",note:"미련 없이 makes it clear this was your decision and you feel lighter."},{ko:"숨기려고 했는데 결국 말하고 말았어요.",en:"I meant to keep it hidden, but in the end it came out.",romanization:"sumgiryeogo haenneunde gyeolguk malhago marasseoyo.",note:"Same verb as 말해 버렸어요, but here the telling defeated you."}],more:{func:"Both say the action reached its end and both often carry regret, so learners treat them as interchangeable. They are not. -아/어 버리다 usually reports something YOU did, deliberately, and can just as easily feel like relief. -고 말다 reports an outcome that arrived despite you, and never feels like relief.",funcLead:"Both say the action reached its end and both often carry regret, so learners treat them as interchangeable.",keyPoint:{label:"Ask whether you wanted it",body:"If you chose the ending and feel lighter for it, use -아/어 버리다. If the ending beat you, use -고 말다. And only -고 말다 turns into determination in the future (-고 말겠어요), because that reading comes from the same core idea: the outcome arrives whether anyone likes it or not."},pronunciation:"해 버리니까 runs together as [해버리니까]. 붙고 말겠어요 tenses to [붇꼬 말게써요], since the ㅌ of 붙 closes as [ㄷ] and tenses the following ㄱ.",pitfall:{wrong:"일이 다 끝나서 기분 좋게 끝내고 말았어요.",right:"일이 다 끝나서 기분 좋게 끝내 버렸어요.",explanation:'-고 말다 always carries defeat, so pairing it with 기분 좋게 contradicts itself. When you finished something and feel good about it, -아/어 버리다 is the auxiliary you want. Learners swap the two because both come out as "ended up" in English.'}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I sold that bag off without a second thought."',tokens:["미련","없이","그","가방을","팔아","버렸어요."],correct:"미련 없이 그 가방을 팔아 버렸어요.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I meant to keep it hidden, but in the end it came out." (숨기려고 시작 · Start with 숨기려고.)',tokens:["숨기려고","했는데","결국","말하고","말았어요."],correct:"숨기려고 했는데 결국 말하고 말았어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"일이 다 끝나서 기분 좋게 끝내고 말았어요.",ok:!1},{text:"일이 다 끝나서 기분 좋게 끝내 버렸어요.",ok:!0}],explanation:'-고 말다 always carries defeat, so pairing it with 기분 좋게 contradicts itself. When you finished something and feel good about it, -아/어 버리다 is the auxiliary you want. Learners swap the two because both come out as "ended up" in English.'}],canDo:"Keep V-(으)ㄹ 뻔하다 apart from the adjective 뻔하다 ('obvious, predictable')",id:"chapter-69-b8",chapterId:"chapter-69",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends catch up the day after one of them left a gathering abruptly. It turns out she had been putting a brave face on all evening.",lines:[{speaker:"지원",ko:"어제 왜 그렇게 일찍 갔어요? 인사도 없이 가 버렸잖아요.",en:"Why did you leave so early yesterday? You just took off without saying goodbye.",romanization:"eoje wae geureoke iljjik gasseoyo? insado eopsi ga beoryeotjanayo."},{speaker:"유진",ko:"죄송해요. 사실 그때 너무 졸려서 지하철에서 내릴 역을 지나칠 뻔했어요.",en:"Sorry. Honestly, I was so sleepy I almost rode past my stop on the subway.",romanization:"joesonghaeyo. sasil geuttae neomu jollyeoseo jihacheoreseo naeril yeogeul jinachil ppeonhaesseoyo."},{speaker:"지원",ko:"괜찮아요? 요즘 계속 늦게까지 일하시더니 무리하시는 거 아니에요?",en:"Are you okay? You've been working late constantly — aren't you overdoing it?",romanization:"gwaenchanayo? yojeum gyesok neutgekkaji ilhasideoni murihasineun geo anieyo?"},{speaker:"유진",ko:"괜찮은 척했는데 사실 어제 계단에서 미끄러져서 크게 다칠 뻔했어요.",en:"I was putting on a brave face, but I actually slipped on the stairs yesterday and nearly hurt myself badly.",romanization:"gwaenchaneun cheokaenneunde sasil eoje gyedaneseo mikkeureojyeoseo keuge dachil ppeonhaesseoyo."},{speaker:"지원",ko:"네? 그걸 왜 이제 말해요? 그러다 진짜 사고 나요.",en:"What? Why are you only telling me now? You'll actually have an accident at this rate.",romanization:"ne? geugeol wae ije malhaeyo? geureoda jinjja sago nayo."},{speaker:"유진",ko:"말하면 걱정하실까 봐 숨기려고 했는데, 결국 말하고 말았네요.",en:"I wanted to keep it from you in case you worried, but in the end it came out anyway.",romanization:"malhamyeon geokjeonghasilkka bwa sumgiryeogo haenneunde, gyeolguk malhago mallanneyo."},{speaker:"지원",ko:"잘했어요. 오늘은 밀린 일 다 끝내 버리고 일찍 들어가세요.",en:"Good. Today, get all your backlog done and dusted and go home early.",romanization:"jalhaesseoyo. oneureun millin il da kkeunnae beorigo iljjik deureogaseyo."},{speaker:"유진",ko:"네. 오늘은 무슨 일이 있어도 일찍 자고 말겠어요.",en:"Okay. Tonight I'm getting to bed early no matter what happens.",romanization:"ne. oneureun museun iri isseodo iljjik jago malgesseoyo."}]},{kind:"order",prompt:"Build: 'I very nearly left my wallet behind.' (Start with 하마터면.)",tokens:["하마터면","지갑을","두고","나올 뻔했어요"],correct:"하마터면 지갑을 두고 나올 뻔했어요",explanation:"하마터면 is the fixed partner of -(으)ㄹ 뻔했어요 and goes at the front of the sentence."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"죄송해요. 사실 그때 너무 졸려서 지하철에서 내릴 역을 지나칠 뻔했어요.",options:[{text:"유진",ok:!0},{text:"지원",ok:!1}],explanation:"Sorry. Honestly, I was so sleepy I almost rode past my stop on the subway."}],canDo:"Carry an action right through with V-아/어 버리다, and hear whether it lands as relief or as regret",id:"chapter-69-b9",chapterId:"chapter-69",index:8},{kind:"reading",title:"읽기 Reading · 다 해 버린 일과 못 한 일",cards:[{kind:"read",title:"다 해 버린 일과 못 한 일",chunks:["하루를 돌아보면 끝낸 일, 어쩔 수 없이 벌어진 일, 겨우 피한 일이 섞여 있다. 한국어는 이 셋을 다른 어미로 나눈다. 내가 마음먹고 끝까지 해치웠으면 -아/어 버리다를 쓴다. 후련할 수도 있고 아까울 수도 있다. 막으려고 애썼는데도 그렇게 됐으면 -고 말다를 쓴다.","여기에는 후련함이 없다. 일어날 뻔했지만 결국 일어나지 않았으면 -(으)ㄹ 뻔했다를 쓴다. 이 표현은 항상 과거형이다. 그리고 속마음과 다른 표정을 지었다면 -(으)ㄴ/는 척하다를 쓴다."],translation:"Look back over a day and you find things you finished, things that happened whether you liked it or not, and things you only just avoided. Korean sorts those three with different endings. If you set your mind to it and saw it through, you use -아/어 버리다 — which may feel unburdening or may feel like a waste. If you fought to prevent it and it happened anyway, you use -고 말다, and there is no relief in that one. If it nearly happened but in the end did not, you use -(으)ㄹ 뻔했다, which is always in the past. And if the face you showed did not match what was going on inside, you use -(으)ㄴ/는 척하다.",qas:[{q:"내가 마음먹고 끝까지 한 일에는 어떤 어미를 써요?",a:"-아/어 버리다를 써요. 후련할 수도 있고 아까울 수도 있어요."},{q:"-고 말다에는 어떤 느낌이 없어요?",a:"후련함이 없어요. 막으려고 애썼는데도 그렇게 된 일에만 써요."},{q:"-(으)ㄹ 뻔했다는 왜 항상 과거형이에요?",a:"일어날 뻔했지만 결국 일어나지 않은 일이라서 이미 끝난 이야기이기 때문이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"내가 마음먹고 끝까지 해치웠으면 -아/어 ___를 쓴다.",options:[{text:"참다",ok:!1},{text:"버리다",ok:!0},{text:"울다",ok:!1}],explanation:""}],canDo:"Report an outcome that beat you with V-고 말다, and flip it to resolve with -고 말겠어요",id:"chapter-69-b10",chapterId:"chapter-69",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which is correct for 'I blew my whole salary in two days'?",sentence:null,options:[{text:"월급을 이틀 만에 다 써 버렸어요.",ok:!0},{text:"월급을 이틀 만에 다 쓰다 버렸어요.",ok:!1},{text:"월급을 이틀 만에 다 써 말았어요.",ok:!1}],explanation:"버리다 attaches to the -아/어 form, so 쓰다 becomes 써. And 말다 needs -고 in front of it, never -아/어."},{kind:"drill",prompt:"You held back the tears and in fact did NOT cry. Which fits?",sentence:null,options:[{text:"울 뻔했어요",ok:!0},{text:"울고 말았어요",ok:!1},{text:"울어 버렸어요",ok:!1}],explanation:"-(으)ㄹ 뻔했다 is the only one of the three where the event did not actually happen. Both 울고 말았어요 and 울어 버렸어요 mean you really did cry."},{kind:"drill",prompt:"Which sentence attaches 척하다 to an adjective correctly?",sentence:null,options:[{text:"사실 아픈데 안 아픈 척했어요.",ok:!0},{text:"사실 아픈데 안 아프는 척했어요.",ok:!1},{text:"사실 아픈데 안 아팠는 척했어요.",ok:!1}],explanation:"아프다 is an adjective, so it takes -(으)ㄴ 척하다: 안 아픈 척했어요. -는 척하다 is reserved for verbs describing an ongoing action, like 자는 척하다."},{kind:"drill",prompt:"Which one expresses determination ('I'll do it no matter what')?",sentence:null,options:[{text:"이번엔 꼭 이기고 말겠어요.",ok:!0},{text:"이번엔 꼭 이겨 버리겠어요.",ok:!1},{text:"이번엔 꼭 이길 뻔했어요.",ok:!1}],explanation:"Only -고 말다 flips to determination in the future: -고 말겠어요. -아/어 버리다 stays a report of completion, and -(으)ㄹ 뻔했다 is always a past near miss."},{kind:"drill",prompt:"조심했는데도 컵___ 깨지고 말았어요. (the cup ended up broken)",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"깨지다 means 'it breaks', so the cup is the subject: 컵이. 컵을 would need the transitive 깨다 — 컵을 깨고 말았어요."},{kind:"drill",prompt:"다 들었으면서 ____ 척하지 마세요. (pretend not to have heard)",sentence:null,options:[{text:"못 들은",ok:!0},{text:"못 듣는",ok:!1},{text:"못 들을",ok:!1}],explanation:"The hearing already happened, so the completed-action modifier -(으)ㄴ is right: 못 들은 척하다."}],canDo:"Describe a near miss with 하마터면 …-(으)ㄹ 뻔했어요, always in the past",id:"chapter-69-b11",chapterId:"chapter-69",index:10}]},{id:"chapter-70",number:70,title:"V/A-(으)며 · V/A-(으)나",goal:"Join two clauses inside one sentence with -(으)며 for parallel facts and -(으)나 for contrast.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 공지~",cards:[{kind:"guess",word:{ko:"공지",romanization:"gongji",en:"notice, announcement",pos:"noun",nuance:"공지 is more official than a casual message. It often hides the actor and foregrounds the posted information."},sentence:{ko:"공지 내용이 변경되었으므로 최신 글을 다시 확인하기 바람.",en:"The content of the notice has changed, so please check the most recent post again."},target:"공지",options:["guidance, information (for the public)","notice, announcement","application, request"],note:"-(으)므로 for the reason and -기 바람 for the request."},{kind:"guess",word:{ko:"안내",romanization:"annae",en:"guidance, information (for the public)",pos:"noun"},sentence:{ko:"이용 안내는 게시판에 게시되어 있으며 변경 시 다시 공지된다.",en:"The usage guidance is posted on the board, and it is announced again if it changes."},target:"안내",options:["notice, announcement","guidance, information (for the public)","application, request"],note:"-(으)며 joins two facts about one notice."},{kind:"guess",word:{ko:"신청",romanization:"sincheong",en:"application, request",pos:"noun",nuance:"신청 is a Sino-Korean noun (申請, 申 'state/report' + 請 'request') meaning a formal application or request you put in to an office, bank, or service — you are asking an authority to grant or process something. It overwhelmingly takes 하다 to become the verb 신청하다 ('to apply for'), and 신청서 is the physical form you fill in. Compare it carefully with 지원 (支援/志願): 신청 is the neutral 'put in a request' (카드를 신청하다 = apply for a card), while 지원 is 'apply to/for' a job or school where you are a candidate being selected (회사에 지원하다 = apply to a company). Also distinguish 접수, which is the office's act of RECEIVING and logging your 신청. Register is neutral-to-formal, standard in any official or banking setting. The classic English-speaker pitfall is reaching for 지원 for everyday errands (it sounds like job-hunting) and forgetting that 신청 needs 하다 to act as a verb — 신청 by itself is only the noun, so 'I apply' is 신청해요, not bare 신청."},sentence:{ko:"신청은 이번 주까지 받으며, 결과는 다음 주에 발표된다.",en:"Applications are taken until the end of this week, and results are announced next week."},target:"신청",options:["notice, announcement","application, request","guidance, information (for the public)"],note:"-(으)며 lists two stages of one process in a single sentence."},{kind:"guess",word:{ko:"접수",romanization:"jeopsu",en:"receipt, intake (of applications)",pos:"noun",nuance:"접수 is a Sino-Korean noun (接受, 接 'receive/connect' + 受 'accept') meaning the RECEIVING and logging of an application or document by an office — both the act of an institution taking your submission in, and (loosely) your act of handing it in at the 접수 창구 (intake window). It takes 하다 and 되다: from your side 서류를 접수하다 can mean 'submit/file', while 접수가 되다 / 접수되다 means 'it has been received/registered by them'. The crucial trio for learners: 신청 (you REQUEST) → 접수 (the office RECEIVES/logs it) → 처리 (處理, they PROCESS it). So 접수 sits in the middle, the moment your paperwork is officially accepted and assigned a 접수 번호. Distinguish it from 제출 (提出, the physical act of 'submitting/handing over' a document) — 제출 is the handing in, 접수 is the institution accepting and registering it. Register is neutral-formal, standard at hospitals, offices, and event desks (병원 접수 = hospital reception/check-in). The English-speaker pitfall is treating 접수 as plain 'submit' (that is 제출) and missing its 'be accepted/logged' meaning — 접수가 됐어요 means your application is now officially in the system, not merely handed over."},sentence:{ko:"접수는 선착순으로 진행되므로 서둘러 신청하기 바랍니다.",en:"Intake is first come, first served, so please apply promptly."},target:"접수",options:["notice, announcement","guidance, information (for the public)","receipt, intake (of applications)"],note:"-(으)므로 may be followed by a request, which -아서/어서 could not."},{kind:"guess",word:{ko:"제출",romanization:"jechul",en:"submission, handing in",pos:"noun"},sentence:{ko:"제출 방법은 두 가지이며, 온라인 제출을 권장함.",en:"There are two submission methods, and online submission is recommended."},target:"제출",options:["submission, handing in","notice, announcement","guidance, information (for the public)"],note:"-(으)며 in the middle and a bare -(으)ㅁ at the close."},{kind:"guess",word:{ko:"규정",romanization:"gyujeong",en:"rule, regulation",pos:"noun"},sentence:{ko:"규정은 개정되었으나 시행일은 아직 정해지지 않았다.",en:"The rules have been revised, but the date they take effect has not yet been set."},target:"규정",options:["rule, regulation","notice, announcement","guidance, information (for the public)"],note:"-(으)나 gives the written contrast inside one sentence."},{kind:"guess",word:{ko:"기한",romanization:"gihan",en:"deadline, time limit",pos:"noun"},sentence:{ko:"대출 기한은 기존과 동일하며 연장은 일 회만 가능하다.",en:"The loan period is the same as before, and one renewal is permitted."},target:"기한",options:["notice, announcement","deadline, time limit","guidance, information (for the public)"],note:"기존과 동일하다 is stock notice phrasing for 'unchanged'."},{kind:"payoff",line:{speaker:"유진",ko:"공지 초안 보셨어요? 문장이 자꾸 끊겨서 좀 딱딱해요.",en:"Did you see the draft notice? The sentences keep breaking up, so it reads a bit stiff."},hl:"공지"}],canDo:"Join two clauses inside one sentence with -(으)며 for parallel facts and simultaneity",id:"chapter-70-b1",chapterId:"chapter-70",index:0},{kind:"pattern",title:"문법 Grammar · V/A-(으)며",cards:[{kind:"hunt",name:"V/A-(으)며",sub:"listing and simultaneity inside one sentence",lines:[{tokens:[{pre:"이번",mid:"",post:"",hit:!1},{pre:"행사는",mid:"",post:"",hit:!1},{pre:"다음",mid:"",post:"",hit:!1},{pre:"달에",mid:"",post:"",hit:!1},{pre:"시작되",mid:"며",post:"",hit:!0},{pre:"총",mid:"",post:"",hit:!1},{pre:"사",mid:"",post:"",hit:!1},{pre:"주간",mid:"",post:"",hit:!1},{pre:"진행된다.",mid:"",post:"",hit:!1}],ko:"이번 행사는 다음 달에 시작되며 총 사 주간 진행된다.",en:"This event begins next month and runs for a total of four weeks.",romanization:"ibeon haengsaneun daeum dare sijakdoemyeo chong sa jugan jinhaengdoenda."},{tokens:[{pre:"신청서는",mid:"",post:"",hit:!1},{pre:"온라인으로",mid:"",post:"",hit:!1},{pre:"접수하",mid:"며",post:",",hit:!0},{pre:"서류는",mid:"",post:"",hit:!1},{pre:"방문",mid:"",post:"",hit:!1},{pre:"제출도",mid:"",post:"",hit:!1},{pre:"가능하다.",mid:"",post:"",hit:!1}],ko:"신청서는 온라인으로 접수하며, 서류는 방문 제출도 가능하다.",en:"Applications are received online, and documents may also be submitted in person.",romanization:"sincheongseoneun onnaineuro jeopsuhamyeo, seoryuneun bangmun jechuldo ganeunghada."}],rule:{name:"V/A-(으)며",rows:[{when:"Stem ends in a vowel or ㄹ",add:"-며",ex:"비싸다 → 값은 비싸며 (it is expensive, and…)"},{when:"Stem ends in a consonant",add:"-으며",ex:"좋다 → 품질이 좋으며 (the quality is good, and…)"},{when:"Past tense",add:"-았/었으며",ex:"끝나다 → 회의는 끝났으며 (the meeting has ended, and…)"},{when:"Simultaneity — the written -(으)면서",add:"-(으)며",ex:"보다 → 자료를 보며 (while looking at the materials)"},{when:"The spoken forms you are replacing",add:"-고 / -(으)면서",ex:"값이 싸고 품질도 좋아요 → 값이 싸며 품질도 좋다"}]},more:{func:"-(으)며 is the written counterpart of two spoken endings at once: -고 when it lists parallel facts, and -(으)면서 when the two things happen together. It keeps both clauses under a single final ending, which is what makes a report read as connected prose rather than a list of short statements.",funcLead:"-(으)며 is the written counterpart of two spoken endings at once: -고 when it lists parallel facts, and -(으)면서 when the two things happen together.",keyPoint:{label:"Two different layers of written Korean",body:"The written connectors you already know — 따라서 and 그러나 — stand BETWEEN sentences and begin a new one. (즉 is the exception that proves the rule: it can start a sentence, but it just as often sits mid-sentence right after the term it defines.) -(으)며 and everything else in this chapter work INSIDE a sentence, joining clauses under one ending. Formal prose uses both at once: 값이 싸며 품질도 좋다. 따라서 수요가 늘고 있다."},pronunciation:"After a ㄹ-stem the ㄹ survives, because 며 begins with ㅁ: 알다 → 알며 [알며], 만들다 → 만들며 [만들며]. 좋으며 is [조으며], with the ㅎ silent between vowels.",pitfall:{wrong:"회의를 마치며 자료를 배포했다.",right:"회의를 마친 후 자료를 배포했다.",explanation:'-(으)며 means the two things are true together or happen at the same time — never one after the other. English "and" covers both, so learners reach for -(으)며 to mean "and then." For sequence use -(으)ㄴ 후(에) or -고 나서, and keep -(으)며 for parallel or simultaneous facts.'}}},{kind:"drill",prompt:"He is a researcher and at the same time also teaches at a university.",sentence:"그는 연구원이___ 동시에 대학에서 강의도 맡고 있다.",options:[{text:"며",ok:!0},{text:"으나",ok:!1},{text:"으므로",ok:!1}],explanation:"이다 takes -며 directly: 연구원이며, 학생이며."},{kind:"drill",prompt:"We reviewed the next schedule together while looking at the meeting materials.",sentence:"회의 자료를 보___ 다음 일정을 함께 검토했다.",options:[{text:"으나",ok:!1},{text:"으므로",ok:!1},{text:"며",ok:!0}],explanation:"The simultaneity reading — here -(으)며 is doing the job of -(으)면서."},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"회의를 마친 후 자료를 배포했다.",ok:!0},{text:"회의를 마치며 자료를 배포했다.",ok:!1}],explanation:'-(으)며 means the two things are true together or happen at the same time — never one after the other. English "and" covers both, so learners reach for -(으)며 to mean "and then." For sequence use -(으)ㄴ 후(에) or -고 나서, and keep -(으)며 for parallel or simultaneous facts.'}],canDo:"Join two clauses inside one sentence with -(으)며 for parallel facts and simultaneity",id:"chapter-70-b2",chapterId:"chapter-70",index:1},{kind:"words",title:"단어 Words 2 · 변경~",cards:[{kind:"guess",word:{ko:"변경",romanization:"byeongyeong",en:"change, alteration (formal)",pos:"noun"},sentence:{ko:"주말 개관 시간도 함께 변경되며 자세한 내용은 홈페이지에 게시된다.",en:"The weekend opening hours change as well, and details are posted on the website."},target:"변경",options:["notice, announcement","guidance, information (for the public)","change, alteration (formal)"],note:"변경되다 is the formal written cousin of the everyday 바뀌다."},{kind:"guess",word:{ko:"문의",romanization:"munui",en:"enquiry",pos:"noun"},sentence:{ko:"자세한 내용을 확인하고자 하는 이용자는 안내 데스크에 문의하기 바람.",en:"Users wishing to confirm the details are asked to enquire at the information desk."},target:"문의",options:["enquiry","notice, announcement","guidance, information (for the public)"],note:"문의하기 바람 closes almost every Korean public notice."},{kind:"guess",word:{ko:"서류",romanization:"seoryu",en:"documents, paperwork",pos:"noun",nuance:"서류 is a Sino-Korean noun (書類, 書 'writing/document' + 類 'kind/category') meaning official documents or paperwork as a category — the bundle of forms, copies, and certificates a procedure demands. It is a collective, somewhat abstract term: 서류를 준비하다 = get your paperwork in order, covering many individual papers at once. Contrast it with 문서 (文書), which is 'a document' as a discrete file or record (often electronic or archival, e.g. an internal 문서), while 서류 evokes the practical stack you submit for an application. A single sheet is 종이 (paper) and one specific form is e.g. 신청서; 서류 is the umbrella. Natural collocations are 서류를 준비하다/챙기다/제출하다/접수하다 and 서류 심사 (document review). Register is neutral, ubiquitous at banks, immigration, and government offices. The English-speaker pitfall is treating 서류 as countable like 'a document' — Korean uses it as a mass/collective noun, so you rarely say 한 서류; for one item name the specific form (신청서 한 장) or use 문서 for a discrete record."},sentence:{ko:"필요한 서류를 모두 갖추었으며 원본은 따로 보관 중이다.",en:"All the required documents have been assembled, and the originals are kept separately."},target:"서류",options:["notice, announcement","documents, paperwork","guidance, information (for the public)"],note:"-(으)며 joins two facts about the same paperwork."},{kind:"guess",word:{ko:"자료",romanization:"jaryo",en:"materials, data",pos:"noun",nuance:"자료 can mean data, but in daily work and study talk it often means the file, handout, or slide deck someone needs."},sentence:{ko:"자료를 검토하고자 담당자에게 원본을 요청했다.",en:"I requested the originals from the person in charge in order to review the materials."},target:"자료",options:["notice, announcement","guidance, information (for the public)","materials, data"],note:"-고자 states the purpose, with one subject across both clauses."},{kind:"guess",word:{ko:"회의",romanization:"hoeui",en:"meeting",pos:"noun",nuance:"회의 (漢字 會議, 會 'gather' + 議 'discuss') is a formal, work-style meeting where people gather to discuss and decide something — a board meeting, a team sync, a planning session. The near-synonym learners reach for is 모임, but 모임 is a social get-together (a dinner, a club, friends meeting up) with no agenda, so calling drinks with friends a 회의 sounds robotic; conversely calling a budget review a 모임 sounds too loose. It pairs naturally with 회의를 하다 (hold), 회의에 들어가다 (go into), 회의가 길어지다 (run long). The English-speaker pitfall is the particle: you are *in* a meeting as a location, so the action takes 회의에서, but you *enter* a meeting with 회의에 들어가다 — and never confuse 회의 with the look-alike 회사 (company) or 회비 (membership fee)."},sentence:{ko:"회의는 이미 끝났으며 결과는 곧 공유될 예정임.",en:"The meeting has already ended, and the outcome will be shared shortly."},target:"회의",options:["meeting","notice, announcement","guidance, information (for the public)"],note:"-(으)며 plus a -(으)ㅁ close: two written layers in one short line."},{kind:"guess",word:{ko:"일정",romanization:"iljeong",en:"schedule",pos:"noun",nuance:"일정 is the planned schedule of where you go and what you do, day by day — for a trip, but equally for work or events. The hanja 日程 is 日 (day) + 程 (journey/measure), an 'apportioning of the days'. Distinguish it from 시간 (time, clock time) and 계획 (plan): 시간 is just the hour on the clock, 계획 is the broad intention ('I plan to save money'), while 일정 is the concrete time-tabled sequence of items. Note the signature verb 짜다 — you 일정을 짜다 (literally 'weave a schedule'), the same verb used for 계획을 짜다. Watch the adjective 빡빡하다 / 바쁘다 for a packed itinerary. English-speaker pitfall: don't reach for 시간 when you mean the agenda — '오늘 시간이 어때요?' asks if someone is free, but '오늘 일정이 어때요?' asks about the day's plan."},sentence:{ko:"일정이 변경되었으므로 참석자 전원에게 다시 안내해야 한다.",en:"The schedule has changed, so all attendees must be notified again."},target:"일정",options:["notice, announcement","schedule","guidance, information (for the public)"],note:"-(으)므로 supplies the reason a notice needs before an obligation."},{kind:"guess",word:{ko:"장소",romanization:"jangso",en:"venue, place",pos:"noun",nuance:"장소 is broader and more formal than 데 or 곳."},sentence:{ko:"장소는 변경되지 않으나 시간은 한 시간 앞당겨진다.",en:"The venue does not change, but the time is being moved an hour earlier."},target:"장소",options:["notice, announcement","guidance, information (for the public)","venue, place"],note:"-(으)나 keeps the unchanged part and the changed part in one sentence."},{kind:"payoff",line:{speaker:"지원",ko:"네. '접수는 온라인으로 합니다. 그리고 서류는 방문 제출도 됩니다.' 이 두 문장을 하나로 합치면 어때요?",en:'Right. "Applications are taken online. And documents can also be handed in in person." How about merging those two?'},hl:"서류"}],canDo:"Contrast inside a sentence with -(으)나, adding 으 only after a consonant",id:"chapter-70-b3",chapterId:"chapter-70",index:2},{kind:"pattern",title:"문법 Grammar · V/A-(으)나",cards:[{kind:"hunt",name:"V/A-(으)나",sub:'the written "but" inside a sentence',lines:[{tokens:[{pre:"예산은",mid:"",post:"",hit:!1},{pre:"늘었",mid:"으나",post:"",hit:!0},{pre:"인력은",mid:"",post:"",hit:!1},{pre:"그대로이다.",mid:"",post:"",hit:!1}],ko:"예산은 늘었으나 인력은 그대로이다.",en:"The budget has grown, but the staffing is unchanged.",romanization:"yesaneun neureosseuna illyeogeun geudaeroida."},{tokens:[{pre:"신청은",mid:"",post:"",hit:!1},{pre:"누구",mid:"나",post:"",hit:!0},{pre:"가능하",mid:"나",post:"",hit:!0},{pre:"선정은",mid:"",post:"",hit:!1},{pre:"심사를",mid:"",post:"",hit:!1},{pre:"거친다.",mid:"",post:"",hit:!1}],ko:"신청은 누구나 가능하나 선정은 심사를 거친다.",en:"Anyone may apply, but selection goes through a review.",romanization:"sincheongeun nuguna ganeunghana seonjeongeun simsareul geochinda."}],rule:{name:"V/A-(으)나",rows:[{when:"Stem ends in a vowel",add:"-나",ex:"비싸다 → 값은 비싸나 (it is expensive, but…)"},{when:"Stem ends in a consonant",add:"-으나",ex:"좋다 → 품질은 좋으나 (the quality is good, but…)"},{when:"Past tense",add:"-았/었으나",ex:"늘다 → 예산은 늘었으나 (the budget grew, but…)"},{when:"이다 — contrast on a noun",add:"N(이)나",ex:"신입 → 그는 신입이나 (he is new, but…)"},{when:"The spoken form you are replacing",add:"-지만",ex:"예산은 늘었지만 → 예산은 늘었으나"}]},more:{func:"-(으)나 is the clause-internal contrast, the written equivalent of -지만. It sets the second clause against the first without breaking the sentence, which is why reports prefer it when the two halves belong to a single point rather than two separate beats.",funcLead:"-(으)나 is the clause-internal contrast, the written equivalent of -지만.",keyPoint:{label:"-(으)나 vs 그러나 — one sentence or two",body:"그러나 starts a new sentence; -(으)나 keeps both halves inside one. 예산은 늘었다. 그러나 인력은 그대로이다 gives the contrast its own beat. 예산은 늘었으나 인력은 그대로이다 presents it as a single observation. Neither is more correct — choose by how much weight the contrast deserves."},pronunciation:"Because -(으)나 begins with ㄴ, a ㄹ-stem drops its ㄹ: 알다 → 아나, 살다 → 사나. That is the same drop you already know from 압니다 and 사는. 늘었으나 links as [느러쓰나].",pitfall:{wrong:"값은 비싸으나 품질이 좋다.",right:"값은 비싸나 품질이 좋다.",explanation:'비싸다 ends in a vowel, so it takes plain -나. Learners insert 으 everywhere because they memorise the ending as "-으나," but the 으 appears only after a consonant: 좋으나, 늘었으나. After a vowel it is 비싸나, 가나, 하나.'}}},{kind:"drill",prompt:"We reviewed the material several times but could not find the error.",sentence:"자료를 여러 번 검토했___ 오류를 찾지 못했다.",options:[{text:"으며",ok:!1},{text:"으므로",ok:!1},{text:"으나",ok:!0}],explanation:"Past tense sits inside the ending: 검토했으나."},{kind:"drill",prompt:"He is new, but his grasp of the work is very high.",sentence:"그는 신입이___ 업무 이해도가 매우 높다.",options:[{text:"으며",ok:!1},{text:"나",ok:!0},{text:"으므로",ok:!1}],explanation:"After a noun the form is N(이)나 — here 신입이나."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The budget has grown, but the staffing is unchanged."',tokens:["예산은","늘었으나","인력은","그대로이다."],correct:"예산은 늘었으나 인력은 그대로이다.",explanation:""},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Anyone may apply, but selection goes through a review."',tokens:["신청은","누구나","가능하나","선정은","심사를","거친다."],correct:"신청은 누구나 가능하나 선정은 심사를 거친다.",explanation:""}],canDo:"Contrast inside a sentence with -(으)나, adding 으 only after a consonant",id:"chapter-70-b4",chapterId:"chapter-70",index:3},{kind:"words",title:"단어 Words 3 · 등록~",cards:[{kind:"guess",word:{ko:"등록",romanization:"deungnok",en:"registration, enrolment",pos:"noun",nuance:"등록 is a Sino-Korean noun (登錄, 登 'record/ascend' + 錄 'register/record') meaning officially entering a person or thing onto a register or roll — enrolling, registering, recording in a system. It takes 하다 (등록하다 = to register) or 되다 (등록되다 = to be registered), and appears in 외국인 등록증 (alien registration card), 주민등록 (resident registration), 등록금 (registration/tuition fee), 등록 번호 (registration number). The contrast learners need is with 신청 and 접수: 신청 is REQUESTING something, 접수 is the office RECEIVING your request, and 등록 is the result of being formally ENTERED onto the official record — often you 신청 first, the desk 접수, and finally you are 등록 in the system. Compare also 가입 (加入, 'joining/subscribing' to a membership, service, or insurance — 보험 가입, 회원 가입), which is about becoming a MEMBER, whereas 등록 is about being recorded in a registry. Register is neutral-formal. The English-speaker pitfall is using 등록 for joining a club or signing up for a service (that is 가입) and using 가입 for recording an official entry (that is 등록) — and remembering 등록 needs 하다/되다 to function as a verb."},sentence:{ko:"등록은 선착순으로 진행되며 정원이 차면 마감된다.",en:"Registration runs first come, first served, and closes once the quota is filled."},target:"등록",options:["notice, announcement","registration, enrolment","guidance, information (for the public)"],note:"선착순 is the fixed word for first-come-first-served in notices."},{kind:"guess",word:{ko:"마감",romanization:"magam",en:"closing, deadline",pos:"noun",nuance:"마감 is a native Korean noun (from the verb 막다 'to block/close off') meaning the point at which something is sealed shut: a report's due date, an application cutoff, a shop's last order, even a magazine going to press. The near-synonym confusion is with 기한 and 데드라인: 기한 (期限) is the dry, official 'time limit/term' you see on documents (제출 기한), while 마감 feels more like the live moment things close, and 데드라인 is a borrowed buzzword. Its signature collocation is the idiom 마감에 쫓기다 (chased by the deadline), the universal way to describe last-minute panic. The English-speaker pitfall is mapping 'meet a deadline' onto 만나다 ('meet a person'): you do NOT 마감을 만나다 — you 마감을 지키다 (keep/protect it). Note 지키다 is the same verb used for keeping a promise (약속을 지키다), which is the right mental image."},sentence:{ko:"접수는 오늘 오후 여섯 시에 마감되므로 서둘러 주시기 바랍니다.",en:"Intake closes at six this afternoon, so please hurry."},target:"마감",options:["notice, announcement","closing, deadline","guidance, information (for the public)"],note:"-(으)므로 can be followed by a request, which -아서/어서 could not."},{kind:"guess",word:{ko:"연기",romanization:"yeongi",en:"postponement",pos:"noun",nuance:"연기 is the noun; 연기하다 is the verb 'to act/perform.'"},sentence:{ko:"행사는 우천으로 연기되었으며 새 일정은 추후 공지 예정임.",en:"The event was postponed because of rain, and the new schedule will be announced later."},target:"연기",options:["notice, announcement","guidance, information (for the public)","postponement"],note:"우천으로 is the written way to say 'due to rain'."},{kind:"guess",word:{ko:"첨부",romanization:"cheombu",en:"attachment (to a document or email)",pos:"noun",nuance:"첨부 means attaching a file to a message, and 첨부 파일 (attached file) is one of the highest-frequency phrases in Korean work email. It is Sino-Korean 添附, literally 'add-attach', both characters meaning to append something extra. The distinction to keep is digital 첨부하다 (attach an email file) vs physical 붙이다 (stick/glue something to a surface) vs 부착하다 (affix a label/poster) — English says 'attach' for all three, but a file is only ever 첨부하다. Its fixed companion line 첨부 파일을 확인해 주세요 is basically email etiquette you can paste anywhere. The English-speaker pitfall, beyond reaching for 붙이다, is spacing: in careful business writing it is two words, 첨부 파일, not 첨부파일 (though the squished form is tolerated in casual chat). Also note 첨부 has no plain past on its own — you write 첨부했어요/첨부했습니다, never 첨부 했어요 with a gap."},sentence:{ko:"자세한 내용은 첨부 파일을 참고하기 바람.",en:"Please refer to the attached file for details."},target:"첨부",options:["notice, announcement","attachment (to a document or email)","guidance, information (for the public)"],note:"참고하기 바람 is the terse notice version of 참고해 주시기 바랍니다."},{kind:"guess",word:{ko:"시간",romanization:"sigan",en:"time, hours",pos:"noun",nuance:"시간 works with 있어요/없어요 and is essential for scheduling."},sentence:{ko:"평일은 아홉 시에 문을 여나 주말에는 여섯 시에 닫는다.",en:"On weekdays it opens at nine, but at weekends it closes at six."},target:null,options:["notice, announcement","time, hours","guidance, information (for the public)"],note:"여다 is not a word — 열다 loses its ㄹ before -나, giving 여나."},{kind:"guess",word:{ko:"참석하다",romanization:"chamseokada",en:"to attend",pos:"verb",nuance:"참석하다 is Sino-Korean 參席 — 參 'take part' + 席 'seat' — literally 'take one's seat (and take part)', i.e. attend a formal event like a meeting, ceremony, or banquet. Its register is more formal than just 가다 'to go'; you 결혼식에 가요 casually but 결혼식에 참석합니다 in polite/written contexts. Distinguish it from its close cousin 참가하다 (參加, 'participate/enter'): 참석하다 emphasizes being PRESENT and seated at a gathering, while 참가하다 emphasizes actively TAKING PART (참가하다 fits a contest, race, or program — 대회에 참가하다). The big English-speaker pitfall is the particle: English 'attend THE meeting' (object) drives learners to 회의를 참석하다, but Korean uses 에 — 회의에 참석하다 — because you 'join INTO' the event. As a noun+하다 verb it conjugates on 하다 (참석해요, 참석했어요, formal 참석합니다); negative/impossible split the noun (참석 안 해요, 참석 못 해요)."},sentence:{ko:"전원 참석했음이 확인되었으므로 별도 안내는 생략한다.",en:"It was confirmed that everyone attended, so separate guidance is omitted."},target:"참석했",options:["notice, announcement","to attend","guidance, information (for the public)"],note:"확인되다 takes -(으)ㅁ, never -기: 참석했음이 확인되었다."}],canDo:"State a written reason with -(으)므로 and keep it apart from -(으)ㅁ으로(써)",id:"chapter-70-b5",chapterId:"chapter-70",index:4},{kind:"pattern",title:"문법 Grammar · V/A-(으)므로",cards:[{kind:"hunt",name:"V/A-(으)므로",sub:'the written "because," and why it is not -(으)ㅁ으로',lines:[{tokens:[{pre:"관련",mid:"",post:"",hit:!1},{pre:"규정이",mid:"",post:"",hit:!1},{pre:"바뀌었",mid:"으므로",post:"",hit:!0},{pre:"신청",mid:"",post:"",hit:!1},{pre:"전에",mid:"",post:"",hit:!1},{pre:"반드시",mid:"",post:"",hit:!1},{pre:"확인해야",mid:"",post:"",hit:!1},{pre:"한다.",mid:"",post:"",hit:!1}],ko:"관련 규정이 바뀌었으므로 신청 전에 반드시 확인해야 한다.",en:"The relevant rules have changed, so you must check before applying.",romanization:"gwallyeon gyujeongi bakkwieosseumeuro sincheong jeone bandeusi hwaginhaeya handa."},{tokens:[{pre:"해당",mid:"",post:"",hit:!1},{pre:"구역은",mid:"",post:"",hit:!1},{pre:"공사",mid:"",post:"",hit:!1},{pre:"중이",mid:"므로",post:"",hit:!0},{pre:"출입을",mid:"",post:"",hit:!1},{pre:"금한다.",mid:"",post:"",hit:!1}],ko:"해당 구역은 공사 중이므로 출입을 금한다.",en:"This area is under construction, so entry is prohibited.",romanization:"haedang guyeogeun gongsa jungimeuro churibeul geumhanda."}],rule:{name:"V/A-(으)므로",rows:[{when:"Stem ends in a vowel or ㄹ",add:"-므로",ex:"하다 → 공사 중이므로 (since it is under construction)"},{when:"Stem ends in a consonant",add:"-으므로",ex:"좋다 → 상태가 좋으므로 (since the condition is good)"},{when:"Past tense",add:"-았/었으므로",ex:"지나다 → 기한이 지났으므로 (since the deadline has passed)"},{when:"A command may follow — unlike -아서/어서",add:"-(으)므로 + 금한다 / 하십시오",ex:"위험하다 → 위험하므로 출입을 금한다"},{when:"NOT the same word: 'by means of'",add:"-(으)ㅁ으로(써)",ex:"노력하다 → 노력함으로써 (by making an effort)"}]},more:{func:"-(으)므로 states a reason in the written register, more logical and less personal than -아서/어서 or -(으)니까. It is the everyday reason ending of notices, regulations, and reports — and unlike -아서/어서 it can be followed by a command or a prohibition.",funcLead:"-(으)므로 states a reason in the written register, more logical and less personal than -아서/어서 or -(으)니까.",keyPoint:{label:"-(으)므로 vs -(으)ㅁ으로(써)",body:'One is a reason, the other is a method, and Korean writers confuse them constantly. 노력했으므로 성공했다 means "he succeeded BECAUSE he made an effort." 노력함으로써 성공했다 means "he succeeded BY making an effort." The tell is the ㅁ: -(으)므로 contains no noun, while -(으)ㅁ으로 is the nominal -(으)ㅁ plus the instrumental particle 으로.'},pronunciation:"않으므로 is [아느므로] and 좋으므로 is [조으므로] — the ㅎ goes silent before the 으. 바뀌었으므로 links as [바뀌어쓰므로].",pitfall:{wrong:"규정이 바뀌었음으로 확인해야 한다.",right:"규정이 바뀌었으므로 확인해야 한다.",explanation:'The reason ending is -(으)므로, with no 음 in it. 바뀌었음으로 literally reads "by the fact of having changed," which is the nominal -(으)ㅁ plus 으로. Korean writers make this slip too, so learn the split rather than copying what you see online: reason = -(으)므로, method = -(으)ㅁ으로써.'}}},{kind:"drill",prompt:"The submission deadline has passed, so this application will not be accepted.",sentence:"제출 기한이 지났___ 이번 신청은 접수되지 않는다.",options:[{text:"으므로",ok:!0},{text:"으며",ok:!1},{text:"으나",ok:!1}],explanation:"Past inside the ending, present result — the usual shape for a rule."},{kind:"drill",prompt:"The material is not sufficient, so we are holding off on a conclusion.",sentence:"자료가 충분하지 않___ 결론을 유보한다.",options:[{text:"으며",ok:!1},{text:"으므로",ok:!0},{text:"으나",ok:!1}],explanation:"Negation goes inside: -지 않으므로."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "This area is under construction, so entry is prohibited."',tokens:["해당","구역은","공사","중이므로","출입을","금한다."],correct:"해당 구역은 공사 중이므로 출입을 금한다.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"규정이 바뀌었으므로 확인해야 한다.",ok:!0},{text:"규정이 바뀌었음으로 확인해야 한다.",ok:!1}],explanation:'The reason ending is -(으)므로, with no 음 in it. 바뀌었음으로 literally reads "by the fact of having changed," which is the nominal -(으)ㅁ plus 으로. Korean writers make this slip too, so learn the split rather than copying what you see online: reason = -(으)므로, method = -(으)ㅁ으로써.'}],canDo:"State a written reason with -(으)므로 and keep it apart from -(으)ㅁ으로(써)",id:"chapter-70-b6",chapterId:"chapter-70",index:5},{kind:"pattern",title:"문법 Grammar · V-고자",cards:[{kind:"hunt",name:"V-고자",sub:'"in order to," the written form of -(으)려고',lines:[{tokens:[{pre:"행사",mid:"",post:"",hit:!1},{pre:"일정을",mid:"",post:"",hit:!1},{pre:"안내드리",mid:"고자",post:"",hit:!0},{pre:"메일을",mid:"",post:"",hit:!1},{pre:"드립니다.",mid:"",post:"",hit:!1}],ko:"행사 일정을 안내드리고자 메일을 드립니다.",en:"I am writing to let you know the event schedule.",romanization:"haengsa iljeongeul annaedeurigoja meireul deurimnida."},{tokens:[{pre:"본",mid:"",post:"",hit:!1},{pre:"조사는",mid:"",post:"",hit:!1},{pre:"이용자의",mid:"",post:"",hit:!1},{pre:"의견을",mid:"",post:"",hit:!1},{pre:"파악하",mid:"고자",post:"",hit:!0},{pre:"실시되었다.",mid:"",post:"",hit:!1}],ko:"본 조사는 이용자의 의견을 파악하고자 실시되었다.",en:"This survey was conducted in order to understand users' opinions.",romanization:"bon josaneun iyongjaui uigyeoneul paakagoja silsidoeeotda."}],rule:{name:"V-고자",rows:[{when:"Any action verb stem",add:"-고자",ex:"문의하다 → 문의하고자 (in order to enquire)"},{when:"Stating an intention",add:"V-고자 하다",ex:"도입하다 → 새 제도를 도입하고자 한다"},{when:"The opening line of a formal email",add:"V-고자 연락드렸습니다 / 메일을 드립니다",ex:"안내드리다 → 일정을 안내드리고자 메일을 드립니다"},{when:"The spoken form you are replacing",add:"-(으)려고",ex:"물어보려고 전화했어요 → 문의하고자 연락드렸습니다"}]},more:{func:"-고자 states a purpose in formal writing and official speech. It behaves exactly like -(으)려고: the person who intends and the person who acts must be the same, and it attaches only to action verbs. In email and announcements, -고자 followed by 연락드렸습니다 or 안내드립니다 is close to a fixed opening formula.",funcLead:"-고자 states a purpose in formal writing and official speech.",keyPoint:{label:"One subject, and a real intention",body:"-고자 carries the same two restrictions as -(으)려고. The intender and the doer have to be the same, and the verb has to be something you can decide to do — so an adjective or an involuntary event cannot take it. When the purpose belongs to somebody or something else, Korean switches to -도록."},pronunciation:"-고자 behaves like the plain connective -고. After a vowel-final stem nothing changes: 하고자 is [하고자] and 확인하고자 is [화긴하고자]. After an obstruent coda the ㄱ tenses, exactly as in 먹고 [먹꼬] — so 찾고자 is [찯꼬자].",pitfall:{wrong:"회사가 발전하고자 직원들이 노력했다.",right:"회사가 발전하도록 직원들이 노력했다.",explanation:"-고자, like -(으)려고, needs the intender and the doer to be the same. Here the company is what develops but the employees are what act, so the clauses have different subjects. When the goal belongs to someone else, use -도록 instead."}}},{kind:"drill",prompt:"I enquired with the department in charge in order to confirm the details.",sentence:"자세한 내용을 확인하___ 담당 부서에 문의했다.",options:[{text:"고자",ok:!0},{text:"으며",ok:!1},{text:"으나",ok:!1}],explanation:"One subject throughout — the same person confirms and enquires."},{kind:"drill",prompt:"We intend to introduce a new system from next semester.",sentence:"다음 학기부터 새로운 제도를 도입하___ 한다.",options:[{text:"으며",ok:!1},{text:"으나",ok:!1},{text:"고자",ok:!0}],explanation:"-고자 하다 states the intention itself rather than a purpose clause."},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "I am writing to let you know the event schedule."',tokens:["행사","일정을","안내드리고자","메일을","드립니다."],correct:"행사 일정을 안내드리고자 메일을 드립니다.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "This survey was conducted in order to understand users' opinions."`,tokens:["본","조사는","이용자의","의견을","파악하고자","실시되었다."],correct:"본 조사는 이용자의 의견을 파악하고자 실시되었다.",explanation:""}],canDo:"Open a formal email or report with V-고자 while keeping one subject",id:"chapter-70-b7",chapterId:"chapter-70",index:6},{kind:"pattern",title:"문법 Grammar · Nominal -(으)ㅁ",cards:[{kind:"teach",name:"Nominal -(으)ㅁ",sub:"how notices end their sentences",rows:[{when:"Stem ends in a vowel",add:"-ㅁ",ex:"하다 → 함, 바라다 → 바람"},{when:"Stem ends in a consonant",add:"-음",ex:"있다 → 있음, 없다 → 없음"},{when:"ㄹ-final stem",add:"-ㅁ (written on the ㄹ)",ex:"알다 → 앎, 만들다 → 만듦"},{when:"Closing a notice line",add:"-(으)ㅁ. / -기 바람.",ex:"제출하다 → 기한 내 제출하기 바람"},{when:"-(으)ㅁ vs -기",add:"-(으)ㅁ = a settled fact · -기 = an activity or a not-yet event",ex:"참석했음이 확인되었다 / 참석하기가 어렵다"}],examples:[{ko:"본 행사는 우천 시 취소될 수 있음.",en:"This event may be cancelled in the event of rain.",romanization:"bon haengsaneun ucheon si chwisodoel su isseum.",note:"A notice line closes on the noun form — no 습니다, no 요."},{ko:"신청자는 아래 서류를 기한 내에 제출하기 바람.",en:"Applicants are asked to submit the documents below by the deadline.",romanization:"sincheongjaneun arae seoryureul gihan naee jechulhagi baram.",note:"-기 바람 is the terse written form of -기 바랍니다."}],more:{func:"-(으)ㅁ turns a whole clause into a noun. Two places you meet it constantly: as the subject or object of verbs like 확인되다 and 밝혀지다, and as the closing of a terse notice line, where the sentence simply stops on the noun form instead of taking a polite ending.",funcLead:"-(으)ㅁ turns a whole clause into a noun.",keyPoint:{label:"-(으)ㅁ vs -기 — settled fact or activity",body:"-(으)ㅁ turns a clause into something already established, confirmed, or observed: 사실임이 밝혀졌다, 참석했음을 확인했다. -기 turns it into an activity or something not yet done: 참석하기가 어렵다, 매일 운동하기. Verbs like 밝혀지다, 확인되다, and 드러나다 take -(으)ㅁ; 바라다, 시작하다, and 어렵다 take -기."},pronunciation:"있음 is [이씀] and 없음 is [업씀]. 만들다 → 만듦 keeps the ㄻ in writing but is pronounced [만듬], and 앎 is [암].",pitfall:{wrong:"참석하기가 확인되었습니다.",right:"참석했음이 확인되었습니다.",explanation:"확인되다, 밝혀지다, and 드러나다 all report an established fact, so the clause in front of them takes -(으)ㅁ. Learners default to -기 because it is the nominalizer they met first. Keep -기 for activities and things not yet done — 참석하기가 어렵다 — and use -(으)ㅁ for what has been confirmed."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"참석하기가 확인되었습니다.",ok:!1},{text:"참석했음이 확인되었습니다.",ok:!0}],explanation:"확인되다, 밝혀지다, and 드러나다 all report an established fact, so the clause in front of them takes -(으)ㅁ. Learners default to -기 because it is the nominalizer they met first. Keep -기 for activities and things not yet done — 참석하기가 어렵다 — and use -(으)ㅁ for what has been confirmed."}],canDo:"Close a notice line with nominal -(으)ㅁ or -기 바람, and choose -(으)ㅁ over -기 after 확인되다",id:"chapter-70-b8",chapterId:"chapter-70",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two colleagues are editing a draft notice before it goes out. One of them keeps writing the way she speaks, and the other walks her through the written layer.",lines:[{speaker:"유진",ko:"공지 초안 보셨어요? 문장이 자꾸 끊겨서 좀 딱딱해요.",en:"Did you see the draft notice? The sentences keep breaking up, so it reads a bit stiff.",romanization:"gongji chotan bosyeosseoyo? munjangi jakku kkeungyeoseo jom ttakttakaeyo."},{speaker:"지원",ko:"네. '접수는 온라인으로 합니다. 그리고 서류는 방문 제출도 됩니다.' 이 두 문장을 하나로 합치면 어때요?",en:'Right. "Applications are taken online. And documents can also be handed in in person." How about merging those two?',romanization:"ne. 'jeopsuneun onnaineuro hamnida. geurigo seoryuneun bangmun jechuldo doemnida.' i du munjangeul hanaro hapchimyeon eottaeyo?"},{speaker:"유진",ko:"'접수는 온라인으로 하며, 서류는 방문 제출도 가능하다'로 가죠.",en:`Let's go with "Applications are taken online, and documents may also be handed in in person."`,romanization:"'jeopsuneun onnaineuro hamyeo, seoryuneun bangmun jechuldo ganeunghada'ro gajyo."},{speaker:"지원",ko:"좋네요. 그다음 문장은 '기한이 지났습니다. 그래서 접수가 안 됩니다'인데요.",en:`Nice. The next one is "The deadline has passed. So we can't accept it."`,romanization:"jonneyo. geudaeum munjangeun 'gihani jinatseumnida. geuraeseo jeopsuga an doemnida'indeyo."},{speaker:"유진",ko:"공지에서는 '기한이 지났으므로 접수되지 않음'이 자연스러워요.",en:'In a notice, "As the deadline has passed, it will not be accepted" reads more naturally.',romanization:"gongjieseoneun 'gihani jinasseumeuro jeopsudoeji aneum'i jayeonseureowoyo."},{speaker:"지원",ko:"아, 끝을 '-음'으로 닫는 거군요. 그럼 마지막 줄은요?",en:"Ah, so you close it on -음. Then what about the last line?",romanization:"a, kkeuteul '-eum'euro danneun geogunyo. geureom majimak jureunnyo?"},{speaker:"유진",ko:"'서류를 기한 내에 제출하기 바람'으로 하면 됩니다. 안내드리고자 쓴 글이니까 너무 차갑지 않게요.",en:`"Documents are to be submitted by the deadline" will do. It's written to inform people, so let's keep it from sounding cold.`,romanization:"'seoryureul gihan naee jechulhagi baram'euro hamyeon doemnida. annaedeurigoja sseun geurinikka neomu chagapji ankeyo."},{speaker:"지원",ko:"알겠습니다. 문장 사이는 '따라서'로, 문장 안은 '-며'랑 '-므로'로 정리할게요.",en:"Got it. Between sentences I'll use 따라서, and inside sentences -며 and -므로.",romanization:"algetseumnida. munjang saineun 'ttaraseo'ro, munjang aneun '-myeo'rang '-meuro'ro jeongnihalgeyo."}]},{kind:"order",prompt:"Build: 'As the deadline has passed, this application will not be accepted.' (Start with 제출 기한이.)",tokens:["제출 기한이","지났으므로","이번 신청은","접수되지 않는다"],correct:"제출 기한이 지났으므로 이번 신청은 접수되지 않는다",explanation:"The reason clause comes first and the result second — the standard order for a written rule."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"네. '접수는 온라인으로 합니다. 그리고 서류는 방문 제출도 됩니다.' 이 두 문장을 하나로 합치면 어때요?",options:[{text:"유진",ok:!1},{text:"지원",ok:!0}],explanation:'Right. "Applications are taken online. And documents can also be handed in in person." How about merging those two?'},{kind:"drill",prompt:'무엇이 들어갈까요? · "Did you see the draft notice? The sentences keep breaking up, so it reads a bit stiff."',sentence:"___ 초안 보셨어요? 문장이 자꾸 끊겨서 좀 딱딱해요.",options:[{text:"공지",ok:!0},{text:"안내",ok:!1},{text:"신청",ok:!1}],explanation:""}],canDo:"Join two clauses inside one sentence with -(으)며 for parallel facts and simultaneity",id:"chapter-70-b9",chapterId:"chapter-70",index:8},{kind:"reading",title:"읽기 Reading · 시설 이용 안내",cards:[{kind:"read",title:"시설 이용 안내",chunks:["본 도서관은 다음 달부터 새 운영 시간을 적용하며, 주말 개관 시간도 함께 변경된다. 평일은 오전 아홉 시에 문을 열어 오후 열 시에 닫으나, 주말에는 오후 여섯 시에 닫는다. 열람실은 좌석 예약제로 운영되므로 이용 전에 반드시 좌석을 신청해야 한다.","자료 대출 기한은 기존과 동일하며, 연장은 한 번만 가능함. 공사 중인 삼 층은 당분간 이용할 수 없음. 자세한 내용을 확인하고자 하는 이용자는 안내 데스크에 문의하기 바람."],translation:"From next month this library will apply new opening hours, and the weekend opening times change as well. On weekdays it opens at nine in the morning, but at weekends it closes at six in the evening. The reading room runs on a seat-reservation basis, so you must book a seat before using it. The loan period for materials is unchanged, and one renewal is permitted. The third floor, which is under construction, cannot be used for the time being. Users who wish to confirm the details are asked to enquire at the information desk.",qas:[{q:"평일과 주말의 닫는 시간이 어떻게 달라요?",a:"평일은 오후 열 시에 닫고, 주말에는 오후 여섯 시에 닫아요. 안내문에서는 '닫으나'로 두 경우를 대조했어요."},{q:"열람실을 이용하기 전에 무엇을 해야 해요?",a:"좌석 예약제로 운영되므로 먼저 좌석을 신청해야 해요."},{q:"안내문의 마지막 문장은 왜 '-기 바람'으로 끝나요?",a:"공지문에서는 '-기 바랍니다'를 짧게 줄여 '-기 바람'으로 닫기 때문이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"본 도서관은 다음 달부터 새 운영 시간을 적용하며, 주말 개관 시간도 함께 ___된다.",options:[{text:"공지",ok:!1},{text:"변경",ok:!0},{text:"접수",ok:!1}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"열람실은 좌석 예약제로 운영되므로 이용 전에 반드시 좌석을 ___해야 한다.",options:[{text:"공지",ok:!1},{text:"접수",ok:!1},{text:"신청",ok:!0}],explanation:""}],canDo:"Contrast inside a sentence with -(으)나, adding 으 only after a consonant",id:"chapter-70-b10",chapterId:"chapter-70",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Join into one written sentence: '값이 쌉니다. 그리고 품질도 좋습니다.'",sentence:null,options:[{text:"값이 싸며 품질도 좋다.",ok:!0},{text:"값이 싸으며 품질도 좋다.",ok:!1},{text:"값이 싸므로 품질도 좋다.",ok:!1}],explanation:"싸다 ends in a vowel, so it takes plain -며. -(으)므로 would claim the low price causes the quality, which is a different meaning."},{kind:"drill",prompt:"Which is the correct written contrast for '예산은 늘었지만 인력은 그대로예요'?",sentence:null,options:[{text:"예산은 늘었으나 인력은 그대로이다.",ok:!0},{text:"예산은 늘었나 인력은 그대로이다.",ok:!1},{text:"예산은 늘었으며 인력은 그대로이다.",ok:!1}],explanation:"After the past marker 었 the ending takes 으: 늘었으나. -(으)며 would list the two as parallel facts instead of contrasting them."},{kind:"drill",prompt:"Which sentence means 'he succeeded BY making an effort' (method, not reason)?",sentence:null,options:[{text:"그는 노력함으로써 성공했다.",ok:!0},{text:"그는 노력했으므로 성공했다.",ok:!1},{text:"그는 노력하고자 성공했다.",ok:!1}],explanation:"-(으)ㅁ으로써 states the means. -(으)므로 states the reason, and -고자 states a purpose, which cannot sit in front of a completed result."},{kind:"drill",prompt:"Which one does 확인되다 require in front of it?",sentence:null,options:[{text:"참석했음이",ok:!0},{text:"참석하기가",ok:!1},{text:"참석하고자",ok:!1}],explanation:"확인되다, 밝혀지다, and 드러나다 report a settled fact, so they take -(으)ㅁ. -기 is for activities and things not yet done."},{kind:"drill",prompt:"응답자의 절반이 제도 변경을 모르고 있음___ 확인되었다.",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"확인되다 is passive, so the nominalised clause is its subject and takes 이/가: 있음이 확인되었다."},{kind:"drill",prompt:"Which sentence uses -(으)며 correctly for two things happening at once?",sentence:null,options:[{text:"회의 자료를 보며 다음 일정을 검토했다.",ok:!0},{text:"회의를 마치며 자료를 배포했다.",ok:!1},{text:"회의를 하며 어제 자료를 만들었다.",ok:!1}],explanation:"-(으)며 means the two things overlap in time. 마치며 would wrongly mean 'after finishing', and 어제 in the third option puts the two clauses in different timeframes."}],canDo:"State a written reason with -(으)므로 and keep it apart from -(으)ㅁ으로(써)",id:"chapter-70-b11",chapterId:"chapter-70",index:10}]},{id:"chapter-71",number:71,title:"News passives · -적(的)",goal:"Read the news passives — 밝혀지다, 알려지다, 전해지다, 예상되다 — and see who has been left out of the sentence.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 기사~",cards:[{kind:"guess",word:{ko:"기사",romanization:"gisa",en:"(news) article, report",pos:"noun",nuance:"기사 (記事, 記 'record/write down' + 事 'matter, event') means a news article or report — a single written piece of journalism in a newspaper, magazine, or online; the hanja literally means 'a written record of an event'. Distinguish it carefully from neighbors: 언론 is the press as an institution, 보도 (報道) is the ACT of reporting, and 기사 is the concrete written unit of content that results. A crucial English-speaker pitfall is the homonym trap: 기사 is also a completely separate word meaning 'driver' (司機/운전기사) — and historically 'knight' (騎士) — so 택시 기사 is 'taxi driver', not 'taxi article'; only context tells which 기사 is meant. Natural collocations: 기사를 쓰다, 기사가 나다, 신문 기사, 기사를 검색하다. Don't reach for 기사 when you mean the abstract media institution — that is 언론."},sentence:{ko:"그 기사에 따르면 제도가 올해 안에 바뀔 가능성이 높다.",en:"According to the article, the system is likely to change within the year."},target:"기사",options:["(news) article, report","announcement","result, findings"],note:"N에 따르면 plus 가능성이 높다 — two news frames in one sentence."},{kind:"guess",word:{ko:"보도",romanization:"bodo",en:"news coverage, reporting",pos:"noun",nuance:"보도 is Sino-Korean, 步道, literally 'step-road' (步 walk + 道 road) — the formal name for the pedestrian walkway beside a street, identical in meaning to 인도 (人道, 'person-road'). The dividing line between the two is register and channel: 보도 dominates official signage and traffic law (보도 침범 = encroaching on the sidewalk), while 인도 is what people more often say in casual speech; both are correct. Its true opposite is 차도 (車道, 'car-road', the roadway). The everyday compound 보도블록 (the tiled paving blocks) comes up constantly in complaints about uneven sidewalks. The big English-speaker pitfall is a homograph collision: another 보도 means 'news report' (報道, as in 언론 보도 = press coverage) — same hangul, different hanja — so a sentence about 보도 could be about pavement or the press, and only context tells them apart. Also note British 'pavement' = American 'sidewalk' = 보도; don't read it as the road surface."},sentence:{ko:"해당 내용은 어제 여러 매체를 통해 보도됐다.",en:"The matter was reported yesterday across several outlets."},target:"보도",options:["announcement","result, findings","news coverage, reporting"],note:"보도되다 is the 되다 passive: the outlets do it, but they are not the subject."},{kind:"guess",word:{ko:"발표",romanization:"balpyo",en:"announcement",pos:"noun",nuance:"발표(發表)는 '필 발 + 겉 표', 곧 '안에 있던 것을 겉으로 드러내 알림'이라는 뜻으로, 여러 사람 앞에서 자기 생각이나 조사한 내용을 말로 알리는 것을 가리켜요. 비슷한 '연설'은 정치인·대표가 청중에게 행하는 더 공식적이고 일방적인 말하기라 학교 과제에는 안 어울리고, '공지'는 '날짜·결과를 알리는 통보'라 말로 설명하는 발표와 다르며, '보고'는 윗사람에게 결과를 전달하는 데 초점이 있어요. 그래서 학생이 수업에서 하는 것은 '발표'가 딱 맞아요. '발표하다' 동사와 '발표를 하다' 형태가 둘 다 자연스럽고, '발표 준비/자료/순서'와 잘 어울려요. 한 가지 더, '합격자 발표'처럼 결과를 공표한다는 뜻도 있어 영어 announce와 겹치지만, 수업 맥락에서는 말로 설명하는 presentation을 뜻한다는 점을 구분하세요."},sentence:{ko:"새 정책은 다음 주 월요일에 발표될 것으로 알려졌다.",en:"The new policy is understood to be announced next Monday."},target:"발표",options:["(news) article, report","news coverage, reporting","announcement"],note:"-(으)ㄹ 것으로 알려졌다: reported, but not confirmed by the paper."},{kind:"guess",word:{ko:"밝히다",romanization:"balkida",en:"to state, to reveal",pos:"verb"},sentence:{ko:"정부는 지원을 확대하겠다고 밝혔다.",en:"The government stated that it will expand support."},target:"밝혔",options:["(news) article, report","to state, to reveal","news coverage, reporting"],note:"-다고 밝혔다 is how news quotes an official statement. Its passive is 밝혀지다."},{kind:"guess",word:{ko:"결과",romanization:"gyeolgwa",en:"result, findings",pos:"noun",nuance:"결과 (結果, literally '結 form/bear + 果 fruit', i.e. the fruit that an action bears) is the end outcome of an action or event, and it almost always pairs with 나오다 (come out) or 나타나다 (appear) rather than any verb of 'making'. Its built-in partner is 과정 (the process leading up to it) and its mirror image is 원인 (the cause behind it), so Koreans constantly say 과정도 중요하고 결과도 중요하다. Register is neutral — fine in a doctor's office (검사 결과), a classroom (시험 결과), or a news report. The big English-speaker trap is twofold: first, you do not 'get' a result with a transitive verb the way English does — the result 나오다 (comes out) on its own and takes 이/가, so 결과를 나오다 is wrong; second, do not confuse the outcome 결과 with the reason 원인/이유 — 결과 is what happened at the end, never why."},sentence:{ko:"조사 결과 이용자 만족도가 지난해보다 높아진 것으로 나타났다.",en:"The survey found that user satisfaction had risen compared with last year."},target:"결과",options:["result, findings","(news) article, report","news coverage, reporting"],note:"N 결과 with no particle is itself a compressed news frame."},{kind:"guess",word:{ko:"정부",romanization:"jeongbu",en:"the government",pos:"noun",nuance:"정부 (政府, 政 'governing/administration' + 府 'office/seat of authority' — literally the 'office of governance') is the government as the concrete administrative body that runs the state. The contrast to lock in is 정부 vs 정치: 정부 is the institution/body, while 정치 (politics) is the activity and field — '정부가 발표했어요' (the body announced) but '정치에 관심 없어요' (not interested in the field). A grammar point unique to organizational subjects: Korean lets you mark 정부 as the actor with 에서 as well as 가 — both 정부에서 발표했어요 and 정부가 발표했어요 are correct, with 에서 feeling a touch more formal/institutional. Pair 정부 with official verbs: 발표하다, 결정하다, 지원하다, 추진하다."},sentence:{ko:"정부에 따르면 이번 조치는 내년 상반기에 시행된다.",en:"According to the government, this measure takes effect in the first half of next year."},target:"정부",options:["(news) article, report","the government","news coverage, reporting"],note:"N에 따르면 introduces the source, and 시행되다 keeps the actor out."},{kind:"guess",word:{ko:"확대",romanization:"hwakdae",en:"expansion, widening",pos:"noun",nuance:"확대 uses 대 as big: the thing becomes larger in size or scope."},sentence:{ko:"지원 대상이 다음 달부터 확대된다.",en:"The range of recipients expands from next month."},target:"확대",options:["expansion, widening","(news) article, report","news coverage, reporting"],note:"확대하다 is transitive; a thing that expands on its own takes 확대되다."},{kind:"payoff",line:{speaker:"유진",ko:"이 헤드라인 좀 보세요. '정부, 내년부터 지원 대상 확대'. 조사가 하나도 없네요.",en:`Look at this headline: "Government to expand eligibility from next year." There isn't a single particle.`},hl:"정부"}],canDo:"Read the news passives 밝혀지다, 알려지다, 전해지다, 예상되다 and judge how confirmed the claim is",id:"chapter-71-b1",chapterId:"chapter-71",index:0},{kind:"pattern",title:"문법 Grammar · News passives",cards:[{kind:"teach",name:"News passives",sub:"밝혀지다, 알려지다, 전해지다",rows:[{when:"Sino-Korean noun + 되다",add:"N되다",ex:"발표 → 새 정책이 발표됐다 (a new policy was announced)"},{when:"Verb of knowing or telling + -아/어지다",add:"V-아/어지다",ex:"밝히다 → 원인이 밝혀졌다 (the cause was uncovered)"},{when:"Hedged report — 'it is understood that'",add:"-(으)ㄴ/는 것으로 알려졌다",ex:"검토하다 → 검토 중인 것으로 알려졌다"},{when:"Forecast",add:"-(으)ㄹ 것으로 예상된다 / 전망된다",ex:"오르다 → 가격이 오를 것으로 전망된다"},{when:"Naming the source",add:"N에 따르면 … -다고 밝혔다",ex:"정부 → 정부에 따르면 지원이 확대된다고 밝혔다"}],examples:[{ko:"조사 결과 사고의 원인이 정비 불량으로 밝혀졌다.",en:"The investigation found that the cause of the accident was poor maintenance.",romanization:"josa gyeolgwa sagoui wonini jeongbi bullyangeuro balkyeojyeotda.",note:"밝혀지다 reports a finding; nobody is named as having found it."},{ko:"해당 기업은 내년부터 생산 시설을 확대할 것으로 알려졌다.",en:"The company is understood to be expanding its production facilities from next year.",romanization:"haedang gieobeun naenyeonbuteo saengsan siseoreul hwakdaehal geoseuro allyeojyeotda.",note:"-(으)ㄹ 것으로 알려졌다 is the standard hedge: reported, but not confirmed."}],more:{func:"Journalism reports what is known without naming who knows it. Alongside the -이/히/리/기- passives you have already met, news Korean leans on two other families: 되다 attached to a Sino-Korean noun (발표되다, 예상되다, 확인되다), and -아/어지다 attached to a verb of knowing or telling (밝혀지다, 알려지다, 전해지다). The source, when it appears at all, comes in as N에 따르면.",funcLead:"Journalism reports what is known without naming who knows it.",keyPoint:{label:"The passive is doing editorial work",body:"밝혀졌다 and 알려졌다 are not just grammar — they mark how solid the claim is. 확인됐다 means verified; 밝혀졌다 means uncovered by an investigation; 알려졌다 means reported but not confirmed, and is what a paper writes when it does not want to vouch for the claim. Reading the passive tells you how much the writer is willing to stand behind."},pronunciation:"밝혀지다 is [발켜지다]: the ㄺ of 밝 and the ㅎ of 혀 fuse into an aspirated [ㅋ], exactly as in 읽히다 [일키다]. 알려졌다 is [알려젇따] and 전해졌다 is [전해젇따].",pitfall:{wrong:"정부에 의하면 지원이 확대한다.",right:"정부에 따르면 지원이 확대된다.",explanation:"Two slips in one line. 확대하다 is transitive — something expands something else — so a subject like 지원 needs the passive 확대되다. And while 에 의하면 exists, everyday news Korean uses N에 따르면 for 'according to'; 에 의해 is reserved for naming the agent of a passive."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"정부에 따르면 지원이 확대된다.",ok:!0},{text:"정부에 의하면 지원이 확대한다.",ok:!1}],explanation:"Two slips in one line. 확대하다 is transitive — something expands something else — so a subject like 지원 needs the passive 확대되다. And while 에 의하면 exists, everyday news Korean uses N에 따르면 for 'according to'; 에 의해 is reserved for naming the agent of a passive."}],canDo:"Read the news passives 밝혀지다, 알려지다, 전해지다, 예상되다 and judge how confirmed the claim is",id:"chapter-71-b2",chapterId:"chapter-71",index:1},{kind:"words",title:"단어 Words 2 · 증가~",cards:[{kind:"guess",word:{ko:"증가",romanization:"jeungga",en:"increase",pos:"noun"},sentence:{ko:"이용객 수가 지난해보다 증가한 것으로 나타났다.",en:"Passenger numbers were found to have risen compared with last year."},target:"증가",options:["(news) article, report","increase","news coverage, reporting"],note:"-(으)ㄴ 것으로 나타나다: 'was found to have', a standard reporting frame."},{kind:"guess",word:{ko:"감소",romanization:"gamso",en:"decrease",pos:"noun"},sentence:{ko:"생산 공정이 자동화되면서 인력 수요가 크게 감소했다.",en:"As the production process was automated, demand for workers fell sharply."},target:"감소",options:["(news) article, report","decrease","news coverage, reporting"],note:"자동화되다 and 감소하다 — the 화 suffix and its usual consequence."},{kind:"guess",word:{ko:"전망",romanization:"jeonmang",en:"outlook, forecast",pos:"noun"},sentence:{ko:"올해 물가가 더 오를 것으로 전망된다.",en:"Prices are forecast to rise further this year."},target:"전망",options:["(news) article, report","outlook, forecast","news coverage, reporting"],note:"-(으)ㄹ 것으로 전망된다 is the fixed forecast frame."},{kind:"guess",word:{ko:"예정",romanization:"yejeong",en:"scheduled, planned",pos:"noun"},sentence:{ko:"복구 작업은 이달 말까지 이어질 예정이다.",en:"Recovery work is scheduled to continue until the end of this month."},target:"예정",options:["(news) article, report","news coverage, reporting","scheduled, planned"],note:"-(으)ㄹ 예정이다 states a plan; notices shorten it to 예정임."},{kind:"guess",word:{ko:"가능성",romanization:"ganeungseong",en:"possibility, likelihood",pos:"noun",nuance:"가능성 is a noun, so it pairs with 있다, 없다, 높다, and 낮다. It is a little more formal than just saying -ㄹ지도 몰라요."},sentence:{ko:"제도가 올해 안에 바뀔 가능성이 높다.",en:"The system is likely to change within the year."},target:"가능성",options:["(news) article, report","news coverage, reporting","possibility, likelihood"],note:"가능성 pairs with 높다, never 크다."},{kind:"guess",word:{ko:"필요성",romanization:"piryoseong",en:"necessity, the need for something",pos:"noun"},sentence:{ko:"안전 기준 강화의 필요성이 크다는 지적이 이어지고 있다.",en:"Criticism continues that there is a strong need to tighten safety standards."},target:"필요성",options:["necessity, the need for something","(news) article, report","news coverage, reporting"],note:"필요성 takes 크다, unlike 가능성, which takes 높다."},{kind:"guess",word:{ko:"경제",romanization:"gyeongje",en:"the economy",pos:"noun",nuance:"경제 (經濟, 經 'manage/govern' + 濟 'aid/relieve' — from 經世濟民 'govern the world and relieve the people') means 'the economy' as a system. The biggest learner trap is the adjective 경제적이다, which splits into TWO everyday meanings: (1) 'economical', i.e. money-saving (버스가 더 경제적이에요), and (2) 'economic/financial' (경제적 부담 = financial burden) — context decides which. Equally important is the slump idiom: to say the economy is doing badly, Korean uses 경제가 어렵다 or 경제가 안 좋다, NOT a literal 경제가 나쁘다, because 어렵다 ('hard, strained') is the conventional collocation. Keep 경제 (the system/field) distinct from 경영 (經營, business management of a company); they look similar but 경영 is running a firm."},sentence:{ko:"물가 상승이 가계에 경제적 부담을 주고 있다.",en:"Rising prices are placing an economic burden on households."},target:"경제",options:["(news) article, report","the economy","news coverage, reporting"],note:"경제적 with no 인 — the compressed modifier form of written Korean."}],canDo:"Use N에 따르면 to cite a source and -(으)ㄹ 것으로 알려졌다 to hedge a report",id:"chapter-71-b3",chapterId:"chapter-71",index:2},{kind:"pattern",title:"문법 Grammar · -적(的)",cards:[{kind:"teach",name:"-적(的)",sub:"turning a noun into a modifier",rows:[{when:"Before a noun — terse, written",add:"N적 + N",ex:"경제 → 경제적 부담 (an economic burden)"},{when:"Before a noun — slightly softer",add:"N적인 + N",ex:"구체 → 구체적인 방안 (a concrete plan)"},{when:"As an adverb",add:"N적으로",ex:"사회 → 사회적으로 (socially, in social terms)"},{when:"As a predicate",add:"N적이다",ex:"적극 → 반응이 적극적이다 (the response is enthusiastic)"},{when:"Native Korean words cannot take it",add:"✗ N적",ex:"마음 → 마음적 ✗ / 정신적 ✓"}],examples:[{ko:"이번 조치는 일시적인 대책일 뿐이라는 비판이 나왔다.",en:"Criticism emerged that this measure is nothing more than a temporary fix.",romanization:"ibeon jochineun ilsijeogin daechaegil ppuniraneun bipani nawatda.",note:"일시적 (temporary) is one of the highest-frequency 적 words in news."},{ko:"정부는 보다 구체적 방안을 다음 주에 내놓기로 했다.",en:"The government decided to put forward a more concrete plan next week.",romanization:"jeongbuneun boda guchejeok bangeaneul daeum jue naenokiro haetda.",note:"구체적 방안 with no 인 — the compressed form that headlines and reports prefer."}],more:{func:"-적 attaches to a Sino-Korean noun and turns it into something that can describe: 경제 (economy) becomes 경제적 (economic). It has three shapes with different weights — N적 directly before a noun is the terse written form, N적인 is slightly softer, and N적으로 works as an adverb. It attaches only to Sino-Korean roots, never to native Korean words.",funcLead:"-적 attaches to a Sino-Korean noun and turns it into something that can describe: 경제 (economy) becomes 경제적 (economic).",keyPoint:{label:"N적 vs N적인 — how much you compress",body:"Both sit in front of a noun and mean the same thing. Bare N적 is denser and belongs to headlines, reports, and academic prose: 경제적 부담, 구체적 방안. N적인 is a little more relaxed and is what you would say out loud: 경제적인 부담. If you are unsure in speech, 적인 is the safer choice; in a written report, drop the 인."},pronunciation:"적 is [적], and before a vowel it links: 경제적인 is [경제저긴], 사회적으로 is [사회저그로], 긍정적이었다 is [긍정저기얻따].",pitfall:{wrong:"마음적 부담이 크다.",right:"정신적 부담이 크다.",explanation:"-적 attaches only to Sino-Korean roots. 마음 is a native Korean word, so 마음적 does not exist; the Sino-Korean equivalent 정신 gives 정신적. When you want a 적 word, check that the base is a Sino-Korean noun — 경제, 사회, 정신, 구체 — not a native one like 마음, 몸, or 일."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"마음적 부담이 크다.",ok:!1},{text:"정신적 부담이 크다.",ok:!0}],explanation:"-적 attaches only to Sino-Korean roots. 마음 is a native Korean word, so 마음적 does not exist; the Sino-Korean equivalent 정신 gives 정신적. When you want a 적 word, check that the base is a Sino-Korean noun — 경제, 사회, 정신, 구체 — not a native one like 마음, 몸, or 일."},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Before a noun — terse, written",sentence:"경제___",options:[{text:"적인 방안",ok:!1},{text:"적 부담",ok:!0},{text:"적으로",ok:!1}],explanation:"경제 → 경제적 부담 (an economic burden)"},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — Before a noun — slightly softer",sentence:"구체___",options:[{text:"적 부담",ok:!1},{text:"적으로",ok:!1},{text:"적인 방안",ok:!0}],explanation:"구체 → 구체적인 방안 (a concrete plan)"}],canDo:"Use N에 따르면 to cite a source and -(으)ㄹ 것으로 알려졌다 to hedge a report",id:"chapter-71-b4",chapterId:"chapter-71",index:3},{kind:"words",title:"단어 Words 3 · 사회~",cards:[{kind:"guess",word:{ko:"사회",romanization:"sahoe",en:"society",pos:"noun",nuance:"사회 (社會, 社 'community/shrine-group' + 會 'gathering') means 'society' as the whole body of people living together, and as a noun-modifier it stacks directly: 현대 사회, 사회 문제, 사회 복지. The trap for English speakers is 사회생활: it does NOT mean 'social life / hanging out', but working life and managing adult/workplace relationships, so 사회생활을 잘하다 praises someone for handling colleagues and obligations well. Contrast 사회 with 모임 — a 모임 is one concrete small gathering (study group, dinner club), while 사회 is the abstract collective; never use 사회 for 'a get-together'. The particle to learn is 에 for location-of-existence (사회에 문제가 있다), not 에서, when you simply say something exists in society."},sentence:{ko:"인구 고령화는 사회적으로도 큰 변화를 가져온다.",en:"Population ageing brings large changes socially as well."},target:"사회",options:["society","(news) article, report","news coverage, reporting"],note:"-적으로 turns the modifier into an adverb: 'in social terms'."},{kind:"guess",word:{ko:"변화",romanization:"byeonhwa",en:"change",pos:"noun",nuance:"변화 (變化, '變 to alter + 化 to transform' — alteration-and-transformation) is the noun 'change', used for shifts in states, trends, weather, society, technology, or one's life, and it is more abstract and global than the plain verb 변하다/바뀌다 (a specific thing changes). Distinguish 변화를 주다 ('introduce/make a change', usually for freshness or variety) from 변화가 생기다 ('a change occurs' on its own), and mark what you adapt to with 에 (변화에 적응하다). The subtle English-speaker pitfall is reaching for 변화하다 as the verb for everyday change: 변화하다 exists but sounds formal/scientific ('the climate is changing' 기후가 변화하다), so for ordinary 'something changed' use 변하다 or 바뀌다 (전화번호가 바뀌었어요 'my number changed'), and reserve 변화 for the noun. Compare 발전 (發展, development/progress — change specifically in a better, advancing direction), which carries positive growth that neutral 변화 does not."},sentence:{ko:"제도 변화가 시장에 미칠 영향이 주목되고 있다.",en:"The effect the change in the system will have on the market is drawing attention."},target:"변화",options:["(news) article, report","news coverage, reporting","change"],note:"변화 is itself a 화 word: 변 plus 화, 'becoming different'."},{kind:"guess",word:{ko:"영향",romanization:"yeonghyang",en:"effect, influence",pos:"noun",nuance:"영향 (影響, '影 shadow + 響 echo' — a shadow-and-echo that one thing casts onto another) is influence or impact, and it crucially works in two opposite directions you must keep straight: the source 영향을 주다 / 미치다 (gives/exerts an effect) while the recipient 영향을 받다 (receives/is affected). 미치다 is the formal, news-and-essay verb for 'exert an effect', whereas 주다 is everyday conversation. The decisive English-speaker trap is the particle: the affected target is marked with 에 (for things — 환경에 영향을 주다) or 에게/께 (for people — 아이들에게/부모님께 영향을 주다), NOT with 을/를, because the actual object slot is already filled by 영향(을). So 'it affects the environment' is 환경에 영향을 줘요, never 환경을 영향을 줘요. Compare 효과 (效果, the resulting effect/efficacy of a measure, e.g. 약의 효과 'the medicine's effect'): 영향 is the act of influencing, 효과 is the beneficial result that comes out."},sentence:{ko:"이번 조치가 물가에 미친 영향은 아직 크지 않은 것으로 분석됐다.",en:"The effect of this measure on prices is analysed as not yet significant."},target:"영향",options:["(news) article, report","effect, influence","news coverage, reporting"],note:"영향을 미치다 is the fixed collocation, not 영향을 주다 in formal writing."},{kind:"guess",word:{ko:"시장",romanization:"sijang",en:"market",pos:"noun",nuance:"시장 (市場, 'market-place/field') is an open traditional market: rows of small independent stalls selling produce, fish, side dishes and clothes, where prices are flexible and you can haggle. The dividing line from its near-synonym 마트 is atmosphere and pricing — 마트 is a single fixed-price corporate store, while 시장 is many vendors and bargaining (깎다) is normal. Don't confuse it with 장 alone (which in 장을 보다 / 장날 means the shopping or market-day event) or with the homophone 시장 (市長, 'mayor'); only context tells them apart. The classic English-speaker trap is the particle: you say 시장에 가요 for *going there* (에 = destination) but 시장에서 사요 for *buying there* (에서 = where the action happens), and English 'go shopping' becomes the fixed idiom 시장을 보다, using 보다 'see', never 사다."},sentence:{ko:"시장에서는 가격이 더 오를 것으로 예상된다는 반응이 나왔다.",en:"The market reaction was that prices are expected to rise further."},target:"시장",options:["(news) article, report","news coverage, reporting","market"],note:"예상되다 keeps the forecaster anonymous — standard in market reporting."},{kind:"guess",word:{ko:"가격",romanization:"gagyeok",en:"price",pos:"noun",nuance:"가격(價格) is Sino-Korean — 價 'value/price' + 格 'standard' — so it literally means the 'value-standard' set on a thing, the official posted price. Its native-Korean twin is 값, and the line is feel and register: 값 is shorter, warmer, and used in fixed everyday phrases (값이 싸다, 값을 치르다), while 가격 sounds more neutral and 'tag/system' (가격표 price tag, 가격 인상 price hike) and is what you read on signs. The biggest English-speaker trap is the adjective: a high price is 비싸요 (expensive), a low price is 싸요 (cheap) — Koreans do NOT say 가격이 높아요/낮아요 the way English says 'high/low price', so importing 'high' here sounds off. Note too that to ask a clerk you rarely say the noun at all: the natural line is just 얼마예요? ('how much?'). 가격 collocates with 비싸다, 싸다, 오르다 (rise), 내리다 (drop), and 깎다 (haggle down)."},sentence:{ko:"원자재 가격이 오르면서 제품 가격도 인상될 전망이다.",en:"As raw material prices rise, product prices are also expected to be raised."},target:"가격",options:["(news) article, report","price","news coverage, reporting"],note:"인상되다 is the formal passive of 인상하다; news avoids the plain 오르다 for deliberate rises."},{kind:"guess",word:{ko:"지역",romanization:"jiyeok",en:"region, area",pos:"noun",nuance:"지역 is Sino-Korean 地域 ('land/earth' 地 + 'boundary/territory' 域), a bounded geographic area, and by extension the 지역 사회 (local community). Two contrasts matter. Against 지방(地方) 'the provinces': 지역 is any neutral region (수도권 지역 included), whereas 지방 specifically means everywhere OUTSIDE Seoul (지방에 살다 = to live in the provinces), often with a center-vs-rest nuance. Against 동네: 지역 is formal/administrative (지역 경제, 지역 주민), while 동네 is your warm, familiar block where neighbors know you. Register is neutral-formal, common in news and policy. English-speaker pitfall: 'I'm from the countryside/regions' becomes 지방, not 지역; and your cozy neighborhood is 동네, so '우리 동네' (my neighborhood) sounds natural where '우리 지역' would feel like a press release."},sentence:{ko:"피해가 큰 지역부터 복구 작업이 본격화될 예정이다.",en:"Recovery work is scheduled to begin in earnest in the worst-hit areas first."},target:"지역",options:["(news) article, report","news coverage, reporting","region, area"],note:"본격화되다 plus -(으)ㄹ 예정이다 — two news frames stacked."}],canDo:"Build and read -적 modifiers, -화 processes, and -성 abstract nouns with their fixed partners",id:"chapter-71-b5",chapterId:"chapter-71",index:4},{kind:"pattern",title:"문법 Grammar · -화(化)",cards:[{kind:"teach",name:"-화(化)",sub:"the '-ization' suffix",rows:[{when:"The process itself, as a noun",add:"N화",ex:"자동 → 자동화 (automation)"},{when:"Something undergoes it",add:"N화되다",ex:"고령 → 사회가 고령화되다 (society ages)"},{when:"Someone brings it about",add:"N화하다",ex:"다양 → 상품을 다양화하다 (to diversify the products)"},{when:"As a modifier",add:"N화된 + N",ex:"자동 → 자동화된 설비 (automated equipment)"},{when:"Frequent in the news",add:"고령화 · 국제화 · 다양화 · 본격화",ex:"본격 → 복구 작업이 본격화됐다"}],examples:[{ko:"생산 공정이 자동화되면서 인력 수요가 크게 줄었다.",en:"As the production process became automated, demand for workers fell sharply.",romanization:"saengsan gongjeongi jadonghwadoemyeonseo illyeok suyoga keuge jureotda.",note:"자동화되다 for the thing that changes; the people who automated it go unmentioned."},{ko:"인구 고령화가 빠르게 진행되고 있는 것으로 나타났다.",en:"Population ageing is found to be progressing rapidly.",romanization:"ingu goryeonghwaga ppareuge jinhaengdoego inneun geoseuro natanatda.",note:"-(으)ㄴ/는 것으로 나타나다 is another standard reporting frame."}],more:{func:"-화 turns a noun into a process of becoming: 자동 (automatic) plus 화 gives 자동화 (automation). It usually appears as a verb with 되다 — 자동화되다, 'to become automated' — and it is how Korean names any large social or technical shift, which is why news writing is full of it.",funcLead:"-화 turns a noun into a process of becoming: 자동 (automatic) plus 화 gives 자동화 (automation).",keyPoint:{label:"N화되다 vs N화하다",body:"The pair works like every other 되다/하다 split you know. N화되다 describes something undergoing the change with no agent named — 사회가 고령화되다, 공정이 자동화되다. N화하다 names somebody doing it deliberately — 상품을 다양화하다. News uses 되다 far more often, because the whole register is built on leaving the actor out."},pronunciation:"화 is [화], but after a ㄱ it aspirates: 본격화 is [본겨콰] and 자동화 stays [자동화]. 고령화 is [고령화], with no change.",pitfall:{wrong:"생산 공정이 자동화했다.",right:"생산 공정이 자동화됐다.",explanation:'English says "the process automated," using one verb for both sides. Korean splits them: the thing that undergoes the change takes N화되다, and only a deliberate actor takes N화하다. A production process does not automate itself on purpose, so it needs 자동화됐다.'}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"생산 공정이 자동화됐다.",ok:!0},{text:"생산 공정이 자동화했다.",ok:!1}],explanation:'English says "the process automated," using one verb for both sides. Korean splits them: the thing that undergoes the change takes N화되다, and only a deliberate actor takes N화하다. A production process does not automate itself on purpose, so it needs 자동화됐다.'}],canDo:"Build and read -적 modifiers, -화 processes, and -성 abstract nouns with their fixed partners",id:"chapter-71-b6",chapterId:"chapter-71",index:5},{kind:"pattern",title:"문법 Grammar · -성(性)",cards:[{kind:"teach",name:"-성(性)",sub:"the '-ness' noun, and what verbs it takes",rows:[{when:"The quality, as a noun",add:"N성",ex:"가능 → 가능성 (possibility)"},{when:"It exists or does not",add:"N성이 있다 / 없다",ex:"위험 → 위험성이 있다"},{when:"Its degree",add:"N성이 높다 / 크다",ex:"가능 → 가능성이 높다 (it is likely)"},{when:"Someone raises it as an issue",add:"N성이 제기되다",ex:"필요 → 제도 개선의 필요성이 제기됐다"},{when:"Frequent in the news",add:"안정성 · 위험성 · 중요성 · 다양성",ex:"안정 → 시설의 안정성이 확인됐다"}],examples:[{ko:"올해 안에 제도가 바뀔 가능성이 높다고 보도됐다.",en:"It was reported that the system is likely to change within the year.",romanization:"olhae ane jedoga bakkwil ganeungseongi noptago bododwaetda.",note:"가능성이 높다, not 크다 — this pairing is fixed."},{ko:"조사 이후 제도 개선의 필요성이 다시 제기됐다.",en:"After the investigation, the need for reform was raised again.",romanization:"josa ihu jedo gaeseonui piryoseongi dasi jegidwaetda.",note:"필요성이 제기되다 is how news says somebody made the case for something."}],more:{func:"-성 turns a noun or a root into an abstract quality: 가능 plus 성 gives 가능성, 'possibility'. Unlike -적 it produces a full noun, so it takes particles and pairs with a small, fixed set of predicates — 있다, 없다, 높다, 크다, 제기되다. Getting that pairing right is most of the work.",funcLead:"-성 turns a noun or a root into an abstract quality: 가능 plus 성 gives 가능성, 'possibility'.",keyPoint:{label:"-성 is a noun, -적 is a modifier",body:"The two suffixes attach to the same roots but do opposite jobs. 가능성 is a thing you can have, count, and mark with a particle: 가능성이 높다. 가능적 does not exist, but where a 적 form does — 경제적, 사회적 — it can only describe, never stand alone as a subject. If the slot needs a noun, reach for 성; if it needs a modifier, reach for 적."},pronunciation:"성 links straight into a following particle: 가능성이 is [가능성이], 필요성이 is [피료성이], 안정성에는 is [안정성에는]. 위험성을 is [위험성을].",pitfall:{wrong:"제도가 바뀔 가능성이 크다고 보도됐다.",right:"제도가 바뀔 가능성이 높다고 보도됐다.",explanation:'가능성 pairs with 높다, not 크다 — Korean measures a probability by height, not size. Learners reach for 크다 because English says "a big possibility." Compare 필요성이 크다, which does take 크다. These pairings are fixed and worth memorising as chunks.'}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"제도가 바뀔 가능성이 높다고 보도됐다.",ok:!0},{text:"제도가 바뀔 가능성이 크다고 보도됐다.",ok:!1}],explanation:'가능성 pairs with 높다, not 크다 — Korean measures a probability by height, not size. Learners reach for 크다 because English says "a big possibility." Compare 필요성이 크다, which does take 크다. These pairings are fixed and worth memorising as chunks.'},{kind:"drill",prompt:"빈칸을 채우세요 · Complete the form — It exists or does not",sentence:"위험___",options:[{text:"성이 있다",ok:!0},{text:"성이 높다",ok:!1}],explanation:"위험 → 위험성이 있다"}],canDo:"Unpack a headline by restoring the dropped particles and the deleted verb",id:"chapter-71-b7",chapterId:"chapter-71",index:6},{kind:"pattern",title:"문법 Grammar · Headline grammar",cards:[{kind:"teach",name:"Headline grammar",sub:"dropped particles and noun-final sentences",rows:[{when:"Topic marked by a comma instead of 은/는",add:"N, …",ex:"정부, 지원 대상 확대 → 정부는 지원 대상을 확대한다"},{when:"Object particle dropped",add:"(을/를 deleted)",ex:"요금 인상 검토 → 요금 인상을 검토한다"},{when:"Verb replaced by a bare noun",add:"… 확대 / 검토 / 예상",ex:"반발 예상 → 반발이 예상된다"},{when:"Ellipsis for a second, linked clause",add:"… (separates two clauses)",ex:"요금 인상 검토… 이용객 반발 예상"},{when:"Quoting without 고",add:'N, "…"라며',ex:'정부, "검토 중"이라며 확답 피해'}],examples:[{ko:"정부, 내년부터 지원 대상 확대",en:"Government to expand eligibility from next year",romanization:"jeongbu, naenyeonbuteo jiwon daesang hwakdae",note:"Unpacked: 정부는 내년부터 지원 대상을 확대한다."},{ko:"지하철 요금 인상 검토… 이용객 반발 예상",en:"Subway fare rise under review… backlash from passengers expected",romanization:"jihacheol yogeum insang geomto… iyonggaek banbal yesang",note:"Unpacked: 지하철 요금 인상을 검토한다. 이용객의 반발이 예상된다."}],more:{func:"A Korean headline is a sentence with its joints removed. Subject and object particles disappear, the verb is replaced by a bare noun or a nominal form, and a comma after the opening noun marks it as the topic. Once you know what has been deleted, you can put it back and read the headline as an ordinary sentence.",funcLead:"A Korean headline is a sentence with its joints removed.",keyPoint:{label:"Read a headline by putting the particles back",body:"Work from the end. The final noun is the verb: 확대 means 확대한다 or 확대된다, 예상 means 예상된다, 검토 means 검토한다. Then the noun before it is usually the object, so restore 을/를. Then whatever sits before the comma is the topic, so restore 은/는. 정부, 지원 대상 확대 unpacks to 정부는 지원 대상을 확대한다."},pronunciation:"Headlines are read aloud with a pause where each particle was deleted, not run together: 정부 / 지원 대상 / 확대. The ellipsis … is read as a longer pause, and it usually separates two whole clauses.",pitfall:{wrong:"정부는 지원 대상 확대한다.",right:"정부는 지원 대상을 확대한다.",explanation:"Headline Korean drops particles, but ordinary Korean does not. Learners who read a lot of headlines start deleting 을/를 in their own writing, which reads as clipped or careless. Treat the dropped particles as a headline convention only, and restore them the moment you write a full sentence."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "Government to expand eligibility from next year" (정부 시작 · Start with 정부.)',tokens:["정부,","내년부터","지원","대상","확대"],correct:"정부, 내년부터 지원 대상 확대",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"정부는 지원 대상 확대한다.",ok:!1},{text:"정부는 지원 대상을 확대한다.",ok:!0}],explanation:"Headline Korean drops particles, but ordinary Korean does not. Learners who read a lot of headlines start deleting 을/를 in their own writing, which reads as clipped or careless. Treat the dropped particles as a headline convention only, and restore them the moment you write a full sentence."}],canDo:"Keep headline ellipsis out of your own full sentences",id:"chapter-71-b8",chapterId:"chapter-71",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two colleagues are looking at the morning news on their phones. One of them is learning to read past the headline into the article underneath.",lines:[{speaker:"유진",ko:"이 헤드라인 좀 보세요. '정부, 내년부터 지원 대상 확대'. 조사가 하나도 없네요.",en:`Look at this headline: "Government to expand eligibility from next year." There isn't a single particle.`,romanization:"i hedeurain jom boseyo. 'jeongbu, naenyeonbuteo jiwon daesang hwakdae'. josaga hanado eomneyo."},{speaker:"지원",ko:"뒤에서부터 풀면 돼요. 마지막 '확대'가 동사예요. '정부는 지원 대상을 확대한다'가 되는 거죠.",en:'Unpack it from the back. The last word, 확대, is the verb. It becomes "The government will expand the range of recipients."',romanization:"dwieseobuteo pulmyeon dwaeyo. majimak 'hwakdae'ga dongsayeyo. 'jeongbuneun jiwon daesangeul hwakdaehanda'ga doeneun geojyo."},{speaker:"유진",ko:"아, 쉼표가 '은/는' 자리였군요. 그럼 본문은요?",en:"Ah, so the comma was where 은/는 goes. Then what about the body text?",romanization:"a, swimpyoga 'eun/neun' jariyeotgunyo. geureom bonmuneunnyo?"},{speaker:"지원",ko:"'정부에 따르면 지원 대상은 다음 달부터 확대된다'예요. 본문에서는 조사가 다시 살아나요.",en:'It reads "According to the government, the range of recipients expands from next month." In the body the particles come back.',romanization:"'jeongbue ttareumyeon jiwon daesangeun daeum dalbuteo hwakdaedoenda'yeyo. bonmuneseoneun josaga dasi saranayo."},{speaker:"유진",ko:"그런데 왜 '확대한다'가 아니라 '확대된다'예요?",en:"But why 확대된다 rather than 확대한다?",romanization:"geureonde wae 'hwakdaehanda'ga anira 'hwakdaedoenda'yeyo?"},{speaker:"지원",ko:"주어가 '지원 대상'이니까요. 대상이 스스로 넓히는 게 아니라 넓혀지는 거잖아요.",en:"Because the subject is 지원 대상. The scope doesn't widen anything itself — it gets widened.",romanization:"jueoga 'jiwon daesang'inikkayo. daesangi seuseuro neolpineun ge anira neolpyeojineun geojanayo."},{speaker:"유진",ko:"이해했어요. 밑에 '반발 예상'도 '반발이 예상된다'겠네요.",en:"I get it. So 반발 예상 below must be 반발이 예상된다 too.",romanization:"ihaehaesseoyo. mite 'banbal yesang'do 'banbari yesangdoenda'genneyo."},{speaker:"지원",ko:"맞아요. 그렇게 읽으면 기사 절반은 이미 읽은 거예요.",en:"Exactly. Read it that way and you're already halfway through the article.",romanization:"majayo. geureoke ilgeumyeon gisa jeolbaneun imi ilgeun geoyeyo."}]},{kind:"order",prompt:"Build: 'According to the government, eligibility expands from next month.' (Start with 정부에 따르면.)",tokens:["정부에 따르면","지원 대상은","다음 달부터","확대된다"],correct:"정부에 따르면 지원 대상은 다음 달부터 확대된다",explanation:"N에 따르면 opens the sentence with the source, and the passive 확대된다 closes it without naming an actor."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"뒤에서부터 풀면 돼요. 마지막 '확대'가 동사예요. '정부는 지원 대상을 확대한다'가 되는 거죠.",options:[{text:"지원",ok:!0},{text:"유진",ok:!1}],explanation:'Unpack it from the back. The last word, 확대, is the verb. It becomes "The government will expand the range of recipients."'},{kind:"drill",prompt:`무엇이 들어갈까요? · "Look at this headline: "Government to expand eligibility from next year." There isn't a single particle."`,sentence:"이 헤드라인 좀 보세요. '___, 내년부터 지원 대상 확대'. 조사가 하나도 없네요.",options:[{text:"기사",ok:!1},{text:"보도",ok:!1},{text:"정부",ok:!0}],explanation:""}],canDo:"Read the news passives 밝혀지다, 알려지다, 전해지다, 예상되다 and judge how confirmed the claim is",id:"chapter-71-b9",chapterId:"chapter-71",index:8},{kind:"reading",title:"읽기 Reading · 지원 대상 확대, 무엇이 달라지나",cards:[{kind:"read",title:"지원 대상 확대, 무엇이 달라지나",chunks:["정부는 내년부터 지원 대상을 확대한다고 밝혔다. 이번 조치로 약 이십만 가구가 새로 지원을 받게 될 것으로 예상된다. 물가 상승이 가계에 경제적 부담을 주고 있다는 지적이 이어지면서 제도 개선의 필요성이 꾸준히 제기돼 왔다.","다만 예산이 늘지 않아 지원 금액은 줄어들 가능성이 높다는 분석도 나온다. 신청 절차는 대부분 자동화될 예정이며, 자세한 기준은 다음 달에 발표될 것으로 알려졌다."],translation:"The government has stated that it will expand the range of support recipients from next year. Around two hundred thousand households are expected to newly receive support as a result of this measure. As criticism continued that rising prices are placing an economic burden on households, the need for reform of the system has steadily been raised. However, some analysis suggests that because the budget is not growing, the amount of support is likely to fall. The application process is scheduled to be largely automated, and the detailed criteria are understood to be announced next month.",qas:[{q:"정부는 무엇을 하겠다고 밝혔어요?",a:"내년부터 지원 대상을 확대하겠다고 밝혔어요."},{q:"지원 금액에 대해서는 어떤 분석이 나왔어요?",a:"예산이 늘지 않아서 지원 금액이 줄어들 가능성이 높다는 분석이 나왔어요."},{q:"'발표될 것으로 알려졌다'는 확정된 사실이에요?",a:"아니에요. '알려졌다'는 전해 들은 내용이라서 아직 확정되지 않았다는 뜻이에요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"___는 내년부터 지원 대상을 확대한다고 밝혔다.",options:[{text:"기사",ok:!1},{text:"보도",ok:!1},{text:"정부",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"물가 상승이 가계에 경제적 부담을 주고 있다는 지적이 이어지면서 제도 개선의 ___이 꾸준히 제기돼 왔다.",options:[{text:"기사",ok:!1},{text:"보도",ok:!1},{text:"필요성",ok:!0}],explanation:""}],canDo:"Use N에 따르면 to cite a source and -(으)ㄹ 것으로 알려졌다 to hedge a report",id:"chapter-71-b10",chapterId:"chapter-71",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Unpack the headline '정부, 내년부터 지원 대상 확대'.",sentence:null,options:[{text:"정부는 내년부터 지원 대상을 확대한다.",ok:!0},{text:"정부가 내년부터 지원 대상이 확대한다.",ok:!1},{text:"정부는 내년부터 지원 대상 확대한다.",ok:!1}],explanation:"The comma stands in for 은/는, the final noun 확대 is the verb, and the noun before it is the object, so 을 comes back."},{kind:"drill",prompt:"Which verb form does 지원 대상 need as a subject?",sentence:null,options:[{text:"확대된다",ok:!0},{text:"확대한다",ok:!1},{text:"확대하고 있다",ok:!1}],explanation:"확대하다 is transitive — somebody expands something. When the thing being expanded is the subject, the passive 확대되다 is required."},{kind:"drill",prompt:"Which predicate goes with 가능성?",sentence:null,options:[{text:"가능성이 높다",ok:!0},{text:"가능성이 크다",ok:!1},{text:"가능성이 많다",ok:!1}],explanation:"Korean measures likelihood by height: 가능성이 높다. 필요성 is the one that takes 크다."},{kind:"drill",prompt:"Which sentence signals the LEAST confirmed claim?",sentence:null,options:[{text:"다음 달에 발표될 것으로 알려졌다.",ok:!0},{text:"다음 달에 발표된다고 확인됐다.",ok:!1},{text:"다음 달에 발표된다.",ok:!1}],explanation:"알려졌다 is secondhand and unverified, 확인됐다 is verified, and a flat 발표된다 states it as settled fact."},{kind:"drill",prompt:"제도 개선의 필요성___ 다시 제기됐다.",sentence:null,options:[{text:"이",ok:!0},{text:"을",ok:!1},{text:"에",ok:!1}],explanation:"제기되다 is passive, so the thing raised is the subject and takes 이/가: 필요성이 제기됐다."},{kind:"drill",prompt:"Which one is the adverb form meaning 'socially'?",sentence:null,options:[{text:"사회적으로",ok:!0},{text:"사회적인",ok:!1},{text:"사회성",ok:!1}],explanation:"-적으로 makes the adverb, -적인 makes a modifier before a noun, and -성 makes an abstract noun."}],canDo:"Build and read -적 modifiers, -화 processes, and -성 abstract nouns with their fixed partners",id:"chapter-71-b11",chapterId:"chapter-71",index:10}]},{id:"chapter-72",number:72,title:"손이 크다 · 발이 넓다",goal:"Use the core body-part idioms for character: 손이 크다, 발이 넓다, 눈이 높다, 입이 무겁다, 귀가 얇다.",biteCount:11,bites:[{kind:"words",title:"단어 Words 1 · 손~",cards:[{kind:"guess",word:{ko:"손",romanization:"son",en:"hand",pos:"noun",nuance:"손 is the hand, and the first thing to fix is the washing verb: hands take 씻다 (손을 씻다), in deliberate contrast to hair, which uses 감다 — mixing them (손을 감다) is a classic beginner slip. Beyond the literal organ, 손 powers vivid idioms that aren't about anatomy: 손이 크다 ('big hand') means generous, especially someone who cooks or gives a lot, not someone with large hands; 손이 가다 ('the hand goes') means a task or person takes a lot of effort/attention; and 손이 모자라다 ('hands are short') means short-staffed. To hold someone's hand is 손을 잡다 (잡다 = grasp), used both romantically and to guide a child across the road. Note the hand is usually the object of an action, so it pairs with 을/를 (손을 씻다, 손을 잡다) rather than 가."},sentence:{ko:"어머니는 손이 크셔서 늘 음식을 넉넉히 하세요.",en:"My mother does things on such a scale that she always makes plenty of food."},target:"손",options:["foot","eye","hand"],note:"손이 크다 is about generosity, never about the size of anyone's hand."},{kind:"guess",word:{ko:"발",romanization:"bal",en:"foot",pos:"noun",nuance:"발 is specifically the foot — the part below the ankle — and Korean keeps it strictly separate from 다리 (the leg, the whole limb above), so pointing at your ankle and saying 다리 is wrong; that is the core mix-up for English speakers who blur 'leg/foot'. Useful collocations: 발을 다치다 (injure the foot, with 다치다 taking 을/를) and 발이 붓다 (the foot swells), where 붓다 is a ㅅ-irregular verb that drops ㅅ before a vowel → 부어요, 부었어요, not 붓어요. Idiomatically 발이 넓다 ('wide foot') means well-connected with a broad social network, never literally big feet (for that you'd say 발이 크다). When you cause an injury yourself, prefer the active 다치다 (발을 다쳤어요) over a passive construction."},sentence:{ko:"지훈 씨는 발이 넓어서 모르는 사람이 없어요.",en:"Jihoon is so well connected that there's nobody he doesn't know."},target:"발",options:["hand","eye","foot"],note:"발이 넓다 is a compliment about someone's social circle."},{kind:"guess",word:{ko:"눈",romanization:"nun",en:"eye",pos:"noun",nuance:"눈 is the eye, but the identical spelling also means 'snow'; the two are split by pitch (eye = short/low, snow = long/high) and above all by context, so listeners rarely confuse them. Korean treats the pair of eyes as one uncountable 눈, so you never pluralize it. The big English-speaker trap is eyesight: vision is rated with 좋다 (good) and 나쁘다 (bad) — 눈이 좋아요 / 눈이 나빠요 — never with 'strong/weak' (강하다/약하다), which would sound bizarre. Note that 눈을 감다 uses the same 감다 as washing hair but means 'close', and the related verb 보다 ('see/look') is what the eye does, while 만나다 ('meet') is for people, so don't blend them."},sentence:{ko:"눈이 높아서 아직 마음에 드는 집을 못 찾았어요.",en:"I'm particular, so I still haven't found a flat I like."},target:"눈",options:["hand","eye","foot"],note:"눈이 높다 is about standards, not eyesight."},{kind:"guess",word:{ko:"입",romanization:"ip",en:"mouth",pos:"noun",nuance:"입 is the mouth, but its most useful expressions are idioms that won't survive word-for-word translation. 입에 맞다 means food 'suits your taste' (lit. 'fits the mouth') — it judges flavor, so 'this fits in my mouth' is a beginner mistranslation. 입이 짧다 ('short mouth') describes a picky or light eater, while 입이 무겁다 ('heavy mouth') means tight-lipped/discreet and 입이 가볍다 ('light mouth') means a blabbermouth — none are about physical size. To physically open the mouth is 입을 벌리다 (벌리다 = spread apart), as a dentist commands; do not use 열다 ('open' a door/box) for the mouth. Note also that 입 (mouth, the organ) is different from 말 (speech/words), so 'watch your mouth' as in language is 말조심하다, not anything with 입."},sentence:{ko:"그 사람은 입이 무거우니까 비밀을 말해도 괜찮아요.",en:"He's discreet, so it's fine to tell him a secret."},target:"입",options:["mouth","hand","foot"],note:"입이 무겁다 keeps a secret; 입이 가볍다 does not."},{kind:"guess",word:{ko:"귀",romanization:"gwi",en:"ear",pos:"noun",nuance:"귀 is the ear, and the key English-speaker pitfall is the verb of hearing. Korean splits 듣다 (to listen actively, by choice) from 들리다 (to be heard / reach the ear, passively, beyond control). So 'I can't hear' is 귀가 안 들려요 with the passive 들리다 — using 못 듣다 implies you deliberately didn't listen, which is rude when talking about someone's deafness. There are two natural ways to describe hard-of-hearing: the plain 귀가 안 들리다 and the gentler idiom 귀가 어둡다 ('the ear is dark'), whose opposite 귀가 밝다 ('bright ear') means keen hearing. To plug your ears against noise is 귀를 막다 (막다 = block), the same 막다 as a blocked nose (코가 막히다). When speaking about elders, pair this with honorifics, e.g. 귀가 어두우세요."},sentence:{ko:"할머니는 귀가 밝으셔서 작은 소리도 다 들으세요.",en:"My grandmother has sharp hearing and catches even the faintest sound."},target:"귀",options:["hand","ear","foot"],note:"귀가 밝다 is about hearing — a different pair from 귀가 얇다."},{kind:"guess",word:{ko:"얼굴",romanization:"eolgul",en:"face",pos:"noun",nuance:"얼굴 is the whole human face — both its looks and its surface you wash — and is the everyday word with no formality issue; you use it equally with friends and elders. Its near-synonym 낯 (as in 낯이 익다 'the face looks familiar', 낯설다 'unfamiliar') is old-fashioned and survives mostly in set idioms, so for plain 'face' always reach for 얼굴. Two pitfalls trip up English speakers. First, hair on the head is 감다 (감다 = wash hair) but the FACE is 씻다, the same verb as for hands and dishes — never say 얼굴을 감다. Second, English 'big face' does not transfer: a flattering 'small face' is 얼굴이 작다 (a real Korean compliment about proportion), and you do not say 얼굴이 커요 to mean handsome. Color uses 빨갛다 (얼굴이 빨개요), and to feel for fever Koreans touch the 이마, not the whole 얼굴."},sentence:{ko:"그렇게 부탁해 놓고 또 오다니, 얼굴이 두껍네요.",en:"Turning up again after asking for all that — what nerve."},target:"얼굴",options:["face","hand","foot"],note:"얼굴이 두껍다 means shameless, the same image as English 'thick-skinned'."},{kind:"guess",word:{ko:"머리",romanization:"meori",en:"head",pos:"noun",nuance:"머리 covers both the head and the hair on it, and only context (the verb or adjective) tells them apart: 머리가 아프다 = head hurts, but 머리가 길다 / 머리를 감다 = hair. The strict word for a single strand is 머리카락, yet in speech Koreans almost always shorten it to 머리, so 'cut my hair' is 머리를 자르다, not 머리카락을 자르다. The pitfall for English speakers is the washing verb: hair takes 감다 (머리를 감다), never the 씻다 you use for hands or face, so 머리를 씻다 sounds childish or wrong. Also note 머리가 좋다/나쁘다 is a fixed idiom for being smart/dim, not a comment on hair quality, and the body part is always marked with 가 (머리가 아파요), not 을."},sentence:{ko:"머리가 좋은 것보다 꾸준한 게 더 중요해요.",en:"Being consistent matters more than being clever."},target:"머리",options:["head","hand","foot"],note:"머리가 좋다 is 'smart'; 머리가 아프다 covers both a headache and a hassle."}],canDo:"Describe someone's character with 손이 크다, 발이 넓다, 눈이 높다, 입이 무겁다, and 귀가 얇다",id:"chapter-72-b1",chapterId:"chapter-72",index:0},{kind:"pattern",title:"문법 Grammar · 손이 크다",cards:[{kind:"teach",name:"손이 크다",sub:"the generous hand, and the rest of the 손 idioms",rows:[{when:"Word for word",add:"손 (hand) + 이 + 크다 (big)",ex:"literally 'the hand is big'"},{when:"What it actually means",add:"generous, does things on a large scale",ex:"어머니는 손이 크시다 (Mum always makes far too much)"},{when:"How it inflects",add:"손이 커요 / 손이 커서 / 손이 크신",ex:"손이 커서 늘 음식이 남아요"},{when:"The opposite",add:"손이 작다",ex:"저는 손이 작아서 딱 먹을 만큼만 해요"},{when:"Other 손 idioms",add:"손을 떼다 · 손이 빠르다 · 손이 많이 가다",ex:"그 일에서는 손을 뗐어요 (I've stepped away from it)"}],examples:[{ko:"어머니는 손이 크셔서 명절만 되면 음식이 늘 남아요.",en:"My mother cooks on such a scale that there are always leftovers at the holidays.",romanization:"eomeonineun soni keusyeoseo myeongjeolman doemyeon eumsigi neul namayo.",note:"The honorific goes on the adjective: 손이 크시다 → 손이 크셔서."},{ko:"손이 크신 건 좋은데 이번엔 좀 줄이는 게 어때요?",en:"It's lovely that you do things so generously, but how about scaling back this time?",romanization:"soni keusin geon joeunde ibeonen jom jurineun ge eottaeyo?",note:"손이 크신 as a modifier before 건 — the clause keeps its shape inside."}],more:{func:"손이 크다 says somebody does things on a generous scale — cooks too much, gives too much, spends freely. It has nothing to do with hand size. Like every idiom in this chapter it is a complete clause, [body part]이/가 [adjective], and you conjugate the adjective at the end.",funcLead:"손이 크다 says somebody does things on a generous scale — cooks too much, gives too much, spends freely.",keyPoint:{label:"The shape is a clause, not a phrase",body:"Every idiom of this family is [body part]이/가 [adjective] — a whole clause. English would build a noun phrase ('a generous hand'), which is why learners produce 큰 손이에요. Korean does not work that way here: keep 손이 크다, 발이 넓다, 눈이 높다 intact and conjugate the adjective on the end."},pronunciation:"손을 뗐어요 links as [소늘 떠써요]. 손이 많이 가는 is [소니 마니 가는], with the ㅎ of 많 silent before the 이.",pitfall:{wrong:"그분은 큰 손이에요.",right:"그분은 손이 크세요.",explanation:"English would say 'a big hand', a noun phrase, so learners build 큰 손이에요. Korean body-part idioms are always a clause: the body part takes 이/가 and the adjective carries the ending. 손이 크세요, 발이 넓으세요, 눈이 높으세요."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"그분은 손이 크세요.",ok:!0},{text:"그분은 큰 손이에요.",ok:!1}],explanation:"English would say 'a big hand', a noun phrase, so learners build 큰 손이에요. Korean body-part idioms are always a clause: the body part takes 이/가 and the adjective carries the ending. 손이 크세요, 발이 넓으세요, 눈이 높으세요."}],canDo:"Describe someone's character with 손이 크다, 발이 넓다, 눈이 높다, 입이 무겁다, and 귀가 얇다",id:"chapter-72-b2",chapterId:"chapter-72",index:1},{kind:"words",title:"단어 Words 2 · 코~",cards:[{kind:"guess",word:{ko:"코",romanization:"ko",en:"nose",pos:"noun",nuance:"코 is the nose, but cold symptoms split into precise collocations English speakers must memorize: a blocked nose is 코가 막히다 (막히다 = be blocked) and a runny nose is 콧물이 나다, where 콧물 literally stitches 코(nose)+물(water) into 'nose-water' = snot. Saying 코가 아프다 actually means the nose physically hurts (an injury), so it does NOT convey a cold — that is the classic 직역 trap. To blow your nose is 코를 풀다 (풀다 'to release/undo'); beware 코를 불다, which means to blow air out like a whistle and sounds absurd here. For looks, a tall nose bridge (admired in Korea) is 코가 높다, with 코가 낮다 as the flat-bridge opposite, paralleling how 키가 크다 works for height."},sentence:{ko:"코가 높은 사람은 먼저 다가가기가 좀 어려워요.",en:"Someone haughty is a little hard to approach first."},target:"코",options:["hand","foot","nose"],note:"코가 높다 means haughty; save it for people who are not in the room."},{kind:"guess",word:{ko:"성격",romanization:"seonggyeok",en:"personality, temperament",pos:"noun",nuance:"성격 (性格, 性 'nature/disposition' + 格 'character/frame') is a person's enduring inborn character — the stable temperament you are born with and keep for life. Contrast it carefully with 기분, which is a passing mood that changes hourly: '오늘 기분이 좋아요' = I'm in a good mood today (temporary), whereas '성격이 좋아요' = he's a good-natured person (permanent). Mixing these is the single most common error: never use 성격 for how you feel right now. The phrase 성격이 좋다 is a warm social compliment meaning kind, tolerant, easy to get along with — broader than English 'good personality'. Note also 성격이 급하다 ('impatient/hot-tempered nature') is an idiomatic fixed expression. Common partner adjectives: 밝다 (cheerful), 활발하다 (lively), 조용하다 (quiet), 까다롭다 (fussy/picky), 무뚝뚝하다 (blunt). Pitfall beyond the 기분 trap: 'I have a ~ personality' is most naturally 성격이 + adjective (성격이 밝아요), not the heavier 저는 ~한 성격을 가지고 있어요 calque, though 급한 성격이에요 is fine."},sentence:{ko:"성격이 급해서 손이 빠른 대신 실수도 잦아요.",en:"I'm impatient, so I work fast but also make frequent mistakes."},target:"성격",options:["hand","foot","personality, temperament"],note:"손이 빠르다 — quick-handed — is another member of the 손 family."},{kind:"guess",word:{ko:"사람",romanization:"saram",en:"person",pos:"noun",nuance:"사람 can mean one person or people in general. It is useful for describing crowds, identity, and who someone is."},sentence:{ko:"발이 넓은 사람은 어디를 가도 아는 얼굴을 만나요.",en:"Someone well connected runs into a familiar face wherever they go."},target:"사람",options:["hand","foot","person"],note:"The idiom becomes a modifier in front of 사람 without changing shape."},{kind:"guess",word:{ko:"친구",romanization:"chingu",en:"friend",pos:"noun",nuance:"친구 can mean friend or same-age peer depending on context."},sentence:{ko:"발이 넓은 친구 덕분에 좋은 사람을 많이 소개받았어요.",en:"Thanks to a well-connected friend I've been introduced to a lot of good people."},target:"친구",options:["hand","foot","friend"],note:"덕분에 credits the cause, as in the reason-connector chapter."},{kind:"guess",word:{ko:"비밀",romanization:"bimil",en:"secret",pos:"noun",nuance:"비밀 (祕密, 祕 'hidden/mysterious' + 密 'dense/close') paints a secret as something kept tightly closed in. The verb it lives with is 지키다 ('to guard/keep'), giving 비밀을 지키다 — note that English 'keep a secret' tempts learners to reach for 가지다 ('to have/hold'), but 비밀을 가지다 sounds wrong; you 지키다 (guard) a secret, or 비밀로 하다 (make it secret). Contrast 비밀 with 비결: both share 비(祕), but 비결 (祕訣) is a 'secret know-how / the trick to success' (성공의 비결 = the secret to success), not confidential information. So a chef's 비결 is their technique, while their 비밀 might be that they hate cooking. The word is register-neutral and used freely from children's games to government affairs. Pitfall to avoid: 비밀 is a noun only — there is no verb 비밀하다. To say 'keep something secret' you must add a verb: 비밀로 하다 or 비밀을 지키다."},sentence:{ko:"입이 무거운 사람이라 비밀을 맡겨도 안심이 돼요.",en:"He's discreet, so I feel safe trusting him with a secret."},target:"비밀",options:["hand","foot","secret"],note:"비밀을 맡기다 and 비밀을 지키다 are the two standard collocations."},{kind:"guess",word:{ko:"마음",romanization:"maeum",en:"heart, mind",pos:"noun",nuance:"마음 is the native word for the heart-mind: the seat of feelings, will, intentions, and disposition — never the physical organ (that is 심장 心臟, the pump). Contrast it with 생각 (thought/idea, the cognitive content) and with 기분 (a passing mood): 마음 is the deeper, more stable inner self where kindness, sincerity, and intentions live. It anchors many high-frequency idioms: 마음에 들다 (to like / be pleased by something you meet), 마음을 먹다 (to make up one's mind), 마음이 아프다 (to be heartsick). The classic English-speaker pitfall is two-fold: using 마음 for the body-heart (say 심장이 빨리 뛰어요 for a racing heart), and translating 'I like it' as 좋아해요 when you mean a settled approval of something in front of you — Koreans naturally reach for 마음에 들어요 there, where 좋아하다 is a broader 'I like/am fond of.'"},sentence:{ko:"눈이 높아서 아직 마음에 드는 걸 못 골랐어요.",en:"I'm particular, so I haven't found one I like yet."},target:"마음",options:["hand","heart, mind","foot"],note:"마음에 들다 is itself an idiom: 'it enters the heart' = you like it."},{kind:"guess",word:{ko:"실력",romanization:"sillyeok",en:"ability, skill",pos:"noun",nuance:"실력 is not confidence or effort; it is the ability itself."},sentence:{ko:"이 정도 문제는 그 사람 실력이면 식은 죽 먹기예요.",en:"With his ability, a problem at this level is a piece of cake."},target:"실력",options:["hand","ability, skill","foot"],note:"식은 죽 먹기 acts as a noun and simply takes 예요."},{kind:"payoff",line:{speaker:"지원",ko:"그냥 사람을 좋아해서 그래요. 대신 저는 입이 좀 가벼운 편이에요.",en:"I just like people, that's all. On the other hand, I'm not great at keeping things to myself."},hl:"사람"}],canDo:"Keep a body-part idiom in its clause shape instead of turning it into a modifier plus noun",id:"chapter-72-b3",chapterId:"chapter-72",index:2},{kind:"pattern",title:"문법 Grammar · 발이 넓다",cards:[{kind:"teach",name:"발이 넓다",sub:"a wide circle, and where else 발 turns up",rows:[{when:"Word for word",add:"발 (foot) + 이 + 넓다 (wide)",ex:"literally 'the foot is wide'"},{when:"What it actually means",add:"well connected, knows a lot of people",ex:"지훈 씨는 발이 넓다 (Jihoon knows everyone)"},{when:"The noun form",add:"마당발",ex:"그 사람은 우리 동네 마당발이에요"},{when:"Stranded — passive",add:"발이 묶이다",ex:"눈 때문에 공항에서 발이 묶였어요"},{when:"Other 발 idioms",add:"발등에 불이 떨어지다 · 발 벗고 나서다",ex:"발등에 불이 떨어져야 시작해요"}],examples:[{ko:"지훈 씨는 발이 넓어서 이 동네에 모르는 사람이 없어요.",en:"Jihoon is so well connected that there's nobody in this neighbourhood he doesn't know.",romanization:"jihun ssineun bari neolbeoseo i dongnee moreuneun sarami eopseoyo.",note:"넓다 is [널따], so 넓어서 links as [널버서]."},{ko:"눈이 많이 와서 어제는 공항에서 발이 묶였어요.",en:"It snowed heavily, so I was stranded at the airport yesterday.",romanization:"nuni mani waseo eojeneun gonghangeseo bari mukkyeosseoyo.",note:"묶이다 is the passive of 묶다 — the snow does the tying, so 발이 takes 이."}],more:{func:"발이 넓다 means somebody knows everybody — a wide social circle, not wide feet. 발 also supplies three more idioms you will hear constantly: 발이 묶이다 for being stranded, 발등에 불이 떨어지다 for a deadline finally biting, and 발 벗고 나서다 for pitching in wholeheartedly.",funcLead:"발이 넓다 means somebody knows everybody — a wide social circle, not wide feet.",keyPoint:{label:"발이 넓다 is a compliment; 마당발 is the person",body:"발이 넓다 describes the quality and is safely complimentary — 발이 넓으시네요 is a normal thing to say to someone who just introduced you to three people. 마당발 is the noun for the person themselves: 그 사람은 마당발이에요. Neither implies anything about being pushy; Korean treats a wide network as straightforwardly good."},pronunciation:"넓다 is [널따] and 넓어서 is [널버서] — the ㅂ of ㄼ only surfaces before a vowel. 발 벗고 is [발 벋꼬], and 묶였어요 is [무껴써요].",pitfall:{wrong:"어제 공항에서 발을 묶었어요.",right:"어제 공항에서 발이 묶였어요.",explanation:"발이 묶이다 is passive — the snow, the strike, or the weather strands you. Learners make it active because English says 'I got stuck', which looks like something you did. The thing that traps you is the cause; your foot takes 이/가 and the verb stays 묶이다."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"어제 공항에서 발이 묶였어요.",ok:!0},{text:"어제 공항에서 발을 묶었어요.",ok:!1}],explanation:"발이 묶이다 is passive — the snow, the strike, or the weather strands you. Learners make it active because English says 'I got stuck', which looks like something you did. The thing that traps you is the cause; your foot takes 이/가 and the verb stays 묶이다."}],canDo:"Keep a body-part idiom in its clause shape instead of turning it into a modifier plus noun",id:"chapter-72-b4",chapterId:"chapter-72",index:3},{kind:"words",title:"단어 Words 3 · 관용구~",cards:[{kind:"guess",word:{ko:"관용구",romanization:"gwanyonggu",en:"idiom, set phrase",pos:"noun"},sentence:{ko:"관용구는 글자 그대로 풀면 뜻이 통하지 않으므로 통째로 외우는 게 좋아요.",en:"Idioms don't make sense word by word, so it's best to memorise them whole."},target:"관용구",options:["hand","foot","idiom, set phrase"],note:"-(으)므로 from the written-style chapter, used here in ordinary speech."},{kind:"guess",word:{ko:"속담",romanization:"sokdam",en:"proverb",pos:"noun"},sentence:{ko:"속담은 문장을 새로 만들지 않고 통째로 인용해요.",en:"You quote a proverb whole rather than building a new sentence out of it."},target:"속담",options:["proverb","hand","foot"],note:"This is the single most useful rule for using proverbs correctly."},{kind:"guess",word:{ko:"소문",romanization:"somun",en:"rumour, word going around",pos:"noun"},sentence:{ko:"소문이 도는 속도를 보면 발 없는 말이 천 리 간다는 말이 맞아요.",en:"Judging by how fast rumours travel, the saying about words going a thousand li is right."},target:"소문",options:["rumour, word going around","hand","foot"],note:"A proverb quoted inside a -는 말이 맞다 frame."},{kind:"guess",word:{ko:"마당발",romanization:"madangbal",en:"a very well-connected person",pos:"noun"},sentence:{ko:"그 사람은 우리 동네 마당발이라 모르는 가게가 없어요.",en:"He's the neighbourhood's great connector — there's no shop he doesn't know."},target:"마당발",options:["hand","a very well-connected person","foot"],note:"마당발 is the noun for the person; 발이 넓다 describes the quality."},{kind:"guess",word:{ko:"우물",romanization:"umul",en:"a well (for water)",pos:"noun"},sentence:{ko:"외국에 나가 보고 나서야 제가 우물 안 개구리였다는 걸 알았어요.",en:"It was only after going abroad that I realised how narrow my world had been."},target:"우물",options:["hand","foot","a well (for water)"],note:"우물 안 개구리 is said about oneself far more comfortably than about others."},{kind:"guess",word:{ko:"태산",romanization:"taesan",en:"a huge mountain (in the proverb 티끌 모아 태산)",pos:"noun"},sentence:{ko:"할 일이 태산인데 아직 시작도 못 했어요.",en:"I have a mountain of things to do and haven't even started."},target:"태산",options:["hand","a huge mountain (in the proverb 티끌 모아 태산)","foot"],note:"할 일이 태산이다 is the other everyday use of 태산."},{kind:"payoff",line:{speaker:"지원",ko:"저도요. 티끌 모아 태산이라고 조금씩 모으려고 했는데 벌써 다 썼어요.",en:"Me too. I meant to save little by little, but I've already spent it all."},hl:"태산"}],canDo:"Use the passive idioms 발이 묶이다 and 눈에 띄다 with the right particles",id:"chapter-72-b5",chapterId:"chapter-72",index:4},{kind:"pattern",title:"문법 Grammar · 눈이 높다",cards:[{kind:"teach",name:"눈이 높다",sub:"high standards, and what the eyes do",rows:[{when:"Word for word",add:"눈 (eye) + 이 + 높다 (high)",ex:"literally 'the eye is high'"},{when:"What it actually means",add:"has high standards, is hard to please",ex:"눈이 높아서 아직 못 골랐어요"},{when:"Standing out — passive",add:"눈에 띄다",ex:"빨간 표지가 눈에 띄었어요"},{when:"Flat out busy",add:"눈코 뜰 새 없다",ex:"요즘 눈코 뜰 새가 없어요"},{when:"Careful — a different word",add:"눈치가 빠르다 (quick to read a room)",ex:"눈치가 빨라서 분위기를 금방 알아채요"}],examples:[{ko:"눈이 높아서 아직 마음에 드는 집을 못 찾았대요.",en:"They say she's so particular that she still hasn't found a flat she likes.",romanization:"nuni nopaseo ajik maeume deuneun jibeul mot chajatdaeyo.",note:"-대요 from the reported-speech chapter: this is somebody else's assessment."},{ko:"표지가 빨개서 책장에서 바로 눈에 띄었어요.",en:"The cover was red, so it stood out on the shelf immediately.",romanization:"pyojiga ppalgaeseo chaekjangeseo baro nune ttuieosseoyo.",note:"눈에 띄다 takes 에, not 을 — the thing catches the eye by itself."}],more:{func:"눈이 높다 means somebody is hard to please — fussy about partners, flats, or clothes. The eyes also give you 눈에 띄다 for standing out, and 눈코 뜰 새 없다 for being flat out. None of them is about eyesight.",funcLead:"눈이 높다 means somebody is hard to please — fussy about partners, flats, or clothes.",keyPoint:{label:"눈이 높다 is gentler about yourself than about others",body:"Said of yourself, 눈이 높다 is a wry admission: 제가 눈이 좀 높아요. Said of somebody else — especially about dating — it can land as a criticism, close to 'too picky for their own good'. If you mean it warmly, 기준이 분명하다 is the safe alternative."},pronunciation:"높다 is [놉따] and 높아서 is [노파서]. 눈코 뜰 새 is [눈코 뜰 쌔], with the ㅅ tensing after ㄹ.",pitfall:{wrong:"빨간 표지가 눈을 띄었어요.",right:"빨간 표지가 눈에 띄었어요.",explanation:"띄다 here is a contraction of 뜨이다, a passive: the thing gets itself noticed. So the eye is where it lands and takes 에. Learners write 눈을 띄다 by analogy with 눈을 뜨다 ('to open one's eyes'), which is a different verb entirely."}}},{kind:"order",prompt:'방금 본 문장을 다시 조립하세요 · Rebuild: "The cover was red, so it stood out on the shelf immediately." (표지가 시작 · Start with 표지가.)',tokens:["표지가","빨개서","책장에서","바로","눈에","띄었어요."],correct:"표지가 빨개서 책장에서 바로 눈에 띄었어요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"빨간 표지가 눈에 띄었어요.",ok:!0},{text:"빨간 표지가 눈을 띄었어요.",ok:!1}],explanation:"띄다 here is a contraction of 뜨이다, a passive: the thing gets itself noticed. So the eye is where it lands and takes 에. Learners write 눈을 띄다 by analogy with 눈을 뜨다 ('to open one's eyes'), which is a different verb entirely."}],canDo:"Use the passive idioms 발이 묶이다 and 눈에 띄다 with the right particles",id:"chapter-72-b6",chapterId:"chapter-72",index:5},{kind:"pattern",title:"문법 Grammar · 입이 무겁다 · 귀가 얇다",cards:[{kind:"teach",name:"입이 무겁다 · 귀가 얇다",sub:"the mouth that keeps a secret and the ear that doesn't",rows:[{when:"Keeps a secret",add:"입이 무겁다",ex:"그 사람은 입이 무거워요 (he's discreet)"},{when:"Cannot keep a secret",add:"입이 가볍다",ex:"입이 가벼운 사람한테는 말하지 마세요"},{when:"Easily persuaded",add:"귀가 얇다",ex:"귀가 얇아서 광고만 보면 사고 싶어져요"},{when:"A picky eater",add:"입이 짧다",ex:"동생은 입이 짧아요"},{when:"Careful — hearing is different",add:"귀가 밝다 / 귀가 어둡다",ex:"할머니가 귀가 어두우세요 (grandma is hard of hearing)"}],examples:[{ko:"그 사람은 입이 무거우니까 말해도 괜찮아요.",en:"He's discreet, so it's fine to tell him.",romanization:"geu sarameun ibi mugeounikka malhaedo gwaenchanayo.",note:"무겁다 is a ㅂ-irregular: 무거우니까, 무거워요."},{ko:"입이 가벼운 사람한테는 비밀을 말하지 마세요.",en:"Don't tell your secrets to someone who can't keep them.",romanization:"ibi gabyeoun saramhanteneun bimireul malhaji maseyo.",note:"입이 가벼운 as a modifier before 사람 — the clause survives intact."}],more:{func:"입이 무겁다 means somebody can be trusted with a secret; its opposite 입이 가볍다 means they cannot. 귀가 얇다 means they are easily talked into things. The weight-and-thickness metaphor is consistent: a heavy mouth stays shut, a thin ear lets everything through.",funcLead:"입이 무겁다 means somebody can be trusted with a secret; its opposite 입이 가볍다 means they cannot.",keyPoint:{label:"귀가 얇다 is not about hearing",body:"The 얇다/두껍다 pair on 귀 measures how easily influence gets through, not sound. 귀가 얇다 = easily persuaded. For actual hearing Korean uses a completely different pair: 귀가 밝다 for sharp hearing and 귀가 어둡다 for poor hearing. Mixing them up produces a sentence that sounds like nonsense to a Korean ear."},pronunciation:"무겁다 is a ㅂ-irregular, so 무거워요 and 무거우니까 lose the ㅂ. 얇다 is [얄따] and 짧다 is [짤따]; both restore the ㅂ before a vowel — [얄바서], [짤바서].",pitfall:{wrong:"할머니는 귀가 얇아서 잘 못 들으세요.",right:"할머니는 귀가 어두우셔서 잘 못 들으세요.",explanation:"귀가 얇다 means easily persuaded and says nothing about hearing. Poor hearing is 귀가 어둡다 and sharp hearing is 귀가 밝다. The thin-ear image is about influence getting through, not sound."}}},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "He's discreet, so it's fine to tell him."`,tokens:["그","사람은","입이","무거우니까","말해도","괜찮아요."],correct:"그 사람은 입이 무거우니까 말해도 괜찮아요.",explanation:""},{kind:"order",prompt:`방금 본 문장을 다시 조립하세요 · Rebuild: "Don't tell your secrets to someone who can't keep them."`,tokens:["입이","가벼운","사람한테는","비밀을","말하지","마세요."],correct:"입이 가벼운 사람한테는 비밀을 말하지 마세요.",explanation:""},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"할머니는 귀가 어두우셔서 잘 못 들으세요.",ok:!0},{text:"할머니는 귀가 얇아서 잘 못 들으세요.",ok:!1}],explanation:"귀가 얇다 means easily persuaded and says nothing about hearing. Poor hearing is 귀가 어둡다 and sharp hearing is 귀가 밝다. The thin-ear image is about influence getting through, not sound."}],canDo:"Quote 티끌 모아 태산, 발 없는 말이 천 리 간다, 우물 안 개구리, 하늘의 별 따기, and 식은 죽 먹기 whole",id:"chapter-72-b7",chapterId:"chapter-72",index:6},{kind:"pattern",title:"문법 Grammar · 속담 다섯",cards:[{kind:"teach",name:"속담 다섯",sub:"the proverbs you will actually hear",rows:[{when:"Small amounts add up",add:"티끌 모아 태산",ex:"티끌 모아 태산이라고 조금씩 모았어요"},{when:"Word travels fast",add:"발 없는 말이 천 리 간다",ex:"발 없는 말이 천 리 간다더니 소문이 다 퍼졌어요"},{when:"Someone with a narrow view",add:"우물 안 개구리",ex:"제가 우물 안 개구리였어요"},{when:"Nearly impossible",add:"하늘의 별 따기",ex:"그 표를 구하는 건 하늘의 별 따기예요"},{when:"Extremely easy",add:"식은 죽 먹기",ex:"이 정도는 식은 죽 먹기죠"}],examples:[{ko:"티끌 모아 태산이라고, 매달 조금씩 모았더니 꽤 됐어요.",en:"Little by little makes a lot — I put a bit aside every month and it's added up.",romanization:"tikkeul moa taesanirago, maedal jogeumssik moatdeoni kkwae dwaesseoyo.",note:"-이라고 quotes the proverb, and -았더니 reports what you found by doing it."},{ko:"발 없는 말이 천 리 간다더니 소문이 벌써 다 퍼졌네요.",en:"Word really does travel — the rumour has already gone everywhere.",romanization:"bal eomneun mari cheolli gandadeoni somuni beolsseo da peojyeonneyo.",note:"-다더니 is the standard way to say 'as the saying goes, and sure enough'."}],more:{func:"Korean proverbs are fixed strings. You quote them whole and attach the grammar to the outside — 이다, -이라고, or -(이)라더니 — rather than rebuilding them into a sentence. These five turn up in ordinary conversation, not just in writing.",funcLead:"Korean proverbs are fixed strings.",keyPoint:{label:"Three ways to hang a proverb on your sentence",body:"Attach 이다 when the proverb IS your point: 하늘의 별 따기예요. Attach -(이)라고 when you are invoking it as received wisdom before your own clause: 티끌 모아 태산이라고, …. Attach -다더니 when reality has just confirmed it: 발 없는 말이 천 리 간다더니, …. What you never do is take the proverb apart."},pronunciation:"천 리 is [철리], with the ㄴ assimilating to the ㄹ. 식은 죽 먹기 is [시근 죽 먹끼], and 없는 in 발 없는 말이 is [엄는].",pitfall:{wrong:"티끌을 모아서 태산을 만들어요.",right:"티끌 모아 태산이에요.",explanation:"Proverbs are fixed strings, so you quote them rather than rebuild them. 티끌 모아 태산 keeps its bare nouns with no particles and its 모아 with nothing attached. Say the whole thing as one unit and hang 이에요, -이라고, or -다더니 on the outside."}}},{kind:"drill",prompt:"어느 쪽이 자연스러워요? · Which one is natural?",sentence:null,options:[{text:"티끌 모아 태산이에요.",ok:!0},{text:"티끌을 모아서 태산을 만들어요.",ok:!1}],explanation:"Proverbs are fixed strings, so you quote them rather than rebuild them. 티끌 모아 태산 keeps its bare nouns with no particles and its 모아 with nothing attached. Say the whole thing as one unit and hang 이에요, -이라고, or -다더니 on the outside."}],canDo:"Judge which idioms are compliments and which are insults before using them to someone's face",id:"chapter-72-b8",chapterId:"chapter-72",index:7},{kind:"dialogue",title:"대화 Dialogue · 진짜 한국어",cards:[{kind:"chat",setting:"Two friends catching up over coffee. They end up describing three different people, and every description comes out as a body-part idiom.",lines:[{speaker:"유진",ko:"지원 씨는 진짜 발이 넓은 것 같아요. 어제 모임에서도 절반은 아는 사이던데요.",en:"You really do know everyone, Jiwon. Half the people at yesterday's gathering were already friends of yours.",romanization:"jiwon ssineun jinjja bari neolbeun geot gatayo. eoje moimeseodo jeolbaneun aneun saideondeyo."},{speaker:"지원",ko:"그냥 사람을 좋아해서 그래요. 대신 저는 입이 좀 가벼운 편이에요.",en:"I just like people, that's all. On the other hand, I'm not great at keeping things to myself.",romanization:"geunyang sarameul joahaeseo geuraeyo. daesin jeoneun ibi jom gabyeoun pyeonieyo."},{speaker:"유진",ko:"그건 아니에요. 지난번에 제 얘기 아무한테도 안 하셨잖아요.",en:"That's not true. You didn't tell a soul about my situation last time.",romanization:"geugeon anieyo. jinanbeone je yaegi amuhantedo an hasyeotjanayo."},{speaker:"지원",ko:"그때는 참았죠. 사실 유진 씨야말로 입이 무거운 사람이잖아요.",en:"I held it in that time. Honestly, you're the discreet one.",romanization:"geuttaeneun chamatjyo. sasil yujin ssiyamallo ibi mugeoun saramijanayo."},{speaker:"유진",ko:"저는 귀가 얇은 게 문제예요. 광고만 보면 다 사고 싶어지거든요.",en:"My problem is that I'm too easily swayed. One advert and I want to buy everything.",romanization:"jeoneun gwiga yalbeun ge munjeyeyo. gwanggoman bomyeon da sago sipeojigeodeunyo."},{speaker:"지원",ko:"저도요. 티끌 모아 태산이라고 조금씩 모으려고 했는데 벌써 다 썼어요.",en:"Me too. I meant to save little by little, but I've already spent it all.",romanization:"jeodoyo. tikkeul moa taesanirago jogeumssik moeuryeogo haenneunde beolsseo da sseosseoyo."},{speaker:"유진",ko:"저는 눈이 높아서 그런지 사고 싶은 게 별로 없긴 해요.",en:"Maybe because I'm so particular, there isn't much I actually want to buy.",romanization:"jeoneun nuni nopaseo geureonji sago sipeun ge byeollo eopgin haeyo."},{speaker:"지원",ko:"부럽네요. 저는 발등에 불이 떨어져야 겨우 정신을 차리거든요.",en:"I'm jealous. I only pull myself together once the deadline is right on top of me.",romanization:"bureomneyo. jeoneun baldeunge buri tteoreojyeoya gyeou jeongsineul charigeodeunyo."}]},{kind:"order",prompt:"Build: 'Word travels fast, and the rumour has already spread.' (Start with 발 없는 말이.)",tokens:["발 없는 말이","천 리 간다더니","소문이","벌써 다 퍼졌네요"],correct:"발 없는 말이 천 리 간다더니 소문이 벌써 다 퍼졌네요",explanation:"-다더니 hangs on the outside of the proverb and means reality has just confirmed it."},{kind:"drill",prompt:"누가 한 말일까요? · Who said this?",sentence:"지원 씨는 진짜 발이 넓은 것 같아요. 어제 모임에서도 절반은 아는 사이던데요.",options:[{text:"지원",ok:!1},{text:"유진",ok:!0}],explanation:"You really do know everyone, Jiwon. Half the people at yesterday's gathering were already friends of yours."},{kind:"drill",prompt:`무엇이 들어갈까요? · "I just like people, that's all. On the other hand, I'm not great at keeping things to myself."`,sentence:"그냥 ___을 좋아해서 그래요. 대신 저는 입이 좀 가벼운 편이에요.",options:[{text:"사람",ok:!0},{text:"손",ok:!1},{text:"발",ok:!1}],explanation:""}],canDo:"Describe someone's character with 손이 크다, 발이 넓다, 눈이 높다, 입이 무겁다, and 귀가 얇다",id:"chapter-72-b9",chapterId:"chapter-72",index:8},{kind:"reading",title:"읽기 Reading · 몸으로 말하는 성격",cards:[{kind:"read",title:"몸으로 말하는 성격",chunks:["한국어에는 몸을 빌려 성격을 말하는 표현이 많다. 손이 큰 사람은 인심이 후하고, 발이 넓은 사람은 아는 사람이 많다. 입이 무거운 사람에게는 비밀을 맡길 수 있으나, 귀가 얇은 사람은 남의 말에 쉽게 흔들린다. 눈이 높다는 말은 기준이 까다롭다는 뜻이지 시력과는 관계가 없다.","이런 표현은 글자 그대로 풀면 뜻이 통하지 않으므로 통째로 외우는 편이 낫다. 속담도 마찬가지다. '티끌 모아 태산'은 조사도 없이 그대로 쓰며, 문장을 새로 만들지 않는다."],translation:"Korean has many expressions that borrow the body to talk about character. A person with a big hand is open-handed, and a person with a wide foot knows a lot of people. You can trust a secret to someone with a heavy mouth, but someone with a thin ear is easily swayed by what others say. Saying that someone's eye is high means their standards are demanding — it has nothing to do with eyesight. Expressions like these do not make sense when unpacked word by word, so it is better to memorise them whole. The same goes for proverbs. 티끌 모아 태산 is used exactly as it stands, with no particles, and you do not build a new sentence out of it.",qas:[{q:"'눈이 높다'는 시력과 관계가 있어요?",a:"아니요. 기준이 까다롭다는 뜻이지 시력과는 관계가 없어요."},{q:"관용구를 왜 통째로 외우는 게 좋아요?",a:"글자 그대로 풀면 뜻이 통하지 않기 때문이에요."},{q:"속담은 어떻게 써요?",a:"조사도 없이 그대로 쓰고, 문장을 새로 만들지 않아요."}]},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"한국어에는 몸을 빌려 ___을 말하는 표현이 많다.",options:[{text:"얼굴",ok:!1},{text:"머리",ok:!1},{text:"성격",ok:!0}],explanation:""},{kind:"drill",prompt:"지문에서 뭐라고 했어요? · What did the passage say?",sentence:"손이 큰 ___은 인심이 후하고, 발이 넓은 사람은 아는 사람이 많다.",options:[{text:"얼굴",ok:!1},{text:"사람",ok:!0},{text:"머리",ok:!1}],explanation:""}],canDo:"Keep a body-part idiom in its clause shape instead of turning it into a modifier plus noun",id:"chapter-72-b10",chapterId:"chapter-72",index:9},{kind:"boss",title:"보스 Boss bite · 다 걸어요",cards:[{kind:"drill",prompt:"Which sentence correctly says 'she is very generous'?",sentence:null,options:[{text:"그분은 손이 크세요.",ok:!0},{text:"그분은 큰 손이에요.",ok:!1},{text:"그분은 손을 크세요.",ok:!1}],explanation:"These idioms are a full clause: the body part takes 이/가 and the adjective carries the ending. A noun phrase like 큰 손이에요 would just describe hand size."},{kind:"drill",prompt:"지훈 씨는 아는 사람이 정말 많아요. Which idiom fits?",sentence:null,options:[{text:"발이 넓어요",ok:!0},{text:"발이 묶였어요",ok:!1},{text:"발등에 불이 떨어졌어요",ok:!1}],explanation:"발이 넓다 is a wide social circle. 발이 묶이다 is being stranded, and 발등에 불이 떨어지다 is a deadline suddenly biting."},{kind:"drill",prompt:"What does 귀가 얇다 mean?",sentence:null,options:[{text:"쉽게 설득당해요",ok:!0},{text:"잘 못 들어요",ok:!1},{text:"귀가 아주 밝아요",ok:!1}],explanation:"귀가 얇다 means easily persuaded. Poor hearing is 귀가 어둡다 and sharp hearing is 귀가 밝다."},{kind:"drill",prompt:"표지가 빨개서 책장에서 바로 눈___ 띄었어요.",sentence:null,options:[{text:"에",ok:!0},{text:"을",ok:!1},{text:"이",ok:!1}],explanation:"띄다 is a contraction of the passive 뜨이다, so the eye is where the thing lands: 눈에 띄다. 눈을 뜨다 is a different verb meaning 'to open one's eyes'."},{kind:"drill",prompt:"Which proverb means 'nearly impossible'?",sentence:null,options:[{text:"하늘의 별 따기",ok:!0},{text:"식은 죽 먹기",ok:!1},{text:"우물 안 개구리",ok:!1}],explanation:"하늘의 별 따기 is picking a star from the sky. 식은 죽 먹기 is the opposite — very easy — and 우물 안 개구리 describes a narrow outlook."},{kind:"drill",prompt:"Which one would you NOT say to someone's face?",sentence:null,options:[{text:"얼굴이 두꺼우시네요.",ok:!0},{text:"발이 넓으시네요.",ok:!1},{text:"입이 무거우시네요.",ok:!1}],explanation:"얼굴이 두껍다 means shameless and is a real insult. 발이 넓다 and 입이 무겁다 are both compliments."}],canDo:"Use the passive idioms 발이 묶이다 and 눈에 띄다 with the right particles",id:"chapter-72-b11",chapterId:"chapter-72",index:10}]}],o={generatedFrom:e,chapters:t};export{t as chapters,o as default,e as generatedFrom};
